-- Step 73, part 1 of 3: breeding guides (creates the table; run parts 2 and 3 after).
--
-- One guide for every species on the Society's point list (227: animals in the Breeder
-- Award Program and plants in the plant program). Names, category and points are NOT
-- copied here: each guide points at its row in club_award_species, and at the species
-- library page (species_slug) or glossary entry (glossary_slug, plants) where one exists,
-- so nothing is stored twice. Every guide was written, then independently fact-checked.
--
-- Safe to run more than once: re-running updates the text of existing guides.

create table if not exists public.breeding_guides (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  award_species_id uuid references public.club_award_species(id) on delete set null,
  species_slug text,
  glossary_slug text,
  seo_title text not null,
  summary text not null,
  intro text not null,
  facts jsonb not null default '{}'::jsonb,
  sections jsonb not null default '[]'::jsonb,
  faq jsonb not null default '[]'::jsonb,
  society_tip text,
  is_published boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists breeding_guides_award_idx on public.breeding_guides (award_species_id);
create index if not exists breeding_guides_species_idx on public.breeding_guides (species_slug);

alter table public.breeding_guides enable row level security;
drop policy if exists "Published breeding guides are public" on public.breeding_guides;
create policy "Published breeding guides are public" on public.breeding_guides
  for select using (is_published);
grant select on public.breeding_guides to anon, authenticated;

insert into public.breeding_guides
  (slug, award_species_id, species_slug, glossary_slug, seo_title, summary, intro, facts, sections, faq, society_tip)
select v.slug, a.id, v.species_slug, v.glossary_slug, v.seo_title, v.summary, v.intro, v.facts, v.sections, v.faq, v.society_tip
from (values
  ($g$paradise-fish$g$, $g$c2c75e49-a9fa-4b50-80b5-f02f5cbfbf09$g$::uuid, $g$paradise-fish$g$, null, $g$How to Breed Paradise Fish: Bubble Nests and Raising Fry$g$, $g$Paradise fish spawn readily under a male's bubble nest. Learn setup, pairing, nest care and how to raise the tiny fry. A great first bubble nester.$g$, $g$Paradise fish are one of the easiest bubble nesters to breed, and watching a male build his nest and guard it is a real treat. A healthy pair often spawns within days of being set up, and a single spawn can give you a few hundred fry. The tricky parts are protecting the female from an eager male and feeding fry small enough foods for their first week.$g$, $g${"method": "Bubble nester (male builds and guards a floating nest)", "sexing": "Males have longer, pointed fins and brighter color; females are plumper with shorter fins", "group": "One pair", "breeding_tank": "10 to 20 gallons, low water, floating plants, tight lid, gentle sponge filter", "conditioning": "Live or frozen bloodworms, brine shrimp and daphnia for 1 to 2 weeks", "trigger": "Warm, still water around 75 to 79°F with floating plants for the nest", "spawn": "Commonly 200 to 500 eggs", "eggs": "Hatch in about 24 to 48 hours at 75 to 79°F", "fry": "Free swimming about 2 to 4 days after hatching; very small", "first_foods": "Infusoria or green water, then microworms and baby brine shrimp after about a week", "grow_out": "About 1 inch in 6 to 8 weeks with heavy feeding", "parents": "Male guards the nest; remove the female after spawning and the male once fry swim freely"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 to 20 gallon tank works well. Fill it to about 6 to 8 inches so the male has less distance to carry falling eggs back to the nest. Add a mat of floating plants such as water sprite or frogbit for him to anchor the bubbles, plus some tall plants or a clump of moss where the female can hide.\n\nKeep the water still. A gentle air driven sponge filter is plenty, since strong current breaks up the nest. Paradise fish tolerate cool water, but spawning goes best at 75 to 79°F, the top of their normal range. A tight lid matters twice over: it keeps humid air above the water for the fry and stops adults from jumping."}, {"heading": "Conditioning and Choosing a Pair", "text": "Pick a male with long, pointed dorsal and anal fins and strong color, and a female who looks rounded through the belly. Females are a little smaller with shorter fins and duller stripes.\n\nCondition both for 1 to 2 weeks on live or frozen foods: bloodworms, brine shrimp, daphnia and mosquito larvae if you have them, with a quality flake on the side. Many breeders condition the pair apart, or with a clear divider, and then put the female in once the male has started a nest. A well fed female will look visibly full of eggs."}, {"heading": "Spawning: What You'll See", "text": "The male blows a raft of bubbles under the floating plants, then flares and displays to lure the female beneath it. He wraps his body around hers in an embrace, and a small batch of eggs is released and fertilized. This repeats many times over an hour or two.\n\nThe eggs float, and the male gathers any strays in his mouth and spits them into the nest. When she is spent, he turns on the female and chases her away. Remove her right after spawning, because a guarding male can injure or kill a female who has nowhere to escape."}, {"heading": "Eggs and the Nest", "text": "Commonly 200 to 500 eggs end up in the nest. They hatch in about 24 to 48 hours at 75 to 79°F, and the larvae hang from the bubbles while they live off their yolk sacs.\n\nLet the male do the work. He repairs the nest and returns any larvae that drop. Don't net the nest or add current, and skip big water changes for these first few days. A few white eggs are normal, since they were infertile. Leaving the male in place usually does a better job than any fungus treatment."}, {"heading": "Raising the Fry", "text": "The fry become free swimming about 2 to 4 days after hatching. Once most are swimming level, remove the male, because his care ends and he may start eating them.\n\n- Days 1 to 7: infusoria, green water or a liquid fry food, a little several times a day\n- Week 2: add microworms and freshly hatched baby brine shrimp\n- Weeks 3 to 4: baby brine shrimp and crushed flake\n\nChange 10 to 20 percent of the water every 2 to 3 days with water matched for temperature. Keep the lid on and the room warm. Fry develop their labyrinth organ at around 3 to 4 weeks, and cold, dry air above the water at that stage causes losses."}, {"heading": "Growing Out", "text": "Paradise fry grow quickly on regular feedings, reaching about 1 inch in roughly 6 to 8 weeks. As they grow, move them into a larger tank or split the group so the water stays clean and the bigger fry don't crowd out the smaller ones.\n\nBy 2 to 3 months, young males begin showing longer fins and start to bicker. Plan where they will go before then. Each spawn is large, so it helps to line up local fish clubs or stores early instead of keeping more than your tanks can handle."}, {"heading": "Common Mistakes", "text": "- Leaving the female in after spawning, where the male can batter her\n- Using a strong filter that breaks up the nest\n- Feeding baby brine shrimp too early; the newly free swimming fry are too small for it\n- Running the tank without a lid, which chills fry during their labyrinth organ stage\n- Raising hundreds of fry in one small tank and losing them to dirty water"}]$g$::jsonb, $g$[{"q": "How long does it take paradise fish eggs to hatch?", "a": "About 24 to 48 hours at 75 to 79°F. The fry then hang from the nest for another 2 to 4 days before swimming freely."}, {"q": "Should I remove the female paradise fish after spawning?", "a": "Yes. The male guards the nest aggressively and will chase and can injure the female, so move her out once spawning is over."}, {"q": "Do paradise fish eat their fry?", "a": "The male protects the eggs and young larvae, but once the fry swim freely he may start eating them. Remove him at that point."}, {"q": "How can you tell a male paradise fish from a female?", "a": "Males have longer, pointed dorsal and anal fins and brighter colors. Females are slightly smaller, rounder in the belly and have shorter fins."}]$g$::jsonb, $g$Open your log before spawning and photograph both fish in the breeding tank with your challenge code card (a shot with the female behind a divider works). The bubble nest full of eggs makes a clear stage 2 photo.$g$),
  ($g$three-spot-gourami$g$, $g$3777bf53-fef5-4953-bb66-d65d717bb92b$g$::uuid, $g$three-spot-gourami$g$, null, $g$How to Breed Three-spot Gouramis: Bubble Nests and Fry Care$g$, $g$Three-spot gouramis spawn readily under a bubble nest and lay hundreds of eggs. Learn setup, sexing, nest care and how to feed their very tiny fry.$g$, $g$Three-spot gouramis, including the blue, gold and opaline forms, are easy to spawn and produce big batches of fry. The male builds a bubble nest and guards it, which is fun to watch in a quiet tank. The real challenge is not the spawn but the fry, which are tiny at first and need very small foods and clean, warm water to make it through the first few weeks.$g$, $g${"method": "Bubble nester (male builds and guards a floating nest)", "sexing": "Male's dorsal fin is long and pointed; female's is short and rounded, and she is plumper", "group": "One pair", "breeding_tank": "20 gallons or more, about 6 to 8 inches of water, floating plants, cover, sponge filter", "conditioning": "Frozen or live bloodworms, brine shrimp and daphnia plus flake for 1 to 2 weeks", "trigger": "Warm, still water around 78 to 82°F with floating plants and a slightly lowered water level", "spawn": "Commonly several hundred eggs, sometimes 1,000 or more", "eggs": "Hatch in about 24 to 48 hours at 78 to 82°F", "fry": "Free swimming about 2 to 3 days after hatching; extremely small", "first_foods": "Infusoria or green water, then microworms and baby brine shrimp at about 1 week", "grow_out": "About 1 inch in 6 to 8 weeks", "parents": "Remove female after spawning; remove male once fry swim freely"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "Use a tank of at least 20 gallons. Three-spots are fairly large and the male can be rough, so the female needs space and cover. Lower the water to about 6 to 8 inches and add floating plants such as water sprite or salvinia where the male can anchor his nest, plus tall plants or driftwood for the female to hide behind.\n\nKeep the temperature at 78 to 82°F, inside the normal range for the species. Filtration should be gentle: an air driven sponge filter is ideal. Cover the tank tightly so the air above the water stays warm and humid."}, {"heading": "Conditioning and Choosing a Pair", "text": "Sexing is straightforward in adults. The male's dorsal fin is long and comes to a point, while the female's is shorter and rounded. A ripe female is noticeably fuller through the belly.\n\nCondition the pair for 1 to 2 weeks on frozen or live bloodworms, brine shrimp and daphnia, alternating with a good flake or small pellet. Many breeders keep the female separate or behind a divider until the male has built a nest, then introduce her. A female who isn't ready will be chased hard, so a full belly is your best sign of timing."}, {"heading": "Spawning: What You'll See", "text": "The male builds a loose raft of bubbles, often wider than it is thick, and darkens in color. He displays to the female and leads her under the nest, where he wraps around her and eggs are released in small batches. The pair repeats this many times.\n\nThe eggs are lighter than water and float up into the nest, and the male tidies them into place. When spawning is done he becomes aggressive toward the female. Remove her promptly to avoid injury."}, {"heading": "Eggs and the Nest", "text": "A single spawn is commonly several hundred eggs and can reach 1,000 or more. At 78 to 82°F they hatch in about 24 to 48 hours, and the larvae hang below the nest while using their yolk.\n\nLeave the male to tend the nest; he picks up and returns falling eggs and larvae. Avoid water changes and strong current during these first days. Some white, infertile eggs are normal and usually aren't a problem with the male in charge."}, {"heading": "Raising the Fry", "text": "The fry swim freely about 2 to 3 days after hatching. Remove the male at this point. Three-spot fry are very small, so the first week of food is what decides how many survive.\n\n- Days 1 to 7: infusoria, green water or liquid fry food, small amounts several times a day\n- Week 2: microworms and newly hatched baby brine shrimp\n- Weeks 3 to 5: baby brine shrimp and finely crushed flake\n\nChange 10 to 20 percent every 2 to 3 days, matching the temperature. Keep the lid on, especially around weeks 3 to 6 when the labyrinth organ develops and cool air can kill fry."}, {"heading": "Growing Out", "text": "With frequent feeding the fry reach about 1 inch in 6 to 8 weeks. Growth is uneven, so split the batch or sort out the largest fish to give smaller ones a chance at food.\n\nA spawn can easily produce more fry than you have room for. Thin the group into larger tanks as they grow and line up homes early. The color forms of this species all breed the same way, so these steps apply to blue, gold and opaline gouramis too."}, {"heading": "Common Mistakes", "text": "- Leaving the female with the male after spawning\n- Strong filtration or surface movement that destroys the nest\n- Starting fry on baby brine shrimp before they can eat it\n- No lid, which lets the air above the water cool and dry out\n- Overfeeding powdered food in a bare tank and fouling the water"}]$g$::jsonb, $g$[{"q": "How do I know if my three-spot gourami is male or female?", "a": "Look at the dorsal fin. Males have a long, pointed dorsal fin, while females have a shorter, rounded one and a fuller belly."}, {"q": "How many eggs do three-spot gouramis lay?", "a": "Commonly several hundred per spawn, and large females can produce 1,000 or more."}, {"q": "Do three-spot gouramis eat their fry?", "a": "The male guards eggs and larvae but may eat fry once they swim freely, and the female should be removed right after spawning."}, {"q": "Why are my gourami fry dying after a few weeks?", "a": "Common causes are cold, dry air above the water while the labyrinth organ forms, starvation from foods that are too large, or fouled water. Keep the tank covered and warm."}]$g$::jsonb, $g$Photograph your chosen pair in the setup with the challenge code card when you open the log, then capture the nest full of eggs for stage 2. For stage 3, a close photo of fry swimming in open water is clearer than a shot of the nest.$g$),
  ($g$gold-barb$g$, $g$226ba966-dde5-4069-a0a4-6970e5c2136d$g$::uuid, $g$gold-barb$g$, null, $g$How to Breed Gold Barbs: Spawning, Eggs and Raising Fry$g$, $g$Gold barbs are easy egg scatterers that spawn at dawn. Learn how to set up a breeding tank, save the eggs from hungry parents and raise healthy fry.$g$, $g$Gold barbs are a great first egg scatterer, and a conditioned group will spawn readily, often at first light, scattering sticky eggs across plants. The parents will happily eat those eggs, so the secret is a simple setup that lets eggs fall out of reach and moving the adults out once spawning is done. After that, the fry are hardy and grow well.$g$, $g${"method": "Egg scatterer (adhesive eggs, no parental care)", "sexing": "Males slimmer with a stronger gold to orange tint; females larger and rounder", "group": "1 female to 2 males, or a small group", "breeding_tank": "10 to 20 gallons, fine plants or spawning mops, mesh or marbles on the bottom", "conditioning": "Live or frozen foods plus flake and some vegetable matter for 1 to 2 weeks", "trigger": "Moving conditioned fish to fresh, slightly warmer water around 75 to 77°F", "spawn": "Commonly 100 to 300 eggs", "eggs": "Hatch in about 1 to 2 days at 75 to 77°F", "fry": "Free swimming about 3 to 5 days after spawning", "first_foods": "Infusoria or liquid fry food, then baby brine shrimp and microworms", "grow_out": "About 1 inch in 8 to 10 weeks", "parents": "Eat eggs readily; remove adults right after spawning"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 to 20 gallon tank is plenty. Leave it bare apart from a layer of fine leaved plants such as java moss, or a few spawning mops, and cover the bottom with a mesh grid or a single layer of marbles so eggs can drop where the parents can't reach them.\n\nUse a gentle sponge filter. Gold barbs are comfortable in cooler water, and their usual range tops out around 79°F, so set the breeding tank at 75 to 77°F. Neutral to slightly acidic, soft to medium water is fine, and fresh, aged water often helps."}, {"heading": "Conditioning and Choosing a Group", "text": "Males are slimmer and, in good condition, show a richer gold that can turn orange to reddish on the throat and fins. Females are larger, deeper bodied and duller.\n\nCondition males and females separately for 1 to 2 weeks if you can, feeding twice daily with frozen bloodworms, brine shrimp, daphnia and a good flake that includes vegetable matter. When the females look plump, move one or two of them with two males into the breeding tank in the evening."}, {"heading": "Spawning: What You'll See", "text": "Spawning usually begins the next morning, often at first light. The males chase the female through the plants, swimming close at her side, and eggs are released and fertilized in bursts. The eggs are slightly sticky and cling to plants or fall through to the bottom.\n\nThe whole event can last a couple of hours. Once the female looks slimmer and the chasing slows down, remove all the adults. Gold barbs don't care for their eggs and will eat as many as they can find."}, {"heading": "Eggs and Fungus Prevention", "text": "A good spawn is commonly 100 to 300 eggs. At 75 to 77°F they hatch in about 1 to 2 days. Fertile eggs look clear to amber, while infertile ones turn white within a day and can grow fungus.\n\nKeep the tank dim, as the eggs are light sensitive, and add a few drops of methylene blue if fungus has been a problem before. Siphon out white eggs with an airline tube where you can. Leave the newly hatched larvae alone; they stay stuck to surfaces and live on their yolk."}, {"heading": "Raising the Fry", "text": "The fry become free swimming about 3 to 5 days after spawning. Start feeding only once they swim in open water.\n\n- Days 1 to 5 of swimming: infusoria or a liquid fry food, a few times a day\n- From about day 5: newly hatched baby brine shrimp and microworms\n- Weeks 3 to 6: baby brine shrimp plus finely crushed flake\n\nChange 10 to 20 percent of the water every 2 to 3 days, matching the temperature. Siphon uneaten food from the bottom. Keep the tank at 75 to 77°F for steady growth."}, {"heading": "Growing Out", "text": "Gold barb fry are hardy and grow at a steady pace, reaching about 1 inch in roughly 8 to 10 weeks with frequent feeding and regular water changes. Move them into a bigger grow out tank once they are eating flake well.\n\nThey are schooling fish, so keep them in groups. They usually start to show adult color in a few months, and sexes become easy to tell as females fill out. Gold barbs breed readily as adults, so you'll have more spawning chances once these youngsters mature."}, {"heading": "Common Mistakes", "text": "- Leaving the parents in, which usually means no eggs left by evening\n- A bare glass bottom with nothing to protect falling eggs\n- Bright light on the eggs, which can lower hatch rates\n- Feeding baby brine shrimp before the fry are big enough\n- Skipping water changes in a small fry tank"}]$g$::jsonb, $g$[{"q": "How long do gold barb eggs take to hatch?", "a": "About 1 to 2 days at 75 to 77°F. The fry then use their yolk for a few days and swim freely about 3 to 5 days after spawning."}, {"q": "Do gold barbs eat their eggs?", "a": "Yes. They give no parental care and will eat eggs and fry, so remove the adults as soon as spawning ends."}, {"q": "How do you tell male and female gold barbs apart?", "a": "Males are slimmer with a stronger gold to orange color, especially when spawning. Females are bigger and rounder through the belly."}, {"q": "Will gold barbs breed in a community tank?", "a": "They often spawn there, but the eggs are eaten quickly. A separate breeding tank is the reliable way to raise fry."}]$g$::jsonb, $g$Photograph your conditioned group in the breeding tank with the challenge code card the evening you set them up, before the morning spawn. A close photo of eggs on the mop or mesh works well for stage 2.$g$),
  ($g$common-goldfish$g$, $g$3934d7f6-e3a7-412e-af1b-e1f7c62ab951$g$::uuid, $g$common-goldfish$g$, null, $g$How to Breed Goldfish: Spawning Mops, Eggs and Fry Care$g$, $g$Goldfish spawn when water warms in spring. Learn to spot breeding males, collect eggs on spawning mops and raise hundreds of fry to sellable size.$g$, $g$Breeding goldfish is a spring ritual for many keepers. When cooled water warms up, males chase females hard and hundreds of sticky eggs end up on plants or mops. Spawning itself is easy; the work is in saving the eggs from the adults and handling a large batch of fry that need plenty of space and clean water as they grow.$g$, $g${"method": "Egg scatterer (adhesive eggs, no parental care)", "sexing": "Ripe males show white breeding tubercles on gill covers and front fin rays; females are rounder", "group": "One female to 2 or 3 males", "breeding_tank": "Large tank or pond with spawning mops or fine plants and strong filtration", "conditioning": "Varied foods, including frozen or live foods, after a cooler winter period", "trigger": "Water warming from the low 60s to about 68 to 72°F with longer days", "spawn": "Commonly several hundred to over a thousand eggs", "eggs": "Hatch in about 3 to 6 days at 68 to 72°F; cooler water is slower", "fry": "Free swimming about 2 to 3 days after hatching", "first_foods": "Liquid or powdered fry food and infusoria, then baby brine shrimp", "grow_out": "About 1 inch in 2 to 3 months; color change can take months longer", "parents": "Eat eggs; move mops to a hatching tank or remove adults after spawning"}$g$::jsonb, $g$[{"heading": "Setting Up for Spawning", "text": "Goldfish usually spawn in their main tank or pond, so the setup is about catching eggs. Hang several spawning mops or add fine leaved plants where the fish can push through. Keep filtration strong in the adults' tank, but prepare a separate hatching tank of 10 to 20 gallons with a sponge filter and water from the main tank.\n\nThe site's care range for goldfish is 60 to 74°F with harder, alkaline water, and spawning fits right in it. A natural pattern works best: cooler water in winter, then a steady warm up into spring."}, {"heading": "Conditioning and Sexing", "text": "In breeding season, males develop small white bumps called breeding tubercles on the gill covers and the leading rays of the pectoral fins. They also chase females. Females are rounder from above and may show a slightly protruding vent. Outside the season, sexing is unreliable, so don't rely on body shape alone.\n\nCondition fish well in late winter with a varied diet: quality pellets, gel food, frozen bloodworms and brine shrimp, and blanched vegetables. Healthy fish of a year or older, with full bodies, spawn most reliably."}, {"heading": "Spawning: What You'll See", "text": "As the water warms to about 68 to 72°F and the days get longer, males start following and nudging the female, often pushing at her belly and vent. Spawning usually starts early in the morning and can be frantic.\n\nThe female scatters eggs through the mops and plants while the males fertilize them. The eggs are sticky and cling wherever they land. Chasing can be rough on the female, so watch for damage and make sure she has room to rest. Spawning can repeat every week or two through spring."}, {"heading": "Eggs and Fungus Prevention", "text": "A large female can release several hundred to over a thousand eggs. Lift the mops into the hatching tank as soon as spawning stops, or remove the adults if you're using a separate breeding setup. Goldfish eat their own eggs eagerly.\n\nAt 68 to 72°F the eggs hatch in about 3 to 6 days; cooler water takes longer. Infertile eggs turn white and fuzzy. Add gentle aeration and pick out fungused eggs with tweezers or a pipette so the fungus doesn't spread to good ones."}, {"heading": "Raising the Fry", "text": "Newly hatched fry cling to the glass and mops, then swim freely about 2 to 3 days later.\n\n- First days of swimming: liquid or powdered fry food, infusoria or green water\n- From about day 3 to 5: newly hatched baby brine shrimp, several feeds a day\n- Weeks 3 to 6: baby brine shrimp plus crushed flake or fry powder\n\nGoldfish fry produce a lot of waste. Change 20 to 30 percent of the water every 1 to 2 days once they're eating well, matching temperature carefully. Keep them around 68 to 72°F."}, {"heading": "Growing Out and Culling", "text": "Fry reach about 1 inch in 2 to 3 months with heavy feeding and frequent water changes. Most start out dark bronze and change to gold, red or white over the following months; some never change.\n\nA spawn can be far larger than you can house. Thin the batch early and move fish into bigger tanks or a pond as they grow. Fancy varieties often produce many fry without the parents' traits, so keep the best and plan humane culling or rehoming for the rest. Never release goldfish into ponds or waterways."}, {"heading": "Common Mistakes", "text": "- Leaving eggs with the adults overnight\n- Keeping too many fry in too little water, which stunts growth\n- Skipping the cool winter period, then wondering why fish won't spawn\n- Letting fungus spread through a mop of eggs\n- Releasing extra fish outdoors instead of rehoming them"}]$g$::jsonb, $g$[{"q": "How long do goldfish eggs take to hatch?", "a": "About 3 to 6 days at 68 to 72°F. Cooler water slows hatching, while warmer water speeds it up."}, {"q": "How can I tell if my goldfish is male or female?", "a": "In breeding season, males show white breeding tubercles on their gill covers and front pectoral fin rays and chase the females. Females look rounder from above."}, {"q": "Do goldfish eat their eggs?", "a": "Yes. Move the eggs or remove the adults soon after spawning to save them."}, {"q": "Why are my baby goldfish black or brown?", "a": "Most goldfish fry start out dark bronze and change color over several months. Some keep their dark color for good."}]$g$::jsonb, $g$Open your log and photograph the breeding group with your challenge code card before spring warming starts, since goldfish can spawn with little warning. Plan grow out space early so you can document healthy fry through stage 5.$g$),
  ($g$pearl-danio$g$, $g$0530386f-938e-4977-9da2-677d19abb4f1$g$::uuid, $g$pearl-danio$g$, null, $g$How to Breed Pearl Danios: Easy Egg Scatterer Guide$g$, $g$Pearl danios scatter eggs at dawn and breed easily with the right setup. Learn to protect the eggs, hatch them in a day or two and raise the fry.$g$, $g$Pearl danios are easy and rewarding to breed: a conditioned group spawns readily, usually in the morning, scattering non sticky eggs that sink fast. Like all danios, the adults will eat any eggs they can reach, so a simple trap of marbles, mesh or dense moss is the key. The fry are tiny but grow quickly with small live foods and clean water.$g$, $g${"method": "Egg scatterer (non adhesive eggs, no parental care)", "sexing": "Males slimmer with brighter orange to red markings; females deeper bodied", "group": "1 female to 2 males, or a small group", "breeding_tank": "5 to 10 gallons, 4 to 6 inches of water, marbles, mesh or dense moss", "conditioning": "Live or frozen foods plus flake for 1 to 2 weeks", "trigger": "Fresh water at 75 to 78°F and morning light after a night in the breeding tank", "spawn": "Commonly 100 to 300 eggs", "eggs": "Hatch in about 1 to 2 days at 75 to 78°F", "fry": "Free swimming about 3 to 4 days after hatching; very small", "first_foods": "Infusoria or liquid fry food, then microworms and baby brine shrimp", "grow_out": "About 1 inch in 8 to 10 weeks", "parents": "Eat eggs; remove adults after spawning"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 5 to 10 gallon tank is enough. Fill it to only 4 to 6 inches so eggs reach safety fast. Cover the bottom with a layer of marbles, a plastic mesh raised slightly off the glass, or a thick mat of java moss. The eggs are not sticky and sink, so anything that hides them from the adults works.\n\nUse a gentle sponge filter and set the temperature at 75 to 78°F, the warmer end of the pearl danio's range. Clean, fresh water helps trigger spawning."}, {"heading": "Conditioning and Choosing a Group", "text": "Males are slimmer and show a stronger orange to red stripe on the rear half of the body, plus brighter fins. Females are deeper bodied and become noticeably rounder when full of eggs.\n\nCondition the group for 1 to 2 weeks on frozen or live bloodworms, brine shrimp, daphnia and a good flake. Separating the sexes during this time makes the reunion more effective. Move one plump female and two males into the breeding tank in the evening."}, {"heading": "Spawning: What You'll See", "text": "Spawning usually starts at first light the next morning. The males chase the female close to the bottom or through the moss, and eggs are released and fertilized in quick bursts. The eggs drop straight down into the marbles, mesh or moss.\n\nGive them a few hours. Once the female looks slimmer and the chasing stops, remove all the adults. If nothing happens the first morning, a cool partial water change in the evening can often trigger a spawn the next day."}, {"heading": "Eggs and Fungus Prevention", "text": "A good spawn is commonly 100 to 300 eggs. At 75 to 78°F they hatch in about 1 to 2 days. Infertile eggs turn white and may grow fungus.\n\nKeep the tank dim and the water clean. A few drops of methylene blue can help if fungus has been a problem before. If you used mesh, you can lift it out once the adults are gone. Newly hatched larvae hang on the glass and among the marbles while living off their yolk."}, {"heading": "Raising the Fry", "text": "The fry swim freely about 3 to 4 days after hatching. They are very small, so start with microscopic foods.\n\n- First 4 to 5 days of swimming: infusoria, green water or liquid fry food, small amounts several times a day\n- From about day 5: microworms and newly hatched baby brine shrimp\n- Weeks 3 to 6: baby brine shrimp and crushed flake\n\nChange 10 to 20 percent every 2 to 3 days with temperature matched water. Siphon the bottom carefully, as the fry are hard to see."}, {"heading": "Growing Out", "text": "Pearl danio fry grow quickly, reaching about 1 inch in 8 to 10 weeks with frequent feeding. Move them to a larger tank once they are eating flake so they have swimming room, since this is an active schooling species.\n\nThe pearly sheen and orange markings develop as they mature over the next few months. Keep them in groups; they become nervous and dull when kept in small numbers.\n\nYoung pearl danios are usually ready to spawn themselves within several months. Once you have a few batches behind you, keep notes on which females gave the biggest spawns, and raise the next generation from your strongest, best colored fish."}, {"heading": "Common Mistakes", "text": "- Water too deep, so eggs are eaten on the way down\n- Leaving the adults in for a whole day\n- Feeding baby brine shrimp to newly swimming fry\n- Strong filtration that sucks up fry\n- Uncovered tanks; danios of all sizes can jump"}]$g$::jsonb, $g$[{"q": "How long do pearl danio eggs take to hatch?", "a": "About 1 to 2 days at 75 to 78°F. The fry swim freely about 3 to 4 days after hatching."}, {"q": "Do pearl danios eat their eggs?", "a": "Yes. They give no parental care, so use marbles, mesh or moss and remove the adults after spawning."}, {"q": "How do you sex pearl danios?", "a": "Males are slimmer with a stronger orange to red stripe and brighter fins. Females are deeper bodied and rounder when full of eggs."}, {"q": "What time of day do pearl danios spawn?", "a": "Usually in the early morning, at or just after first light."}]$g$::jsonb, $g$Set up the breeding trio the evening before, open your log and photograph them with the challenge code card right away. A photo of eggs in the marbles or moss after the adults are out makes a clear stage 2 record.$g$),
  ($g$rosy-barb$g$, $g$9e23339a-ea31-4760-b398-7c70b797449a$g$::uuid, $g$rosy-barb$g$, null, $g$How to Breed Rosy Barbs: Spawning Setup and Raising Fry$g$, $g$Rosy barbs are easy egg scatterers whose males turn deep red to spawn. Learn the setup, how to save eggs from the adults and raise the fry to size.$g$, $g$Rosy barbs make a great introduction to breeding egg scatterers, as conditioned males blush a deep rose red and chase females through fine plants at dawn, leaving hundreds of sticky eggs behind. The adults eat eggs eagerly, so success comes from a dedicated spawning tank and moving the parents out promptly. The fry are hardy and easy to raise on small live foods.$g$, $g${"method": "Egg scatterer (adhesive eggs, no parental care)", "sexing": "Males turn deep rose red with dark fin edges; females are olive gold and rounder", "group": "1 female to 2 males", "breeding_tank": "15 to 20 gallons, fine plants or spawning mops, mesh or marbles on the bottom", "conditioning": "Live or frozen foods plus vegetable flake for 1 to 2 weeks", "trigger": "Fresh water around 74 to 77°F and morning light after an evening move", "spawn": "Commonly 100 to 300 eggs", "eggs": "Hatch in about 1 to 2 days at 74 to 77°F", "fry": "Free swimming about 3 to 4 days after hatching", "first_foods": "Infusoria or liquid fry food, then baby brine shrimp and microworms", "grow_out": "About 1 inch in 8 to 10 weeks", "parents": "Eat eggs readily; remove adults after spawning"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "Rosy barbs grow to around 4 inches, so use a 15 to 20 gallon spawning tank. Add bunches of fine leaved plants or several spawning mops, and protect the bottom with a mesh grid or a layer of marbles so eggs fall out of reach.\n\nRun a gentle sponge filter and keep the water at 74 to 77°F, the warm end of the site's range for this species. They aren't fussy about water chemistry; clean, slightly soft to medium water with a pH near neutral works well."}, {"heading": "Conditioning and Choosing a Pair", "text": "Sexing is easy in mature fish. Males take on a deep rose to red body color, especially in breeding condition, with dark edges on the dorsal and pelvic fins. Females stay olive gold, are slightly larger and get visibly round when full of eggs.\n\nCondition the sexes apart for 1 to 2 weeks with frozen or live bloodworms, brine shrimp and daphnia plus flake that includes vegetable matter. Move a plump female and two colorful males into the breeding tank in the evening."}, {"heading": "Spawning: What You'll See", "text": "Spawning usually starts at first light. The males flare their color and drive the female into the plants, pressing alongside her as eggs and milt are released. The sticky eggs cling to leaves and mops or fall into the mesh.\n\nThis continues for an hour or two. When the female looks thinner and the males lose interest, remove all the adults. If the group doesn't spawn in a day or two, a partial water change with slightly cooler water often sets them off."}, {"heading": "Eggs and Fungus Prevention", "text": "A good spawn is commonly 100 to 300 eggs. At 74 to 77°F they hatch in about 1 to 2 days. Fertile eggs stay clear, and infertile ones turn white and may grow fungus.\n\nKeep the tank dim and add a few drops of methylene blue if fungus is a regular problem. Pick out white eggs with a pipette when you can. After hatching, the larvae cling to plants and glass while using up their yolk sacs."}, {"heading": "Raising the Fry", "text": "The fry become free swimming about 3 to 4 days after hatching. Start feeding as soon as they swim in open water.\n\n- First 4 to 5 days: infusoria or liquid fry food, a few times a day\n- From about day 5: baby brine shrimp and microworms\n- Weeks 3 to 6: baby brine shrimp plus crushed flake\n\nChange 10 to 20 percent of the water every 2 to 3 days, matching temperature. Siphon uneaten food from the bottom so the water stays clean."}, {"heading": "Growing Out", "text": "Rosy barb fry are hardy and reach about 1 inch in 8 to 10 weeks with steady feeding. Move them into a larger tank when they are taking flake well, because crowding slows growth.\n\nYoung males begin to show red as they mature over the following months. Keep the youngsters in a group, since rosy barbs are schooling fish and can get nippy when kept in small numbers.\n\nRosy barbs usually reach breeding size within the first year. Long fin rosy barbs breed the same way, but their fry will not all have long fins, so expect a mix in each batch and keep your best fish as future breeders."}, {"heading": "Common Mistakes", "text": "- Leaving the parents with the eggs\n- No mesh or marbles, so eggs are eaten from the glass\n- Too small a spawning tank for 4 inch fish\n- Feeding baby brine shrimp before fry can take it\n- Letting fungus spread through clumps of infertile eggs"}]$g$::jsonb, $g$[{"q": "How do you tell male and female rosy barbs apart?", "a": "Males turn a deep rose red with dark edges on the fins. Females stay olive gold and are rounder in the belly."}, {"q": "How long do rosy barb eggs take to hatch?", "a": "About 1 to 2 days at 74 to 77°F. The fry swim freely a few days later."}, {"q": "Do rosy barbs eat their eggs?", "a": "Yes. Remove the adults after spawning or the eggs will quickly disappear."}, {"q": "How many eggs do rosy barbs lay?", "a": "A conditioned female commonly lays 100 to 300 eggs in a spawn."}]$g$::jsonb, $g$Photograph the trio in the breeding tank with your challenge code card when you open the log. Rosy barb males color up strongly, so a clear photo showing both sexes makes a good stage 1 record.$g$),
  ($g$rosy-red-minnow$g$, $g$78b819b7-a38b-4f04-aaa7-b70183cd3529$g$::uuid, $g$rosy-red-minnow$g$, null, $g$How to Breed Rosy Red Minnows: Tiles, Eggs and Guarding Males$g$, $g$Rosy red minnows lay eggs under tiles or pipes, guarded by the male. Learn how to set up spawning sites, hatch the eggs and raise the fry easily.$g$, $g$Rosy red minnows, the pink form of the fathead minnow, are easy to breed and fun to watch. Males claim a flat spot under a tile or pipe, defend it, and care for the eggs females stick to the ceiling. With a few good spawning sites and some warmth and long days, a group will breed over and over, giving you a steady supply of fry.$g$, $g${"method": "Egg depositor (eggs stuck under a surface, guarded by the male)", "sexing": "Breeding males have dark heads, bumps on the snout and a pad behind the head; females are plain", "group": "1 male to 2 or 3 females, or a group with one spawning site per male", "breeding_tank": "20 gallons, clay pots, split PVC pipes or slate tiles as spawning caves, sponge filter", "conditioning": "Frozen or live foods plus flake for 1 to 2 weeks", "trigger": "Longer days and water warming to about 70 to 77°F", "spawn": "Commonly 50 to a few hundred eggs per spawning", "eggs": "Hatch in about 4 to 6 days at around 75 to 77°F", "fry": "Free swimming soon after hatching; small", "first_foods": "Infusoria or liquid fry food, then baby brine shrimp and microworms", "grow_out": "About 1 inch in 6 to 10 weeks", "parents": "Male guards and cleans the eggs; adults may eat fry, so move eggs or fry out"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 20 gallon tank suits a small group. The important part is the spawning sites: give each male a flat ceiling such as a slate tile set on stones, a clay pot on its side, or a piece of PVC pipe cut in half lengthwise and placed curved side up. Males clean the underside and the eggs are laid there.\n\nUse a sponge filter and plants for cover. Rosy reds handle a wide range of temperatures, and the site lists 50 to 77°F. Spawning goes best when water warms to about 70 to 77°F with 14 or more hours of light."}, {"heading": "Conditioning and Choosing a Group", "text": "Out of season, sexes can look alike. In breeding condition, males are easy to spot: they get a dark head, white bumps called tubercles on the snout and a spongy pad on the back behind the head, which they use to clean the eggs. Females stay plain and get rounder.\n\nCondition with frozen bloodworms, brine shrimp, daphnia and a good flake for 1 to 2 weeks. Keep one male for every 2 or 3 females, and provide more spawning sites than males to reduce fighting."}, {"heading": "Spawning: What You'll See", "text": "The male picks a site, cleans its underside and chases off rivals. He then leads a ripe female under it. The pair turns upside down or on their sides and she presses eggs onto the ceiling one patch at a time while he fertilizes them.\n\nAfterwards the male drives her away and stays to guard. He rubs the eggs with his back pad and fans them. A single male may collect eggs from several females, so the patch can keep growing over a few days."}, {"heading": "Eggs and Their Care", "text": "Each spawning commonly produces 50 to a few hundred eggs. At around 75 to 77°F they hatch in about 4 to 6 days, more slowly when cooler.\n\nYou can leave the eggs with the male, who keeps them clean, or lift the tile or pipe into a separate tank with gentle aeration and a few drops of methylene blue. Taking the eggs out protects the fry from the adults. Eggs that turn white and fuzzy were infertile; remove them so fungus doesn't spread."}, {"heading": "Raising the Fry", "text": "The fry are free swimming soon after hatching and are fairly small.\n\n- First week: infusoria, green water or liquid fry food several times a day\n- Week 2: baby brine shrimp and microworms\n- Weeks 3 to 6: baby brine shrimp and crushed flake\n\nChange 10 to 20 percent every 2 to 3 days with matched water. Keep the fry tank at about 72 to 77°F for good growth. Avoid strong filter intakes; a sponge filter is safest."}, {"heading": "Growing Out", "text": "Fry grow steadily and reach about 1 inch in 6 to 10 weeks with regular feeding. Move them to larger quarters as they grow, as crowding slows them down.\n\nRosy reds mature quickly in warm, well fed conditions and keep spawning through long days. A healthy group can produce a lot of young, so plan where they will go. Never release them into ponds or streams, even though fathead minnows are native to parts of North America."}, {"heading": "Common Mistakes", "text": "- No flat ceilings, so males have nowhere to spawn\n- One site for several males, which leads to constant fighting\n- Leaving free swimming fry with hungry adults\n- Short day length, which keeps fish out of breeding mode\n- Treating a darkened, bumpy male as sick; that is breeding dress"}]$g$::jsonb, $g$[{"q": "Where do rosy red minnows lay their eggs?", "a": "On the underside of a flat surface such as a tile, a clay pot or a split pipe. The male cleans the spot and guards the eggs."}, {"q": "How long do rosy red minnow eggs take to hatch?", "a": "About 4 to 6 days at around 75 to 77°F, longer in cooler water."}, {"q": "Why does my male rosy red minnow have bumps on his head?", "a": "Those are breeding tubercles, along with a pad on his back. They are normal signs of a male in breeding condition."}, {"q": "Do rosy red minnows eat their babies?", "a": "Adults may eat fry, so move the eggs or the young fry into their own tank for the best survival."}]$g$::jsonb, $g$Show the group and their tile or pipe sites with your challenge code card in your stage 1 photo. Flip the tile gently for a quick stage 2 photo of the egg patch, then put it straight back.$g$),
  ($g$convict-cichlid$g$, $g$aa74080a-b99f-463d-9d0d-2fb75ec3466f$g$::uuid, $g$convict-cichlid$g$, null, $g$How to Breed Convict Cichlids: Pairs, Caves and Raising Fry$g$, $g$Convict cichlids pair up, spawn in caves and guard their fry fiercely. Learn setup, sexing, egg care and how to manage the many fry they produce.$g$, $g$Convict cichlids are famous for breeding almost anywhere, which makes them a perfect first cichlid. A pair cleans a cave, lays a patch of eggs and then guards the cloud of fry with real dedication, doing most of the work for you. Your main jobs are giving the pair their own space, keeping other fish safe and planning for the large numbers of fry they keep producing.$g$, $g${"method": "Cave spawner (substrate spawner, both parents guard)", "sexing": "Females have orange or gold scales on the belly; males are larger with a steeper forehead", "group": "One pair", "breeding_tank": "About 40 gallons, caves or flowerpots, sand or fine gravel, sponge filter", "conditioning": "Pellets plus frozen or live foods for 1 to 2 weeks", "trigger": "A bonded pair with a cave and water around 76 to 80°F", "spawn": "Commonly 100 to 300 eggs", "eggs": "Hatch in about 3 days at 78 to 80°F", "fry": "Free swimming about 4 to 6 days after hatching, guarded by both parents", "first_foods": "Baby brine shrimp and crushed flake or fry powder", "grow_out": "About 1 inch in 6 to 8 weeks", "parents": "Excellent parents; fry can stay with them for several weeks"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "Give a pair its own tank. The site lists 40 gallons as the minimum for this species, and that is a good size for a breeding pair with room to raise fry. Add a few caves such as flowerpots on their sides, rock piles or coconut shells, over sand or fine gravel they can dig.\n\nKeep the water at 76 to 80°F with a pH between 6.5 and 8. A sponge filter is ideal because it won't suck in fry. Expect the pair to rearrange the substrate, so skip delicate plants."}, {"heading": "Conditioning and Choosing a Pair", "text": "Females are smaller and show orange or gold scales on the lower belly and often on the dorsal fin. Males are larger, with a steeper forehead and longer, pointed dorsal and anal fins, and lack the orange.\n\nThe best pairs form naturally: raise a group of young fish together and let two choose each other. Feed quality cichlid pellets plus frozen bloodworms, brine shrimp and mysis for 1 to 2 weeks. A bonded pair swims together, digs together and chases other fish away."}, {"heading": "Spawning: What You'll See", "text": "The pair cleans a flat surface inside a cave and digs out pits nearby. Both fish show darker bars and become protective. The female passes over the cleaned spot laying rows of eggs, and the male follows to fertilize them.\n\nAfterwards the female usually stays close to the eggs, fanning them, while the male patrols the area. If you see the pair hiding and chasing everything that comes near the cave, look carefully inside: you'll often find a patch of amber eggs."}, {"heading": "Eggs and Wrigglers", "text": "A spawn is commonly 100 to 300 eggs. At 78 to 80°F they hatch in about 3 days. The parents eat infertile or fungused eggs, so leave the cleaning to them.\n\nNewly hatched young, often called wrigglers, can't swim yet. The parents move them to pits in the substrate and guard them. Don't move rocks or do major cleaning during this stage. First time pairs sometimes eat a spawn; most get it right after one or two attempts."}, {"heading": "Raising the Fry", "text": "The fry swim freely about 4 to 6 days after hatching and move around the tank in a tight cloud with the parents. They are big enough to eat food straight away.\n\n- Week 1: newly hatched baby brine shrimp 2 to 3 times a day, plus fry powder\n- Weeks 2 to 4: baby brine shrimp and crushed flake or small pellets\n- From week 4: crushed pellets and flake\n\nChange 20 percent of the water weekly, or more often as the fry grow, matching temperature carefully. Keep a lid on and the tank calm."}, {"heading": "Growing Out", "text": "Fry reach about 1 inch in 6 to 8 weeks. They can stay with the parents for several weeks, but once the pair starts preparing for another spawn they may chase the older fry. Move the young into their own tank at that point.\n\nConvicts can breed every few weeks, so a single pair can produce far more fish than local stores want. Plan homes for the young before they're grown, and give the pair breaks if you can't place the offspring."}, {"heading": "Common Mistakes", "text": "- Keeping a breeding pair in a community tank, where they attack tankmates\n- Removing the parents too early; they are the fry's best protection\n- Moving rocks and caves while eggs or wrigglers are present\n- Breeding nonstop without homes lined up for the fry\n- Mixing with other Central American cichlids, which can hybridize"}]$g$::jsonb, $g$[{"q": "How can you tell a male convict cichlid from a female?", "a": "Females have orange or gold scales on the belly and are smaller. Males are larger with a steeper forehead and longer, pointed fins."}, {"q": "How long do convict cichlid eggs take to hatch?", "a": "About 3 days at 78 to 80°F. The fry then become free swimming about 4 to 6 days later."}, {"q": "Do convict cichlids eat their fry?", "a": "Most pairs guard their fry well for several weeks. Inexperienced pairs sometimes eat a first spawn, and parents may chase older fry once they're ready to breed again."}, {"q": "How often do convict cichlids breed?", "a": "A healthy pair can spawn every few weeks once the previous batch of fry is moved out."}]$g$::jsonb, $g$Convicts can spawn within days of being set up, so open the log and take your stage 1 photo with the challenge code card as soon as the pair is in the tank. A clear shot of the fry cloud with a parent nearby makes an easy stage 3 photo.$g$),
  ($g$white-cloud-mountain-minnow$g$, $g$5dbd563b-0033-4bc8-8b12-c02fbec96c35$g$::uuid, $g$white-cloud-mountain-minnow$g$, null, $g$How to Breed White Cloud Mountain Minnows: Easy Fry Guide$g$, $g$White Cloud Mountain Minnows breed readily in cool, planted tanks and often spare their fry. Learn the setup, sexing and how to raise healthy young.$g$, $g$White Cloud Mountain Minnows are one of the gentlest fish to breed: they spawn readily in cool water among fine plants, and unlike many egg scatterers, adults often leave fry alone in a well planted tank. You can raise a few in the main tank or set up a simple spawning tank for bigger numbers. Either way, it is a great first breeding project.$g$, $g${"method": "Egg scatterer (slightly adhesive eggs, no parental care)", "sexing": "Males slimmer with brighter red and white edged fins; females rounder and paler", "group": "A small group, or 2 males to 1 or 2 females", "breeding_tank": "10 gallons, java moss or spawning mops, sponge filter, no heater needed in a warm room", "conditioning": "Live or frozen foods plus flake for 1 to 2 weeks", "trigger": "Cool to moderate water around 68 to 72°F with fine plants", "spawn": "Small batches daily over several days, adding up to dozens or more", "eggs": "Hatch in about 2 days (roughly 36 to 60 hours) at 68 to 72°F", "fry": "Free swimming a few days after hatching; tiny", "first_foods": "Infusoria or liquid fry food, then microworms and baby brine shrimp", "grow_out": "About 3/4 inch in 8 to 10 weeks", "parents": "Adults eat some eggs but often ignore fry; dense moss boosts survival"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 gallon tank is plenty. Fill it with a thick mat of java moss or a few spawning mops, and run a gentle sponge filter. White Clouds are cool water fish, and the site's range is 60 to 72°F, so most homes don't need a heater. Spawning goes well at 68 to 72°F.\n\nYou can also breed them in a mature, heavily planted species tank. Many keepers find fry simply appearing at the surface among floating plants, because this species is less of an egg eater than most."}, {"heading": "Conditioning and Choosing a Group", "text": "Males are slimmer and more colorful, with red tails and dorsal and anal fins edged in white or yellow. They often spread their fins in displays to each other. Females are rounder through the belly and a little paler.\n\nCondition with frozen or live brine shrimp, daphnia and bloodworms plus a fine flake for 1 to 2 weeks. A small group, or a ratio of two males to one or two females, works well. Move them into the spawning tank once the females look full."}, {"heading": "Spawning: What You'll See", "text": "Males display to the females with flared fins, then swim alongside them into the moss or mops. Eggs are scattered a few at a time and stick lightly to the plants.\n\nWhite Clouds tend to spawn in small batches, often every day for several days, rather than all at once. After about a week you can move the adults out, or leave them in if the moss is thick. Look closely at the plants for tiny clear eggs."}, {"heading": "Eggs and Fungus Prevention", "text": "The eggs are small and clear. At 68 to 72°F they hatch in about 2 days, roughly 36 to 60 hours depending on temperature. Infertile eggs turn white and can grow fungus.\n\nKeep the tank dim and the water clean. With many eggs in a small tank, a few drops of methylene blue can help. Because spawning happens in batches, you'll see eggs and fry of slightly different ages at the same time, which is normal."}, {"heading": "Raising the Fry", "text": "The fry swim freely a few days after hatching and tend to hang near the surface. They are tiny and easy to overlook.\n\n- First week: infusoria, green water or liquid fry food, a little several times a day\n- Week 2: microworms and newly hatched baby brine shrimp\n- Weeks 3 to 8: baby brine shrimp and finely crushed flake\n\nChange 10 to 20 percent every 2 to 3 days, matching temperature. The fry handle the same cool temperatures as the adults, but growth is quicker around 70 to 72°F."}, {"heading": "Growing Out", "text": "With steady feeding the fry reach about 3/4 inch in 8 to 10 weeks. The famous neon stripe of juveniles is bright at this stage, and fins color up as they mature.\n\nBecause adults are fairly gentle, you can grow the fry in the same tank once they are too big to be eaten. Keep them in groups; they color and behave best in schools.\n\nYoung White Clouds can begin spawning within a few months. Gold and long fin forms breed the same way. Since the species breeds so easily, consider adding a few fish from another breeder now and then so your line isn't all siblings."}, {"heading": "Common Mistakes", "text": "- Keeping them too warm for long periods, which shortens their lives\n- Sparse plants, leaving fry with nowhere to hide\n- Feeding baby brine shrimp to newly swimming fry\n- Strong filters that pull in tiny fry\n- Expecting one big spawn instead of small daily batches"}]$g$::jsonb, $g$[{"q": "Do White Cloud Mountain Minnows eat their fry?", "a": "They may eat some eggs, but adults often leave fry alone, especially in a tank with lots of moss and floating plants."}, {"q": "How long do White Cloud eggs take to hatch?", "a": "About 2 days at 68 to 72°F, roughly 36 to 60 hours depending on temperature."}, {"q": "How can you tell male and female White Clouds apart?", "a": "Males are slimmer and brighter with red and white edged fins. Females are rounder and paler."}, {"q": "Do White Cloud Mountain Minnows need a heater to breed?", "a": "Usually not. They breed at room temperature, with 68 to 72°F working well."}]$g$::jsonb, $g$Open your log and take your stage 1 photo of the group in the breeding tank with the challenge code card right away, since they can start spawning within days. Tiny fry are hard to photograph, so a close shot against a dark background helps for stage 3.$g$),
  ($g$zebra-danio$g$, $g$f35cffee-58de-43e2-b5a3-a25f6ce37f93$g$::uuid, $g$zebra-danio$g$, null, $g$How to Breed Zebra Danios: A Simple Step by Step Guide$g$, $g$Zebra danios are among the easiest egg scatterers to breed. Learn the shallow marble setup, morning spawns, hatch times and how to raise the fry.$g$, $g$Zebra danios are a classic first breeding fish, and in the right setup a well fed group can give you a hundred or more eggs in a single morning spawn. The adults will eat every egg they find, so the trick is a shallow tank with marbles or mesh that lets eggs sink out of reach. After that, the fry are easy to raise.$g$, $g${"method": "Egg scatterer (non adhesive eggs, no parental care)", "sexing": "Males slimmer with a gold tint between stripes; females larger, rounder and more silvery", "group": "1 female to 2 males, or a small group", "breeding_tank": "5 to 10 gallons, 4 to 6 inches of water, marbles or mesh on the bottom", "conditioning": "Frozen or live foods plus flake for 1 to 2 weeks, sexes apart", "trigger": "Morning light after an evening move into fresh water around 75 to 77°F", "spawn": "Commonly 100 to 300 eggs", "eggs": "Hatch in about 2 to 3 days at 75 to 77°F", "fry": "Free swimming about 5 to 6 days after spawning", "first_foods": "Infusoria or liquid fry food, then microworms and baby brine shrimp", "grow_out": "About 1 inch in 8 to 10 weeks", "parents": "Eat eggs; remove adults once spawning stops"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "Use a 5 to 10 gallon tank with only 4 to 6 inches of water, so eggs sink to safety quickly. Cover the bottom with marbles, a raised plastic mesh, or a thick layer of java moss. Zebra danio eggs aren't sticky and fall straight down.\n\nAdd a gentle sponge filter and keep the water at 75 to 77°F, the warm end of the site's range. A lid is essential; danios jump, especially during spawning."}, {"heading": "Conditioning and Choosing a Group", "text": "Males are slimmer and torpedo shaped, with a gold or yellowish tint between the blue stripes. Females are larger and rounder, with a more silvery white tint, and look clearly plump when full of eggs.\n\nCondition males and females in separate tanks for 1 to 2 weeks on frozen or live bloodworms, brine shrimp and daphnia plus flake. Move one plump female and two males into the breeding tank in the evening."}, {"heading": "Spawning: What You'll See", "text": "The fish usually spawn when the lights come on the next morning. Males chase the female in fast loops close to the bottom, and eggs are released and fertilized in quick bursts. You'll see them drop like tiny clear beads into the marbles.\n\nSpawning often lasts an hour or two. Remove the adults once the female looks slim. If nothing happens, give them another morning; a partial water change in the evening often helps."}, {"heading": "Eggs and Fungus Prevention", "text": "A spawn is commonly 100 to 300 eggs. At 75 to 77°F they hatch in about 2 to 3 days. Fertile eggs are clear, while infertile ones turn cloudy white within a day.\n\nKeep the tank dim. Remove white eggs where you can, or add a few drops of methylene blue to help control fungus. The newly hatched larvae lie on the bottom and stick to the glass while they use their yolk."}, {"heading": "Raising the Fry", "text": "The fry swim freely about 5 to 6 days after spawning, when they fill their swim bladders and move up into open water. Start feeding then.\n\n- First 4 to 5 days of swimming: infusoria, green water or liquid fry food, small amounts several times a day\n- From about day 5: microworms and newly hatched baby brine shrimp\n- Weeks 3 to 6: baby brine shrimp plus crushed flake\n\nChange 10 to 20 percent every 2 to 3 days with temperature matched water. Siphon the bottom gently."}, {"heading": "Growing Out", "text": "Zebra danio fry grow fast with regular feeding and reach about 1 inch in 8 to 10 weeks. Stripes appear early, and the fish start to look like small adults within a month or two.\n\nMove them to a larger tank as they grow so they have room to school and swim. Long fin and color forms of zebra danio breed the same way, though fry of fancy forms may not all match the parents.\n\nZebra danios usually mature within a few months and can be spawned again every week or two once conditioned. Because one good morning gives so many eggs, start with one batch at a time. It's better to raise 100 healthy fry than to crowd 300 into a tank too small for them, where growth stalls and losses climb."}, {"heading": "Common Mistakes", "text": "- Water too deep, so the adults catch the eggs as they fall\n- Leaving the adults in after spawning\n- Feeding baby brine shrimp before the fry can eat it\n- No lid; danios are strong jumpers\n- Overfeeding powdered food in a small, bare tank"}]$g$::jsonb, $g$[{"q": "How long do zebra danio eggs take to hatch?", "a": "About 2 to 3 days at 75 to 77°F. The fry start swimming freely about 5 to 6 days after spawning."}, {"q": "How can you tell male and female zebra danios apart?", "a": "Males are slimmer with a gold tint between the stripes. Females are larger, rounder and more silvery."}, {"q": "Do zebra danios eat their eggs?", "a": "Yes. Use marbles or mesh in shallow water and remove the adults after spawning."}, {"q": "When do zebra danios spawn?", "a": "Usually in the early morning, right after the lights come on."}]$g$::jsonb, $g$Open the log and photograph the trio with your challenge code card the evening you set up the tank. Eggs among the marbles show up best with a flashlight from the side for your stage 2 photo.$g$),
  ($g$cherry-shrimp$g$, $g$3934ce6c-4e5c-4eda-bf7b-1bd2c4fa5f82$g$::uuid, $g$cherry-shrimp$g$, null, $g$Breeding Cherry Shrimp: A Complete Colony Guide$g$, $g$Cherry shrimp breed easily in a stable, mature tank. Learn sexing, berried females, water needs and how to grow a thriving colony from a small group.$g$, $g$Cherry shrimp are one of the easiest animals in the hobby to breed: give a small group a stable, mature tank with no fish to hunt the babies, and you'll soon see females carrying eggs under their tails. The young hatch as tiny, fully formed shrimp, so there are no larval stages to manage. Success is mostly about patience and steady water.$g$, $g${"method": "Egg carrier (female carries eggs under her tail; young hatch as tiny shrimp)", "sexing": "Females larger and more colorful, often with a yellow saddle behind the head; males smaller, paler", "group": "A colony of 10 or more", "breeding_tank": "5 to 10 gallons or more, mature and planted, sponge filter, no fish", "conditioning": "Biofilm and algae plus small amounts of shrimp food, blanched vegetables and leaves", "trigger": "Stable, mature water around 72 to 78°F; mating often follows a female's molt", "spawn": "Commonly 20 to 30 eggs, sometimes up to around 50", "eggs": "Carried about 3 to 4 weeks at 72 to 78°F; slower when cooler", "fry": "Hatch as tiny shrimp about 1 to 2 mm long, able to graze straight away", "first_foods": "Biofilm, algae, moss and powdered shrimp or fry food", "grow_out": "Breeding size in about 2 to 4 months, faster in warmer water", "parents": "Adults don't harm babies; fish in the tank will eat them"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "Cherry shrimp breed best in a dedicated tank of 5 to 10 gallons or larger that has been running for at least a month, so there is plenty of biofilm on surfaces. Add java moss or other fine plants, some leaf litter and a few rocks or wood. Moss gives babies cover and constant grazing.\n\nUse a sponge filter, or cover any filter intake with a sponge, so babies aren't sucked in. Keep water within the site's ranges: 65 to 80°F, pH 6.5 to 8 and GH 4 to 14. Breeding is steady around 72 to 78°F. Never use medications or plant products that contain copper."}, {"heading": "Starting a Colony and Sexing", "text": "Start with at least 10 shrimp to be sure you have both sexes. Adult females are larger, with deeper color and a curved underside that forms a pouch for eggs. You can often see a yellow or greenish saddle behind the head in a female, which is developing eggs. Males are smaller, slimmer and paler.\n\nFeed lightly: shrimp graze most of the day. Offer a pinch of shrimp food, blanched zucchini or spinach and dried leaves a few times a week, and remove what isn't eaten within a few hours."}, {"heading": "Mating and Berried Females", "text": "Mating usually follows a female's molt. Right after she sheds, she releases a scent and you may see males swimming frantically around the tank looking for her. This frenzy is normal and short lived.\n\nWithin a day or so, she moves eggs into the swimmerets under her tail and becomes \"berried.\" She fans them constantly to keep them oxygenated and clean. The eggs start yellow or orange and darken as they develop, and near the end you can sometimes see tiny eyes."}, {"heading": "Carrying the Eggs", "text": "A berried female commonly carries 20 to 30 eggs, sometimes up to around 50 in a large female. They take about 3 to 4 weeks to hatch at 72 to 78°F, longer in cooler water.\n\nAvoid big changes while she's carrying. Stress, sudden temperature swings or large water changes can make a female drop her eggs. Young females sometimes lose their first clutch; that usually improves with time. Leave her in the main tank; moving her is usually more stressful than staying with the colony."}, {"heading": "Raising the Babies", "text": "Babies hatch as miniature shrimp about 1 to 2 mm long and immediately start grazing. There is no larval stage, so you don't need special live foods.\n\n- First weeks: biofilm, algae and the surfaces of moss and leaves\n- Add a little powdered shrimp food or fry powder a few times a week\n- Keep water changes small, about 10 to 20 percent weekly, dripped in slowly with matched temperature\n\nThe babies hide in moss for the first couple of weeks, so you may not see many at first."}, {"heading": "Growing the Colony", "text": "Young shrimp reach breeding size in about 2 to 4 months, and a healthy colony grows quickly after the first few generations. To keep color strong, remove pale or wild colored shrimp and keep the reddest ones as breeders.\n\nDon't mix different color forms of Neocaridina in the same tank if you want to keep a line pure, because they interbreed and offspring tend to revert to brown or clear. Mixed colonies are fine as pets but shouldn't be sold as a specific color."}, {"heading": "Common Mistakes", "text": "- Keeping shrimp with fish, which eat the babies\n- Large water changes that cause molting problems or egg dropping\n- Copper in medications, fertilizers or old plumbing\n- Overfeeding, which fouls the water\n- Starting a colony in a brand new tank with no biofilm"}]$g$::jsonb, $g$[{"q": "How long are cherry shrimp pregnant?", "a": "A berried female carries her eggs for about 3 to 4 weeks at 72 to 78°F. Cooler water stretches that out."}, {"q": "Why did my cherry shrimp drop her eggs?", "a": "Usually stress, such as a sudden water change, temperature swing or poor water quality. Young females sometimes lose their first clutch."}, {"q": "Do cherry shrimp eat their babies?", "a": "No. Adult shrimp leave the young alone, but almost any fish will eat them."}, {"q": "How can you tell a male cherry shrimp from a female?", "a": "Females are larger and more colorful, often with a yellow saddle behind the head. Males are smaller and paler."}]$g$::jsonb, $g$Photograph the colony with your challenge code card when you open the log, and for stage 2 a clear shot of a berried female works well. Small shrimp are easiest to photograph on a dark leaf or moss with the camera close.$g$),
  ($g$mystery-snail$g$, $g$6c52387f-d772-4166-b54f-2705532a7107$g$::uuid, $g$mystery-snail$g$, null, $g$How to Breed Mystery Snails: Egg Clutches and Hatchlings$g$, $g$Mystery snails lay pink egg clutches above the waterline. Learn how to keep the clutch moist, hatch it in a few weeks and raise the tiny snails.$g$, $g$Mystery snails are fun to breed because you can watch the whole process, as females climb out of the water at night and lay a pink clutch that slowly darkens until tiny snails hatch and drop in. The main things to get right are humidity, a tight lid and enough calcium. Unlike many snails they have separate sexes, so you need both a male and a female.$g$, $g${"method": "Egg layer (clutch laid above the waterline)", "sexing": "Separate sexes, hard to sex; with practice a male's sheath can be seen inside the shell opening", "group": "A group of 4 to 6 to be sure of both sexes", "breeding_tank": "10 gallons or more, water lowered 2 to 4 inches, tight lid, sponge filter", "conditioning": "Algae wafers, sinking pellets, blanched vegetables and a calcium source", "trigger": "A gap above the waterline, warm water and good feeding", "spawn": "Varies widely; keepers report roughly 50 to a few hundred eggs per clutch", "eggs": "Hatch in about 2 to 4 weeks at 72 to 80°F if kept humid", "fry": "Hatchlings are tiny, fully formed snails that drop into the water", "first_foods": "Biofilm, algae, crushed algae wafers and blanched vegetables", "grow_out": "About 1/2 inch in 1 to 2 months; adult size in several months", "parents": "No care for eggs; adults don't harm hatchlings, but fish may eat them"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 gallon or larger tank works well. The key feature is space above the water: lower the water level 2 to 4 inches and fit a tight lid. Females crawl out to lay their eggs on the glass, the lid or the rim, and the clutch needs warm, humid air to develop.\n\nKeep water within the site's ranges of 68 to 82°F, pH 7 to 8.5 and GH 8 to 20. Hard, alkaline water matters for snails because they build their shells from calcium. Use a sponge filter or a covered intake so hatchlings aren't pulled in."}, {"heading": "Conditioning and Choosing Breeders", "text": "Mystery snails have separate sexes, but you can't reliably tell them apart by shell color or size. Some keepers check by gently holding a snail upside down until it extends from its shell: a male shows a sheath under the mantle on the right side. Since that takes practice, most breeders keep 4 to 6 snails and let nature sort it out.\n\nFeed well with algae wafers, sinking pellets and blanched zucchini or spinach. Add a calcium source such as cuttlebone or a mineral supplement for strong shells."}, {"heading": "Mating and Egg Laying", "text": "Mating looks like one snail riding on top of another's shell, often for hours. Females can store sperm and may lay several clutches from one mating.\n\nEgg laying usually happens at night. The female climbs above the waterline and lays a clutch of soft eggs, which hardens into a light pink cluster within a few hours. Clutch size varies widely, from roughly 50 to a few hundred eggs. Don't move it while it's still soft."}, {"heading": "Caring for the Egg Clutch", "text": "At 72 to 80°F the clutch usually hatches in about 2 to 4 weeks. It gets darker and duller as the babies develop, and you may see tiny shapes inside near the end.\n\nThe clutch must stay humid but out of the water. If it dries out the eggs die, and if it is submerged they drown. A tight lid usually keeps humidity right. If the clutch looks dry, gently mist it, or place a damp paper towel nearby. Some keepers lift a hardened clutch into a small container over water; handle it gently if you do."}, {"heading": "Raising the Hatchlings", "text": "Hatchlings chew out of the clutch and drop into the water. They are tiny, fully formed snails and start grazing at once.\n\n- First weeks: biofilm and algae, plus crushed algae wafers and fine sinking food\n- Add blanched vegetables once they are a few millimeters across\n- Keep calcium available and water changes small and regular, about 10 to 20 percent weekly\n\nFish will eat newborn snails, so raise them in a fish free tank or a breeder box."}, {"heading": "Growing Out", "text": "With plenty of food, hatchlings grow quickly and reach around 1/2 inch in 1 to 2 months, with adult size of about 2 inches in several months. Shells should look smooth and solid; thin or pitted shells point to low calcium or soft water.\n\nOne clutch can give you more snails than you can house. If you don't want more, simply remove clutches before they hatch. Never release snails or put unwanted clutches anywhere they could reach natural waterways; apple snails can become serious pests outdoors."}, {"heading": "Common Mistakes", "text": "- Filling the tank to the brim, leaving no place to lay\n- Letting the clutch dry out or fall into the water\n- Soft, acidic water that erodes shells\n- Raising hatchlings with fish that eat them\n- Hatching more clutches than you can house"}]$g$::jsonb, $g$[{"q": "How long do mystery snail eggs take to hatch?", "a": "Usually about 2 to 4 weeks at 72 to 80°F, as long as the clutch stays humid and out of the water."}, {"q": "Do you need a male and female mystery snail to breed?", "a": "Yes. Mystery snails have separate sexes, and a female can store sperm and lay several clutches after one mating."}, {"q": "Why is my mystery snail clutch turning dark?", "a": "A clutch naturally darkens as the babies develop. A clutch that shrivels and gets moldy has usually dried out or failed."}, {"q": "How do I stop mystery snails from breeding?", "a": "Remove the clutches above the waterline before they hatch. Never dispose of snails or eggs where they could reach outdoor waters."}]$g$::jsonb, $g$For stage 1, photograph your snail group in the tank with your challenge code card and the lowered water line visible. A dated photo of the pink clutch above the waterline is clear stage 2 evidence.$g$),
  ($g$american-flagfish$g$, $g$38dd6fe7-b481-4d6d-80ac-93cf55f3be44$g$::uuid, $g$american-flagfish$g$, null, $g$How to Breed American Flagfish: Guarding Males and Fry Care$g$, $g$American flagfish are easy killifish whose males guard the eggs. Learn how to set up a planted tank, sex your fish and raise the algae grazing fry.$g$, $g$American flagfish are a hardy North American killifish that breeds readily in a planted tank. Unusually for a killifish, the male guards the eggs, fanning them and chasing off intruders, while the female lays just a few eggs at a time over several days. With mossy cover and some algae for the fry to graze on, this is a very approachable fish to breed and a fun one to watch.$g$, $g${"method": "Egg layer (non annual killifish; male guards eggs)", "sexing": "Males colorful with red lines; females plainer with a dark spot on the rear of the dorsal fin", "group": "One pair, or 1 male to 2 females", "breeding_tank": "15 to 20 gallons, java moss or fine plants, some algae, sponge filter", "conditioning": "Frozen or live foods plus vegetable flake or algae for 1 to 2 weeks", "trigger": "Warm, clean water around 72 to 78°F with longer days and fine plants", "spawn": "A few eggs a day over several days, totaling dozens", "eggs": "Hatch in about 5 to 10 days depending on temperature", "fry": "Small fry that graze algae and microorganisms", "first_foods": "Infusoria, green water and algae, then baby brine shrimp", "grow_out": "About 1 inch in 8 to 10 weeks", "parents": "Male guards eggs; remove the female, and the male once fry are swimming"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 15 to 20 gallon tank lets the male claim a territory while giving the female room to escape. Add a mat of java moss or bunches of fine leaved plants on or near the bottom. The male may also guard a shallow spot he clears in the substrate. Leave some algae on the glass and decorations; flagfish graze it, and it's valuable food for fry.\n\nRun a gentle sponge filter and keep the water at 72 to 78°F, within the site's range of 66 to 82°F with pH 6.5 to 8."}, {"heading": "Conditioning and Choosing a Pair", "text": "Males are more colorful, with red lines along the body that give the flag pattern and brighter fins. Females are plainer, and usually show a dark spot on the rear of the dorsal fin and often a dark blotch on the side.\n\nCondition with frozen or live bloodworms, brine shrimp and daphnia, plus a flake with plenty of vegetable matter or spirulina. They need greens in their diet. Use one male per tank; males fight each other when breeding."}, {"heading": "Spawning: What You'll See", "text": "The male picks a spot in the moss or a shallow pit and displays to the female with spread fins. When she joins him, the pair presses together and a few eggs are laid and fertilized.\n\nThis happens repeatedly over several days, with the female laying just a few eggs at a time. The male then guards the eggs, fanning them and driving the female and any other fish away. Once he is guarding, remove the female to protect her from his aggression."}, {"heading": "Eggs and the Guarding Male", "text": "The eggs are small and stick to the plants. They hatch in about 5 to 10 days depending on temperature, faster in warmer water. Because they are laid over several days, they hatch over several days too.\n\nThe male is a good guardian and usually keeps fungus down by fanning and removing bad eggs. If you prefer, you can move the moss with eggs to a separate container with gentle aeration and a few drops of methylene blue."}, {"heading": "Raising the Fry", "text": "Flagfish fry are small but active. Remove the male once most fry are swimming, as his care ends there.\n\n- First week: infusoria, green water and algae from the tank\n- Week 2: baby brine shrimp and microworms\n- Weeks 3 to 6: baby brine shrimp plus crushed vegetable flake\n\nChange 10 to 20 percent of the water every 3 to 4 days with matched temperature. A tank with algae growing on the surfaces gives fry a constant snack between feedings."}, {"heading": "Growing Out", "text": "Fry reach about 1 inch in 8 to 10 weeks with regular feeding. Young males begin showing red lines as they mature, and the female's dorsal spot becomes clear.\n\nKeep vegetable foods in the diet as they grow. Flagfish are native to Florida, so if you collect your own or get wild stock, check your local rules, and never release captive bred fish.\n\nAdults keep breeding through warm months, so a pair can give you several batches in a season. Raise one batch at a time, though, so younger fry aren't outcompeted by older siblings sharing the tank. Sort by size every few weeks if you do mix ages."}, {"heading": "Common Mistakes", "text": "- Leaving the female with a guarding male\n- Two males in one breeding tank\n- A spotless tank with no algae for fry to graze\n- Expecting one big spawn instead of eggs over several days\n- Feeding a diet with no greens"}]$g$::jsonb, $g$[{"q": "How long do American flagfish eggs take to hatch?", "a": "Usually about 5 to 10 days, depending on temperature. Since eggs are laid over several days, they hatch over several days too."}, {"q": "Do American flagfish guard their eggs?", "a": "Yes. The male guards and fans the eggs and chases away other fish, including the female."}, {"q": "How can you tell male and female flagfish apart?", "a": "Males have red lines along the body and brighter fins. Females are plainer, usually with a dark spot on the rear of the dorsal fin."}, {"q": "Are American flagfish annual killifish?", "a": "No. They are a non annual species whose eggs hatch in water within days, with no drying period."}]$g$::jsonb, $g$Photograph the pair with your challenge code card when you open the log, before eggs appear. Since eggs hide in the moss, a photo of the male guarding his spot with eggs visible makes good stage 2 evidence.$g$),
  ($g$medaka-ricefish$g$, $g$cb26ccb1-86f2-42aa-80ae-8ed5ebe6ef2c$g$::uuid, $g$medaka-ricefish$g$, null, $g$How to Breed Medaka Ricefish: Eggs, Hatching and Fry Care$g$, $g$Medaka spawn almost daily with long days, and females carry eggs before leaving them on plants. Learn to collect the eggs, hatch them and raise fry.$g$, $g$Medaka are one of the easiest egg layers to breed: with long days and comfortable water, females spawn nearly every morning, carrying a little cluster of eggs at their vent before brushing them onto plants. Collect those eggs, keep them clean and you'll have fry in about one to two weeks. The adults will eat eggs and fry, so separating them is the main job.$g$, $g${"method": "Egg layer (female carries eggs briefly, then attaches them to plants)", "sexing": "Males have a notched dorsal fin and a larger, squarer anal fin; females have a smaller one", "group": "1 male to 2 or 3 females, or a small group", "breeding_tank": "10 gallons, floating plants or spawning mops, sponge filter", "conditioning": "Small live or frozen foods plus fine flake, fed 2 to 3 times a day", "trigger": "About 13 or more hours of light and water around 72 to 77°F", "spawn": "Often 10 to 30 eggs a day per female during the season", "eggs": "Hatch in about 7 to 14 days; nearer 7 to 10 days at 77°F", "fry": "Tiny at hatching; swim near the surface right away", "first_foods": "Green water, infusoria and fine powdered fry food, then baby brine shrimp", "grow_out": "About 3/4 inch in 2 to 3 months", "parents": "Adults eat eggs and fry; move eggs or plants to a hatching container"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 gallon tank or a tub works well. Medaka lay eggs among roots of floating plants and on fine leaves, so add water hyacinth, water lettuce, frogbit roots or spawning mops. A gentle sponge filter is enough.\n\nThe site's range is 60 to 77°F with pH 7 to 8. Medaka tolerate cool water, but spawning depends on long days and warmth: give about 13 or more hours of light and keep the water at around 72 to 77°F. Outdoors, they spawn naturally from late spring into summer."}, {"heading": "Conditioning and Sexing", "text": "Sexing is reliable in adults. Males have a small notch or split near the back of the dorsal fin and a large, long anal fin with a squarer outline. Females have an unnotched dorsal fin and a smaller anal fin that tapers toward the tail, plus a rounder belly.\n\nFeed small amounts two or three times a day: fine flake, frozen or live baby brine shrimp, daphnia and micro pellets. Medaka have small mouths. Keep one male to two or three females to spread his attention."}, {"heading": "Spawning: What You'll See", "text": "Spawning usually happens in the early morning, soon after lights on. The male courts the female with quick circling swims, then wraps his fins around her and the eggs are fertilized as they're released.\n\nThe female then swims around with a small cluster of eggs hanging at her vent, often for several hours. She eventually brushes them off on plant roots, mops or leaves, where they stick by fine threads. During a good season, a female can spawn nearly every day."}, {"heading": "Collecting and Hatching Eggs", "text": "Each spawn is often 10 to 30 eggs. Gently pick them off the plants with your fingers, or move the mops or plants to a separate container with water from the breeding tank. The eggs are tough and can be rolled gently to separate them.\n\nAt around 77°F, eggs usually hatch in about 7 to 10 days, and cooler water takes up to 2 weeks. Keep them in shallow water with gentle aeration or a daily water change. Remove white or fuzzy eggs daily; a little methylene blue helps prevent fungus."}, {"heading": "Raising the Fry", "text": "Newly hatched fry are tiny and swim near the surface straight away.\n\n- First week: green water, infusoria and very fine powdered fry food, several small feeds a day\n- Weeks 2 to 3: newly hatched baby brine shrimp and microworms\n- Weeks 4 to 8: baby brine shrimp plus crushed flake\n\nChange 10 to 20 percent of the water every 2 to 3 days with matched temperature, or use a large container with green water and floating plants. Keep fry at about 72 to 77°F for good growth."}, {"heading": "Growing Out", "text": "Fry reach about 3/4 inch in 2 to 3 months with good feeding, and many are ready to spawn themselves soon after. Sort by size so the bigger fry don't outcompete or eat the smallest ones.\n\nMedaka come in many color and fin forms. If you want to keep a line true, raise and select from the best fish of each batch. Never release medaka into local waters, even though they handle cool weather. Unwanted fish should be rehomed to other hobbyists."}, {"heading": "Common Mistakes", "text": "- Short days in winter, which stop spawning\n- Leaving eggs or fry with the adults\n- Food too large for tiny fry\n- Letting fungus spread on unfertilized eggs\n- Mixing fry of very different sizes"}]$g$::jsonb, $g$[{"q": "How long do medaka eggs take to hatch?", "a": "Usually about 7 to 10 days at around 77°F, and up to 2 weeks in cooler water."}, {"q": "Why is my female medaka carrying eggs?", "a": "Females hold freshly fertilized eggs at their vent for a while after spawning, then brush them off onto plants. It's normal."}, {"q": "How do you tell male and female medaka apart?", "a": "Males have a notch near the back of the dorsal fin and a larger, squarer anal fin. Females have a smaller, tapering anal fin and a rounder belly."}, {"q": "Do medaka eat their eggs and fry?", "a": "Yes. Move eggs or egg laden plants into a separate container to raise the fry."}]$g$::jsonb, $g$Photograph the group with your challenge code card when you open the log. A female carrying her egg cluster is ideal stage 2 evidence, so have your camera ready in the morning.$g$),
  ($g$endlers-livebearer$g$, $g$ca894170-1622-4206-bb75-f425fd7327c9$g$::uuid, $g$endlers-livebearer$g$, null, $g$How to Breed Endler's Livebearers: Pure Lines and Fry Care$g$, $g$Endler's livebearers breed easily and drop small broods every few weeks. Learn sexing, gestation, fry care and how to keep your line pure from guppies.$g$, $g$Endler's livebearers are about as easy to breed as fish get. A small group in a planted tank will have fry within weeks, and the brilliant males make every generation a treat. The real skill is keeping a pure line, since Endlers readily cross with guppies, and growing out healthy fish instead of letting the tank overcrowd.$g$, $g${"method": "Livebearer", "sexing": "Males small and brightly colored with a gonopodium; females larger and plain gray gold", "group": "1 male to 2 or 3 females", "breeding_tank": "10 gallons, dense java moss or floating plants, sponge filter", "conditioning": "Quality flake plus frozen or live baby brine shrimp and daphnia", "trigger": "Simply keeping mature males and females together in warm water", "spawn": "Commonly 5 to 25 fry per brood", "eggs": "Gestation about 3 to 4 weeks at 75 to 80°F", "fry": "Born fully formed and swimming, able to eat at once", "first_foods": "Crushed flake, fry powder and baby brine shrimp", "grow_out": "Males show color at about 3 to 6 weeks; mature in about 2 to 3 months", "parents": "Adults may eat some fry; dense moss saves most of them"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 gallon tank is ideal for a breeding group. Pack it with java moss, guppy grass or floating plants so newborns have instant cover. A sponge filter keeps fry safe from intakes.\n\nKeep the water within the site's ranges: 72 to 82°F, pH 7 to 8.5 and GH 8 to 25. Harder, alkaline water suits them. Around 75 to 80°F, broods arrive regularly. Avoid breeder boxes for long periods; they stress pregnant females.\n\nIf you plan to raise lots of fry, set up a second tank of 10 gallons or more for grow out at the same time. Endlers breed quickly, and it's much easier to move fry into a ready, cycled tank than to scramble when the first tank gets crowded."}, {"heading": "Choosing Breeders and Keeping the Line Pure", "text": "Males are small, slim and brightly colored, with a pointed anal fin called a gonopodium. Females are larger, plain gray gold and have a rounded anal fin.\n\nEndlers and guppies cross easily, and many fish sold as Endlers are hybrids. If you want a pure line, buy from a breeder who keeps them separate and never house them with guppies. Keep one male to two or three females so no single female is chased constantly. Don't sell hybrids as Endler's livebearers."}, {"heading": "Pregnancy and Birth", "text": "Mating happens constantly and needs no setup from you. Females can store sperm and drop several broods from one mating.\n\nGestation is about 3 to 4 weeks at 75 to 80°F. A pregnant female becomes rounder and shows a dark gravid spot near her vent. Broods are small, commonly 5 to 25 fry, and females can drop again roughly once a month. Births usually happen quietly among the plants, and you'll often just spot new fry hiding in the moss the next morning. A female near the end of gestation looks boxy from the front and may hide or hang near the heater."}, {"heading": "Saving the Fry", "text": "Adults may eat some newborn fry, though Endlers are less fry hungry than many livebearers. In a densely planted tank many fry survive with the parents.\n\nFor more fry, move a heavily pregnant female into a well planted 5 to 10 gallon tank and return her once she's dropped. Skip small plastic breeder boxes, which can stress females into dropping early or losing fry."}, {"heading": "Raising the Fry", "text": "Endler fry are born ready to eat.\n\n- Week 1: crushed flake, fry powder and newly hatched baby brine shrimp, 3 to 4 small feeds a day\n- Weeks 2 to 4: baby brine shrimp and crushed flake\n- From week 4: regular flake and small frozen foods\n\nChange 20 to 30 percent of the water weekly with matched temperature. Keep the fry tank at about 76 to 80°F for steady growth. Frequent small meals matter more than big ones, because fry have tiny stomachs and grow fastest when they can eat several times a day."}, {"heading": "Growing Out", "text": "Males start showing color at about 3 to 6 weeks and are mature in about 2 to 3 months. Separate young males from females as soon as you can sex them if you're selecting for a line, so you control which fish breed.\n\nKeep only the best fish of each line as breeders. Because Endlers breed so fast, a tank can fill quickly; plan where extra fish will go, and never release them."}, {"heading": "Common Mistakes", "text": "- Keeping Endlers with guppies, which leads to hybrids\n- Too many males per female\n- Long stays in breeder boxes\n- Overcrowding, which stunts growth\n- Selling hybrids as pure Endlers"}]$g$::jsonb, $g$[{"q": "How long are Endler's livebearers pregnant?", "a": "About 3 to 4 weeks at 75 to 80°F."}, {"q": "Do Endlers eat their fry?", "a": "Some adults do eat fry, but less than many livebearers. Dense moss or floating plants lets most fry survive."}, {"q": "Can Endlers breed with guppies?", "a": "Yes. They cross easily, so keep them apart if you want a pure line, and never sell hybrids as pure Endlers."}, {"q": "How many fry do Endlers have?", "a": "Broods are small, commonly 5 to 25 fry."}]$g$::jsonb, $g$Open your log with a stage 1 photo of the breeding group and your challenge code card in the planted tank. Since there are no eggs, a dated photo of newborn fry right after the drop is a clear way to show stage 2.$g$),
  ($g$guppy$g$, $g$25178a65-1656-4c4d-beb9-80bbffb46a8e$g$::uuid, $g$guppy$g$, null, $g$How to Breed Guppies: Pregnancy, Fry Care and Line Breeding$g$, $g$Guppies breed easily, but raising quality fish takes planning. Learn sexing, gestation, how to save fry from adults and how to grow them out well.$g$, $g$Guppies are famous for breeding with no help at all, which makes them a perfect first livebearer. Getting fry is easy; raising strong, well colored fish takes a little more care. A planted tank or a separate fry tank, steady warmth and frequent small feeds will give you healthy young, and selecting your best fish each generation is where guppy breeding gets really rewarding.$g$, $g${"method": "Livebearer", "sexing": "Males smaller and colorful with long fins and a gonopodium; females larger with a fan shaped anal fin", "group": "1 male to 2 or 3 females", "breeding_tank": "10 gallons or more, dense plants or moss, sponge filter", "conditioning": "Quality flake plus frozen or live brine shrimp and daphnia", "trigger": "Simply keeping mature males and females together in warm water", "spawn": "Commonly 20 to 60 fry per brood; large females can have more", "eggs": "Gestation about 3 to 4 weeks at 75 to 80°F", "fry": "Born fully formed and swimming, able to eat at once", "first_foods": "Baby brine shrimp, fry powder and crushed flake", "grow_out": "Sexes visible at about 4 to 6 weeks; mature in about 3 months", "parents": "Adults eat fry; use dense plants or move the female before she drops"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 gallon tank or larger makes a good breeding tank. Fill much of it with java moss, guppy grass or floating plants so newborn fry can hide immediately. A sponge filter is the safest choice, since fry can be pulled into hang on back filter intakes.\n\nKeep water within the site's ranges: 72 to 82°F, pH 6.8 to 8 and GH 8 to 25. Around 75 to 80°F, females drop broods regularly. A second tank for growing out fry is worth setting up early, so it is cycled and ready by the time the first broods need more room."}, {"heading": "Choosing Breeders", "text": "Males are smaller with long, colorful tails and a pointed anal fin called a gonopodium. Females are larger, mostly plainer and have a fan shaped anal fin.\n\nKeep one male to two or three females so females aren't harassed constantly. If you want fish that look like their parents, start with a matched trio from a breeder's line, not mixed store guppies. Females store sperm and can drop several broods from one mating, so a female that has been with other males may carry their fry for months."}, {"heading": "Pregnancy and Birth", "text": "Gestation is about 3 to 4 weeks at 75 to 80°F, and a female can drop roughly once a month. As birth approaches she gets larger and boxy from the front, and the dark gravid spot near her vent grows bigger.\n\nBroods are commonly 20 to 60 fry, with young females having fewer and large, mature females sometimes having more. Births often happen over several hours. Fry drop to the bottom or head straight for cover."}, {"heading": "Saving the Fry", "text": "Adult guppies, including the mother, will eat newborn fry. In a heavily planted tank many survive, but for the best results move a heavily pregnant female into a separate well planted tank to give birth, then return her to the group.\n\nBreeder boxes and nets can work for a short stay, but long periods in them stress females, which can lead to early or failed births. Move her as close to her due date as you can and keep the move gentle."}, {"heading": "Raising the Fry", "text": "Guppy fry are born able to swim and eat.\n\n- Week 1: newly hatched baby brine shrimp, fry powder and finely crushed flake, 3 to 5 small feeds a day\n- Weeks 2 to 4: baby brine shrimp and crushed flake\n- From week 4: regular flake, small pellets and frozen foods\n\nChange 20 to 30 percent of the water once or twice a week with matched temperature. Clean water and frequent feeding make the biggest difference to fin and body size in adult guppies. Keep them around 76 to 80°F.\n\nSiphon leftover food from the bottom daily in a small fry tank. Uneaten baby brine shrimp die within hours in fresh water and foul it quickly."}, {"heading": "Growing Out and Selecting", "text": "Sexes usually become visible at around 4 to 6 weeks, when young males' anal fins start to point and their colors appear. If you're breeding for a line, separate males from females as soon as you can tell them apart so you choose the parents of the next generation.\n\nGuppies are mature in about 3 months. Keep the best fish from each batch for breeding and rehome the rest. Overcrowded tanks give small, poorly finned fish, so thin batches before they become crowded."}, {"heading": "Common Mistakes", "text": "- Leaving newborns in a bare tank with adults\n- Long stays in small breeder boxes\n- Too many males chasing too few females\n- Not separating young males and females, which ruins line breeding\n- Overcrowded grow out tanks and infrequent water changes"}]$g$::jsonb, $g$[{"q": "How long are guppies pregnant?", "a": "About 3 to 4 weeks at 75 to 80°F. Cooler water can stretch gestation a bit longer."}, {"q": "Do guppies eat their fry?", "a": "Yes. Adults, including the mother, will eat newborns, so provide dense plants or move the female to her own tank before she gives birth."}, {"q": "How many babies do guppies have?", "a": "Commonly 20 to 60 fry per brood. Young females have fewer, and large, mature females can have more."}, {"q": "How can I tell if my guppy is about to give birth?", "a": "She looks boxy from the front, the dark gravid spot near her vent is large, and she may hide or hang near the heater or plants."}]$g$::jsonb, $g$Open your log with a stage 1 photo of your trio and challenge code card before the female is due. A dated photo of the newborn fry makes clear stage 2 evidence, and stage 3 follows at least 3 days later.$g$),
  ($g$mosquitofish$g$, $g$239a49b5-dcdc-4020-b2e7-04344ca6dda7$g$::uuid, null, null, $g$How to Breed Mosquitofish: Livebearer Care and Saving Fry$g$, $g$Mosquitofish are hardy livebearers that breed fast but eat their own fry. Learn sexing, gestation and setup, plus why they must never be released.$g$, $g$Mosquitofish are tough, fast breeding livebearers, best known for their use in mosquito control. Getting broods is easy, but adults are hungry predators that eat their own fry, so saving the young takes a planted tank or a separate birthing setup. They are also invasive in many places, so responsible breeding means keeping every fish indoors and checking your local rules before you start.$g$, $g${"method": "Livebearer", "sexing": "Males small and slim with a gonopodium; females much larger with a dark gravid spot", "group": "1 male to 3 or more females", "breeding_tank": "10 to 20 gallons, very dense plants or moss, lid, sponge filter", "conditioning": "Flake plus frozen or live bloodworms, brine shrimp and daphnia", "trigger": "Mature males and females together in warm water with long days", "spawn": "Commonly a few dozen fry per brood; large females can have more", "eggs": "Gestation commonly about 3 to 4 weeks in warm water", "fry": "Born fully formed and swimming, able to eat at once", "first_foods": "Baby brine shrimp, fry powder and crushed flake", "grow_out": "Sexes visible in about 4 to 6 weeks; mature in a few months in warm water", "parents": "Adults readily eat fry; use heavy cover or a separate birthing tank"}$g$::jsonb, $g$[{"heading": "Before You Start: Legal and Responsible Keeping", "text": "Mosquitofish have been released widely for mosquito control and are now considered invasive in many regions, where they harm native fish and amphibians. Some places restrict keeping or moving them. Check your local wildlife rules first, and if you got your fish from a local mosquito control program, follow their guidance.\n\nNever release mosquitofish or their fry into ponds, streams or storm drains. Plan where every fry will go before you breed them, and keep them in tanks that can't overflow to the outdoors."}, {"heading": "Setting Up the Breeding Tank", "text": "A 10 to 20 gallon tank works for a small group. The most important feature is cover: pack the tank with java moss, guppy grass, hornwort or floating plants so newborns have somewhere to hide the moment they're born. Use a sponge filter and a lid.\n\nMosquitofish handle a very wide range of temperatures, but breeding goes best in warm water around 75 to 80°F with long days. They accept a wide range of water chemistry, from neutral to hard and alkaline.\n\nSet up a second, smaller planted tank as a birthing and fry tank at the same time. Because adults hunt fry so actively, having that tank ready is the single biggest step toward raising a good number of young."}, {"heading": "Choosing Breeders", "text": "Sexing is easy in adults. Males are small and slim, with a long, pointed anal fin called a gonopodium. Females are much larger and heavier bodied, with a rounded anal fin and a dark gravid spot near the vent.\n\nKeep one male to three or more females. Males chase females constantly, and females need space and plants to escape. Mosquitofish can be nippy with each other and with other fish, so keep them in their own species tank."}, {"heading": "Pregnancy and Birth", "text": "Females store sperm and can have several broods from one mating. Gestation is commonly about 3 to 4 weeks in warm water, and is slower when it's cool. A pregnant female grows wider and her gravid spot darkens as birth nears.\n\nBroods are commonly a few dozen fry, with bigger females having more. Fry are born ready to swim and head for cover immediately. Births often happen over several hours, usually among the plants."}, {"heading": "Saving and Raising the Fry", "text": "Adult mosquitofish are serious fry eaters, so even dense plants won't save them all. For the most fry, move a heavily pregnant female into her own planted tank to give birth, then take her out once she's done.\n\n- Week 1: baby brine shrimp, fry powder and crushed flake, 3 to 4 small feeds a day\n- Weeks 2 to 4: baby brine shrimp and crushed flake\n- From week 4: flake and small frozen foods\n\nChange 20 to 30 percent of the water weekly with matched temperature. Keep the fry tank around 75 to 80°F for steady growth, and siphon leftover food so the water stays clean."}, {"heading": "Growing Out", "text": "Fry grow quickly in warm water. Young males can usually be spotted at around 4 to 6 weeks as their anal fins start to lengthen, and fish mature within a few months in good conditions.\n\nSort fry by size, since larger young will eat much smaller siblings. Keep only as many as you can house, and line up homes with other hobbyists or fish clubs. Unwanted mosquitofish should never be released."}, {"heading": "Common Mistakes", "text": "- Releasing fry or adults outdoors\n- Breeding without checking local rules\n- Too little cover, so fry are eaten within hours\n- Keeping them with gentle community fish they will nip\n- Mixing fry of very different sizes"}]$g$::jsonb, $g$[{"q": "How long are mosquitofish pregnant?", "a": "Gestation is commonly about 3 to 4 weeks in warm water, and longer when the water is cool."}, {"q": "Do mosquitofish eat their babies?", "a": "Yes, readily. Use very dense plants or move pregnant females to a separate tank to give birth."}, {"q": "Is it legal to keep mosquitofish?", "a": "It depends on where you live, since they are invasive in many places. Check local wildlife rules and never release them."}, {"q": "How can you tell male and female mosquitofish apart?", "a": "Males are small and slim with a pointed gonopodium. Females are much larger with a rounded anal fin and a dark gravid spot."}]$g$::jsonb, $g$Take your stage 1 photo of the breeding group and challenge code card before moving a pregnant female to her birthing tank. A dated photo of newborn fry in that tank works well for stage 2.$g$),
  ($g$platy$g$, $g$57ab6b1d-1dff-4310-ba2e-ad32d624a90a$g$::uuid, $g$platy$g$, null, $g$How to Breed Platies: Pregnancy, Fry and Growing Out$g$, $g$Platies are easy livebearers that drop a brood about once a month. Learn sexing, gestation, how to protect newborn fry and how to grow them on well.$g$, $g$Platies are one of the friendliest fish to start breeding with, since they're peaceful, colorful and drop healthy broods regularly with no special effort. Adults will snack on fry, so a heavily planted tank or a separate birthing tank makes a big difference to how many you raise. With steady water and good food, the fry grow quickly and color up within a couple of months.$g$, $g${"method": "Livebearer", "sexing": "Males have a pointed gonopodium; females are larger with a fan shaped anal fin", "group": "1 male to 2 or 3 females", "breeding_tank": "10 to 20 gallons, dense plants or moss, sponge filter", "conditioning": "Flake with vegetable matter plus frozen or live brine shrimp and daphnia", "trigger": "Simply keeping mature males and females together in warm water", "spawn": "Commonly 20 to 50 fry per brood; large females can have more", "eggs": "Gestation about 4 weeks at 75 to 80°F", "fry": "Born fully formed and swimming, able to eat at once", "first_foods": "Baby brine shrimp, fry powder and crushed flake", "grow_out": "Sexes visible at about 6 to 8 weeks; mature in about 3 to 4 months", "parents": "Adults eat some fry; use dense plants or a separate birthing tank"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 to 20 gallon tank with lots of cover works well. Add java moss, hornwort, guppy grass or floating plants so fry can hide the moment they're born. A sponge filter keeps them safe from strong intakes.\n\nPlaties like hard, alkaline water. Keep within the site's ranges of 70 to 82°F, pH 7 to 8.2 and GH 10 to 28. Around 75 to 80°F, broods come regularly. Soft, acidic water is a common cause of poor health in livebearers.\n\nIt helps to set up a second tank for fry at the same time, ideally a cycled 10 gallon with a sponge filter and some plants. Platies breed steadily, and broods from several females add up quickly, so having grow out space ready keeps the breeding tank from getting crowded."}, {"heading": "Choosing Breeders", "text": "Males have a pointed, rod like anal fin called a gonopodium. Females are a bit larger and rounder, with a fan shaped anal fin. Young males can be slow to develop, so a fish that looks female at 2 months may still turn out male.\n\nKeep one male to two or three females to spread his attention. Females store sperm and can drop several broods from one mating. Platies are often mixed color varieties; if you want fry that match, start with a matched group from one line."}, {"heading": "Pregnancy and Birth", "text": "Gestation is about 4 weeks at 75 to 80°F, and females often drop roughly once a month. As birth approaches, a female becomes wider and boxy from the front, and the area near her vent may darken, though this is harder to see on some colors.\n\nBroods are commonly 20 to 50 fry, fewer for young females and sometimes more for large ones. Births usually take a few hours, with fry heading straight for plants. Avoid netting or moving a female while she is actively giving birth."}, {"heading": "Saving the Fry", "text": "Platies are less fry hungry than some livebearers, but adults will still eat newborns. In a densely planted tank, a good share survive.\n\nTo save more, move a heavily pregnant female into a separate planted tank to give birth and then return her. Breeder boxes work for a short stay, but long periods in a small box stress females and can lead to early or failed births."}, {"heading": "Raising the Fry", "text": "Platy fry are born ready to eat.\n\n- Week 1: baby brine shrimp, fry powder and finely crushed flake, 3 to 4 small feeds a day\n- Weeks 2 to 4: baby brine shrimp, crushed flake and some vegetable flake\n- From week 4: regular flake and small frozen foods\n\nChange 20 to 30 percent of the water weekly with matched temperature. Keep the fry tank at 75 to 80°F. Fry also graze algae and biofilm between meals, which helps steady growth."}, {"heading": "Growing Out", "text": "Sexes are usually visible at about 6 to 8 weeks, though some males show late. Fry color up as they grow and are mature in about 3 to 4 months.\n\nPlaties can cross with swordtails and variatus platies. If you want to keep a line pure or sell fish as a specific type, keep them separate from related species. Keep the best fish of each batch, and plan homes for extras before the tank gets crowded."}, {"heading": "Common Mistakes", "text": "- Soft, acidic water\n- Bare tanks where adults pick off fry\n- Long stays in breeder boxes\n- Mixing with swordtails or variatus when breeding for a pure line\n- Overcrowding grow out tanks"}]$g$::jsonb, $g$[{"q": "How long are platies pregnant?", "a": "About 4 weeks at 75 to 80°F, and a female can often drop a new brood roughly once a month."}, {"q": "Do platies eat their fry?", "a": "Adults will eat some fry. Dense plants or moving the pregnant female to her own tank saves most of them."}, {"q": "How many babies do platies have?", "a": "Commonly 20 to 50 per brood, with young females having fewer."}, {"q": "How can you tell a male platy from a female?", "a": "Males have a pointed anal fin called a gonopodium. Females have a fan shaped anal fin and are usually larger."}]$g$::jsonb, $g$Open your log and take the stage 1 photo with the trio and challenge code card before the first female is due. A dated photo of newborn fry makes good stage 2 evidence.$g$),
  ($g$variatus-platy$g$, $g$f02f090c-e071-4454-989d-b31addedbf33$g$::uuid, $g$variatus-platy$g$, null, $g$How to Breed Variatus Platies: Livebearer Breeding Guide$g$, $g$Variatus platies are easy, cool tolerant livebearers. Learn sexing, gestation and how to protect fry, plus tips on late maturing males and pure lines.$g$, $g$Variatus platies are hardy, peaceful livebearers that breed readily in a planted tank. They tolerate cooler water than common platies, and the males often take months to show full color, so breeding them is a lesson in patience. Adults will eat some fry, but with lots of cover and good feeding you'll raise healthy broods without much trouble.$g$, $g${"method": "Livebearer", "sexing": "Males have a pointed gonopodium and brighter color; females larger with a fan shaped anal fin", "group": "1 male to 2 or 3 females", "breeding_tank": "15 to 20 gallons, dense plants or moss, sponge filter", "conditioning": "Flake with vegetable matter plus frozen or live brine shrimp and daphnia", "trigger": "Mature males and females together in water around 72 to 77°F", "spawn": "Commonly 20 to 50 fry per brood", "eggs": "Gestation about 4 weeks; slower in cooler water", "fry": "Born fully formed and swimming, able to eat at once", "first_foods": "Baby brine shrimp, fry powder and crushed flake", "grow_out": "Females sexable in a few months; some males mature and color up late", "parents": "Adults eat some fry; use dense plants or a separate birthing tank"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 15 to 20 gallon tank suits a breeding group, in line with the site's 15 gallon minimum. Add plenty of cover: java moss, hornwort or floating plants give newborns places to hide. A sponge filter keeps them safe.\n\nVariatus platies come from cooler waters than common platies, and the site lists 64 to 77°F with pH 7 to 8.2 and GH 10 to 25. For breeding, around 72 to 77°F works well. Cooler water slows gestation and growth, so keep the fry tank at the upper end of the range."}, {"heading": "Choosing Breeders", "text": "Males have a pointed anal fin called a gonopodium and usually develop brighter colors, often yellow, orange or red fins. Females are larger with a fan shaped anal fin and plainer coloring.\n\nVariatus males are known for maturing late. Some show their gonopodium and color within a few months, while others take much longer, so a fish you thought was female may turn out male. Keep one male to two or three females. Females store sperm and can have several broods from one mating."}, {"heading": "Pregnancy and Birth", "text": "Gestation is about 4 weeks in warm water, longer when it's cooler. A pregnant female grows wider and boxy from the front. Some show a darker area near the vent as birth approaches.\n\nBroods are commonly 20 to 50 fry, fewer for young females. Births usually take a few hours, and fry swim straight into the plants. A female can drop roughly once a month in good conditions. Avoid netting or moving her while she is actively giving birth."}, {"heading": "Saving the Fry", "text": "Adults will eat some newborns. In a densely planted tank a good number survive, which is often enough for most keepers.\n\nTo raise more, move a heavily pregnant female into a separate planted tank to give birth, then return her. Short stays in a breeder box are fine, but long ones stress females and can cause early or failed births."}, {"heading": "Raising the Fry", "text": "Variatus fry are born ready to eat.\n\n- Week 1: baby brine shrimp, fry powder and finely crushed flake, 3 to 4 small feeds a day\n- Weeks 2 to 4: baby brine shrimp, crushed flake and vegetable flake\n- From week 4: regular flake and small frozen foods\n\nChange 20 to 30 percent of the water weekly with matched temperature. Keep the fry tank at 74 to 77°F for steady growth; growth slows noticeably in cooler water.\n\nFeed little and often rather than one big meal, and siphon uneaten food from the bottom daily. Clean water and frequent feeding in the first two months set the size and shape of the adult fish."}, {"heading": "Growing Out", "text": "Fry grow steadily, and females are usually recognizable within a few months. Because some males mature late, wait before deciding a group is all female, and keep a close eye on young fish if you're breeding a specific color.\n\nVariatus can cross with common platies and swordtails. To keep a pure line, or to sell fish as variatus, keep them apart from related species. Choose the best colored fish of each batch as your next breeders, and plan homes for extras before the tank fills up."}, {"heading": "Common Mistakes", "text": "- Assuming late developing males are females\n- Keeping fry too cool, which slows growth a lot\n- Bare tanks where adults pick off fry\n- Mixing with common platies or swordtails when breeding a pure line\n- Long stays in breeder boxes"}]$g$::jsonb, $g$[{"q": "How long are variatus platies pregnant?", "a": "About 4 weeks in warm water. Cooler temperatures can make gestation longer."}, {"q": "Why does my female variatus platy look like she's turning into a male?", "a": "She was most likely a late developing male. Variatus males can take months to develop their gonopodium and color."}, {"q": "Can variatus platies breed with regular platies?", "a": "Yes, they can cross with common platies and swordtails, so keep them separate if you want a pure line."}, {"q": "Do variatus platies eat their fry?", "a": "Adults will eat some newborns, so give lots of plant cover or move the pregnant female to her own tank."}]$g$::jsonb, $g$Make sure your stage 1 photo with the challenge code card clearly shows at least one male with a visible gonopodium, since late males can make a group look all female. A dated photo of newborn fry works for stage 2.$g$),
  ($g$java-moss$g$, $g$fb29f693-e49d-4b8f-9779-a11f48493403$g$::uuid, null, $g$java-moss$g$, $g$How to Propagate Java Moss: Fragments, Mats and Walls$g$, $g$Java moss spreads from tiny fragments. Snip a pinch, tie or press it onto wood or mesh and it grows into a new mat in weeks. One of the easiest plants to grow.$g$, $g$Java moss is about as forgiving as aquarium plants get. Every small piece you trim off can grow into a new mat, so propagating it is really just a matter of cutting, attaching and waiting. It grows slowly in low light and faster with more light and nutrients, and a healthy clump gives shrimp and fry a place to hide and graze, which makes it useful far beyond looks.$g$, $g${"method": "Fragments: any trimmed piece regrows", "light": "Low to moderate; more light means denser, faster growth but more algae risk", "co2": "Not needed; added CO2 or liquid carbon speeds it up", "substrate": "None needed; attach to wood, rock or mesh rather than burying it", "timeline": "New growth visible in 1 to 3 weeks; a fuller mat in 2 to 3 months", "first_steps": "Trim a healthy green clump and tease off a pinch of strands to attach"}$g$::jsonb, $g$[{"heading": "How Java Moss Propagates", "text": "Java moss is a moss, so it has no true roots and never flowers or sets seed. It spreads by fragmentation: every snipped strand can keep growing and send out small rhizoids that grip whatever it touches. That is why stray bits end up stuck in filters and on the glass.\n\nIn practice, propagation means taking pieces from a healthy clump and giving them a surface to anchor to. Over a few weeks the strands branch, grip on and thicken into a mat."}, {"heading": "What You Need", "text": "- A healthy parent clump, bright green rather than brown\n- Sharp aquarium scissors\n- Cotton thread, fishing line or a plant-safe gel glue\n- Something to attach to: driftwood, a rock, stainless or plastic mesh\n- A tank around 70 to 79°F with gentle to moderate flow\n\nThe moss does not need fertile substrate, CO2 or strong light. It does appreciate clean water and a little flow that keeps debris from settling on it."}, {"heading": "Step by Step", "text": "Trim a section from the parent clump. Rinse it in old tank water and pick out any debris or algae.\n\nSpread a thin layer over the surface you want covered. Thin is better than thick: a layer you can almost see through grows in faster and does not rot underneath.\n\nTie it down with cotton thread or fishing line wrapped every half inch or so, or dab small spots of gel glue and press the moss on. Cotton slowly breaks down once the moss has gripped; fishing line can be cut away later.\n\nFor a moss wall, sandwich a thin layer between two pieces of mesh and fix it to the back glass with suction cups."}, {"heading": "Caring for New Mats", "text": "For the first few weeks, keep flow gentle so pieces are not torn loose and keep the light moderate. Most growers see new bright green tips within 1 to 3 weeks.\n\nTrim the mat every few weeks once it fills in. Trimming keeps it dense, stops the inner layers from going brown, and gives you more pieces to start new mats. Clean trims out of the tank so they do not clog the filter intake.\n\nIf you dose a liquid fertilizer, a light dose is plenty. A gentle swish or turkey baster during water changes keeps mulm from building up in the mat.\n\nJava moss is happiest from about 70 to 79°F. Above that, growth slows and the mat can turn brown, so in a warm breeding room keep it in the coolest tank you have."}, {"heading": "Common Mistakes", "text": "- Piling on too much moss: thick layers block light and flow and the bottom turns brown\n- Too much light without enough plant mass: java moss traps algae easily, so balance light and nutrients\n- Leaving loose trimmings to drift: they jam filters and grow where you do not want them\n- Expecting it to grow fast in warm, still water: it does best below about 79°F with some flow\n- Burying it in the gravel: buried moss rots, so attach it on top of hardscape instead"}, {"heading": "Using Java Moss for Fry and Shrimp", "text": "Propagating java moss pays off in a breeding room. Shrimp graze biofilm from it all day, newborn livebearers hide in it, and egg scatterers will drop eggs into a dense clump where adults have trouble reaching them.\n\nA spare tank with a few mats growing on mesh squares gives you ready-made spawning mops and fry cover. Keep a starter clump going in a low light tank and you will always have pieces to share with other hobbyists or swap at club meetings."}]$g$::jsonb, $g$[{"q": "How fast does java moss grow?", "a": "It is a slow to moderate grower. Expect new tips within a few weeks and a full mat in a couple of months, faster with more light and some fertilizer."}, {"q": "Can java moss grow without being tied down?", "a": "Yes, it will grow loose, but it tends to drift into filters and corners. Tying or gluing it gives you a tidy mat that stays where you want it."}, {"q": "Why is my java moss turning brown?", "a": "Usually it is too thick, too warm, starved of light, or smothered by debris. Thin it out, trim the brown parts and improve flow."}, {"q": "Does java moss need CO2?", "a": "No. It grows fine without CO2. Adding CO2 or liquid carbon can speed growth, but it is not necessary."}]$g$::jsonb, $g$For the plant program, photograph the trimmed fragment on the day you attach it, then take dated photos of the same piece every couple of weeks until it has clearly grown into a new mat.$g$),
  ($g$anubias$g$, $g$34937f68-a435-46c1-8640-908a3c7e7600$g$::uuid, null, $g$anubias$g$, $g$How to Propagate Anubias: Rhizome Division Made Simple$g$, $g$Anubias propagates by cutting the rhizome into pieces with a few leaves each. It is easy and reliable, but slow, so expect weeks before new leaves appear.$g$, $g$Anubias barteri is one of the most reliable plants in the hobby and one of the easiest to propagate. Each section of its thick, creeping rhizome can become a new plant, so one healthy specimen turns into several with a clean cut. The catch is patience: anubias grows slowly, and a divided piece may take a few weeks to push its first new leaf.$g$, $g${"method": "Rhizome division", "light": "Low to moderate; strong light encourages algae on the slow-growing leaves", "co2": "Not needed; it grows well in low-tech tanks", "substrate": "Attach to wood or rock; roots can go in substrate but keep the rhizome uncovered", "timeline": "First new leaf on a division often in 2 to 6 weeks; growth is slow", "first_steps": "Cut the rhizome into sections with at least 3 to 4 leaves each"}$g$::jsonb, $g$[{"heading": "How Anubias Propagates", "text": "Anubias grows from a horizontal stem called a rhizome. Leaves sprout from the top and roots grow from the underside. As the rhizome lengthens it often branches, and each section can live on its own once it is separated.\n\nAnubias can also flower underwater, but seeds are not a practical way to propagate it in the aquarium. Division is the method nearly everyone uses.\n\nOlder plants often send out side shoots from the rhizome on their own. If you see a young growing tip with two or three small leaves branching off the main rhizome, that is the easiest place to make a cut, because the new piece is already growing."}, {"heading": "What You Need", "text": "- A mature plant with a rhizome at least 3 to 4 inches long\n- A clean, sharp blade or scissors\n- Cotton thread, fishing line or plant-safe gel glue\n- Wood or rock to attach the new pieces to\n- A tank roughly 72 to 82°F; anubias is not fussy about pH or hardness\n\nNo CO2 or special substrate is needed. A root tab nearby or a light liquid fertilizer helps divisions grow a bit faster."}, {"heading": "Step by Step", "text": "Lift the plant out and rinse it in tank water so you can see the rhizome clearly.\n\nPick the cut points so each section keeps at least 3 or 4 healthy leaves and some roots. Smaller pieces can survive, but they recover more slowly.\n\nMake one clean cut straight through the rhizome. Do not tear it.\n\nAttach each section to wood or rock with thread or a dab of glue on the rhizome, or wedge it into a gap between stones. If you plant it in substrate, push only the roots in and leave the rhizome sitting on top. A buried rhizome tends to rot.\n\nWork quickly and keep the plants wet. Anubias handles a few minutes out of water, but the leaves can dry out under lights or in a warm room. Rinse any slimy or soft spots off the rhizome before you reattach it."}, {"heading": "Caring for New Divisions", "text": "Place new pieces in low to moderate light, ideally a bit shaded by other plants or wood. Slow-growing leaves under bright light pick up algae spots that are hard to remove.\n\nExpect a pause. Many divisions sit still for a few weeks while they recover, then put out a new leaf from the growing tip. Once roots grip the hardscape, remove fishing line, or leave cotton to rot away on its own.\n\nTrim old or algae-covered leaves at the base if needed, but keep enough leaves for the plant to feed itself."}, {"heading": "Common Mistakes", "text": "- Burying the rhizome: this is the classic way to lose an anubias\n- Cutting pieces too small: one or two leaves is a slow, risky start\n- Too much light: leaves get covered in algae before the plant can outgrow it\n- Expecting fast results: slow growth is normal, not a sign of failure\n- Ignoring mushy or smelly sections: trim any soft, rotting rhizome back to firm tissue"}, {"heading": "Why It Is Worth Doing", "text": "Anubias divisions are tough and almost impossible to kill with normal care, which makes them ideal for breeding tanks, shrimp tanks and anywhere fish might nibble softer plants. Many fish lay eggs on or under the broad leaves.\n\nA single good plant can become three or four over a year. They make great trade material at club auctions because they ship and travel well."}]$g$::jsonb, $g$[{"q": "Can you cut anubias in half?", "a": "Yes. Cut the rhizome so each half has at least a few leaves and some roots, and both halves usually keep growing."}, {"q": "Should anubias be planted in gravel?", "a": "Its roots can go into gravel, but the rhizome should stay above the substrate. Many people simply tie it to wood or rock instead."}, {"q": "How long does anubias take to grow a new leaf?", "a": "It is slow. A healthy plant may add a leaf every few weeks, and a fresh division often takes a little longer to get going."}, {"q": "Why does my anubias have algae on the leaves?", "a": "Usually the light is too strong for such a slow plant. Move it to a shadier spot and trim the worst leaves."}]$g$::jsonb, $g$For the plant program, take a dated photo of the parent plant, the cut sections, and each division attached in place, then follow up with dated photos showing a brand new leaf on the division.$g$),
  ($g$java-fern$g$, $g$b8c4fa37-e129-4958-81df-eb6c4cddd2fd$g$::uuid, null, $g$java-fern$g$, $g$How to Propagate Java Fern: Rhizome Division and Plantlets$g$, $g$Java fern propagates two ways: dividing the rhizome or collecting baby plantlets from its leaves. Both are simple, low-tech and very beginner friendly.$g$, $g$Java fern is one of the most rewarding plants for a first propagation project. It does the work for you by growing tiny plantlets on its older leaves, and its rhizome can be cut into pieces that each become a new plant. It is slow, but it needs no CO2 or special substrate, and fish rarely eat it.$g$, $g${"method": "Plantlets on leaves and rhizome division", "light": "Low to moderate; strong light can cause brown or transparent patches", "co2": "Not needed", "substrate": "Attach to wood or rock; never bury the rhizome", "timeline": "Plantlets often appear within weeks to months; ready to detach at 1 to 2 inches with roots", "first_steps": "Look under older leaves for plantlets, or cut a long rhizome into leafy sections"}$g$::jsonb, $g$[{"heading": "How Java Fern Propagates", "text": "Java fern spreads in two ways in the aquarium. Older leaves grow small adventitious plantlets, usually along the leaf edges or tips, often near dark brown patches. Each plantlet grows its own tiny leaves and roots while still attached.\n\nThe plant also grows along a horizontal rhizome. A long rhizome can be cut into sections, and each section with some leaves grows on as its own plant. The brown dots under the leaves are sori, the fern's spore structures. They are normal and not a disease."}, {"heading": "What You Need", "text": "- A healthy java fern with a rhizome of several inches or leaves carrying plantlets\n- Sharp scissors\n- Cotton thread, fishing line or plant-safe gel glue\n- Wood or rock for attaching\n- Water roughly 68 to 82°F; it is very adaptable\n\nCO2 and rich substrate are not required. A light liquid fertilizer is helpful because java fern feeds through its leaves and rhizome."}, {"heading": "Step by Step", "text": "For plantlets: wait until a plantlet has several leaves and roots, usually around 1 to 2 inches tall. Gently pull it from the parent leaf or let it drop off naturally. Tie it or glue it lightly to wood or rock, or tuck its roots into a crevice.\n\nFor division: lift the plant and pick cut points so each piece keeps at least 3 or 4 leaves. Make one clean cut through the rhizome. Attach each piece by the rhizome to hardscape.\n\nYou can also leave an older, plantlet-covered leaf floating or pinned down in a quiet corner. The plantlets keep growing as the old leaf breaks down."}, {"heading": "Caring for New Plants", "text": "Keep young plants in gentle flow and moderate light. They grow slowly, so do not worry if they barely change for the first couple of weeks.\n\nOnce roots grab the wood or rock, you can cut off fishing line or let cotton rot away. Remove leaves that turn mushy or fully black so they do not foul the water, but leaves with a few brown spots are often still useful because that is where plantlets form.\n\nJava fern grows best in the low 70s °F and slows down in very warm water. A light dose of liquid fertilizer once a week is plenty. If young plants turn black and mushy from the rhizome outward, cut away the soft part and reattach the firm remainder."}, {"heading": "Common Mistakes", "text": "- Burying the rhizome in gravel or sand, which often leads to rot\n- Pulling plantlets off before they have roots\n- Blasting it with strong light, which can cause brown or clear patches\n- Mistaking normal brown spore dots for disease and stripping healthy leaves\n- Tying it so tightly that the rhizome is crushed\n- Expecting quick results: java fern often adds just one or two leaves a month"}, {"heading": "Getting More Plantlets", "text": "Some plants produce plantlets freely while others rarely do, and narrow leaf and Windelov forms behave a little differently from the standard form. Mature leaves that are starting to age tend to produce the most.\n\nIf you want a steady supply, keep one parent plant in a low light tank and let old leaves age naturally instead of trimming them right away. Collect the plantlets as they root and grow them on.\n\nPlantlets that drop off on their own often drift into corners or get caught in plants. Check the tank every week or two and collect them before they get sucked into the filter."}]$g$::jsonb, $g$[{"q": "How do I get java fern babies?", "a": "Older leaves naturally grow small plantlets. Leave them attached until they have roots and a few leaves, then remove them and tie them to wood or rock."}, {"q": "Can you plant java fern in substrate?", "a": "Not by the rhizome. The rhizome should stay exposed, so attach it to hardscape or let only the roots touch the substrate."}, {"q": "What are the brown dots under java fern leaves?", "a": "Those are sori, the clusters that hold the fern's spores. They are normal on a mature plant."}, {"q": "How long until a java fern plantlet is ready?", "a": "It varies, but many are ready to detach once they reach about 1 to 2 inches with visible roots, often a few weeks after they first appear."}]$g$::jsonb, $g$For the plant program, photograph the parent leaf carrying plantlets or the rhizome before cutting, then take dated photos of each new plant attached on its own and again once it has grown new leaves.$g$),
  ($g$vallisneria$g$, $g$5c097699-7c4e-4515-9803-aa7a90fe920b$g$::uuid, null, null, $g$How to Propagate Vallisneria: Runners and Daughter Plants$g$, $g$Vallisneria spreads by runners that sprout daughter plants along the substrate. Separate them once rooted. Easy, fast and great for background planting.$g$, $g$Vallisneria propagates itself. A healthy plant sends out runners along the substrate, and every few inches a new daughter plant appears with its own leaves and roots. Your job is mostly to give it a stable spot, steady nutrients and then decide where the babies go. Once it settles, a few plants can fill a background in a few months.$g$, $g${"method": "Runners with daughter plants", "light": "Moderate; tall leaves reach toward the light and can float along the surface", "co2": "Not required; does well in low-tech tanks with root tabs", "substrate": "Plain gravel or sand works; root tabs help in inert substrate", "timeline": "Runners often appear within weeks once settled; daughters ready at 3 to 4 leaves", "first_steps": "Find a daughter plant with several leaves and roots on a runner"}$g$::jsonb, $g$[{"heading": "How Vallisneria Propagates", "text": "Vallisneria is a rosette plant. Mature plants send out thin runners along or just under the substrate, and new daughter plants grow at points along each runner. One plant can produce a chain of several daughters.\n\nVallisneria does flower in aquariums at times, but sexual reproduction is not a practical way to propagate it. Runners do all the work."}, {"heading": "What You Need", "text": "- An established parent plant, not one that is still melting back after planting\n- Gravel or sand with root tabs, or a nutrient substrate\n- Moderate light\n- Stable water: it tends to prefer neutral to harder water and many keepers report it doing poorly with liquid carbon products\n- Clean scissors for cutting runners\n\nCO2 is optional. Steady, unchanging conditions matter more for vallisneria than fancy equipment.\n\nVallisneria spiralis is happiest at roughly 68 to 82°F. It does not need a deep substrate, but 2 inches or more gives the roots room to spread and gives the runners something to grip."}, {"heading": "Step by Step", "text": "Wait until a daughter plant has 3 or 4 leaves and its own roots. Rushing this step gives you weak transplants.\n\nCut the runner on both sides of the daughter, leaving a short stub. Gently lift it with its roots.\n\nReplant it with the roots in the substrate and the crown, the pale area where leaves meet roots, sitting just at the surface. Burying the crown is a common cause of rot.\n\nIf you want the plants to fill in on their own, simply leave the runners alone and steer them by moving daughters to where you want coverage.\n\nSpace daughters about 2 to 3 inches apart if you want a dense wall of leaves. Plant them in a line along the back glass and they will fill the gaps by themselves within a couple of months."}, {"heading": "Caring for New Plants", "text": "New plants can lose a leaf or two while they settle. Keep conditions steady and add a root tab nearby if your substrate is inert.\n\nAs leaves reach the surface, trim the longest ones straight across or remove whole older leaves at the base. Cut leaf tips can brown, so removing full leaves looks tidier.\n\nWithin a few weeks, healthy daughters usually start sending out their own runners."}, {"heading": "Common Mistakes", "text": "- Burying the crown, which leads to rotting plants\n- Moving plants around constantly; vallisneria likes to be left alone\n- Dosing liquid carbon products that many growers report cause melting\n- Separating daughters before they have roots\n- Letting leaves cover the whole surface and shade everything below"}, {"heading": "Melting After Planting", "text": "It is common for new vallisneria to drop some leaves in its first weeks, especially if it was grown differently at the store. As long as the crown and roots stay firm, it usually recovers and begins sending out runners once it settles.\n\nRemove melted leaves promptly and resist the urge to pull it up to check the roots. Patience at this stage pays off with a carpet of runners later."}, {"heading": "Getting the Most Runners", "text": "A stable tank with steady light, regular root tabs and good water changes is the best way to encourage runners. Vallisneria often spreads faster once it has been left alone for a few months.\n\nIf you are growing it to share or trade, give the parent plants a dedicated corner where you can lift daughters without disturbing the rest of the tank. Many hobbyists keep a shallow tub of plain gravel with root tabs just for growing out vallisneria daughters."}]$g$::jsonb, $g$[{"q": "How do you propagate vallisneria?", "a": "Let it send out runners, then cut off daughter plants once they have a few leaves and roots and replant them with the crown at substrate level."}, {"q": "How fast does vallisneria spread?", "a": "Once settled, it can spread quickly, often sending out runners within weeks in a stable tank with moderate light and root nutrients."}, {"q": "Why is my vallisneria melting?", "a": "Common causes are recent replanting, big changes in water, a buried crown, or liquid carbon dosing. Keep conditions steady and give it time."}, {"q": "Does vallisneria need root tabs?", "a": "It feeds heavily through its roots, so root tabs help a lot in plain gravel or sand."}]$g$::jsonb, $g$For the plant program, take a dated photo of the runner and daughter plant before cutting, then dated photos of the replanted daughter in its new spot and again once it sends out its own runner.$g$),
  ($g$hornwort$g$, $g$daf682b1-a990-4d26-b4fc-ec64f077121d$g$::uuid, null, $g$hornwort$g$, $g$How to Propagate Hornwort: Cuttings and Side Shoots$g$, $g$Hornwort propagates from simple cuttings: snip a stem, float or anchor it and it keeps growing. Very fast and very easy, a true beginner plant.$g$, $g$Hornwort is one of the fastest growing aquarium plants and one of the easiest to propagate. It has no true roots, so any cut piece of stem simply keeps growing and branching. A single bunch can fill a tank within weeks in good light, which makes it great for fry tanks and soaking up nutrients, though it may shed needles when moved.$g$, $g${"method": "Stem cuttings and fragments", "light": "Moderate to bright; grows in low light, but more slowly", "co2": "Not needed", "substrate": "None needed; float it or lightly anchor stems", "timeline": "Visible new growth often within days; doubles quickly in good conditions", "first_steps": "Cut a healthy green tip section several inches long"}$g$::jsonb, $g$[{"heading": "How Hornwort Propagates", "text": "Hornwort grows as long, branching stems covered in whorls of stiff needle-like leaves. It does not form true roots. Instead, it absorbs nutrients directly from the water through its leaves and stems.\n\nWhen a stem breaks or is cut, each piece keeps growing. Side branches also form along the stem, so a single stem quickly becomes a bushy clump."}, {"heading": "What You Need", "text": "- Healthy green stems, not ones that are brown and shedding\n- Sharp scissors\n- Moderate to bright light\n- Water anywhere from about 60 to 82°F; it handles cooler temperatures well\n- Optional: plant weights or a stone to anchor stems\n\nNo CO2 or substrate is needed. In a tank with fish, there are usually enough nutrients for strong growth."}, {"heading": "Step by Step", "text": "Choose a healthy stem and cut off a section several inches long, ideally a growing tip.\n\nDecide whether to float it or anchor it. Floating works well and keeps it near the light. To anchor it, slip the base of the stem gently under a rock or plant weight, or push it lightly into the substrate. Be aware that buried sections may rot.\n\nThe parent stem will branch from the cut point, so you get more growth on both sides of the cut.\n\nEach cut stem can be cut again once it grows. A good rule is to take tops about 4 to 6 inches long and keep the lower part in the tank to branch. Repeat every week or two and one bunch becomes a dozen."}, {"heading": "Caring for New Stems", "text": "New pieces usually show fresh green growth at the tips within days. Trim regularly once it gets going, or it will crowd out the surface and shade other plants.\n\nHornwort sometimes drops a lot of needles after being moved to a new tank. This is common and usually settles once it adjusts. Net out the fallen needles so they do not clog the filter.\n\nHornwort uses a lot of nutrients. In tanks with very few fish, a light dose of liquid fertilizer keeps it green. In heavily stocked tanks, it often grows fast enough that you will be removing a bunch every week. Pale or yellow tips usually mean it is short on nutrients or light."}, {"heading": "Common Mistakes", "text": "- Burying stems deep in the substrate, where they can rot\n- Moving it between very different tanks and panicking at the needle drop\n- Letting it take over the whole tank and shade slower plants\n- Using it in tanks with plant-eating fish that strip it\n- Forgetting to remove shed needles, which can clog intakes"}, {"heading": "Using Hornwort in Breeding Tanks", "text": "Hornwort is a favorite in breeding setups. Its dense stems give egg scatterers somewhere to drop eggs and give livebearer fry a place to hide. It also uses up nitrate and helps limit algae in tanks with heavy feeding.\n\nKeep a spare floating bunch in a grow-out tank and pull stems as needed. Because it grows so fast, it is also great trade material for club meetings."}, {"heading": "Moving Hornwort Between Tanks", "text": "Hornwort can be sensitive to sudden changes in temperature, hardness and pH. When moving cuttings to a new tank, float them in a bag for a while and then release them, the same way you would acclimate fish.\n\nRinse new stems from other people's tanks well and check for snails, hydra or pest eggs. A short quarantine in a bucket or spare tank is a good habit, especially before adding hornwort to a fry tank where hydra could harm tiny fry."}]$g$::jsonb, $g$[{"q": "Does hornwort need to be planted?", "a": "No. It has no true roots and grows well floating. You can anchor it if you like, but avoid burying it deeply."}, {"q": "How fast does hornwort grow?", "a": "Very fast in good light, often an inch or more a week. Trim it regularly to keep it under control."}, {"q": "Why is my hornwort shedding needles?", "a": "It often sheds after a move or a big change in water conditions. It usually recovers once it settles."}, {"q": "Can hornwort grow in cold water?", "a": "Yes. It tolerates cooler water well, which is why it is common in ponds and unheated tanks."}]$g$::jsonb, $g$For the plant program, photograph the cut stem on the day you take it with a ruler beside it, then take dated photos every week to show its new tips and side branches.$g$),
  ($g$water-sprite$g$, $g$dbfc040c-54bd-4e57-8b29-eadb14e8cc8b$g$::uuid, null, null, $g$How to Propagate Water Sprite: Leaf Plantlets Explained$g$, $g$Water sprite grows baby plants on its leaves. Let them root, then float or plant them. A fast, forgiving fern that suits beginners and fry tanks alike.$g$, $g$Water sprite is a fast growing aquatic fern that makes propagation almost automatic. Mature leaves sprout little plantlets that grow roots while still attached, and each one can become a full sized plant. It grows well either rooted in the substrate or floating, and its soft, finely cut leaves are ideal cover for fry and shrimp.$g$, $g${"method": "Plantlets on leaves", "light": "Moderate to bright; floating plants grow fastest", "co2": "Not required; helps planted specimens grow faster", "substrate": "Optional: grows rooted in any substrate or floating", "timeline": "Plantlets often appear within a few weeks on mature leaves", "first_steps": "Find a mature leaf with plantlets that already have small roots"}$g$::jsonb, $g$[{"heading": "How Water Sprite Propagates", "text": "Water sprite, Ceratopteris thalictroides, is a true fern. In the aquarium it propagates mainly through adventitious plantlets that form on its mature leaves. These tiny plants grow their own roots and leaves while still attached to the parent leaf.\n\nOnce they reach a decent size, they break free or can be removed and grown on as new plants. Ferns also produce spores, but plantlets are the easy and reliable way to propagate it in an aquarium.\n\nPlanted water sprite also forms new shoots around its base, which can be separated like small side plants once they have roots of their own. The floating form tends to produce plantlets fastest because it gets the most light and CO2 from the air."}, {"heading": "What You Need", "text": "- A healthy parent plant with mature leaves\n- Moderate to bright light\n- Some fertilizer, either liquid or root tabs, since it grows fast\n- Water roughly 70 to 82°F\n- Scissors and tweezers\n\nCO2 is not required, though it can speed up rooted plants. Floating plants get plenty of CO2 from the air."}, {"heading": "Step by Step", "text": "Look for plantlets along the leaves of mature growth.\n\nWait until a plantlet has a few leaves and small roots. Gently pinch or cut it away from the parent leaf.\n\nEither float it, where it will grow quickly near the light, or plant its roots lightly into the substrate. Do not bury the crown.\n\nYou can also float a whole leaf with several plantlets on it. The plantlets keep growing and the old leaf eventually breaks down.\n\nIf you are planting the new plants, put them 3 to 4 inches apart. Water sprite grows broad, and crowded plants shade each other and lose their lower leaves.\n\nFor a floating raft, simply release the plantlets at the surface. Keep them away from strong filter outflow so they stay together."}, {"heading": "Caring for New Plants", "text": "Young plants grow quickly in good light. Floating plants can cover the surface fast, so thin them regularly to keep light reaching the tank below.\n\nRooted plants appreciate root tabs in plain gravel or sand. Remove yellow or decaying leaves at the base so they do not break down in the tank.\n\nLeaf shape can change a lot depending on how it is grown. Floating plants often have broader, less divided leaves, while planted ones grow more finely cut leaves. Both are normal."}, {"heading": "Common Mistakes", "text": "- Burying the crown when planting, which can lead to rot\n- Letting floating plants cover the whole surface and shade everything else\n- Starving it of nutrients; fast growers need regular feeding\n- Keeping it with fish that eat soft plants\n- Removing plantlets before they have roots"}, {"heading": "Water Sprite in Fry Tanks", "text": "Water sprite is a great plant for breeding setups. Floating mats give bubble nesters and surface spawners shelter, and the roots hold microorganisms that tiny fry can graze on.\n\nKeeping a floating raft in a grow-out tank also helps use up excess nutrients from heavy feeding. Thin it out weekly and you will have plenty of spare plants to pass along."}, {"heading": "Light, Nutrients and Growth Speed", "text": "Water sprite is a hungry plant. In good light with regular fertilizer it can produce new plantlets every couple of weeks. In low light and lean water, it grows slowly and its leaves may yellow.\n\nIf leaves turn pale or translucent, add a liquid fertilizer with iron and potassium. If algae coats the leaves, reduce the light period a bit and keep up with water changes."}]$g$::jsonb, $g$[{"q": "Is water sprite a floating plant?", "a": "It can be grown either way. It roots well in substrate or grows quickly as a floating plant."}, {"q": "How do I get baby plants from water sprite?", "a": "Mature leaves grow plantlets. Wait until they have roots and leaves, then remove and float or plant them."}, {"q": "How fast does water sprite grow?", "a": "It is a fast grower, especially when floating in good light. Plantlets often appear within a few weeks on mature leaves."}, {"q": "Is water sprite good for shrimp and fry?", "a": "Yes. Its fine leaves and roots offer cover and surfaces for the microorganisms that young animals graze on."}]$g$::jsonb, $g$For the plant program, take a dated photo of the parent leaf with plantlets before removing any, then dated photos of the new plant floating or planted on its own as it grows.$g$),
  ($g$peaceful-betta$g$, $g$fec1aed7-4c8e-429e-9da6-673b38716397$g$::uuid, $g$peaceful-betta$g$, null, $g$How to Breed Crescent Bettas (Betta imbellis) Step by Step$g$, $g$Betta imbellis is a wild bubble nesting betta. Condition a pair, give soft water and floating cover, then raise tiny fry on live foods. Moderate difficulty.$g$, $g$Betta imbellis, the crescent or peaceful betta, is a wild bubble nester that breeds much like the familiar Siamese fighter, but with calmer males and a subtler beauty. A well conditioned pair in a quiet, planted tank will often spawn on their own. The hard part is the fry, which start out tiny and need microscopic live foods for their first week.$g$, $g${"method": "Bubble nester", "sexing": "Males show blue-green iridescence and a red crescent edge on the tail; females paler, often barred", "group": "One pair", "breeding_tank": "10 gallon, shallow water, floating plants, gentle sponge filter, tight lid", "conditioning": "1 to 2 weeks of live or frozen foods like brine shrimp, bloodworms and daphnia", "trigger": "Warm, still, soft water around 79 to 82°F with leaf litter and floating cover", "spawn": "Commonly reported from several dozen up to about 200 eggs", "eggs": "Hatch in about 24 to 48 hours around 80°F; male tends the nest", "fry": "Free swimming about 3 days after hatching; very small", "first_foods": "Infusoria or paramecium, then microworms and baby brine shrimp after about a week", "grow_out": "Juvenile coloring at 6 to 8 weeks; adult size in roughly 4 to 6 months", "parents": "Male guards eggs; remove female after spawning and male once fry swim freely"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 gallon tank is plenty for one pair. Keep the water fairly shallow, around 6 to 8 inches, so the male does not have to work as hard to keep eggs in the nest and fry can reach the surface easily.\n\nAim for 79 to 82°F, soft water and a pH in the 5 to 7 range the species likes, toward the lower end for spawning. Floating plants and a few leaves help the male anchor a nest and give the female hiding spots. Use a gentle sponge filter and a snug lid so warm, humid air sits over the water."}, {"heading": "Choosing and Conditioning a Pair", "text": "Males show blue-green iridescent scales and the red crescent at the edge of the tail that gives the species its name. Females are paler, often show horizontal or vertical bars, and have a rounder belly with a visible egg spot when ready.\n\nFeed both fish live or frozen foods like brine shrimp, daphnia and bloodworms for 1 to 2 weeks. Imbellis males are much less aggressive than domestic bettas, but watch the female for torn fins and give her cover."}, {"heading": "Spawning: What You Will See", "text": "The male builds a bubble nest, often under a floating leaf or plants. When the female is ready, he leads her under the nest and wraps around her in an embrace. Eggs fall and the male gathers them in his mouth and places them in the nest.\n\nThis repeats many times over a few hours. A typical spawn is commonly reported from several dozen to around 200 eggs."}, {"heading": "Eggs and the Nest", "text": "After spawning, remove the female so the male can focus on the nest. He will pick up falling eggs and put them back.\n\nEggs usually hatch in about 24 to 48 hours at around 80°F. Hatched fry hang from the nest with yolk sacs for about 3 days. Once they swim horizontally and leave the nest, remove the male to protect them.\n\nDo not disturb the nest during these days. Bettas can eat eggs if stressed, and big water changes or bright lights near the tank are common triggers. Keep a lid or cling wrap over the tank so the surface stays calm and warm."}, {"heading": "Raising the Fry", "text": "- Week 1: infusoria or paramecium cultures several times a day\n- Week 2: add microworms and newly hatched baby brine shrimp\n- Weeks 3 to 4: mostly baby brine shrimp, plus finely crushed food\n- Keep the lid on to protect the developing labyrinth organ\n- Small water changes of 10 to 20 percent, matched for temperature, a few times a week"}, {"heading": "Growing Out", "text": "Fry grow steadily on frequent feeding. Juveniles start showing color around 6 to 8 weeks, and adult size comes at roughly 4 to 6 months.\n\nBecause imbellis males are relatively peaceful, many breeders grow them out together longer than domestic bettas, but watch for nipping and separate males if fights break out.\n\nGrow-out tanks should be at least 10 gallons for a typical spawn, ideally 20. Feed 3 to 4 times a day and do larger water changes, 25 to 30 percent weekly, once the fry are past a month old. Sort out larger fish if smaller siblings are falling behind."}, {"heading": "Common Mistakes", "text": "- Leaving the tank uncovered, which can harm fry as their labyrinth organ develops\n- Starting with baby brine shrimp, which is too large for newly free swimming fry\n- Big water changes that chill or shock the fry\n- Leaving the female in with the male after spawning\n- Hard, alkaline water that discourages spawning"}]$g$::jsonb, $g$[{"q": "Is Betta imbellis easy to breed?", "a": "It breeds readily if the pair is well fed and the water is soft and warm. The fry are small and need microscopic foods at first."}, {"q": "How do you tell male and female Betta imbellis apart?", "a": "Males have blue-green iridescence and a red crescent at the edge of the tail. Females are paler and usually show bars."}, {"q": "How long do Betta imbellis eggs take to hatch?", "a": "Usually about 24 to 48 hours at around 80°F, then the fry stay at the nest for a few days."}, {"q": "Can Betta imbellis males live together?", "a": "They are calmer than domestic bettas, but mature males can still fight. A large planted tank helps, but separation is safest."}]$g$::jsonb, $g$Open your log before the spawn and photograph the pair in the breeding tank with your challenge code card. A clear photo of the bubble nest with eggs makes a good stage 2 entry.$g$),
  ($g$emerald-betta$g$, $g$4b9c7b41-8a33-47a5-83e3-e37822f8d353$g$::uuid, null, null, $g$How to Breed Emerald Bettas (Betta smaragdina)$g$, $g$Betta smaragdina is a wild bubble nesting betta. Pair them carefully, keep water warm and calm, and raise tiny fry on live foods. Moderate difficulty.$g$, $g$Betta smaragdina, the emerald betta, is a wild relative of the Siamese fighter with shimmering green-blue scales on the males. It spawns like other bubble nesting bettas, with the male building a nest and guarding the eggs. Breeding is very doable with a good pair, but males can be rough on females and the fry need very small live foods at first.$g$, $g${"method": "Bubble nester", "sexing": "Males show green-blue iridescent scales and longer, colorful fins; females are duller and often barred", "group": "One pair", "breeding_tank": "10 gallon, shallow water, floating plants, cover for the female, tight lid", "conditioning": "1 to 2 weeks of live or frozen foods like brine shrimp, daphnia and bloodworms", "trigger": "Warm, still water around 79 to 82°F, soft and slightly acidic, with floating cover", "spawn": "Commonly reported from several dozen to about 200 eggs; varies by pair", "eggs": "Hatch in about 24 to 48 hours around 80°F; male tends the nest", "fry": "Free swimming about 2 to 3 days after hatching; very small", "first_foods": "Infusoria or paramecium, then microworms and baby brine shrimp after about a week", "grow_out": "Juvenile coloring at 6 to 8 weeks; adult size in roughly 4 to 6 months", "parents": "Male guards eggs; remove female after spawning and male once fry swim freely"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 gallon tank is a good size for one pair. Keep the water around 6 to 8 inches deep, with floating plants for the nest and plenty of cover lower down for the female.\n\nAim for 79 to 82°F and soft, slightly acidic water. A small sponge filter on very gentle flow is enough. Cover the tank tightly, since bettas can jump and fry need warm, humid air above the water.\n\nLeaf litter and a few floating plants help keep the water soft and slightly tinted, which many wild betta keepers find encourages spawning. Keep the tank in a quiet spot with little foot traffic."}, {"heading": "Choosing and Conditioning a Pair", "text": "Males are the showier fish, with iridescent green and blue scales and longer fins. Females are duller, often show bars, and have a rounder belly and visible egg spot when ready to spawn.\n\nCondition both fish separately for 1 to 2 weeks with live or frozen foods. Introduce the female carefully, ideally with a divider first, because smaragdina males can be rough. Remove her right away if she is being chased hard."}, {"heading": "Spawning: What You Will See", "text": "The male builds a bubble nest at the surface, often under a leaf or among floating plants. He displays and leads the female to the nest, then wraps around her in the classic betta embrace. Eggs drop and he collects them into the nest.\n\nThe spawn can take a few hours. Clutches are commonly reported from several dozen to about 200 eggs, though this varies a lot by pair."}, {"heading": "Eggs and the Nest", "text": "Remove the female after spawning. The male will guard the nest and pick up falling eggs.\n\nEggs usually hatch in about 24 to 48 hours at around 80°F. Fry hang from the nest with yolk sacs for a couple of days. When they start swimming horizontally, remove the male.\n\nAvoid disturbing the nest in these days. Bettas can eat eggs if stressed. Keep the light low and avoid water changes until the fry are free swimming."}, {"heading": "Raising the Fry", "text": "- Week 1: infusoria or paramecium several times a day\n- Week 2: microworms and newly hatched baby brine shrimp\n- Weeks 3 to 4: mostly baby brine shrimp plus fine crushed foods\n- Keep the lid on so the labyrinth organ develops in warm, humid air\n- Small water changes of 10 to 20 percent a few times a week\n\nStart an infusoria culture a week before you expect a spawn so it is ready when the fry need it."}, {"heading": "Growing Out", "text": "Fry grow steadily with frequent feeding. Juveniles start to color up around 6 to 8 weeks.\n\nAs they mature, males may start sparring. Separate males that fight. Adult size usually comes at around 4 to 6 months.\n\nGrow-out tanks should be at least 10 gallons for a typical spawn, ideally 20. Feed 3 to 4 times a day and do larger water changes, 25 to 30 percent weekly, once the fry are past a month old. Sort out larger fish if smaller siblings are falling behind.\n\nEmerald bettas are a wild species. Keep the line pure and avoid mixing it with domestic bettas or other species, so the fry you raise are true Betta smaragdina."}, {"heading": "Common Mistakes", "text": "- Introducing the pair too quickly and letting the male injure the female\n- Starting fry on baby brine shrimp before they can eat it\n- Leaving the tank uncovered while fry develop their labyrinth organ\n- Big, cold water changes\n- Letting the male stay too long once fry are free swimming"}]$g$::jsonb, $g$[{"q": "Is Betta smaragdina a bubble nester?", "a": "Yes. The male builds a bubble nest and guards the eggs, like the Siamese fighting fish."}, {"q": "How do you sex emerald bettas?", "a": "Males have bright green-blue iridescent scales and longer fins. Females are duller, often barred, and show an egg spot when ready."}, {"q": "How long do emerald betta eggs take to hatch?", "a": "About 24 to 48 hours at around 80°F, then the fry stay near the nest for a couple of days."}, {"q": "Are emerald bettas aggressive?", "a": "Males can be rough, especially toward females and other males. Give cover and watch the pair closely."}]$g$::jsonb, $g$Open your log and photograph the pair in the breeding tank with your challenge code card before the spawn. A clear shot of eggs in the bubble nest is a good stage 2 photo.$g$),
  ($g$honey-gourami$g$, $g$1ca67e97-5b74-40f9-99fb-1a9c29bb58ca$g$::uuid, $g$honey-gourami$g$, null, $g$How to Breed Honey Gouramis: Bubble Nests and Tiny Fry$g$, $g$Honey gouramis are peaceful bubble nesters. A warm, shallow tank triggers spawning, but the tiny fry need infusoria at first. A good step up for beginners.$g$, $g$Honey gouramis are one of the gentlest gouramis to breed. The male turns a rich honey orange with a dark throat, builds a bubble nest and guards the eggs. Getting a spawn is often easy in a warm, quiet tank. The challenge is raising the tiny fry, which need microscopic food at first and a covered tank while their labyrinth organ develops.$g$, $g${"method": "Bubble nester", "sexing": "Breeding males turn orange-gold with a dark blue-black throat; females paler with a brown stripe", "group": "One pair", "breeding_tank": "10 gallon, 6 to 8 inches of water, floating plants, sponge filter, tight lid", "conditioning": "1 to 2 weeks of live or frozen foods like brine shrimp, daphnia and bloodworms", "trigger": "Warm, still water around 80 to 82°F with floating cover", "spawn": "Commonly reported from several dozen up to about 300 eggs", "eggs": "Hatch in about 24 to 36 hours around 80°F; male guards the nest", "fry": "Free swimming about 2 to 3 days after hatching; very tiny", "first_foods": "Infusoria or paramecium, then microworms and baby brine shrimp after about a week", "grow_out": "About 1 inch by 2 to 3 months; adult size in around 6 months", "parents": "Male guards eggs; remove female after spawning and male once fry swim freely"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 gallon tank is ideal. Lower the water to about 6 to 8 inches and add floating plants for the male to anchor a nest. Use a small sponge filter with very gentle flow, because strong currents break up bubble nests.\n\nHoney gouramis do fine in the 72 to 82°F range, but for spawning raise the temperature to around 80 to 82°F. Keep the tank covered so the air above the water stays warm and humid.\n\nSoft to medium water is fine, and the library range of pH 6 to 7.5 works well for spawning. A few floating plants like water sprite or salvinia give the male a place to build and help hold infusoria for the fry."}, {"heading": "Choosing and Conditioning a Pair", "text": "Breeding males are easy to spot: they turn a deep honey orange with a dark blue-black throat and chest. Females are paler with a brownish horizontal stripe and get rounder when full of eggs.\n\nCondition the pair for 1 to 2 weeks with live and frozen foods like brine shrimp, daphnia and bloodworms. Honey gouramis are peaceful, but still give the female hiding places."}, {"heading": "Spawning: What You Will See", "text": "The male builds a bubble nest, often smaller and looser than a betta nest. He displays to the female and leads her under the nest. They embrace, eggs are released and float up or are carried to the nest by the male.\n\nSpawning repeats over a few hours. Spawns are commonly reported from several dozen up to about 300 eggs.\n\nBefore spawning, the male often swims in front of the female with his fins spread, then turns back toward the nest. If the female is not ready, he may chase her. Give her plants to hide in and watch closely the first day."}, {"heading": "Eggs and the Nest", "text": "Remove the female after spawning. The male guards the nest and gathers stray eggs.\n\nEggs usually hatch in about 24 to 36 hours around 80°F. Fry hang near the nest for a few days. Once they start swimming freely, remove the male, since he may eat them.\n\nAvoid big water changes while the male guards the nest. Stress and sudden changes can make males eat eggs. Keep the room quiet and the tank lid on."}, {"heading": "Raising the Fry", "text": "Honey gourami fry are very small, which is why many first spawns fail.\n\n- Week 1: infusoria or paramecium cultures several times a day\n- Week 2: start microworms and newly hatched baby brine shrimp\n- Weeks 3 to 4: baby brine shrimp and fine crushed foods\n- Keep the lid on while the labyrinth organ develops over the first few weeks\n- Small water changes of 10 to 20 percent a few times a week\n\nStart an infusoria culture a week before you expect a spawn so it is ready when the fry need it."}, {"heading": "Growing Out", "text": "Feed small amounts several times a day. Fry reach about an inch by 2 to 3 months and adult size around 6 months.\n\nSort by size if some grow faster, because the larger fry can outcompete the small ones for food.\n\nGrow-out tanks should be at least 10 gallons for a typical spawn. Feed 3 to 4 times a day and do larger water changes, 25 to 30 percent weekly, once the fry are past a month old."}, {"heading": "Common Mistakes", "text": "- Starting with food that is too big for the newly free swimming fry\n- Leaving the tank uncovered\n- Strong filter flow that destroys the nest\n- Leaving the male in too long\n- Big water changes that drop the temperature"}]$g$::jsonb, $g$[{"q": "How do you tell a male honey gourami from a female?", "a": "Breeding males turn bright orange-gold with a dark throat. Females are paler with a brown stripe."}, {"q": "Do honey gouramis build bubble nests?", "a": "Yes. The male builds a bubble nest and guards the eggs and young fry."}, {"q": "How long do honey gourami eggs take to hatch?", "a": "About 24 to 36 hours at around 80°F."}, {"q": "What do honey gourami fry eat?", "a": "Start with infusoria or paramecium, then move to microworms and baby brine shrimp after about a week."}]$g$::jsonb, $g$Open your log and photograph the pair in the breeding tank with your challenge code card before they spawn. A photo of the bubble nest with eggs works well for stage 2.$g$),
  ($g$pearl-gourami$g$, $g$9fbf4e1e-6d18-419f-8427-156e43e45a24$g$::uuid, $g$pearl-gourami$g$, null, $g$How to Breed Pearl Gouramis: Nests, Eggs and Fry Care$g$, $g$Pearl gouramis are bubble nesters with large spawns. Give a warm, shallow tank, then raise very small fry on infusoria. Rewarding with moderate effort.$g$, $g$Pearl gouramis are among the most beautiful bubble nesters, and breeding males put on a striking show with deep orange-red throats. They usually spawn readily in a warm, calm tank, and spawns are large. The main challenge is feeding hundreds of very small fry in their first couple of weeks.$g$, $g${"method": "Bubble nester", "sexing": "Males have a longer, pointed dorsal fin and orange-red throat when breeding; females rounder fins, paler", "group": "One pair", "breeding_tank": "20 to 30 gallon, lowered water, floating plants, sponge filter, tight lid", "conditioning": "2 weeks of live or frozen foods like brine shrimp, bloodworms and daphnia", "trigger": "Warm, still water around 80 to 82°F with floating plants", "spawn": "Several hundred eggs is common; large spawns are reported", "eggs": "Hatch in about 24 to 48 hours around 80°F; male guards the nest", "fry": "Free swimming about 2 to 3 days after hatching; very small", "first_foods": "Infusoria or paramecium, then microworms and baby brine shrimp after about a week", "grow_out": "About 1 inch by 2 to 3 months; adult size in about 6 to 9 months", "parents": "Male guards eggs; remove female after spawning and male once fry swim freely"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "Pearl gouramis grow to around 4 to 4.5 inches, so a 20 to 30 gallon tank is a good breeding size. Lower the water to about 8 inches and add plenty of floating plants.\n\nThe library range is 75 to 82°F; for spawning aim for the warm end, around 80 to 82°F. Use a gentle sponge filter and keep a tight lid on the tank.\n\nPearl gouramis spawn in soft to medium water. The library range is pH 6 to 8, but the soft, slightly acidic side, around pH 6.5 to 7, tends to work best. Floating plants also help the male anchor his nest and hold infusoria for the fry."}, {"heading": "Choosing and Conditioning a Pair", "text": "Males have a longer, more pointed dorsal fin and a longer anal fin with extended rays. When breeding, their throat and chest turn bright orange-red. Females have a rounder dorsal fin, paler colors and fill out with eggs.\n\nCondition the pair for about two weeks with live and frozen foods. A healthy, well fed female will look noticeably rounder.\n\nPick fish that are at least 3 inches long and look healthy, with full fins. Young or small females often produce weak, small spawns. A pair that has grown up together is often calmer during spawning."}, {"heading": "Spawning: What You Will See", "text": "The male builds a large bubble nest, often anchored to floating plants. He displays with spread fins and leads the female under the nest. They embrace and release eggs, which float up into the nest.\n\nSpawning can last a few hours and often produces several hundred eggs.\n\nThe male may chase the female before she is ready. Give her plenty of cover, and remove her if she is being harassed. Once she is ready, the spawning embrace looks much like a betta's."}, {"heading": "Eggs and the Nest", "text": "Remove the female after spawning. The male guards the nest closely.\n\nEggs usually hatch in about 24 to 48 hours around 80°F. Fry stay near the nest for a few days. Remove the male once the fry are swimming freely.\n\nDo not disturb the nest while the male guards it. Keep the light low and avoid water changes for these few days. Stress can cause the male to eat eggs."}, {"heading": "Raising the Fry", "text": "- Week 1: infusoria or paramecium several times a day\n- Week 2: add microworms and newly hatched baby brine shrimp\n- Weeks 3 to 4: mainly baby brine shrimp and finely crushed foods\n- Keep the lid on while the labyrinth organ develops\n- Small, frequent water changes of 10 to 20 percent at matched temperature\n\nStart an infusoria culture a week before you expect a spawn. A large spawn can eat a lot, and running out in the first week is the most common reason fry are lost."}, {"heading": "Growing Out", "text": "Large spawns mean lots of mouths. Spread the fry across extra tanks as they grow so they do not stunt from crowding.\n\nFry reach about an inch by 2 to 3 months. Adult size can take around 6 to 9 months.\n\nGrow-out tanks should be at least 20 gallons. Feed 3 to 4 times a day and do larger water changes, 25 to 30 percent weekly, once the fry are past a month old. Sort out larger fish if smaller siblings are falling behind."}, {"heading": "Common Mistakes", "text": "- Too little infusoria for the size of the spawn\n- Crowding hundreds of fry in one small tank\n- Uncovered tanks and cold air over the water\n- Strong filter flow that breaks the nest\n- Leaving the male in after the fry are swimming"}]$g$::jsonb, $g$[{"q": "How can you tell a male pearl gourami from a female?", "a": "Males have a longer, pointed dorsal fin and an orange-red throat when breeding. Females have rounder fins and paler colors."}, {"q": "How many eggs do pearl gouramis lay?", "a": "Several hundred eggs is common, and large spawns are reported."}, {"q": "How long do pearl gourami eggs take to hatch?", "a": "Usually about 24 to 48 hours at around 80°F."}, {"q": "Do pearl gouramis eat their fry?", "a": "The male guards the eggs, but adults may eat fry once they are free swimming, so remove the parents."}]$g$::jsonb, $g$Open your log and photograph the pair in the breeding tank with your challenge code card before spawning. A clear photo of eggs in the bubble nest makes a strong stage 2 entry.$g$),
  ($g$black-ruby-barb$g$, $g$7f4398c4-e758-4969-9ffd-4ab9b1f0bd2d$g$::uuid, $g$black-ruby-barb$g$, null, $g$How to Breed Black Ruby Barbs: Spawning Tank to Fry$g$, $g$Black ruby barbs are egg scatterers that eat their eggs. Condition a pair, spawn over mesh or moss, remove the adults, and raise fry on tiny foods.$g$, $g$Black ruby barbs are a great first egg scatterer. When a male is ready to spawn, his front half turns a deep ruby red, which is a real treat to watch. They scatter eggs over plants and will eat them right away, so the key is a separate spawning tank and removing the parents quickly. Fry are small but grow well with good feeding.$g$, $g${"method": "Egg scatterer", "sexing": "Males turn deep red on head and front body when spawning; females paler, rounder bellied", "group": "One pair or 1 male to 2 females", "breeding_tank": "10 gallon, mesh or marbles on bottom, java moss or spawning mop, sponge filter", "conditioning": "1 to 2 weeks of live and frozen foods; condition sexes apart if possible", "trigger": "Soft, slightly acidic water at the warm end of the range, often at first morning light", "spawn": "Often a hundred or more eggs; varies by female size", "eggs": "Hatch in about 24 to 48 hours at around 77°F; adhesive, scattered among plants", "fry": "Free swimming a few days after hatching (often 2 to 4); small", "first_foods": "Infusoria or powdered fry food, then baby brine shrimp after about a week", "grow_out": "About 1 inch by 2 to 3 months; full color in about 6 months", "parents": "Adults eat eggs; remove them right after spawning"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 gallon tank works well. Cover the bottom with mesh, marbles or a thick layer of java moss so eggs can fall where the adults cannot reach them. Add a spawning mop or a clump of fine leaved plants.\n\nBlack ruby barbs come from soft, slightly acidic streams in Sri Lanka. The library range is 72 to 79°F and pH 6 to 7. For spawning, aim for the warm end, around 77 to 79°F, with soft water toward pH 6.5. Use a gentle sponge filter."}, {"heading": "Choosing and Conditioning a Pair", "text": "Males in breeding condition turn a deep red across the head and front of the body, with the black bars getting darker. Females are paler and rounder.\n\nCondition the fish for 1 to 2 weeks on live and frozen foods like brine shrimp, daphnia and bloodworms. Keeping males and females apart during conditioning often leads to a stronger spawn when you put them together."}, {"heading": "Spawning: What You Will See", "text": "Move a pair or a male with two females into the spawning tank in the evening. Spawning often begins at first light the next morning.\n\nThe male chases the female through the plants, and the pair release eggs and sperm in short bursts. The adhesive eggs stick to the plants or fall to the bottom. A spawn often produces a hundred or more eggs.\n\nIf nothing happens in a couple of days, try a partial water change with slightly softer water. Pairs that have not spawned within 3 to 4 days are often better returned to conditioning and tried again in a week."}, {"heading": "Eggs and Fungus Prevention", "text": "Remove the adults as soon as spawning is finished, because they will eat the eggs.\n\nEggs usually hatch in about 24 to 48 hours around 77°F. Keep the tank dimly lit. Remove any white, fuzzy eggs, which are infertile or fungused. A few alder cones or a small amount of methylene blue in a separate hatching container can help reduce fungus.\n\nFertile eggs stay clear and slowly darken as the fry develop."}, {"heading": "Raising the Fry", "text": "- Days 1 to 4: fry hang on the glass and plants living off their yolk sacs\n- Days 4 to 10: infusoria or powdered fry food several times a day\n- From about day 7 to 10: newly hatched baby brine shrimp\n- Weeks 3 onward: baby brine shrimp plus crushed flake\n- Small water changes of 10 to 20 percent every few days\n\nKeep the fry tank at the same temperature as spawning. Add a few snails or a sponge filter cleaning routine to deal with uneaten food, and use a light sponge-covered intake so fry are not pulled in."}, {"heading": "Growing Out", "text": "Fry grow steadily on frequent feedings. They reach about an inch by 2 to 3 months and show adult color at around 6 months.\n\nMove them into a larger grow-out tank as they grow and keep up regular water changes.\n\nA 20 gallon grow-out tank with weekly 25 to 30 percent water changes works well. Feed 3 to 4 times a day. Black ruby barbs are schooling fish, so they do best raised in a group. Keep the stock pure and avoid crossing it with other barbs."}, {"heading": "Common Mistakes", "text": "- Leaving the adults in after spawning\n- No mesh or moss to protect eggs\n- Bright light on the eggs, which encourages fungus\n- Feeding baby brine shrimp too early\n- Hard, alkaline water that reduces spawning success"}]$g$::jsonb, $g$[{"q": "How do you tell a male black ruby barb from a female?", "a": "Breeding males turn deep red on the head and front body. Females are paler and rounder."}, {"q": "Do black ruby barbs eat their eggs?", "a": "Yes. Remove the adults as soon as spawning is done."}, {"q": "How long do black ruby barb eggs take to hatch?", "a": "Usually about 24 to 48 hours at around 77°F."}, {"q": "What water do black ruby barbs need to breed?", "a": "Soft, slightly acidic water around pH 6.5 and the warm end of their range works well."}]$g$::jsonb, $g$Open your log and photograph the pair or trio in the spawning tank with your challenge code card. For stage 2, a close photo of eggs on the moss or mesh works well.$g$),
  ($g$giant-danio$g$, $g$20f4a4c4-ffe5-4d84-9677-4f5ff2a33553$g$::uuid, $g$giant-danio$g$, null, $g$How to Breed Giant Danios: Egg Scattering Made Simple$g$, $g$Giant danios scatter eggs over plants and eat them if allowed. Use a long spawning tank, remove the adults, and raise fry on infusoria. Fairly easy.$g$, $g$Giant danios are active, shimmering fish that breed fairly easily once they are mature and well fed. Like other danios, they scatter eggs over plants and will eat them as soon as they can, so a dedicated spawning tank with plants or mesh pays off. Fry are small at first but grow quickly with good feeding.$g$, $g${"method": "Egg scatterer", "sexing": "Females deeper bodied and rounder; males slimmer and more vividly colored", "group": "One female with 1 or 2 males, or a small group", "breeding_tank": "20 gallon long, mesh or marbles, plenty of fine plants, gentle filter", "conditioning": "1 to 2 weeks of live and frozen foods with quality flake", "trigger": "Morning light after moving conditioned fish; a slightly cooler water change can help", "spawn": "Often a few hundred eggs from a mature female", "eggs": "Hatch in about 24 to 48 hours around 77°F", "fry": "Free swimming a few days after hatching, often 2 to 4", "first_foods": "Infusoria or powdered fry food, then baby brine shrimp after about a week", "grow_out": "About 1 inch by 2 to 3 months; adult size in about 6 to 9 months", "parents": "Adults eat eggs; remove them right after spawning"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "Giant danios grow to around 4 inches and are strong swimmers, so a 20 gallon long tank is a good breeding size. Cover the bottom with mesh or marbles and add lots of fine leaved plants or spawning mops.\n\nThe library range is 72 to 81°F and pH 6 to 8. Around 75 to 77°F with clean, well oxygenated water works well for spawning. A gentle sponge filter keeps the eggs safe.\n\nGiant danios are strong jumpers, especially during spawning chases. Keep a tight lid on the tank. Moderate oxygenation from a sponge filter keeps the water fresh without blowing eggs around.\n\nSome breeders spawn giant danios in a group of 6 or more in a larger tank planted heavily with fine leaved plants, then remove the adults after a day. This works, but a pair or trio in a smaller setup usually gives cleaner, easier to manage spawns."}, {"heading": "Choosing and Conditioning Fish", "text": "Females are deeper bodied and rounder, especially when full of eggs. Males are slimmer and often show brighter color.\n\nCondition the fish for 1 to 2 weeks on live and frozen foods. Many breeders separate males and females during conditioning, then put them together in the spawning tank.\n\nPick mature fish, usually at least 2.5 to 3 inches long. Young or underweight fish often fail to spawn or produce small, weak clutches. Females should look visibly rounder after conditioning."}, {"heading": "Spawning: What You Will See", "text": "Move a female with one or two males into the spawning tank in the evening. Spawning often starts at first light.\n\nThe males chase the female through the plants, and the eggs are scattered. A mature female can often release a few hundred eggs.\n\nSpawning often lasts a couple of hours. If nothing happens in 2 to 3 days, try a water change with water a few degrees cooler, or return the fish to conditioning and try again in a week."}, {"heading": "Eggs and Fungus Prevention", "text": "Remove the adults once spawning ends.\n\nEggs usually hatch in about 24 to 48 hours around 77°F. Keep the lighting dim and remove any fungused eggs. Clean water and good oxygen help.\n\nMany eggs fall to the bottom during the chase, which is why the mesh or marbles matter. Look for small clear eggs between the marbles and on the plants. Unfertilized eggs turn white within a day."}, {"heading": "Raising the Fry", "text": "- Days 1 to 4: fry live off their yolk sacs\n- Days 4 to 10: infusoria or powdered fry food\n- From about day 7: newly hatched baby brine shrimp\n- Weeks 3 onward: baby brine shrimp plus crushed flake\n- Small water changes of 10 to 20 percent every few days\n\nKeep the fry tank at the same temperature as spawning and cover the filter intake. Fry are small, so use a sponge filter only."}, {"heading": "Growing Out", "text": "Giant danio fry grow quickly and need room to swim. Move them into a larger tank as they grow.\n\nThey reach about an inch by 2 to 3 months, and adult size around 6 to 9 months.\n\nA 20 to 30 gallon grow-out tank with weekly 25 to 30 percent water changes works well. Feed 3 to 4 times a day. Raise them in a group, since they are schooling fish."}, {"heading": "Common Mistakes", "text": "- Leaving the adults in after spawning\n- A tank that is too small for these active swimmers\n- No mesh or plants to protect eggs\n- Overfeeding the fry tank and fouling the water\n- Skipping infusoria and going straight to brine shrimp\n- Using small, immature fish that are not ready to spawn"}]$g$::jsonb, $g$[{"q": "Do giant danios eat their eggs?", "a": "Yes. Use mesh or dense plants and remove the adults after spawning."}, {"q": "How do you tell male and female giant danios apart?", "a": "Females are deeper bodied and rounder. Males are slimmer and often brighter."}, {"q": "How long do giant danio eggs take to hatch?", "a": "Usually about 24 to 48 hours around 77°F."}, {"q": "How many eggs do giant danios lay?", "a": "A mature female can release a few hundred eggs in a spawn."}]$g$::jsonb, $g$Open your log and photograph the spawning group in the tank with your challenge code card. For stage 2, a clear photo of eggs on the mesh or plants works well.$g$),
  ($g$odessa-barb$g$, $g$9f958b23-2336-4b5c-a173-defc64e80eca$g$::uuid, $g$odessa-barb$g$, null, $g$How to Breed Odessa Barbs: Spawning, Eggs and Fry Care$g$, $g$Odessa barbs are egg scatterers that eat their eggs. Condition a pair, spawn over mesh or moss, remove adults, and raise fry on tiny foods. Fairly easy.$g$, $g$Odessa barbs are a lovely, underrated barb, and the males' bright red stripe makes them a joy to breed. They spawn like most barbs, scattering eggs among plants and then eating them, so a separate spawning tank is the way to go. With good conditioning and quick removal of the parents, they are a straightforward and rewarding project.$g$, $g${"method": "Egg scatterer", "sexing": "Males show a bright red stripe along the body; females paler, silver to yellowish, rounder", "group": "One pair or 1 male to 2 females", "breeding_tank": "10 gallon, mesh or marbles, java moss or spawning mop, sponge filter", "conditioning": "1 to 2 weeks of live and frozen foods; condition sexes apart if possible", "trigger": "Morning light after introducing conditioned fish; a fresh water change can help", "spawn": "Often a hundred or more eggs", "eggs": "Hatch in about 24 to 48 hours around 75°F", "fry": "Free swimming a few days after hatching, often 2 to 4", "first_foods": "Infusoria or powdered fry food, then baby brine shrimp after about a week", "grow_out": "About 1 inch by 2 to 3 months; adult color in around 6 months", "parents": "Adults eat eggs; remove them right after spawning"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 gallon tank is enough for a pair. Cover the bottom with mesh, marbles or java moss, and add a spawning mop or fine plants.\n\nThe library range is 70 to 79°F and pH 6 to 7.5. Around 74 to 77°F with clean, slightly soft water works well for spawning. Use a gentle sponge filter.\n\nA tight lid is a good idea, since spawning chases can be lively. Keep the lighting dim or use a few floating plants to soften it. Odessa barbs are fine at normal community water parameters, so you rarely need to change much.\n\nOdessa barbs come from Myanmar and are fairly hardy. Clean, well oxygenated water matters more than exact chemistry, and dim, natural lighting helps them settle quickly in a new tank."}, {"heading": "Choosing and Conditioning a Pair", "text": "Males have a bright red stripe along the body and dark spots on the fins. Females are paler, silver to yellowish, and rounder when full of eggs.\n\nCondition the fish for 1 to 2 weeks on live and frozen foods. Conditioning males and females separately often helps trigger a strong spawn.\n\nPick fish at least 1.5 inches long. The male's red stripe gets much brighter when he is ready to spawn, and females should look noticeably round in the belly after conditioning."}, {"heading": "Spawning: What You Will See", "text": "Introduce the pair or trio to the spawning tank in the evening. Spawning often starts at first light.\n\nThe male chases the female through the plants, and eggs are scattered. Spawns often produce a hundred or more eggs.\n\nSpawning often lasts a couple of hours. If nothing happens in 2 to 3 days, return the fish to conditioning and try again in a week. Adding a little fresh, slightly cooler water can help trigger spawning."}, {"heading": "Eggs and Fungus Prevention", "text": "Remove the adults right after spawning.\n\nEggs usually hatch in about 24 to 48 hours around 75°F. Keep lighting dim and remove fungused eggs.\n\nEggs are small and slightly sticky. They are easy to miss, so look carefully at the moss and mesh. Unfertilized eggs turn white within a day and should be removed to stop fungus spreading. Fertile eggs stay clear and darken as the fry develop."}, {"heading": "Raising the Fry", "text": "- Days 1 to 4: fry live off their yolk sacs\n- Days 4 to 10: infusoria or powdered fry food\n- From about day 7: newly hatched baby brine shrimp\n- Weeks 3 onward: baby brine shrimp plus crushed flake\n- Small water changes of 10 to 20 percent every few days\n\nKeep the fry tank at the same temperature as spawning. Cover the filter intake, and feed small amounts often rather than a lot at once."}, {"heading": "Growing Out", "text": "Fry grow steadily with frequent feedings. They reach about an inch by 2 to 3 months and show adult color around 6 months.\n\nMove them into a larger tank as they grow and keep the water clean.\n\nA 20 gallon grow-out tank with weekly 25 to 30 percent water changes works well. Feed 3 to 4 times a day. Raise them in a group, since they are schooling fish. Males start to show red as they mature."}, {"heading": "Common Mistakes", "text": "- Leaving the adults in the tank after spawning\n- No mesh or moss to protect eggs\n- Feeding baby brine shrimp too early\n- Bright light on eggs, which encourages fungus\n- Overfeeding and fouling the fry tank\n- Using a tank with strong flow that pushes eggs into the filter"}]$g$::jsonb, $g$[{"q": "How do you tell a male Odessa barb from a female?", "a": "Males show a bright red stripe along the body. Females are paler and rounder."}, {"q": "Do Odessa barbs eat their eggs?", "a": "Yes. Remove the adults right after spawning."}, {"q": "How long do Odessa barb eggs take to hatch?", "a": "Usually about 24 to 48 hours around 75°F."}, {"q": "Are Odessa barbs easy to breed?", "a": "They are fairly easy if well conditioned and given a separate spawning tank."}]$g$::jsonb, $g$Open your log and photograph the pair in the spawning tank with your challenge code card. For stage 2, a close photo of eggs on the moss or mesh works well.$g$),
  ($g$dwarf-hairgrass$g$, $g$c24979de-bb4e-4c9e-879a-048f36f42ea6$g$::uuid, null, null, $g$How to Propagate Dwarf Hairgrass: Runners and Carpeting$g$, $g$Dwarf hairgrass spreads by runners. Split a pot into small tufts, plant them an inch apart and give good light. Moderately easy, faster with CO2.$g$, $g$Dwarf hairgrass is one of the classic carpeting plants. It spreads by runners that send up new blades every so often, so a few small tufts can fill a foreground over time. It is more demanding than the rhizome plants: good light, nutrient rich substrate and ideally CO2 make a big difference in how quickly the carpet closes in.$g$, $g${"method": "Runners from small tufts", "light": "Moderate to high; low light gives slow, thin growth", "co2": "Strongly recommended for a dense carpet; possible without, but slow", "substrate": "Fine grained, nutrient rich substrate or root tabs", "timeline": "Runners often appear in 2 to 4 weeks; a carpet takes a few months", "first_steps": "Split a pot or clump into small tufts of a few blades each"}$g$::jsonb, $g$[{"heading": "How Dwarf Hairgrass Propagates", "text": "Dwarf hairgrass, Eleocharis parvula, is a small spikerush. It spreads by thin runners under or along the substrate, and new tufts of blades rise up from points along those runners. Over time the tufts link together into a carpet.\n\nWhat you propagate is really the runner network. Splitting a clump into many small tufts gives the runners lots of starting points.\n\nEleocharis parvula stays shorter than its larger cousin Eleocharis acicularis, usually just a few inches tall, which makes it popular for low carpets. Both spread the same way."}, {"heading": "What You Need", "text": "- A healthy pot or tissue culture cup of dwarf hairgrass\n- Fine grained substrate, nutrient rich or with root tabs\n- Moderate to high light\n- CO2 injection if possible\n- Long planting tweezers\n- Scissors\n\nWithout CO2 it can still spread, but expect slower, thinner growth and more risk of algae on the blades.\n\nTissue culture cups are popular because they are free of pests and algae. Potted plants work fine too but need careful cleaning before planting."}, {"heading": "Step by Step", "text": "Remove the plant from its pot and gently clean off rock wool or gel.\n\nSplit it into small tufts of a few blades each. Small tufts spread faster than big clumps.\n\nTrim the blades to about an inch if they are long, so light can reach the base.\n\nPlant each tuft with tweezers, pushing the roots in and leaving the blades above the substrate. Space tufts roughly an inch apart in a grid across the area you want to carpet.\n\nWork in a drained or half-drained tank if you can, which makes it much easier to see what you are doing. Refill slowly so the tufts are not knocked loose."}, {"heading": "Caring for New Plants", "text": "New plants often look sparse for the first couple of weeks while they root in. Keep the light on a steady schedule and do frequent water changes to limit algae while the plant establishes.\n\nOnce runners appear, usually within a few weeks in good conditions, the carpet fills in steadily. Trim the top to encourage dense, low growth, and vacuum gently above the carpet rather than through it.\n\nAmmonia from fresh nutrient substrate can trigger algae in the first weeks. Large water changes, 30 to 50 percent a couple of times a week for the first month, help a lot. Keep the light at 6 to 8 hours a day while it settles."}, {"heading": "Common Mistakes", "text": "- Planting big clumps instead of small tufts\n- Low light and no CO2 while expecting a fast carpet\n- Loose, coarse gravel that will not hold small tufts in place\n- Fish that dig and uproot young tufts\n- Not trimming, which lets older blades shade the base and turn brown"}, {"heading": "Keeping a Hairgrass Carpet Healthy", "text": "Once established, a hairgrass carpet needs regular trimming and consistent nutrients. Feed with root tabs or a nutrient rich substrate, and keep the CO2 steady if you use it.\n\nOld carpets sometimes build up dead material underneath. Thinning and replanting sections every so often keeps the carpet fresh and gives you more tufts for trading."}, {"heading": "Without CO2", "text": "Dwarf hairgrass can be grown in low-tech tanks, but expect it to spread slowly and stay sparser. Use a nutrient rich substrate or root tabs, moderate light and patience. Trimming less often helps, since the plant needs all its blades to feed itself.\n\nIf algae starts on the blades, reduce the light period and keep up with water changes. Many low-tech growers report a decent lawn after several months."}]$g$::jsonb, $g$[{"q": "Does dwarf hairgrass need CO2?", "a": "It can grow without it, but CO2 makes a big difference in how quickly and densely it carpets."}, {"q": "How long does dwarf hairgrass take to carpet?", "a": "It varies a lot by light and CO2, but expect a few months for a full carpet. Runners often show up within a few weeks."}, {"q": "How far apart should I plant dwarf hairgrass?", "a": "Small tufts spaced about an inch apart in a grid usually fill in well."}, {"q": "Why is my dwarf hairgrass turning brown?", "a": "Common causes are low light, lack of nutrients or CO2, or older blades shading the base. Trim and adjust conditions."}]$g$::jsonb, $g$For the plant program, take a dated overhead photo of the planted tufts on day one, then dated photos from the same angle every few weeks so the runners and new tufts are easy to see.$g$),
  ($g$bristlenose-pleco$g$, $g$19b8d3bf-492f-41b7-9e14-5503283e48bf$g$::uuid, $g$bristlenose-pleco$g$, null, $g$How to Breed Bristlenose Plecos (Step by Step)$g$, $g$Bristlenose plecos breed in caves, with the male guarding the eggs. Give a cave, wood and good food, and the fry are easy to raise. A great first catfish.$g$, $g$Bristlenose plecos are one of the most rewarding catfish to breed. A mature pair with a suitable cave often spawns on its own, and the male does the hard work of guarding and fanning the eggs. The fry are large enough to eat vegetables and wafers right away, so raising them is much easier than raising tiny egg scatterer fry.$g$, $g${"method": "Cave spawner", "sexing": "Mature males grow branched bristles across the snout; females have few or none, mostly along the edge", "group": "One pair or 1 male to 2 females", "breeding_tank": "20 to 30 gallon, caves sized to fit the male snugly, driftwood, good filtration", "conditioning": "2 to 3 weeks of vegetables, algae wafers and some protein like bloodworms", "trigger": "A large, slightly cooler water change, often after a period of heavy feeding", "spawn": "Commonly 20 to 100 or more eggs, depending on the female", "eggs": "Hatch in about 4 to 7 days at around 77°F; male fans and guards them", "fry": "Stay in the cave on their yolk sacs for several days, then emerge and graze", "first_foods": "Algae wafers, blanched zucchini, cucumber and biofilm on driftwood", "grow_out": "About 1 inch by roughly 2 months; 2 inches in about 3 to 5 months", "parents": "Male guards eggs and young fry; parents rarely harm fry"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 20 to 30 gallon tank works well for a pair or trio. Add caves that fit the male snugly, with one opening. Clay or ceramic caves are common. Add driftwood for grazing and good filtration, since plecos produce a lot of waste.\n\nThe library range is 72 to 80°F and pH 6 to 7.8. Bristlenose are adaptable and breed in a wide range of water, so you do not need to change much.\n\nMany breeders use several caves so the male can choose. A cave around 1.5 to 2 inches wide for an adult male, closed at one end, works well. Place caves in a quiet, slightly darker part of the tank."}, {"heading": "Choosing and Conditioning a Pair", "text": "Mature males have long, branched bristles across the snout. Females have few or no bristles, mostly along the edge of the head. Males are often a little larger with a broader head.\n\nCondition for 2 to 3 weeks with vegetables, algae wafers and some protein like bloodworms. A well fed female looks rounder from above.\n\nBristlenose usually mature by about 9 to 12 months. A pair with a well fed female will often spawn every few weeks once they start."}, {"heading": "Spawning: What You Will See", "text": "The male claims a cave and cleans it. When the female is ready, she joins him in the cave and lays a clump of sticky, orange eggs on the ceiling or walls.\n\nShe leaves, and the male stays to guard the eggs. Clutches commonly range from about 20 to 100 or more eggs depending on the female.\n\nYou may not see the spawning itself. Often the first sign is the female out and about again looking thinner, while the male stays tucked in the cave, fanning his tail at the entrance."}, {"heading": "Eggs and the Male's Care", "text": "The male fans the eggs with his fins and guards the cave entrance. Eggs usually hatch in about 4 to 7 days at around 77°F.\n\nAfter hatching, fry stay in the cave on their yolk sacs for several days. Avoid disturbing the cave, as a stressed male may abandon or eat eggs. A good, steady water flow helps.\n\nIf the male abandons the eggs or keeps pushing them out, some breeders hatch them in a container with gentle aeration. This is a backup plan, not the normal route."}, {"heading": "Raising the Fry", "text": "- Once they emerge, offer algae wafers and blanched zucchini or cucumber\n- Driftwood provides grazing surface and fiber\n- Feed small amounts several times a day\n- Remove leftover vegetables within a day\n- Regular water changes of 20 to 30 percent weekly\n\nFry need wood and plenty of greens. Adding a few pieces of driftwood to the grow-out tank helps with growth and digestion."}, {"heading": "Growing Out", "text": "Fry grow steadily on a vegetable based diet. They commonly reach about an inch by around 2 months and about 2 inches in roughly 3 to 5 months, depending on feeding and water changes.\n\nMove them to a grow-out tank if the breeding tank gets crowded, and keep driftwood in there too.\n\nBristlenose are prolific, so plan ahead. A good pair may spawn again every few weeks, and fry need room. Have a home for the young fish, whether through local clubs, auctions or fish stores."}, {"heading": "Common Mistakes", "text": "- Caves that are too large for the male to defend\n- Disturbing the cave while he guards eggs\n- Not enough driftwood or vegetables for the fry\n- Overcrowding and poor water quality\n- Underfeeding the female before spawning\n- Too few hiding places, which leaves the female stressed and less willing to spawn"}]$g$::jsonb, $g$[{"q": "How do you tell male and female bristlenose plecos apart?", "a": "Mature males have long, branched bristles across the snout. Females have few or none, mostly along the edge."}, {"q": "How long do bristlenose pleco eggs take to hatch?", "a": "Usually about 4 to 7 days at around 77°F."}, {"q": "Do bristlenose plecos eat their fry?", "a": "Usually not. The male guards the eggs and young fry, and parents rarely harm them."}, {"q": "What do bristlenose pleco fry eat?", "a": "Algae wafers, blanched vegetables and biofilm on driftwood."}]$g$::jsonb, $g$Open your log and photograph the pair and the cave in the tank with your challenge code card. For stage 2, a careful photo of the eggs in the cave with a flashlight works well.$g$),
  ($g$venezuelan-orange-cory$g$, $g$1ae580a1-0fc1-40b4-b870-314427ef0c3b$g$::uuid, $g$venezuelan-orange-cory$g$, null, $g$How to Breed Bronze Corydoras: T-Position Spawns to Fry$g$, $g$Bronze corydoras lay sticky eggs on glass after a cool water change. Move the eggs, prevent fungus and raise fry on microworms. Easy for a dedicated tank.$g$, $g$Bronze corydoras, including the Venezuelan orange form, are one of the easiest cories to breed. A cool water change often triggers spawning, and you will see the famous T-position as the female carries eggs in her pelvic fins and sticks them to the glass. The main tasks are moving the eggs away from hungry adults and keeping fungus at bay.$g$, $g${"method": "Egg depositor: sticks eggs to glass and plants", "sexing": "Females larger and rounder, especially viewed from above; males slimmer", "group": "2 males to 1 female, or a small group", "breeding_tank": "10 to 20 gallon, bare or sand bottom, sponge filter, some plants", "conditioning": "1 to 2 weeks of bloodworms, brine shrimp and sinking pellets", "trigger": "A large, slightly cooler water change, simulating a rainy season", "spawn": "Often dozens to a few hundred eggs over a spawning session", "eggs": "Hatch in about 3 to 5 days at around 75°F", "fry": "Live on yolk sacs for 2 to 3 days, then forage on the bottom", "first_foods": "Microworms, crushed sinking pellets, baby brine shrimp", "grow_out": "About 1 inch by 2 to 3 months", "parents": "Adults eat eggs; move eggs or adults after spawning"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 to 20 gallon tank works well. Use a bare bottom or fine sand, a sponge filter and a few plants.\n\nThe library range is 72 to 79°F and pH 6 to 7.5. Keep the water clean and well oxygenated.\n\nBronze corydoras are hardy and breed in a wide range of water. A sponge filter is best so eggs and fry are not pulled in. Some fine leaved plants or a spawning mop give the female more surfaces to choose from, though most still pick the glass."}, {"heading": "Choosing and Conditioning a Group", "text": "Females are larger and rounder, especially when viewed from above. Males are slimmer.\n\nA ratio of 2 males to 1 female works well. Condition for 1 to 2 weeks on bloodworms, brine shrimp and sinking pellets.\n\nThe Venezuelan orange is a color form of Corydoras aeneus. Breed it with the same form, not with other color forms or species, if you want true to type fry.\n\nMature fish, usually around 1.5 to 2 inches, breed best. A well conditioned female looks noticeably broader across the body when viewed from above."}, {"heading": "Spawning: What You Will See", "text": "After a large, slightly cooler water change, the males chase the female. A male positions himself across her head in the famous T-position.\n\nThe female holds eggs in her pelvic fins and then sticks them to the glass, plants or decor. This repeats over a few hours. Spawns often total dozens to a few hundred eggs.\n\nIf a spawn does not follow the water change, repeat it daily for a few days. Spawning often happens in the morning or after the water change, and a group can spawn every week or two once they get going."}, {"heading": "Eggs and Fungus Prevention", "text": "Adults will eat eggs, so move the eggs or the adults after spawning. Eggs can be rolled off the glass gently with a finger or razor blade.\n\nEggs usually hatch in about 3 to 5 days around 75°F. Remove fungused eggs promptly and keep gentle aeration nearby. Some breeders use a small amount of methylene blue in a separate hatching container.\n\nEggs are about the size of a pinhead, clear at first and then darken. Unfertilized eggs turn white within a day or two. A small hatching container with an airstone, kept in the main tank to stay at the same temperature, works well."}, {"heading": "Raising the Fry", "text": "- Days 1 to 3: fry live on their yolk sacs\n- Days 3 to 10: microworms and crushed sinking foods\n- From about week 2: baby brine shrimp\n- Keep the bottom clean to prevent bacterial problems\n- Small water changes of 10 to 20 percent every few days\n\nCory fry are sensitive to dirty substrate. Siphon uneaten food daily and avoid deep gravel in the fry tank."}, {"heading": "Growing Out", "text": "Fry grow steadily on frequent small feedings. They reach about an inch by 2 to 3 months.\n\nA bare bottom tank makes it easier to keep clean during grow-out.\n\nA 20 gallon grow-out tank with weekly 25 to 30 percent water changes works well. Feed 3 to 4 times a day with crushed pellets and baby brine shrimp. Raise them in a group, since corydoras are social.\n\nThe orange coloring often shows within the first few weeks and deepens as the fry grow. Juveniles can join a community tank once they are too large to be eaten, usually around an inch."}, {"heading": "Common Mistakes", "text": "- Leaving eggs with the adults\n- Not removing fungused eggs quickly\n- Dirty bottoms that harm the fry\n- Overfeeding\n- Skipping the cool water change trigger"}]$g$::jsonb, $g$[{"q": "How do corydoras breed?", "a": "They use a T-position. The female carries eggs in her pelvic fins and sticks them to surfaces."}, {"q": "How long do bronze corydoras eggs take to hatch?", "a": "Usually about 3 to 5 days around 75°F."}, {"q": "Do corydoras eat their eggs?", "a": "Yes. Move the eggs or the adults after spawning."}, {"q": "What triggers corydoras to spawn?", "a": "A large, slightly cooler water change often triggers spawning."}]$g$::jsonb, $g$Open your log and photograph the group in the breeding tank with your challenge code card. For stage 2, a clear photo of eggs on the glass works well.$g$),
  ($g$peppered-cory$g$, $g$e4d60285-396c-4995-b92c-19ca1fd069eb$g$::uuid, $g$peppered-cory$g$, null, $g$How to Breed Peppered Corydoras: Cool Water and Sticky Eggs$g$, $g$Peppered corydoras spawn in cooler water after a big cool water change. Move the eggs, prevent fungus and raise fry on microworms. Easy with a dedicated tank.$g$, $g$Peppered corydoras are one of the classic catfish to breed, and they prefer cooler water than many tropical fish. A cool water change often triggers spawning, and the female sticks eggs to the glass in batches. Like bronze cories, they will eat eggs, so moving the eggs and watching for fungus are the main jobs.$g$, $g${"method": "Egg depositor: sticks eggs to glass and plants", "sexing": "Females larger and rounder; males slimmer with a taller dorsal fin", "group": "2 males to 1 female, or a small group", "breeding_tank": "10 to 20 gallon, bare or sand bottom, sponge filter, some plants", "conditioning": "1 to 2 weeks of bloodworms, brine shrimp and sinking pellets", "trigger": "A large cool water change, simulating a rainy season", "spawn": "Often dozens to a few hundred eggs over a spawning session", "eggs": "Hatch in about 4 to 6 days at around 72°F", "fry": "Live on yolk sacs for 2 to 3 days, then forage on the bottom", "first_foods": "Microworms, crushed sinking pellets, baby brine shrimp", "grow_out": "About 1 inch by 2 to 3 months", "parents": "Adults eat eggs; move eggs or adults after spawning"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 to 20 gallon tank works well. Use a bare bottom or fine sand, a sponge filter and some plants.\n\nThe library range is 64 to 75°F and pH 6 to 7.5. Peppered cories like cooler water than many tropicals, so do not overheat the tank.\n\nA sponge filter is best so eggs and fry are not pulled in. Fine leaved plants or a spawning mop give the female surfaces to choose from, though most eggs end up on the glass. Room temperature works in many homes, but avoid letting the water get above the mid 70s °F."}, {"heading": "Choosing and Conditioning a Group", "text": "Females are larger and rounder. Males are slimmer and often have a taller dorsal fin.\n\nCondition for 1 to 2 weeks with bloodworms, brine shrimp and sinking pellets.\n\nMature fish, usually around 2 inches, breed best. A well conditioned female looks noticeably broader across the body when viewed from above. Use a group with more males than females, such as 2 males to 1 female."}, {"heading": "Spawning: What You Will See", "text": "A large cool water change often triggers spawning. Males chase the female and use the T-position.\n\nShe sticks eggs to the glass and plants in batches. Spawns often total dozens to a few hundred eggs.\n\nUse water a few degrees cooler than the tank for the water change, and change a large amount, often 30 to 50 percent. Some breeders also increase aeration. If nothing happens, repeat daily for a few days. Peppered cories often spawn in the morning, and a group can spawn every week or two once they start."}, {"heading": "Eggs and Fungus Prevention", "text": "Move the eggs or the adults after spawning. Eggs usually hatch in about 4 to 6 days at around 72°F.\n\nRemove fungused eggs promptly and keep gentle aeration nearby.\n\nEggs are about the size of a pinhead, clear at first, then darken. Unfertilized eggs turn white within a day or two. A small hatching container with an airstone, kept in the main tank to hold temperature, works well. Some breeders add a small amount of methylene blue to the hatching container."}, {"heading": "Raising the Fry", "text": "- Days 1 to 3: fry live on their yolk sacs\n- Days 3 to 10: microworms and crushed sinking foods\n- From about week 2: baby brine shrimp\n- Keep the bottom clean\n- Small water changes every few days\n\nCory fry are sensitive to dirty substrate. Siphon uneaten food daily and avoid deep gravel. A bare bottom or thin sand layer makes cleaning easier. Feed small amounts 3 to 4 times a day.\n\nKeep the fry at the same cool temperature as the breeding tank, around 70 to 72°F, and avoid sudden temperature swings."}, {"heading": "Growing Out", "text": "Fry reach about an inch by 2 to 3 months. Keep the water cool and clean.\n\nA 20 gallon grow-out tank with weekly 25 to 30 percent water changes works well. Feed with crushed pellets and baby brine shrimp. Raise them in a group, since corydoras are social. Fry develop their peppered spots as they grow.\n\nPeppered corydoras are also bred as albino and long-finned forms. These breed the same way, though long-finned fish need clean water to keep their fins healthy. Keep forms separate if you want true to type fry."}, {"heading": "Common Mistakes", "text": "- Keeping them too warm\n- Leaving eggs with adults\n- Not removing fungused eggs\n- Dirty bottoms\n- Overfeeding\n- Expecting warm tropical temperatures to trigger spawning, when cooler water works better for this species\n- Moving eggs into water much warmer than the tank they came from"}]$g$::jsonb, $g$[{"q": "Do peppered corydoras like cold water?", "a": "They prefer cooler water than many tropicals, around 64 to 75°F."}, {"q": "How long do peppered cory eggs take to hatch?", "a": "Usually about 4 to 6 days at around 72°F."}, {"q": "Do peppered corydoras eat their eggs?", "a": "Yes. Move the eggs or adults after spawning."}, {"q": "How do you tell male and female peppered cories apart?", "a": "Females are larger and rounder. Males are slimmer with a taller dorsal fin."}]$g$::jsonb, $g$Open your log and photograph the group in the breeding tank with your challenge code card. For stage 2, a clear photo of eggs on the glass works well.$g$),
  ($g$black-skirt-tetra$g$, $g$08ab9b5d-a53d-424f-9ad7-851404ed5542$g$::uuid, $g$black-skirt-tetra$g$, null, $g$How to Breed Black Skirt Tetras: Spawning and Fry Guide$g$, $g$Black skirt tetras are prolific egg scatterers. Spawn a pair over plants or mesh, remove adults, and raise fry on infusoria then brine shrimp. Fairly easy.$g$, $g$Black skirt tetras are one of the easier tetras to breed and can produce large spawns. They scatter eggs among plants and will eat them, so a separate spawning tank and quick removal of the adults are key. Fry are small but hardy, and with steady feeding you can raise a big batch.$g$, $g${"method": "Egg scatterer", "sexing": "Females rounder and deeper bodied; males slimmer, with a broader anal fin", "group": "One pair or 1 male to 2 females", "breeding_tank": "10 to 20 gallon, mesh or marbles, fine plants or spawning mop, sponge filter", "conditioning": "1 to 2 weeks of live and frozen foods", "trigger": "Soft, slightly acidic water and morning light after introducing the pair", "spawn": "Often several hundred eggs", "eggs": "Hatch in about 24 to 36 hours around 77°F", "fry": "Free swimming a few days after hatching, often 2 to 4", "first_foods": "Infusoria or powdered fry food, then baby brine shrimp after about a week", "grow_out": "About 1 inch by 2 to 3 months; adult size in about 6 months", "parents": "Adults eat eggs; remove them right after spawning"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 to 20 gallon tank works well. Use mesh, marbles or java moss on the bottom and add fine leaved plants or a spawning mop.\n\nThe library range is 70 to 80°F and pH 6 to 7.5. For spawning, aim for soft, slightly acidic water around pH 6.5 and about 77 to 79°F. Use a gentle sponge filter and dim lighting.\n\nBlack skirts are not fussy about water for everyday keeping, but soft water does improve egg hatching. If your tap water is hard, mixing in some RO or rain water for the spawning tank is a common approach.\n\nBlack skirts are strong swimmers and can be a little nippy. In the spawning tank they will focus on each other, but keep them alone, with no other fish, to protect the eggs."}, {"heading": "Choosing and Conditioning a Pair", "text": "Females are rounder and deeper bodied, especially when full of eggs. Males are slimmer and often have a broader anal fin.\n\nCondition the fish for 1 to 2 weeks on live and frozen foods. Healthy, well fed fish give the best spawns.\n\nChoose fish that are at least an inch and a half long and healthy, with full fins. Mature fish around a year old spawn best. Condition males and females separately for a stronger spawn."}, {"heading": "Spawning: What You Will See", "text": "Introduce the pair or trio to the spawning tank in the evening. Spawning often happens the next morning.\n\nThe male chases the female through the plants, and eggs are scattered. Spawns can be large, often several hundred eggs.\n\nSpawning often lasts a couple of hours. If nothing happens in 2 to 3 days, try a partial water change with slightly softer water, or return the fish to conditioning and try again in a week."}, {"heading": "Eggs and Fungus Prevention", "text": "Remove the adults right after spawning.\n\nEggs usually hatch in about 24 to 36 hours around 77°F. Keep the tank dim and remove fungused eggs.\n\nEggs are small and slightly sticky. Check the plants and mesh carefully. Unfertilized eggs turn white within a day and should be removed. Fertile eggs stay clear. Many breeders keep the tank dark until the eggs hatch, which also helps limit fungus."}, {"heading": "Raising the Fry", "text": "- Days 1 to 4: fry live off their yolk sacs\n- Days 4 to 10: infusoria or powdered fry food\n- From about day 7: newly hatched baby brine shrimp\n- Weeks 3 onward: baby brine shrimp plus crushed flake\n- Small water changes of 10 to 20 percent every few days\n\nKeep the fry tank at the same temperature as spawning. Cover the filter intake and feed small amounts often. Infusoria cultures should be started a week before spawning so they are ready when needed."}, {"heading": "Growing Out", "text": "Large spawns mean lots of fry. Spread them out as they grow so the water stays clean.\n\nFry reach about an inch by 2 to 3 months and adult size around 6 months.\n\nA 20 gallon grow-out tank with weekly 25 to 30 percent water changes works well. Feed 3 to 4 times a day. Fry develop their black color as they grow.\n\nLong-finned and colored forms of black skirt tetras are common in the trade. If you breed one of these, keep it with the same form so the fry come out true to type. Avoid buying or breeding artificially dyed or tattooed fish."}, {"heading": "Common Mistakes", "text": "- Leaving the adults in after spawning\n- No protection for the eggs\n- Bright light on the eggs\n- Not enough food for a large spawn\n- Overcrowding the grow-out tank\n- Using small, immature fish that are not ready to spawn\n- Hard water that reduces hatch rates"}]$g$::jsonb, $g$[{"q": "How do you tell male and female black skirt tetras apart?", "a": "Females are rounder and deeper bodied. Males are slimmer, often with a broader anal fin."}, {"q": "Do black skirt tetras eat their eggs?", "a": "Yes. Remove the adults right after spawning."}, {"q": "How long do black skirt tetra eggs take to hatch?", "a": "Usually about 24 to 36 hours around 77°F."}, {"q": "How many eggs do black skirt tetras lay?", "a": "Spawns can be large, often several hundred eggs."}]$g$::jsonb, $g$Open your log and photograph the pair in the spawning tank with your challenge code card. For stage 2, a clear photo of eggs on the plants or mesh works well.$g$),
  ($g$blind-cave-tetra$g$, $g$546e4779-120f-4b31-aca8-1570b2d7cc06$g$::uuid, $g$blind-cave-tetra$g$, null, $g$How to Breed Blind Cave Tetras: Eggs, Fry and Grow-Out$g$, $g$Blind cave tetras are prolific egg scatterers. Spawn them over mesh, remove the adults, and raise fry on infusoria and brine shrimp. Fairly easy to breed.$g$, $g$Blind cave tetras are fascinating fish to breed. Despite having no functional eyes as adults, they find each other and spawn readily in the aquarium. They scatter eggs and will eat them, so a separate spawning tank helps. The fry are born with eyes that later regress as they grow, which is a remarkable thing to watch.$g$, $g${"method": "Egg scatterer", "sexing": "Females rounder and deeper bodied; males slimmer", "group": "One pair or a small group", "breeding_tank": "20 gallon, mesh or marbles, plants or spawning mop, gentle filter", "conditioning": "1 to 2 weeks of live and frozen foods", "trigger": "A cooler water change and introduction to the spawning tank", "spawn": "Often several hundred eggs", "eggs": "Hatch in about 24 to 48 hours around 72 to 77°F", "fry": "Free swimming about 4 to 5 days after spawning", "first_foods": "Infusoria or powdered fry food, then baby brine shrimp after about a week", "grow_out": "About 1 inch by 2 to 3 months; adult size in about 6 to 9 months", "parents": "Adults eat eggs; remove them right after spawning"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 20 gallon tank works well. Use mesh or marbles on the bottom and add plants or a spawning mop.\n\nThe library range is 68 to 77°F and pH 6.5 to 8. Aim for around 72 to 77°F for spawning. Use a gentle sponge filter.\n\nBlind cave tetras are hardy and not fussy about water chemistry. A tight lid is useful, as spawning chases can be energetic. Lighting does not matter much to the adults, but dim light helps reduce fungus on the eggs."}, {"heading": "Choosing and Conditioning Fish", "text": "Females are rounder and deeper bodied, especially when full of eggs. Males are slimmer.\n\nCondition the fish for 1 to 2 weeks on live and frozen foods.\n\nPick mature fish, at least 2 to 2.5 inches long. Healthy females should look visibly round after conditioning. Because they find food by smell and their lateral line, make sure food sinks where they can find it."}, {"heading": "Spawning: What You Will See", "text": "Introduce the fish to the spawning tank and do a slightly cooler water change. Spawning often happens at night or early morning.\n\nThe fish chase and scatter eggs. Spawns can be large, often several hundred eggs.\n\nSpawning often lasts a couple of hours. Breeders report spawning is frequently triggered by a drop in temperature of a few degrees from a water change. If nothing happens in 2 to 3 days, return the fish to conditioning and try again.\n\nA group with one female and two males often works well. Watch for the males closely following the female along the plants or bottom, which is the sign spawning is about to start."}, {"heading": "Eggs and Fungus Prevention", "text": "Remove the adults right after spawning.\n\nEggs usually hatch in about 24 to 48 hours. Keep the tank dim and remove fungused eggs.\n\nEggs are small and slightly sticky and fall into the mesh or plants. Unfertilized eggs turn white within a day and should be removed. Fertile eggs stay clear. A small amount of methylene blue in a separate hatching container can help reduce fungus."}, {"heading": "Raising the Fry", "text": "- Days 1 to 4: fry live off their yolk sacs\n- Days 4 to 10: infusoria or powdered fry food\n- From about day 7: newly hatched baby brine shrimp\n- Weeks 3 onward: baby brine shrimp plus crushed flake\n- Small water changes of 10 to 20 percent every few days\n\nKeep the fry tank at the same temperature as spawning. Cover the filter intake and feed small amounts often. Start infusoria cultures a week before spawning."}, {"heading": "Growing Out", "text": "Fry grow steadily. They are born with eyes, which gradually regress and become covered by skin as they grow.\n\nThey reach about an inch by 2 to 3 months and adult size around 6 to 9 months.\n\nA 20 to 30 gallon grow-out tank with weekly 25 to 30 percent water changes works well. Feed 3 to 4 times a day. Raise them in a group.\n\nBlind cave tetras are fun to watch as they grow. Fry hunt by scent and touch as well as sight early on, and adults rely on their lateral line to navigate. They are long lived and hardy, which makes them a good fish to share with other hobbyists.\n\nKeep the grow-out tank uncrowded. Blind cave tetras are active and can be pushy at feeding time, so spread food across the tank so smaller fish get their share."}, {"heading": "Common Mistakes", "text": "- Leaving the adults in after spawning\n- No protection for eggs\n- Overfeeding and fouling the fry tank\n- Feeding baby brine shrimp too early\n- Not spreading out a large spawn\n- Using small, immature fish that are not ready to spawn"}]$g$::jsonb, $g$[{"q": "Can blind cave tetras breed?", "a": "Yes. They spawn readily in aquariums and can produce large numbers of eggs."}, {"q": "Do blind cave tetra fry have eyes?", "a": "Yes. Fry start with eyes, which regress and become covered by skin as they grow."}, {"q": "How long do blind cave tetra eggs take to hatch?", "a": "Usually about 24 to 48 hours."}, {"q": "Do blind cave tetras eat their eggs?", "a": "Yes. Remove the adults right after spawning."}]$g$::jsonb, $g$Open your log and photograph the fish in the spawning tank with your challenge code card. For stage 2, a clear photo of eggs on the mesh works well.$g$),
  ($g$bloodfin-tetra$g$, $g$2c659601-aa4b-4f59-a6b2-acea3a28f9ea$g$::uuid, $g$bloodfin-tetra$g$, null, $g$How to Breed Bloodfin Tetras: Spawning Tank and Raising Fry$g$, $g$Bloodfin tetras scatter hundreds of eggs near the surface. Learn the spawning tank, how to save eggs from hungry parents and how to raise the tiny fry.$g$, $g$Bloodfin tetras are hardy, active and surprisingly easy to spawn once you give a well fed group a dedicated tank. The adults scatter eggs freely and eat them just as freely, so the real skill is getting the eggs away from the parents and feeding very small fry. It is a great first egg scatterer project and a solid step up from livebearers.$g$, $g${"method": "Egg scatterer (non-adhesive eggs, often released near the surface)", "sexing": "Females fuller and deeper bodied; males slimmer, often brighter red fins with tiny hooks on the anal fin", "group": "One pair, or 2 males to 1 female, or a small group spawned together", "breeding_tank": "10 to 20 gallons, shallow water, mesh or marbles on the bottom, fine plants or mops", "conditioning": "1 to 2 weeks of live or frozen foods with sexes separated", "trigger": "Fresh slightly cooler water change, morning light, gravid females rejoining males", "spawn": "Commonly 200 to 400 eggs, sometimes more", "eggs": "Hatch in about 24 to 36 hours at 77 to 80°F", "fry": "Free swimming about 3 to 5 days after hatching; very small", "first_foods": "Infusoria or green water, then microworms and newly hatched brine shrimp after about a week", "grow_out": "About 3 to 4 months to a sellable 1 inch size", "parents": "No care; adults eat eggs, so remove them right after spawning"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 10 to 20 gallon tank is plenty for a pair or trio. Keep the water fairly shallow, around 6 to 8 inches, because bloodfins often spawn near the top and the eggs need to drop quickly out of reach.\n\nCover the bottom with a layer of marbles, plastic mesh or a sheet of egg crate topped with java moss or spawning mops. The goal is a floor the eggs can fall through but the adults cannot reach. Use a gentle sponge filter and a heater set to about 77 to 80°F. Bloodfins are not fussy about water: anything inside the library range of pH 6 to 8 works, and many breeders use slightly softer, slightly acidic water around pH 6.5 to 7 for the spawning tank. Put the tank where it gets morning light, since spawning usually starts at first light."}, {"heading": "Conditioning and choosing a pair", "text": "Sexing is easiest in mature fish of about 1.5 inches. Females are deeper and rounder through the belly, especially when full of eggs. Males are slimmer and often show stronger red in the fins. Males also carry tiny hooks on the anal fin that can snag in a net, which is a handy check.\n\nSeparate the sexes for 1 to 2 weeks and feed generously two or three times a day with frozen bloodworms, brine shrimp, daphnia and a good flake. Pick the plumpest female and one or two of the most colorful males. Move them into the breeding tank in the evening."}, {"heading": "Spawning: what you will see", "text": "Most spawns happen the next morning. The male chases the female hard, then the pair swim side by side, often near the surface or over the plants, and release eggs and milt with a quiver. This repeats many times over a few hours. Eggs are small, clear and non-adhesive, and they drift down into the mesh or moss.\n\nIf nothing happens in 2 or 3 days, do a 20 to 30 percent water change with slightly cooler water. As soon as the female looks thin and the chasing stops, take both adults out. They will eat every egg they can find."}, {"heading": "Eggs and fungus", "text": "At 77 to 80°F the eggs hatch in about 24 to 36 hours. Unfertilized eggs turn white within a day and can grow fungus that spreads to good eggs. Keep the light dim for the first two days, keep a little water movement from the sponge filter, and siphon out white eggs with a pipette where you can. Some breeders add a few drops of methylene blue, but clean water and good aeration do most of the work.\n\nThe new hatchlings hang on the glass and plants, living off their yolk sacs. Leave them alone and do not feed yet."}, {"heading": "Raising the fry", "text": "About 3 to 5 days after hatching, the fry start swimming level and hunting. They are tiny, so the first foods must be tiny too.\n\n- Week 1: infusoria, green water or a fine powdered fry food, a few times a day in small amounts.\n- Week 2: add microworms and newly hatched brine shrimp once you see them taking the bigger food.\n- Weeks 3 to 6: brine shrimp, crushed flake and fine granules.\n\nChange 10 to 20 percent of the water every day or two from week two on, matching the temperature carefully. Keep the sponge filter running and siphon uneaten food. A few ramshorn snails help clean up."}, {"heading": "Growing out", "text": "With frequent feeding and clean water, fry reach half an inch in about 6 weeks and a sellable 1 inch in roughly 3 to 4 months. Move them to a bigger tank as they grow, since crowding slows growth. The red in the fins develops gradually as they grow. Spread out several meals a day and keep up with water changes: those two things decide how fast they grow."}, {"heading": "Common mistakes", "text": "- Leaving the parents in too long. The eggs disappear within hours.\n- Feeding brine shrimp too early. Most fry cannot swallow it for the first week.\n- Deep water with no mesh, so the adults catch eggs on the way down.\n- Big water changes on day one or two, which stress fragile hatchlings.\n- Overfeeding powdered food in a bare tank, which fouls the water fast."}]$g$::jsonb, $g$[{"q": "How can you tell male and female bloodfin tetras apart?", "a": "Females are rounder and deeper bodied, especially when carrying eggs. Males are slimmer, often brighter in the fins, and have tiny hooks on the anal fin."}, {"q": "How long do bloodfin tetra eggs take to hatch?", "a": "Usually about 24 to 36 hours at 77 to 80°F. The fry become free swimming a few days after that."}, {"q": "Do bloodfin tetras eat their eggs?", "a": "Yes. They give no parental care and will eat eggs and fry, so remove the adults right after spawning."}, {"q": "Can bloodfin tetras breed in a community tank?", "a": "They may spawn there, but the eggs are almost always eaten. A separate spawning tank is the reliable way to raise fry."}]$g$::jsonb, $g$Open your log before the spawn and take your stage 1 photo of the conditioned pair or trio in the spawning tank with the challenge code card visible. Bloodfin fry are tiny, so a clear photo of the free-swimming fry for stage 3 is easiest taken against a dark background with a flashlight from the side.$g$),
  ($g$buenos-aires-tetra$g$, $g$d5139020-5e3a-4e5d-b16e-44e54d675e78$g$::uuid, $g$buenos-aires-tetra$g$, null, $g$How to Breed Buenos Aires Tetras: Spawning and Fry Care$g$, $g$Buenos Aires tetras are prolific egg scatterers that spawn readily when conditioned. Learn the tank setup, egg protection and fry feeding plan step by step.$g$, $g$Buenos Aires tetras are tough, eager spawners that can produce hundreds of eggs in a single morning. The catch is that they eat eggs, fry and soft plants with equal enthusiasm, so you need a simple spawning tank and a quick hand to remove the parents. If you can hatch brine shrimp and keep water clean, this is a very rewarding characin to breed.$g$, $g${"method": "Egg scatterer (slightly adhesive eggs dropped among fine plants or mops)", "sexing": "Males slimmer with brighter red fins; females larger, deeper bodied and rounder", "group": "One pair, or a small group of 2 males and 2 females", "breeding_tank": "15 to 20 gallons, mops or moss, mesh or marbles on the bottom", "conditioning": "1 to 2 weeks of frozen and live foods plus vegetable matter, sexes apart", "trigger": "Fresh water change, morning light, reuniting conditioned fish", "spawn": "Several hundred eggs is common; very large spawns are reported", "eggs": "Hatch in about 24 to 36 hours at 75 to 79°F", "fry": "Free swimming about 3 to 5 days after hatching", "first_foods": "Infusoria or powdered fry food, then microworms and baby brine shrimp", "grow_out": "About 3 months to 1 inch; sellable at 1 to 1.5 inches", "parents": "No care; adults eat eggs and fry, remove them after spawning"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Use a 15 to 20 gallon tank with a sponge filter and a heater set around 75 to 79°F. These fish nibble live plants, so most breeders use synthetic spawning mops or a thick clump of java moss, which they leave alone.\n\nCover the bottom with marbles or a raised mesh so eggs drop out of reach. The library range of pH 6 to 8 and GH 5 to 20 suits them, and they spawn readily in ordinary tap water inside that range. A slightly softer fill, around pH 6.5 to 7, is a common choice for the spawning tank but is not required. Give the tank a tight lid: these are active, jumpy fish."}, {"heading": "Conditioning and choosing a pair", "text": "Adults are easy to sex once they reach about 2 inches. Males are slimmer, with brighter red in the fins. Females are larger, deeper bodied and noticeably round when full of eggs.\n\nSeparate males and females for 1 to 2 weeks. Feed two or three times daily with frozen bloodworms, brine shrimp, mysis, quality flake and some blanched spinach or a vegetable flake, since they are true omnivores. Pick the fullest female and an active, colorful male, and introduce them to the spawning tank in the evening."}, {"heading": "Spawning: what you will see", "text": "Spawning usually starts the next morning. The male drives the female into the mops or moss, the pair press together and scatter eggs, and this repeats for an hour or two. Eggs are slightly sticky and catch on the mops or fall through the mesh.\n\nOnce the female is slim and the chasing has stopped, remove both adults. If they have not spawned after 3 days, try a 25 percent change with slightly cooler water, or return them to conditioning for another week and try again."}, {"heading": "Eggs and fungus", "text": "At 75 to 79°F the eggs hatch in about 24 to 36 hours. Expect a share of infertile eggs, which turn white and fuzzy. Keep the tank dim, keep gentle aeration running, and pick out white eggs with a pipette if you can reach them. A few drops of methylene blue in the spawning tank is a common precaution, though clean water matters most.\n\nThe hatchlings hang on the mops and glass for a few days while they use up the yolk. Do not feed them yet."}, {"heading": "Raising the fry", "text": "The fry are free swimming about 3 to 5 days after hatching. With a large spawn, food and water quality become the main challenges.\n\n- Days 1 to 7 free swimming: infusoria, green water or powdered fry food, small amounts several times a day.\n- Week 2: add microworms and newly hatched brine shrimp.\n- Weeks 3 to 6: brine shrimp, crushed flake and fine granules, plus a little vegetable flake.\n\nFrom week two, change 10 to 20 percent of the water daily or every other day. If you have hundreds of fry, split them into more tanks early, since crowding causes losses and stunting."}, {"heading": "Growing out", "text": "Buenos Aires tetras grow fast. With heavy feeding they reach about 1 inch in roughly 3 months, and they can be sold at 1 to 1.5 inches. Their appetite for plants carries into the grow-out tank, so use hardy plants such as java fern or anubias, or none. Keep the young fish in a decent sized group: they get nippy when crowded or bored."}, {"heading": "Common mistakes", "text": "- Using soft live plants that get eaten before the spawn happens.\n- Leaving adults with the eggs for even a few hours.\n- Feeding brine shrimp before fry can swallow it.\n- Keeping hundreds of fry in one small tank.\n- Skipping water changes because the fry look fine. Losses usually come suddenly."}]$g$::jsonb, $g$[{"q": "How many eggs do Buenos Aires tetras lay?", "a": "Several hundred eggs in one spawn is common, and large conditioned females are reported to lay even more."}, {"q": "How do you tell male and female Buenos Aires tetras apart?", "a": "Males are slimmer with brighter red fins. Females are larger and rounder in the belly."}, {"q": "Do Buenos Aires tetras eat their fry?", "a": "Yes. They give no parental care and will eat eggs and fry, so remove them after spawning."}, {"q": "Why do Buenos Aires tetras eat plants?", "a": "They are omnivores with a strong appetite for greens. Feed some vegetable matter and use tough plants or spawning mops."}]$g$::jsonb, $g$Open your log before you set up the spawn, and show the pair in the spawning tank with your challenge code card for stage 1. With such big spawns, keep at least a dozen of your best fry growing on so your stage 5 photo at 60 days shows healthy, well grown juveniles.$g$),
  ($g$serpae-tetra$g$, $g$3a0e4cbe-0a86-4223-80b8-da59bf83c393$g$::uuid, $g$serpae-tetra$g$, null, $g$How to Breed Serpae Tetras: Soft Water, Spawning and Fry$g$, $g$Serpae tetras spawn in soft, acidic water among fine plants. This guide covers conditioning, the spawning tank, egg care and raising the very small fry.$g$, $g$Serpae tetras are bold, colorful and easier to spawn than their reputation for fin nipping suggests. Give a conditioned pair soft, slightly acidic water, dim light and fine plants, and they will scatter a good batch of eggs. The fry are small and need infusoria first, so this is a step up from the easiest egg scatterers, but very doable.$g$, $g${"method": "Egg scatterer (eggs dropped among fine plants or mops)", "sexing": "Males slimmer and more intensely colored; females rounder and paler. Can be subtle", "group": "One pair, or 2 males with 1 female", "breeding_tank": "10 to 15 gallons, dim light, fine plants or mops, mesh or marbles on the bottom", "conditioning": "1 to 2 weeks of live and frozen foods with sexes separated", "trigger": "Soft acidic water around pH 6 to 6.5, dim light, conditioned female", "spawn": "Commonly reported 100 to 300 eggs, varying with the female", "eggs": "Hatch in about 24 to 48 hours at 77 to 80°F", "fry": "Free swimming about 3 to 5 days after hatching; tiny", "first_foods": "Infusoria or green water, then microworms and newly hatched brine shrimp", "grow_out": "About 3 to 4 months to a sellable 1 inch", "parents": "No care; adults eat eggs, remove them after spawning"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 10 to 15 gallon tank is enough. Serpaes spawn best in soft, slightly acidic water. The library range runs from pH 5 to 7.5, and for spawning most breeders aim for about pH 6 to 6.5 and low hardness, using RO or rain water mixed with tap water. Set the heater to 77 to 80°F.\n\nKeep the light dim: cover the sides with paper or use floating plants. Add fine leaved plants, java moss or spawning mops, and cover the bottom with mesh or marbles so eggs fall out of reach. A small sponge filter on low flow is all you need."}, {"heading": "Conditioning and choosing a pair", "text": "Sexing serpaes takes a careful look. Males are slimmer and usually show deeper red color. Females are rounder and often a little paler, and a ripe female is clearly full through the belly. Comparing fish side by side in a group is the easiest way.\n\nSeparate the sexes for 1 to 2 weeks and feed well with frozen bloodworms, brine shrimp, daphnia and a good flake. Put the best pair, or two males with one female, into the spawning tank in the evening."}, {"heading": "Spawning: what you will see", "text": "Spawning usually happens the next morning. The male displays and drives the female into the plants, and the pair press together and scatter eggs in short bursts. The session can last a couple of hours.\n\nRemove the adults as soon as the female looks slim. If nothing happens after 2 or 3 days, a small change with soft, slightly cooler water often triggers them. If they still will not spawn, condition them for another week and check that the water is soft enough."}, {"heading": "Eggs and fungus", "text": "Eggs hatch in about 24 to 48 hours at 77 to 80°F. Serpae eggs are sensitive to light, so keep the tank dim for the first few days. Infertile eggs turn white and can grow fungus. Remove them with a pipette when you can, keep gentle aeration running, and avoid large water changes during this stage.\n\nAfter hatching the fry hang on the glass and plants for several days while they absorb the yolk."}, {"heading": "Raising the fry", "text": "The fry swim freely about 3 to 5 days after hatching and are very small.\n\n- Week 1: infusoria, green water or a fine liquid or powdered fry food several times a day.\n- Week 2: microworms and newly hatched brine shrimp.\n- Weeks 3 to 6: brine shrimp, crushed flake and small granules.\n\nStart small water changes of 10 to 20 percent every day or two from the second week, using water matched in temperature and softness. Sudden jumps in hardness or pH are a common cause of losses. Keep the light gentle for the first couple of weeks."}, {"heading": "Growing out", "text": "Fry grow steadily with frequent meals. Expect about half an inch at 6 weeks and a sellable 1 inch at roughly 3 to 4 months. Red color develops gradually over the first couple of months. As they grow, you can slowly shift them toward your normal tap water. Keep them in a good sized group with plenty of space, which helps reduce the nipping serpaes are known for."}, {"heading": "Common mistakes", "text": "- Water that is too hard. Eggs may not develop well.\n- Bright light on the eggs and fry.\n- Leaving the adults in the tank after spawning.\n- Offering brine shrimp before the fry can eat it.\n- Changing large amounts of water with a different pH or hardness."}]$g$::jsonb, $g$[{"q": "How do you sex serpae tetras?", "a": "Males are slimmer and usually more intensely red. Females are rounder and slightly paler, and the difference is easiest to see in a group side by side."}, {"q": "What water do serpae tetras need to breed?", "a": "Soft, slightly acidic water works best, around pH 6 to 6.5 and 77 to 80°F, with dim light."}, {"q": "How long do serpae tetra eggs take to hatch?", "a": "Usually about 24 to 48 hours. The fry become free swimming several days after hatching."}, {"q": "Do serpae tetras eat their eggs?", "a": "Yes. They give no parental care, so remove them as soon as spawning is over."}]$g$::jsonb, $g$Open your log and take the stage 1 photo of your pair in the dim spawning tank with the challenge code card before the spawn. For stage 2, a close photo of eggs in the moss or on the mesh is good evidence, and a flashlight held at the side makes the clear eggs show up.$g$),
  ($g$x-ray-tetra$g$, $g$4d14e701-ed45-4d66-a2c3-6c720e74fd3b$g$::uuid, $g$x-ray-tetra$g$, null, $g$How to Breed X-ray Tetras: Spawning Setup and Fry Care$g$, $g$X-ray tetras scatter eggs among fine plants after good conditioning. Learn sexing, the spawning tank, egg care and how to feed the tiny fry week by week.$g$, $g$X-ray tetras are hardy, peaceful fish that spawn readily once a well fed pair is moved into a quiet tank with fine plants. Like most tetras they scatter eggs and then eat them, so a separate tank and quick removal of the adults are key. The see-through fry are tiny, but with infusoria and clean water you can raise a nice batch.$g$, $g${"method": "Egg scatterer (eggs dropped among fine plants or mops)", "sexing": "Females larger and rounder; males slimmer. Seen easily only in mature fish side by side", "group": "One pair, or a small group spawned together", "breeding_tank": "10 gallons, fine plants or mops, mesh or marbles on the bottom, dim light", "conditioning": "1 to 2 weeks of live and frozen foods, sexes separated", "trigger": "Soft slightly acidic water, morning light, reuniting the pair", "spawn": "Commonly up to about 300 eggs", "eggs": "Hatch in about 24 to 36 hours at 77 to 80°F", "fry": "Free swimming about 4 to 5 days after hatching; very small", "first_foods": "Infusoria or powdered fry food, then microworms and newly hatched brine shrimp", "grow_out": "About 3 to 4 months to a sellable 1 inch", "parents": "No care; adults eat eggs and fry, remove them after spawning"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 10 gallon tank is enough for a pair. X-ray tetras tolerate a wide range, pH 6 to 8 in the library, but they spawn most reliably in softer, slightly acidic water. Many breeders aim for about pH 6.5 to 7 with low hardness for the spawning tank. Keep the temperature at 77 to 80°F.\n\nAdd java moss, fine leaved plants or spawning mops and a bottom layer of marbles or mesh. Keep the light low and run a gentle sponge filter. The eggs are small and will be eaten quickly if they can be reached."}, {"heading": "Conditioning and choosing a pair", "text": "Females are larger and rounder in the belly, and when full of eggs the difference is clear. Males are slimmer. Some keepers note that the male's body cavity looks more pointed at the rear, but comparing body shape in mature fish is the reliable test.\n\nSeparate the sexes for 1 to 2 weeks and feed two or three times a day with frozen and live foods such as bloodworms, daphnia and brine shrimp, plus a good flake. Move the best pair into the spawning tank in the evening."}, {"heading": "Spawning: what you will see", "text": "Spawning usually starts early the next morning. The male chases the female into the plants, they swim side by side and release eggs and milt, and this repeats for an hour or more. The eggs scatter into the moss and fall through the mesh.\n\nTake the adults out once the female is slim. If they have not spawned after 2 or 3 days, a small change with softer, slightly cooler water often helps."}, {"heading": "Eggs and fungus", "text": "At 77 to 80°F the eggs hatch in about 24 to 36 hours. Keep the tank dim, keep gentle aeration running, and remove any white, fuzzy eggs with a pipette so fungus does not spread. Avoid big water changes for the first few days.\n\nThe newly hatched fry cling to the glass and plants and are nearly invisible. Be patient: they live off their yolk for several days."}, {"heading": "Raising the fry", "text": "The fry become free swimming about 4 to 5 days after hatching. They are among the smaller tetra fry, so start very small.\n\n- Week 1: infusoria, green water or a fine powdered fry food, small amounts several times daily.\n- Week 2: microworms and newly hatched brine shrimp.\n- Weeks 3 to 6: brine shrimp, crushed flake and fine granules.\n\nFrom the second week, change 10 to 20 percent of the water every day or two, matched in temperature. A bare bottom or a thin layer of sand makes it easier to siphon leftover food."}, {"heading": "Growing out", "text": "X-ray tetras grow at a steady pace. Expect half an inch at about 6 weeks and a sellable 1 inch at 3 to 4 months. The yellow, black and white fin pattern starts to show early. Keep feeding several small meals a day and give them more space as they grow. They can be moved gradually to harder tap water once they are a few weeks old.\n\nIf you want another spawn, put the parents back on conditioning foods right away. A rested, well fed pair can usually be spawned again in about 2 to 3 weeks, which lets you keep batches spaced out and tanks from getting crowded."}, {"heading": "Common mistakes", "text": "- Trying to spawn them in hard, alkaline water with poor results, then giving up.\n- Bright light on eggs and fry.\n- Leaving the adults with the eggs.\n- Starting with brine shrimp too early.\n- Overfeeding and not siphoning, which fouls a small fry tank quickly."}]$g$::jsonb, $g$[{"q": "How do you tell male and female X-ray tetras apart?", "a": "Females are bigger and rounder in the belly, especially when full of eggs. Males are slimmer, and the difference is easiest to see in mature fish side by side."}, {"q": "How long do X-ray tetra eggs take to hatch?", "a": "Usually about 24 to 36 hours at 77 to 80°F. The fry swim freely several days later."}, {"q": "Will X-ray tetras breed in a community tank?", "a": "They may scatter eggs there, but the eggs and fry are almost always eaten. Use a separate spawning tank to raise fry."}, {"q": "What do X-ray tetra fry eat?", "a": "Start with infusoria or a fine powdered fry food, then move to microworms and newly hatched brine shrimp in the second week."}]$g$::jsonb, $g$Open your log before spawning and show the conditioned pair in the spawning tank with the challenge code card for stage 1. X-ray fry are almost transparent, so for stage 3 photograph them against a black background with side lighting so the free-swimming fry show up clearly.$g$),
  ($g$kribensis$g$, $g$45ae7204-8f13-4eb9-8a32-cfad8f7ca4ff$g$::uuid, $g$kribensis$g$, null, $g$How to Breed Kribensis: Pairs, Caves and Raising Fry$g$, $g$Kribensis are cave spawning cichlids that guard their fry as a family. Learn sexing, cave setup, spawning signs and how to raise a healthy batch of young.$g$, $g$Kribensis are one of the best ways to watch real cichlid parenting. A bonded pair picks a cave, the female guards the eggs, and both parents march a cloud of fry around the tank. They breed readily with a dedicated tank and good food, and the main challenges are getting a compatible pair and managing the parents' aggression toward tankmates.$g$, $g${"method": "Cave spawner (biparental care)", "sexing": "Females smaller and rounder with a cherry red belly; males larger with pointed dorsal and anal fins", "group": "One bonded pair", "breeding_tank": "20 gallons or more, sand, a cave or flowerpot, plants and a few dither fish", "conditioning": "1 to 2 weeks of frozen and live foods plus quality pellets", "trigger": "A bonded pair, a suitable cave, warm water and partial water changes", "spawn": "Commonly about 50 to 200 eggs, more from large females", "eggs": "Hatch in about 2 to 4 days at 78 to 80°F", "fry": "Free swimming about 4 to 7 days after hatching, guarded by both parents", "first_foods": "Newly hatched brine shrimp, microworms and fine powdered food", "grow_out": "About 2 to 3 months to a sellable 1 to 1.5 inches", "parents": "Excellent care; remove fry by about 4 to 6 weeks or when the pair spawns again"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 20 gallon long is a good minimum for a pair. Use sand or fine gravel, a few plants, and one or two caves: half a clay flowerpot on its side or a coconut shell with an entrance just big enough for the female. Keep the temperature at 78 to 80°F, inside the library range of 75 to 82°F, and the pH between about 6.5 and 7.5.\n\nA small school of fast, peaceful dither fish helps the pair feel safe and spreads out their aggression, but they will be chased hard once fry arrive. Run a sponge filter or cover the filter intake with a sponge so fry are not sucked in."}, {"heading": "Conditioning and choosing a pair", "text": "Sexing kribs is easy in adults. Females are smaller, rounder and develop a bright cherry red belly when ready. Males are larger, more elongated, and have longer, pointed dorsal and anal fins. Females usually have a rounded dorsal fin.\n\nThe best pairs form naturally. Raise five or six young fish together, or let a male and female settle in the breeding tank and watch for them shimmying and displaying to each other. Feed well for 1 to 2 weeks with frozen brine shrimp, bloodworms, daphnia and quality pellets. If the pair fights rather than displays, separate them and try another combination."}, {"heading": "Spawning: what you will see", "text": "The female does most of the courting. She bends her body into a U shape to show off her red belly and leads the male to the cave. The pair dig out the cave and the female lays her eggs on the inside wall or ceiling, often out of sight. The male fertilizes them and then guards the territory outside.\n\nThe first sign you get is usually that the female disappears into the cave and stays there, coming out only briefly to chase off intruders."}, {"heading": "Eggs and early care", "text": "Eggs hatch in about 2 to 4 days at 78 to 80°F. The female fans them and removes any bad eggs herself, so leave the cave alone. Do not lift the pot to check: disturbed pairs often eat their spawn.\n\nAfter hatching, the wrigglers stay in the cave for several more days. About 4 to 7 days after hatching they come out as a free-swimming cloud, and both parents herd and guard them around the tank."}, {"heading": "Raising the fry", "text": "Krib fry are large enough to take newly hatched brine shrimp and microworms from the first day they swim.\n\n- Weeks 1 to 2: newly hatched brine shrimp and microworms two to four times a day, plus a pinch of powdered fry food.\n- Weeks 3 to 4: add crushed flake and fine granules.\n- Weeks 5 to 8: small pellets and frozen foods.\n\nChange 15 to 25 percent of the water twice a week, siphoning gently around the fry. Keep the temperature steady. It is commonly reported that pH and temperature during development can skew krib sex ratios, so keep conditions moderate rather than extreme."}, {"heading": "Growing out", "text": "The parents usually guard the fry for several weeks. Once the fry are around 4 to 6 weeks old, or when the parents start preparing to spawn again and chase the youngsters, move the fry to a grow-out tank. With good feeding they reach a sellable 1 to 1.5 inches in about 2 to 3 months. You can usually start telling the sexes apart at around 3 months."}, {"heading": "Common mistakes", "text": "- Forcing two random fish together. A mismatched pair can fight badly.\n- Checking the cave every day. Stress leads to eaten eggs.\n- Leaving fry with the parents too long, so the next spawn is lost or the fry get hurt.\n- No sponge on the filter intake.\n- Keeping kribs with other bottom dwellers in a small tank, which leads to injuries during breeding."}]$g$::jsonb, $g$[{"q": "How do you tell male and female kribensis apart?", "a": "Females are smaller and rounder with a bright cherry belly when ready to spawn. Males are larger with longer, pointed dorsal and anal fins."}, {"q": "Do kribensis eat their fry?", "a": "Healthy, settled pairs usually guard their fry well. Stress, disturbance or an inexperienced pair can lead to eaten eggs, and the parents may turn on older fry before the next spawn."}, {"q": "How long until kribensis fry come out of the cave?", "a": "Commonly about 7 to 10 days after the eggs are laid, depending on temperature, when the fry are free swimming."}, {"q": "How often do kribensis breed?", "a": "A healthy pair can spawn every few weeks once the previous batch is moved out."}]$g$::jsonb, $g$Open your log and take the stage 1 photo of your pair in the tank with the cave and the challenge code card before they spawn. Since eggs are hidden in the cave, a clear photo of the female guarding the entrance or a quick shot of the eggs only if they are visible without lifting the cave works best for stage 2, then show the free-swimming fry cloud for stage 3.$g$),
  ($g$cherry-barb$g$, $g$2f8cbad0-0475-4a2f-a446-5ebdf60ed18f$g$::uuid, $g$cherry-barb$g$, null, $g$How to Breed Cherry Barbs: Spawning Tank and Fry Guide$g$, $g$Cherry barbs scatter sticky eggs in fine plants over several days. Learn sexing, a simple spawning tank, how to protect eggs and how to raise the fry.$g$, $g$Cherry barbs are a classic beginner egg layer. They spawn readily in a planted tank with a few females and a red male, scattering small, sticky eggs into moss and fine plants. Adults eat eggs given the chance, so a dedicated tank with plenty of moss gives you the best harvest. It is a simple and colorful way to start breeding egg scatterers.$g$, $g${"method": "Egg scatterer (adhesive eggs dropped in fine plants or moss)", "sexing": "Males cherry red when mature and in color; females tan to brown with a dark side stripe", "group": "1 male to 2 or 3 females", "breeding_tank": "10 to 15 gallons, thick java moss or mops, sponge filter", "conditioning": "1 to 2 weeks of frozen and live foods plus flake", "trigger": "Morning light, fresh water change, a ripe female with a displaying male", "spawn": "Commonly 100 to 300 eggs, laid a few at a time over several sessions", "eggs": "Hatch in about 24 to 48 hours at 77 to 80°F", "fry": "Free swimming about 2 to 4 days after hatching", "first_foods": "Infusoria or powdered fry food, then microworms and newly hatched brine shrimp", "grow_out": "About 3 to 4 months to a sellable 1 inch", "parents": "No care; adults eat eggs, remove them after a few days or move the moss"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 10 to 15 gallon tank works well. Fill a large part of it with java moss or other fine leaved plants, or use several spawning mops. Cherry barbs spread their spawning over several days, laying a few eggs at a time in the plants.\n\nKeep the temperature at 77 to 80°F, inside the library range of 73 to 81°F, and the pH around 6.5 to 7, which is within their 6 to 7.5 range. A sponge filter on low flow is ideal. Gentle light and some floating plants help the fish feel secure."}, {"heading": "Conditioning and choosing a group", "text": "Sexing is easy once fish are mature and in color. Males turn a rich cherry red, especially when displaying. Females are tan to brown with a darker stripe along the side and a rounder belly. Young or stressed males can look washed out, so give them time to color up.\n\nCondition one male and two or three females on frozen bloodworms, brine shrimp, daphnia and a good flake for 1 to 2 weeks. Using more than one female spreads out the male's attention."}, {"heading": "Spawning: what you will see", "text": "Spawning usually starts in the morning. The male turns deep red, flares his fins and leads a female into the moss. They swim side by side and she releases a few eggs at a time, which stick to the plants. This repeats through the morning and over several days.\n\nAfter 3 to 5 days, either remove the adults or lift the moss with its eggs into a separate hatching tank with the same water. Then add fresh moss for the next round if you want to keep collecting."}, {"heading": "Eggs and fungus", "text": "Eggs are small and clear, and hatch in about 24 to 48 hours at 77 to 80°F. Infertile ones turn white within a day. Keep the hatching tank dim, with gentle aeration, and pick out white eggs where you can. Thick moss helps here too, since it hides good eggs from adults and keeps fungus from spreading as easily.\n\nAfter hatching, the fry hang in the moss for a few days while they finish their yolk."}, {"heading": "Raising the fry", "text": "The fry become free swimming about 2 to 4 days after hatching.\n\n- Week 1: infusoria, green water or powdered fry food. Moss tanks grow their own microfauna, which helps.\n- Week 2: microworms and newly hatched brine shrimp.\n- Weeks 3 to 6: brine shrimp, crushed flake and fine granules.\n\nChange 10 to 20 percent of the water every two or three days from week two, matching temperature. Because eggs are laid over several days, expect mixed sizes. Make sure the smallest fry still get fine food."}, {"heading": "Growing out", "text": "Cherry barbs grow at a moderate pace. Expect about half an inch at 6 to 8 weeks and a sellable 1 inch at around 3 to 4 months. Males usually begin to show red as they mature, often from around 3 months. Keep the young fish in a planted tank with regular water changes and several small meals a day for the best color and growth.\n\nWhile the fry grow, the adults can go straight back to conditioning. Because cherry barbs spawn in small batches, many breeders simply rotate moss: lift a clump with eggs every few days into a hatching tank and replace it with fresh moss. This gives a steady supply of fry of similar age in each tank."}, {"heading": "Common mistakes", "text": "- Too little moss, so the adults find most of the eggs.\n- Leaving the adults in for weeks and getting few fry.\n- Starting with brine shrimp before fry can eat it.\n- Assuming a pale male is a female.\n- Big temperature swings during water changes."}]$g$::jsonb, $g$[{"q": "How can you tell male and female cherry barbs apart?", "a": "Mature males are bright cherry red, especially when displaying. Females are tan to brown with a darker side stripe and a rounder body."}, {"q": "Do cherry barbs eat their eggs?", "a": "Yes. They give no parental care and will eat eggs and fry they find, so use lots of moss and remove the adults or the eggs."}, {"q": "How long do cherry barb eggs take to hatch?", "a": "Usually about 24 to 48 hours at 77 to 80°F, with fry swimming freely a few days later."}, {"q": "Will cherry barbs breed in a community tank?", "a": "They often spawn in planted community tanks, and a few fry may survive in thick moss, but a separate tank gives far more fry."}]$g$::jsonb, $g$Open your log before you set up the spawning tank and show the male with his females and the challenge code card in your stage 1 photo. Because cherry barbs lay over several days, note the date you first see eggs for stage 2 so your stage 3 timing is clear.$g$),
  ($g$tiger-barb$g$, $g$4e282603-f657-42a2-8f7d-bfa5570ae573$g$::uuid, $g$tiger-barb$g$, null, $g$How to Breed Tiger Barbs: Spawning Setup and Raising Fry$g$, $g$Tiger barbs scatter hundreds of eggs in fine plants after good conditioning. Learn sexing, the spawning tank, egg care and how to raise the fry to size.$g$, $g$Tiger barbs are energetic, prolific spawners that reward a little preparation with a big batch of fry. A conditioned pair in a planted spawning tank will often spawn the next morning, then try to eat every egg. Remove the adults quickly, feed the fry small foods, and you can raise hundreds. It is a straightforward and satisfying project.$g$, $g${"method": "Egg scatterer (adhesive eggs dropped among fine plants)", "sexing": "Males slimmer with a bright red snout and redder fins; females rounder and plainer", "group": "One pair, or 1 male to 2 females", "breeding_tank": "15 to 20 gallons, fine plants or mops, mesh or marbles on the bottom", "conditioning": "1 to 2 weeks of live and frozen foods with sexes separated", "trigger": "Morning light, slightly softer water and reuniting the conditioned pair", "spawn": "Commonly reported 200 to 500 eggs from a well conditioned female", "eggs": "Hatch in about 24 to 48 hours at 77 to 80°F", "fry": "Free swimming about 3 to 5 days after hatching", "first_foods": "Infusoria or powdered fry food, then microworms and newly hatched brine shrimp", "grow_out": "About 3 months to a sellable 1 inch", "parents": "No care; adults eat eggs, remove them after spawning"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Use a 15 to 20 gallon tank with a sponge filter and the heater set to 77 to 80°F, inside the library range of 72 to 82°F. Fill part of the tank with java moss, fine leaved plants or spawning mops, and cover the bottom with marbles or plastic mesh so eggs fall out of reach.\n\nTiger barbs spawn well in water inside their pH 6 to 7.5 range. Many breeders use somewhat softer water, around pH 6.5 to 7, for the spawning tank. Give the tank morning light if possible."}, {"heading": "Conditioning and choosing a pair", "text": "Mature males are slimmer and show a bright red snout, red edging on the fins and more intense color overall. Females are rounder, especially when full of eggs, and their colors are a little duller. These differences show clearly in fish over about 1.5 inches.\n\nSeparate the sexes for 1 to 2 weeks and feed heavily with frozen bloodworms, brine shrimp, daphnia and flake. Choose a plump female and an active male, or one male with two females. Move them in the evening."}, {"heading": "Spawning: what you will see", "text": "Spawning usually starts at first light. The male chases the female and drives her into the plants, the pair swim close together and scatter eggs, and this repeats for a couple of hours. The eggs are sticky and cling to plants or fall to the bottom.\n\nRemove both adults as soon as spawning ends. If they have not spawned in 2 or 3 days, do a 25 percent change with slightly cooler water. Watch the male: an overly hard chaser can injure a female that is not ready."}, {"heading": "Eggs and fungus", "text": "Eggs hatch in about 24 to 48 hours at 77 to 80°F. Expect some infertile eggs that turn white. Keep gentle aeration, dim the lights, and remove white eggs where practical. Some breeders add a small dose of methylene blue to the spawning tank to slow fungus.\n\nThe new fry hang on the glass and plants for a few days while their yolk sacs are used up."}, {"heading": "Raising the fry", "text": "Tiger barb fry become free swimming about 3 to 5 days after hatching.\n\n- Week 1: infusoria, green water or powdered fry food several times a day.\n- Week 2: microworms and newly hatched brine shrimp.\n- Weeks 3 to 6: brine shrimp, crushed flake and fine granules.\n\nStart 10 to 20 percent water changes every day or two from the second week. With a big spawn, split the fry into more than one tank by week three or four. Crowding is the most common reason growth stalls."}, {"heading": "Growing out", "text": "Tiger barbs grow fast with regular feeding. Fry reach about half an inch at 5 to 6 weeks and a sellable 1 inch at around 3 months. The black bands appear early and the red develops as they mature. Keep juveniles in a large group, which spreads out their natural nipping and chasing.\n\nMove the fry into a larger grow-out tank of 20 gallons or more by about 6 weeks. Feed three or four small meals a day of crushed flake, granules and frozen foods, and change 25 to 30 percent of the water weekly. Pick out any fry with bent spines or missing fins before you sell or trade, so only healthy fish leave your tanks."}, {"heading": "Common mistakes", "text": "- Leaving the adults in after spawning.\n- Too few plants or no mesh, so eggs are eaten as they fall.\n- Brine shrimp offered before fry can swallow it.\n- Keeping hundreds of fry in one small tank.\n- Pairing a pushy male with an unripe female, which leads to injury."}]$g$::jsonb, $g$[{"q": "How do you tell male and female tiger barbs apart?", "a": "Males are slimmer with a bright red snout and redder fins. Females are rounder, especially when carrying eggs, and slightly duller."}, {"q": "How many eggs do tiger barbs lay?", "a": "Breeders commonly report around 200 to 500 eggs from a well conditioned female, fewer from young fish."}, {"q": "Do tiger barbs eat their eggs?", "a": "Yes. They give no parental care, so remove them as soon as spawning is finished."}, {"q": "How fast do tiger barb fry grow?", "a": "With good feeding and water changes, they reach about 1 inch in around 3 months."}]$g$::jsonb, $g$Open your log before spawning and show your conditioned pair or trio in the spawning tank with the challenge code card for stage 1. Keep a group of your best fry growing on in roomy conditions so they look well grown for the 60-day stage 5 photo.$g$),
  ($g$red-root-floater$g$, $g$c87c823a-74c7-4e99-8b1a-8043c6f957ce$g$::uuid, null, null, $g$How to Propagate Red Root Floater: Splitting and Light$g$, $g$Red root floater multiplies on its own by branching side shoots. Learn the light, calm surface and nutrients it needs and how to split and spread it.$g$, $g$Red root floater is a floating plant that spreads by branching and breaking into new plants, so propagation is mostly about giving it the right conditions. With strong light, calm water and enough iron it multiplies steadily and shows its red leaves and roots. Without those, it melts or stays green, which is why the Society rates it a step above the easiest floaters.$g$, $g${"method": "Branching side shoots that break off into new plants", "light": "Medium to high; it sits right under the light and loves it", "co2": "Not needed; it uses air at the surface", "substrate": "None; free floating, feeds from the water column", "timeline": "New side shoots in 1 to 2 weeks; can double in a few weeks in good conditions", "first_steps": "Gently split larger branching plants into pieces with several leaves and roots"}$g$::jsonb, $g$[{"heading": "How it propagates", "text": "Red root floater (Phyllanthus fluitans) grows as small floating stems carrying pairs of rounded leaves. As each plant grows it branches, and those side shoots grow their own roots and eventually break away as new plants. You do not need to cut anything for it to spread. Your job is to keep it healthy and, if you want faster spread, gently split larger clusters.\n\nThe leaves are water repellent on top. Keeping them dry and above the surface is the key to healthy growth."}, {"heading": "What you need", "text": "- Calm water. Strong surface flow or splashing pushes leaves under and they rot. Turn outflows down or use a floating ring.\n- Light. Medium to high light brings out red in the leaves and roots. Under weak light it grows slowly and stays green.\n- Nutrients. It feeds from the water, so a tank with fish load, or a liquid fertilizer with iron, helps. Iron is often linked with stronger red color.\n- A lid gap. A lid helps keep humid air over the leaves, but leave space so leaves are not pressed against condensation for long periods.\n\nCO2 injection is not needed since the leaves take carbon dioxide straight from the air."}, {"heading": "Step by step", "text": "- Start with healthy plants with dry topsides and some red color.\n- Float them in a calm area of the tank, away from filter outflows.\n- After 1 to 2 weeks, look for side shoots with their own roots.\n- Gently pull apart larger clusters into pieces with several leaves and some roots. Use your fingers or fine scissors.\n- Spread pieces across the calm area, leaving open water between them.\n- Remove any yellow or melting leaves so they do not foul the water.\n- Repeat every couple of weeks as the plants fill in."}, {"heading": "Caring for new plants", "text": "New pieces may sit still for a few days before they start growing. Keep the surface calm and the light steady. Dose fertilizer lightly and regularly rather than in big amounts. If leaves get wet on top, they often sink and rot, so watch for splashing during water changes and refill gently.\n\nOnce established, thin the plants out every couple of weeks so they do not shade the tank below. Extra plants can go to a second tank or to fellow hobbyists, never into ponds or waterways."}, {"heading": "Getting good color", "text": "Red color comes mainly from strong light, with steady nutrients behind it. Starved plants turn pale, yellow and slow. Many keepers find that iron supplements help the reds. Expect more color under brighter lights and on plants that have settled for several weeks.\n\nKeep in mind that color is a sign of good conditions, not a requirement for propagation. Green plants that are growing and branching are healthy and will still multiply. Focus first on steady growth, then fine tune light and iron for color once the plants are spreading well."}, {"heading": "Moving plants between tanks", "text": "Red root floater is sensitive to sudden changes. When moving plants to a new tank, carry them in a container of tank water and float them gently, top side up. Avoid tanks with strong surface flow or with fish that nibble floating plants. Expect a short pause in growth of a week or so while they adjust to new light and water. Once new side shoots form, the plants have settled and you can start splitting again."}, {"heading": "Common mistakes", "text": "- Strong surface flow that keeps leaves wet.\n- Weak light, then expecting red color.\n- Letting it cover the whole surface and shade everything.\n- Dumping it into an outdoor pond or drain. Always dispose of extra plants in the trash.\n- Big fertilizer doses that feed algae instead."}]$g$::jsonb, $g$[{"q": "Why is my red root floater melting?", "a": "Usually the leaves are getting wet from surface flow or splashing, or the plant lacks light or nutrients. Calm the surface and check your lighting and fertilizer."}, {"q": "How do I make red root floater red?", "a": "Give it strong light, a calm surface and enough nutrients, especially iron. Color builds over several weeks."}, {"q": "Does red root floater need CO2?", "a": "No. It floats with its leaves in the air and takes carbon dioxide directly from the atmosphere."}, {"q": "How fast does red root floater spread?", "a": "In good conditions it can double in a few weeks. In poor light or strong flow it may barely grow."}]$g$::jsonb, $g$For the plant program, take a dated photo of your starting plants in the tank, then dated photos every week or two as side shoots split off. Counting plants in each photo makes the propagation easy to see.$g$),
  ($g$assassin-snail$g$, $g$a85faeaa-abc4-4c77-95bf-81815c8c8857$g$::uuid, $g$assassin-snail$g$, null, $g$How to Breed Assassin Snails: Eggs, Sand and Slow Growth$g$, $g$Assassin snails breed slowly, laying single eggs in capsules on hard surfaces. Learn the setup, prey supply and patience needed to raise the buried babies.$g$, $g$Assassin snails are slow, steady breeders. Unlike pest snails they have separate sexes, lay just a few eggs at a time, and their babies spend weeks to months hidden in the sand. That makes them easy to keep under control and very satisfying to raise. Success comes down to a sandy bottom, warm hard water, a steady supply of food and lots of patience.$g$, $g${"method": "Egg layer: single eggs in small capsules stuck to hard surfaces", "sexing": "Separate sexes, but males and females cannot be told apart reliably by looks", "group": "A group of 5 or more to make sure both sexes are present", "breeding_tank": "5 to 10 gallons, fine sand bottom, hardscape, gentle sponge filter", "conditioning": "Steady supply of small prey snails plus sinking protein foods", "trigger": "Mature, well fed snails in warm water; pairs mate for hours", "spawn": "A few capsules at a time, each with one egg, laid over weeks", "eggs": "Commonly reported 3 to 6 weeks to hatch, faster in warmer water", "fry": "Tiny babies burrow into the sand right after hatching and stay hidden for months", "first_foods": "Detritus, leftover protein food and tiny snails in the sand", "grow_out": "Commonly several months before juveniles emerge at about a quarter inch", "parents": "No care; adults generally ignore young, keep tank free of fish that eat snails"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 5 to 10 gallon tank is plenty for a breeding group. The most important feature is a fine sand bottom at least 1 to 2 inches deep. Baby assassin snails spend their early life buried, and coarse gravel makes this much harder for them.\n\nKeep the water warm and hard, matching the library range of 72 to 82°F, pH 7 to 8 and GH 8 to 20. Calcium is important for shell growth, so do not use soft RO water without remineralizing it. Add rocks, wood or glass surfaces for egg laying and use a sponge filter. Avoid fish that pick at snails, along with any loaches or puffers."}, {"heading": "Conditioning and choosing a group", "text": "Assassin snails are not hermaphrodites. Each snail is male or female, and there is no reliable way to tell them apart by looking. The simplest approach is to keep a group of five or more adults, which almost always includes both sexes.\n\nFeed them well. Their natural diet is other snails, so add a steady supply of small pond, bladder or ramshorn snails from a separate culture. They also take sinking protein foods such as bloodworms, shrimp pellets and fish food pellets. Well fed adults breed far more often than hungry ones."}, {"heading": "Mating and egg laying", "text": "Mating pairs lock together, one riding on the other's shell, and can stay that way for several hours. Do not separate them.\n\nAfter mating, females lay small, clear, roughly square capsules on hard surfaces such as glass, rocks, wood and filters. Each capsule holds a single egg, and you can see a small yellow dot inside. Expect only a few capsules at a time, spread out over weeks. This slow pace is why assassin snails never overrun a tank."}, {"heading": "Eggs and development", "text": "Development is slow and depends on temperature. Breeders commonly report hatching in about 3 to 6 weeks, quicker at the warmer end of the range. You can watch the dot inside each capsule grow and take shape.\n\nLeave the capsules where they are. They are tough and rarely bothered by other snails. Avoid scraping the glass where they sit, and keep water parameters steady."}, {"heading": "Raising the babies", "text": "Newly hatched snails are tiny and dig straight into the sand. You may not see them again for weeks or months. They feed on detritus, leftover protein food and very small snails.\n\n- Keep feeding the tank lightly with sinking protein foods even when no adults are hungry.\n- Keep small prey snails in the tank so their tiny babies are available as food.\n- Do not vacuum the sand deeply; skim only the surface.\n- Do small, regular water changes and keep calcium up.\n\nThe juveniles usually reappear when they are around a quarter inch long, often months after hatching."}, {"heading": "Growing out", "text": "Growth is slow compared to most snails. Juveniles are commonly reported to take several months to emerge and longer to reach adult size of nearly an inch. Their banded shells are visible once they surface. They are ready to rehome once they are actively hunting and around half an inch. Count your young carefully before selling, since many may still be buried."}, {"heading": "Common mistakes", "text": "- Gravel instead of fine sand, which makes it hard for babies to survive.\n- Soft water with little calcium, leading to weak shells.\n- Deep vacuuming that pulls out hidden babies.\n- Underfeeding, so adults stop laying.\n- Giving up too soon. Babies can stay out of sight for months."}]$g$::jsonb, $g$[{"q": "Do assassin snails need a mate to breed?", "a": "Yes. They have separate sexes and you need a male and a female. Keeping a group of five or more is the easiest way to get both."}, {"q": "How long do assassin snail eggs take to hatch?", "a": "Breeders commonly report about 3 to 6 weeks, depending on temperature."}, {"q": "Where do baby assassin snails go?", "a": "They bury themselves in the sand straight after hatching and can stay hidden for months before showing up as small juveniles."}, {"q": "Will assassin snails overrun my tank?", "a": "No. They lay only a few single eggs at a time and grow slowly, so their numbers rise gradually."}]$g$::jsonb, $g$Open your log before the first eggs appear and show your group in the sand tank with the challenge code card for stage 1. Egg capsules on the glass make clear stage 2 evidence, and since babies stay buried, plan your stage 3 photo around gently sifting a little sand into a dish to show live young.$g$),
  ($g$electric-blue-crayfish$g$, $g$73aaf2dc-35aa-4535-a930-40d3c07218b6$g$::uuid, $g$electric-blue-crayfish$g$, null, $g$How to Breed Electric Blue Crayfish: Berried Females Guide$g$, $g$Electric blue crayfish breed readily once you can sex them. Learn mating signs, caring for a berried female and raising juveniles without heavy losses.$g$, $g$Electric blue crayfish breed readily in captivity and are a fun step into invertebrate breeding. The male passes a sperm packet to the female, she later lays eggs and carries them under her tail, and tiny blue crayfish eventually walk off on their own. The hard parts are keeping the adults from injuring each other and stopping the young from eating one another.$g$, $g${"method": "Egg layer: female carries eggs under her tail (berried)", "sexing": "Males have hard, forward-pointing first swimmerets (gonopods); females have a round sperm receptacle", "group": "One male and one female, paired only for mating", "breeding_tank": "20 gallons or more per adult, many caves and pipes, secure lid", "conditioning": "Varied sinking foods, vegetables and calcium; stable water", "trigger": "Introducing a mature male to a mature female after she molts", "spawn": "Commonly reported 30 to 150 eggs, more from large females", "eggs": "Carried about 3 to 5 weeks, depending on temperature", "fry": "Juveniles cling to the mother for 1 to 2 weeks before walking off", "first_foods": "Crushed sinking pellets, blanched vegetables, leaf litter and biofilm", "grow_out": "About 2 to 3 months to an inch, faster in warmer water", "parents": "Mother protects eggs; remove her once young leave or she may eat them"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Give each adult at least 20 gallons. Use a sand or fine gravel bottom, plenty of caves, PVC pipes and rock piles, and a tight lid with every gap covered. These crayfish climb filter tubes and cords and escape easily.\n\nKeep water inside the library range of 65 to 78°F, pH 6.5 to 8 and GH 6 to 18. Moderate hardness and enough calcium are vital for molting. A temperature around 70 to 75°F suits breeding well. Use a sponge filter or cover intakes so juveniles are not sucked in."}, {"heading": "Sexing and pairing", "text": "Flip a crayfish gently or look from below. Males have the first two pairs of swimmerets modified into hard, white, forward-pointing rods called gonopods. Males also tend to have larger claws. Females have soft swimmerets and a small round opening between the last pairs of walking legs.\n\nElectric blue crayfish are solitary and can be aggressive. Add the male to the female's tank only for mating, ideally a few days after she has molted and hardened. Watch closely and remove the male if fighting goes beyond brief sparring."}, {"heading": "Mating and egg laying", "text": "During mating, the male flips the female onto her back and holds her claws while he passes a sperm packet. This can last several minutes to more than an hour and looks rough. Remove the male afterward.\n\nOver the following days or weeks, the female hides, cleans her underside and lays her eggs, which she attaches to her swimmerets. She is now berried. You will see her fanning the eggs constantly to keep them oxygenated. Keep her alone and undisturbed."}, {"heading": "Eggs and incubation", "text": "The eggs are carried for about 3 to 5 weeks, faster in warmer water. They start dark and become clearer as the young develop, and you may see eyes near the end. A female that is stressed or handled roughly may drop her eggs, so keep the lights steady and avoid big water changes. Do small water changes of 10 to 15 percent once a week."}, {"heading": "Raising the juveniles", "text": "When the eggs hatch, the tiny crayfish stay attached under the mother's tail for 1 to 2 weeks and molt there. Then they begin walking off on their own. At this stage, move the mother back to her own tank, since she may eat the young.\n\n- Week 1 on their own: crushed sinking pellets, blanched vegetables, leaf litter and biofilm.\n- Weeks 2 to 6: small sinking pellets, frozen foods and vegetables.\n- Provide many tiny hides: moss, leaf litter and small pipes.\n\nJuveniles eat each other, especially when one is soft after molting. Plenty of hiding spots and steady feeding keep losses down."}, {"heading": "Growing out", "text": "Juveniles molt often and grow quickly. Expect around an inch in about 2 to 3 months in good conditions. Separate the larger ones as they grow, since size differences increase cannibalism. Rehome them before they reach adult size and begin territorial fights. Never release crayfish into ponds, streams or drains.\n\nGive the mother a few weeks of rest and good food before pairing her again. Females that breed back to back without recovering can struggle with their next molt."}, {"heading": "Common mistakes", "text": "- Leaving the male in after mating, risking injury to the female.\n- Too few hides for juveniles, leading to heavy losses.\n- Soft water with low calcium, causing failed molts.\n- Gaps in the lid, letting crayfish escape.\n- Handling the berried female, which can make her drop her eggs."}]$g$::jsonb, $g$[{"q": "How can you tell if an electric blue crayfish is male or female?", "a": "Males have hard, forward-pointing first swimmerets called gonopods and usually larger claws. Females have soft swimmerets and a small round opening between the rear walking legs."}, {"q": "How long are electric blue crayfish berried?", "a": "Females usually carry eggs for about 3 to 5 weeks, depending on temperature, then carry the young for another week or two."}, {"q": "Will electric blue crayfish eat their babies?", "a": "Yes. The mother may eat them once they leave her tail, and juveniles eat each other, so separate the mother and give plenty of hides."}, {"q": "How many babies do electric blue crayfish have?", "a": "Commonly reported numbers run from about 30 to 150 eggs, depending on the size of the female."}]$g$::jsonb, $g$Open your log before mating and show the male and female with your challenge code card for stage 1. A photo of the berried female's eggs under her tail works well for stage 2, and the young walking on their own count as your free-swimming stage 3.$g$),
  ($g$ghost-shrimp$g$, $g$ed619c5d-4af3-453e-a458-a971af86d982$g$::uuid, $g$ghost-shrimp$g$, null, $g$How to Breed Ghost Shrimp: Berried Females and Larvae Care$g$, $g$Ghost shrimp breed easily but their tiny larvae need careful feeding. Learn how to spot berried females, set up a larvae tank and raise young shrimp.$g$, $g$Ghost shrimp breed readily, and berried females are easy to spot with their green eggs. The challenge is the larvae: unlike cherry shrimp, ghost shrimp hatch as tiny swimming larvae that need very fine food and protection from filters. With a separate larvae tank and patience, you can raise a good batch of clear little shrimp.$g$, $g${"method": "Egg layer: female carries eggs, which hatch into free-swimming larvae", "sexing": "Females larger with a deeper underside and green eggs when ripe; males smaller and slimmer", "group": "A group of 5 to 10 with both sexes", "breeding_tank": "5 to 10 gallons, sponge filter, plants and hides", "conditioning": "Varied sinking foods, algae wafers and blanched vegetables", "trigger": "Mature, well fed females in a stable tank with males", "spawn": "Commonly about 20 to 50 eggs", "eggs": "Carried about 2 to 3 weeks at 72 to 78°F", "fry": "Hatch as tiny larvae that swim in open water; commonly reported 1 to 3 weeks before adult form", "first_foods": "Infusoria, green water and very fine powdered food", "grow_out": "About 2 to 3 months to an inch", "parents": "Adults eat larvae; move berried females to a larvae tank before hatching"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Keep a group of 5 to 10 ghost shrimp in a 5 to 10 gallon tank with a sponge filter, plants and hides. Water inside the library range works well: 72 to 78°F for breeding, pH 7 to 8 and GH 5 to 20.\n\nSet up a second small tank, around 2 to 5 gallons, for the larvae. Use an air stone or a sponge filter on very low flow, no gravel, some java moss and the same water as the main tank. Let it age a couple of weeks to grow some biofilm."}, {"heading": "Sexing and conditioning", "text": "Females are larger, with a deeper underside where they carry eggs. Mature females often show a green saddle of developing eggs in the body. Males are smaller and slimmer.\n\nFeed a varied diet: sinking pellets, algae wafers, blanched spinach or zucchini and frozen foods. Well fed females in stable water breed regularly.\n\nBe aware that shrimp sold as ghost shrimp are sometimes mixed species. Some types need brackish water for larvae. If your larvae fail despite good care, that may be the cause."}, {"heading": "Spawning: what you will see", "text": "After mating, the female carries her eggs under her tail, attached to her swimmerets. They are small, green and easy to see through her clear body. She fans them often.\n\nThe eggs are carried for about 2 to 3 weeks. When you see tiny dark eyes in the eggs, move the female to the larvae tank. Use a cup, not a net, to reduce the chance she drops her eggs."}, {"heading": "Hatching and larvae", "text": "The eggs hatch into tiny swimming larvae that look nothing like adults. They drift and swim in the open water. Return the female to the main tank once the eggs are gone, since adults eat larvae.\n\nThe larvae go through several stages before taking adult form, which breeders commonly report takes about 1 to 3 weeks, depending on temperature. During this time, they cannot handle filter intakes and need very fine food."}, {"heading": "Raising the larvae", "text": "- Days 1 to 7: infusoria, green water and very fine powdered fry food several times a day in small amounts.\n- Week 2: continue fine foods; add crushed flake once they settle and look like small shrimp.\n- Weeks 3 to 6: crushed pellets, algae wafers and blanched vegetables.\n\nKeep the water clean with small changes of 5 to 10 percent a few times a week, dripped in slowly. Keep the temperature steady at 72 to 78°F. Once they look like tiny adults, they can live on the bottom and graze biofilm."}, {"heading": "Growing out", "text": "Young shrimp grow quickly once past the larval stage. Expect about an inch in 2 to 3 months. Keep them in the larvae tank until they are big enough not to be eaten by fish, then move them to a grow-out tank or back with the adults.\n\nSurvival from larvae is often low on the first attempts, so do not be discouraged if only a handful make it. Each batch teaches you how much fine food to give and how gentle the flow must be. A berried female usually comes along again within a few weeks, so you will get plenty of practice."}, {"heading": "Common mistakes", "text": "- Leaving larvae in the main tank, where adults and fish eat them.\n- Strong filters that suck up larvae.\n- No fine food, so larvae starve.\n- Moving berried females with a net.\n- Not knowing your shrimp species, since some need brackish water for larvae."}]$g$::jsonb, $g$[{"q": "How do you tell if a ghost shrimp is pregnant?", "a": "A berried female carries green eggs under her tail. Before laying, you may see a green saddle of developing eggs inside her body."}, {"q": "How long are ghost shrimp pregnant?", "a": "Females usually carry their eggs for about 2 to 3 weeks before they hatch."}, {"q": "Do ghost shrimp larvae need saltwater?", "a": "True freshwater ghost shrimp larvae grow in freshwater, but some shrimp sold under this name need brackish water."}, {"q": "What do baby ghost shrimp eat?", "a": "The larvae need infusoria, green water and very fine powdered food. Once they look like small adults, they eat crushed pellets and biofilm."}]$g$::jsonb, $g$Open your log before your shrimp breed and show the group in the tank with the challenge code card for stage 1. A clear photo of a berried female's green eggs is good stage 2 evidence, and swimming larvae in the larvae tank can be photographed for stage 3.$g$),
  ($g$dwarf-mexican-crayfish$g$, $g$8f193795-f8df-4aaa-86d0-802629ebba38$g$::uuid, $g$dwarf-mexican-crayfish$g$, null, $g$How to Breed Mexican Dwarf Crayfish (CPO): Complete Guide$g$, $g$Mexican dwarf crayfish breed readily in a dedicated tank. Learn how to sex them, care for a berried female and raise tiny orange crayfish to adult size.$g$, $g$Mexican dwarf crayfish, often sold as CPO, are one of the easiest crayfish to breed. They stay small, live peacefully enough in a species tank and produce tiny orange babies every few months. With good hides and steady feeding, you can raise a colony in a simple setup. Their short lifespan means breeding is the best way to keep them going.$g$, $g${"method": "Egg layer: female carries eggs under her tail (berried)", "sexing": "Males have hard, forward-pointing gonopods and longer claws; females have a wider tail", "group": "1 male to 2 females, or a small colony in a larger tank", "breeding_tank": "10 gallons or more, many hides, moss, sponge filter, tight lid", "conditioning": "Sinking pellets, blanched vegetables, leaf litter and calcium", "trigger": "Mature adults in stable water; mating often follows a molt", "spawn": "Commonly about 20 to 60 eggs", "eggs": "Carried about 3 to 4 weeks at room temperature", "fry": "Juveniles cling to the mother for several days before walking off", "first_foods": "Biofilm, crushed sinking pellets, blanched vegetables and leaf litter", "grow_out": "About 2 to 3 months to half an inch; adult at around 4 to 6 months", "parents": "Mother protects eggs; adults may eat young, so offer plenty of cover"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 10 gallon tank is enough for a pair or trio. Add plenty of hides: small pipes, rock piles, wood and thick java moss. A sponge filter keeps juveniles safe, and a tight lid stops escapes.\n\nKeep water inside the library range of 64 to 78°F, pH 7 to 8 and GH 6 to 20. Room temperature in the low to mid 70s works well. Calcium matters for molting, so avoid very soft water."}, {"heading": "Sexing and conditioning", "text": "Look from below. Males have the first two pairs of swimmerets modified into hard, forward-pointing rods called gonopods. Males also usually have longer, slimmer claws. Females have soft swimmerets and a wider tail for carrying eggs.\n\nFeed sinking pellets, blanched vegetables like zucchini and spinach, frozen foods and leaf litter. Keep the water stable with regular small changes. Mexican dwarf crayfish live for only about 1.5 to 2 years, so start breeding young adults."}, {"heading": "Mating and egg laying", "text": "Mating usually happens soon after the female molts. The male flips her over and holds her briefly. Later, she hides and lays eggs under her tail, attaching them to her swimmerets. A berried female hides a lot and fans her eggs constantly.\n\nYou can leave her in a well planted tank with plenty of hides, or move her to a separate tank for best survival of the young. Use a cup, not a net, if you move her."}, {"heading": "Eggs and incubation", "text": "The eggs are carried for about 3 to 4 weeks at room temperature, faster when warmer. They start dark and become lighter as the babies develop. Keep the female undisturbed with steady water. Small weekly water changes of about 10 to 15 percent are best. Stressed females may drop their eggs.\n\nA berried female often eats less and spends most of her time in a cave. That is normal. Offer a small piece of food near her hide every day or two and remove anything left after a few hours."}, {"heading": "Raising the juveniles", "text": "After hatching, the tiny crayfish cling under the mother's tail for several days and molt there. Then they walk off. If you used a separate tank, move the mother back now.\n\n- Week 1 on their own: biofilm, crushed sinking pellets and blanched vegetables.\n- Weeks 2 to 6: small sinking pellets and frozen foods, plus leaf litter.\n- Lots of moss and small hides throughout.\n\nThey are tiny and grow with each molt. Juveniles may eat each other if hungry or crowded, so feed little and often."}, {"heading": "Growing out", "text": "Juveniles reach about half an inch in roughly 2 to 3 months and adult size of about 1.5 to 2 inches in roughly 4 to 6 months. Their orange color becomes more intense as they grow. Thin out the colony if it gets crowded, and never release extras into ponds or streams.\n\nIf you leave the young with the adults, a heavily planted 20 gallon tank with lots of moss and leaf litter lets a small colony build up on its own. For the best numbers, though, raise each batch in its own small tank with the mother removed once the babies walk off. Keep feeding light but often so leftover food does not foul the water."}, {"heading": "Common mistakes", "text": "- Too few hides, leading to injuries and eaten babies.\n- Soft water with low calcium, causing molting problems.\n- Missing escapes through lid gaps.\n- Handling berried females roughly.\n- Waiting too long to breed older adults with a short lifespan."}]$g$::jsonb, $g$[{"q": "How do you sex Mexican dwarf crayfish?", "a": "Males have hard, forward-pointing first swimmerets called gonopods and longer claws. Females have soft swimmerets and a wider tail."}, {"q": "How long are CPO crayfish berried?", "a": "Females usually carry their eggs for about 3 to 4 weeks, then carry the young for several more days."}, {"q": "Do Mexican dwarf crayfish eat their babies?", "a": "They can, especially when hungry or crowded. Lots of moss and hides and steady feeding keep most babies safe."}, {"q": "How many babies do CPO crayfish have?", "a": "A female commonly carries around 20 to 60 eggs."}]$g$::jsonb, $g$Open your log before the female is berried and show your pair or trio in the tank with the challenge code card for stage 1. Photograph the berried female's eggs for stage 2, then the young walking on their own for stage 3.$g$),
  ($g$gardneri-killifish$g$, $g$c28a4882-e6f6-41cc-b900-64f61ceb180b$g$::uuid, $g$gardneri-killifish$g$, null, $g$How to Breed Gardneri Killifish: Mops, Eggs and Fry$g$, $g$Gardneri killifish lay eggs daily in spawning mops. Learn the pair setup, collecting and incubating eggs in water or on peat, and raising the hardy fry.$g$, $g$The blue lyretail, or gardneri, is one of the best killifish for a first breeding project. Pairs lay a few eggs every day in a spawning mop, the eggs are easy to pick and incubate, and the fry are big enough for baby brine shrimp almost right away. It is a non-annual species, so there is no long dry storage to manage, just steady egg collecting.$g$, $g${"method": "Non-annual killifish: egg layer in mops or fine plants", "sexing": "Males colorful with red dots and bright fin edges; females plain brown with small dots", "group": "1 male to 2 or 3 females", "breeding_tank": "5 to 10 gallons, spawning mop, sponge filter, tight lid", "conditioning": "Live and frozen foods for 1 to 2 weeks: bloodworms, brine shrimp, daphnia", "trigger": "Conditioned fish with a mop; they spawn a little most days", "spawn": "Commonly about 10 to 30 eggs a day", "eggs": "Hatch in about 14 to 21 days in water at 72 to 75°F, or on damp peat", "fry": "Free swimming right after hatching; large for killifish fry", "first_foods": "Newly hatched brine shrimp or microworms", "grow_out": "About 2 to 3 months to adult color and size", "parents": "No care; adults eat eggs and fry, so pick eggs daily"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 5 to 10 gallon tank is plenty for a male with two or three females. Use a bare bottom or a thin layer of sand, a sponge filter, a heater set to about 72 to 75°F and a spawning mop that hangs from the surface or sits on the bottom. Gardneri use both.\n\nThe library range of pH 6 to 7.5 and GH 4 to 12 suits breeding well. Use a tight lid: killifish are skilled jumpers. Keep the light moderate and add a few floating plants for cover."}, {"heading": "Conditioning and choosing a group", "text": "Sexing is easy. Males are bright, with red dots on a blue or yellow body and colorful fin edges. Females are plain brown with small reddish dots and short, rounded fins.\n\nUse one male to two or three females so no single female gets too much attention. Condition for 1 to 2 weeks with frozen and live foods such as bloodworms, brine shrimp and daphnia. Males can be rough with each other, so keep only one per small tank."}, {"heading": "Spawning: what you will see", "text": "Gardneri spawn most days once settled. The male displays to a female and leads her into the mop, where they press together and she lays an egg or two at a time. Over the day, she may lay 10 to 30 eggs.\n\nCheck the mop every day or two. The eggs are small, clear and firm, and they can be picked off with your fingers without damage. Fertile eggs are clear; infertile ones turn white."}, {"heading": "Incubating the eggs", "text": "There are two common methods.\n\n- Water: place eggs in a small container of tank water with a drop or two of methylene blue. Remove white eggs daily. At 72 to 75°F, they hatch in about 14 to 21 days.\n- Peat: store eggs on damp peat in a sealed container for about 2 to 3 weeks, then add water when you see eyes. This is useful for shipping or timing hatches.\n\nIn water, they may hatch over several days, so check often and move fry to a growing tank."}, {"heading": "Raising the fry", "text": "Gardneri fry are free swimming as soon as they hatch and big enough for newly hatched brine shrimp or microworms right away.\n\n- Weeks 1 to 2: newly hatched brine shrimp or microworms twice a day.\n- Weeks 3 to 4: add crushed frozen foods and fine flake.\n- Weeks 5 to 8: frozen bloodworms, brine shrimp and small pellets.\n\nChange 10 to 20 percent of the water twice a week, matching temperature. Sort fry by size, since bigger ones may eat smaller siblings."}, {"heading": "Growing out", "text": "Fry grow quickly with good feeding. Males start to show color at about 6 to 8 weeks, and they reach adult size at about 2 to 3 months. Separate males as they mature to avoid fights. Most fish are ready to sell or trade once colors are clear.\n\nGardneri are one of the most widely kept killifish, with many named populations from different collection sites. Most keepers keep the population name with every batch they raise and pass it on with fish they trade. A pair kept on good food will keep spawning for many months, so you can raise several batches without much extra work."}, {"heading": "Common mistakes", "text": "- No lid, so adults jump out.\n- Leaving eggs in the mop where adults eat them.\n- Mixing different populations, which ruins clean locality lines. Keep and label each one separately.\n- Feeding only dry foods during conditioning.\n- Not sorting fry by size."}]$g$::jsonb, $g$[{"q": "Are gardneri killifish annual?", "a": "No. Gardneri are non-annual and their eggs develop in water, though they can also be incubated on damp peat."}, {"q": "How long do gardneri eggs take to hatch?", "a": "Usually about 14 to 21 days in water at 72 to 75°F."}, {"q": "How do you tell male and female gardneri apart?", "a": "Males are colorful with red dots and bright fin edges. Females are plain brown with small dots and short fins."}, {"q": "What do gardneri fry eat?", "a": "Newly hatched brine shrimp or microworms from the day they hatch."}]$g$::jsonb, $g$Open your log before you add the spawning mop and show your trio in the tank with the challenge code card for stage 1. Eggs picked from the mop make simple stage 2 evidence, and noting your collection dates helps your stage 3 timing since water-incubated eggs hatch over several days.$g$),
  ($g$dageti-killifish$g$, $g$5f38d818-7c7e-45a0-8c8b-52a1b0669457$g$::uuid, null, null, $g$How to Breed Dageti Killifish: Red-Chinned Panchax Guide$g$, $g$Dageti killifish lay eggs near the surface in floating plants. Learn sexing, mop or plant setups, egg picking and how to raise the small surface fry.$g$, $g$Epiplatys dageti, the red-chinned panchax, is a peaceful surface killifish that breeds readily once a male has a couple of females and floating plants or a mop. Pairs lay eggs a few at a time, and the main challenge is protecting eggs and fry from the adults. Fry are small at first, so a little care with early foods pays off.$g$, $g${"method": "Non-annual killifish: lays eggs among floating plants or mops near the surface", "sexing": "Males have a red to orange throat and stronger dark bars; females plainer with clear fins", "group": "1 male to 2 or 3 females", "breeding_tank": "5 to 10 gallons, floating plants or a floating mop, sponge filter, tight lid", "conditioning": "Live and frozen foods such as fruit flies, brine shrimp and bloodworms", "trigger": "Conditioned adults with floating plants; they spawn a little most days", "spawn": "A few eggs a day over many days, not one big batch", "eggs": "Commonly reported to hatch in about 8 to 14 days at around 75°F", "fry": "Free swimming at hatching; stay near the surface", "first_foods": "Infusoria or vinegar eels, then newly hatched brine shrimp within days", "grow_out": "About 2 to 3 months to adult color", "parents": "No care; adults eat eggs and small fry, so remove eggs or fry"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 5 to 10 gallon tank works well. Dageti live near the surface, so floating plants such as water sprite or a floating spawning mop are the main spawning sites. Use a sponge filter on low flow and a tight lid, since they can jump.\n\nKeep the temperature around 72 to 77°F and the water soft to moderately hard, with a pH around 6 to 7.5. Breeders report they are adaptable, but stable, clean water matters more than exact numbers.\n\nA few pieces of driftwood or leaf litter on the bottom are welcome but not needed. The fish spend nearly all their time in the top few inches, so focus your setup on the surface: thick floating cover, calm water and a lid that sits close to the waterline."}, {"heading": "Conditioning and choosing a group", "text": "Males are larger and have a bright red to orange throat, which gives the species its common name. They also show stronger dark vertical bars. Females are plainer with clearer fins.\n\nUse one male with two or three females. Condition them for 1 to 2 weeks with live and frozen foods: fruit flies, brine shrimp, daphnia and bloodworms. Surface feeders like this enjoy live insects."}, {"heading": "Spawning: what you will see", "text": "Spawning is gentle. The male displays to a female near the plants or mop, and they lay one or a few eggs at a time among the roots or fibers. A female typically lays only a few eggs a day, spread over many days.\n\nYou can either pick the eggs from the mop every few days, or leave a thick mass of floating plants and remove the fry as they appear at the surface."}, {"heading": "Incubating the eggs", "text": "Breeders commonly report hatching in about 8 to 14 days at around 75°F. Keep picked eggs in a small container of tank water with a drop or two of methylene blue, and remove any white eggs daily.\n\nIf you leave eggs in the mop, move the mop to a separate tank every week or so. This is a simple way to collect fry without picking individual eggs."}, {"heading": "Raising the fry", "text": "The fry are free swimming as soon as they hatch and stay near the surface. They are small at first.\n\n- Days 1 to 4: infusoria, vinegar eels or fine powdered fry food.\n- Days 4 to 14: add newly hatched brine shrimp as soon as they can take it.\n- Weeks 3 to 8: brine shrimp, crushed frozen foods and small flake.\n\nChange 10 to 20 percent of the water twice a week. Sort fry by size, since larger fry may eat smaller ones."}, {"heading": "Growing out", "text": "With good feeding, fry grow steadily. Males start showing red throats at about 6 to 8 weeks, and they reach adult color at around 2 to 3 months. Keep a lid on the grow-out tank too. Dageti are peaceful and can go into community tanks with small, calm fish once grown.\n\nIf you prefer a hands off approach, a heavily planted tank with lots of floating plants will produce a few fry on its own, and you can scoop them from the surface with a small cup each day. This gives fewer fry than egg picking, but it is simple and works well for keeping a line going. Keep the population name with each batch so other keepers know what they have."}, {"heading": "Common mistakes", "text": "- No floating plants or mop near the surface.\n- Leaving eggs and fry with the adults.\n- Starting with only brine shrimp when fry are too small.\n- No lid.\n- Mixing populations, which ruins clean lines. Keep and label each one separately."}]$g$::jsonb, $g$[{"q": "How do you sex dageti killifish?", "a": "Males have a red to orange throat and stronger dark bars. Females are plainer with clearer fins."}, {"q": "How long do dageti eggs take to hatch?", "a": "Breeders commonly report about 8 to 14 days at around 75°F."}, {"q": "Are dageti killifish annual?", "a": "No. They are non-annual and their eggs develop in water."}, {"q": "Do dageti eat their fry?", "a": "Yes. Adults will eat eggs and small fry, so remove eggs or fry to a separate tank."}]$g$::jsonb, $g$Open your log before spawning and show your group with the challenge code card in your stage 1 photo. Since fry appear near the surface, a top-down photo with good light makes stage 3 evidence easy to see.$g$),
  ($g$daisys-ricefish$g$, $g$910e9b14-5b78-4158-aeee-5e0035ca4e13$g$::uuid, null, null, $g$How to Breed Daisy's Ricefish: Eggs, Plants and Fry$g$, $g$Daisy's ricefish females carry eggs before depositing them on plants. Learn sexing, a simple plant setup, collecting eggs and how to raise the tiny fry.$g$, $g$Daisy's ricefish are small, colorful fish that breed readily in a planted tank. Females carry a cluster of eggs at the vent for a while before brushing them onto plants, which makes eggs easy to spot and collect. Adults eat eggs and fry, so the key is a fry tank and very small first foods. It is a fun, practical project for nano tank keepers.$g$, $g${"method": "Egg layer: female carries eggs briefly, then deposits them on plants", "sexing": "Males brighter with red-edged fins and longer dorsal and anal fins; females plainer and rounder", "group": "1 male to 2 or 3 females", "breeding_tank": "5 to 10 gallons, fine plants or moss, sponge filter", "conditioning": "Small live and frozen foods plus quality flake", "trigger": "Conditioned group in stable water; spawns most mornings", "spawn": "Commonly about 10 to 30 eggs at a time", "eggs": "Commonly reported to hatch in about 1 to 2 weeks at 75 to 80°F", "fry": "Free swimming at hatching; very small", "first_foods": "Infusoria or fine powdered food, then newly hatched brine shrimp", "grow_out": "About 2 to 3 months to adult color", "parents": "No care; adults eat eggs and fry, so collect eggs or plants"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 5 to 10 gallon tank is plenty. Fill part of it with fine plants, java moss or spawning mops, and use a sponge filter with gentle flow. A heater set to about 75 to 80°F works well, with a pH of about 6.5 to 7.5.\n\nDaisy's ricefish are peaceful and do well in a species tank. Floating plants and moderate light help them feel secure, and they show their best color in a planted tank.\n\nSet up a second small tank or a few plastic tubs for hatching eggs and raising fry. Fill them with water from the breeding tank so the eggs and fry stay in the same conditions. A clump of java moss in each fry container grows microscopic food that helps the tiny fry in their first days.\n\nIf you have the space, run the spawning tank for a few weeks before adding fish so a little biofilm and algae grows on the plants. Ricefish graze on it, and it helps keep the water stable."}, {"heading": "Conditioning and choosing a group", "text": "Males are brighter, with blue bodies and red or orange edges on their fins. Their dorsal and anal fins are often longer. Females are plainer and rounder, especially when full of eggs.\n\nKeep one male with two or three females. Feed small live and frozen foods such as baby brine shrimp, daphnia and cyclops, plus a fine flake. Daisy's ricefish have small mouths, so choose small foods."}, {"heading": "Spawning: what you will see", "text": "Spawning often happens in the morning. The male courts the female with fin flaring and quick swimming. After spawning, the female carries a small cluster of eggs at her vent, attached by thin threads. She may carry them for a few hours or more before brushing them onto plants or moss.\n\nYou can collect eggs from the plants, or move the moss with eggs to a hatching tank. Breeders report that daily collection gives the best results."}, {"heading": "Incubating the eggs", "text": "Breeders commonly report hatching in about 1 to 2 weeks at 75 to 80°F. Keep eggs in a small container of tank water with gentle aeration, and remove white or fuzzy eggs daily. Methylene blue is a common precaution.\n\nEggs on moss can be left in place in a separate hatching tank, which is easier than picking each one."}, {"heading": "Raising the fry", "text": "The fry are free swimming as soon as they hatch and are very small.\n\n- Week 1: infusoria, green water or fine powdered fry food several times a day.\n- Week 2: add newly hatched brine shrimp and microworms.\n- Weeks 3 to 8: baby brine shrimp, crushed flake and small frozen foods.\n\nChange 10 to 20 percent of the water twice a week, with matching temperature. Keep fry away from adults until they are too large to be eaten."}, {"heading": "Growing out", "text": "Fry grow steadily. Males usually start showing color at about 6 to 8 weeks, and adult color develops by around 2 to 3 months. They can rejoin the adults once they are too big to be eaten.\n\nDaisy's ricefish were only described in 2010, and they come from a small area of Indonesia, so captive bred fish are valuable to the hobby. Keep the best colored males and plump, healthy females to carry the line forward, and avoid crossing them with other ricefish. A well fed group can keep spawning for many months, so space out your batches and keep fry tanks uncrowded."}, {"heading": "Common mistakes", "text": "- Leaving eggs or fry with the adults.\n- Starting with food too large for the fry.\n- Not collecting eggs daily.\n- Strong filter flow in the fry tank.\n- Not keeping enough moss or plants for egg laying."}]$g$::jsonb, $g$[{"q": "How do you tell male and female Daisy's ricefish apart?", "a": "Males are brighter, with red or orange fin edges and longer dorsal and anal fins. Females are plainer and rounder."}, {"q": "Do Daisy's ricefish carry their eggs?", "a": "Females carry a small egg cluster at the vent for a while after spawning, then brush the eggs onto plants or moss."}, {"q": "How long do Daisy's ricefish eggs take to hatch?", "a": "Breeders commonly report about 1 to 2 weeks at 75 to 80°F."}, {"q": "Do Daisy's ricefish eat their fry?", "a": "Yes. Adults will eat eggs and fry, so collect eggs or move moss with eggs to a hatching tank."}]$g$::jsonb, $g$Open your log before spawning and show your group with the challenge code card in your stage 1 photo. A photo of a female carrying her egg cluster is excellent stage 2 evidence.$g$),
  ($g$lyretail-killifish$g$, $g$b45f009d-cbc1-437a-a250-b2de351d3982$g$::uuid, $g$lyretail-killifish$g$, null, $g$How to Breed Lyretail Killifish (Aphyosemion australe)$g$, $g$Lyretail killifish lay eggs daily in mops in soft water. Learn sexing, egg picking, incubating in water or on peat, and raising the strong fry.$g$, $g$Aphyosemion australe, the lyretail killifish, is a classic first killi. Pairs spawn a few eggs a day in a mop, eggs are easy to collect and incubate, and fry can take baby brine shrimp quickly. Soft, slightly acidic water helps, but they are forgiving. With steady egg picking you can raise a steady stream of fry.$g$, $g${"method": "Non-annual killifish: egg layer in mops or fine plants", "sexing": "Males colorful with lyre-shaped tails; females plain brown with rounded fins", "group": "1 male to 2 or 3 females", "breeding_tank": "5 to 10 gallons, spawning mop, sponge filter, tight lid", "conditioning": "Live and frozen foods for 1 to 2 weeks", "trigger": "Conditioned fish with a mop; they spawn most days", "spawn": "Commonly about 10 to 20 eggs a day", "eggs": "Hatch in about 14 to 21 days in water at 72 to 75°F, or on damp peat", "fry": "Free swimming right after hatching", "first_foods": "Newly hatched brine shrimp or microworms", "grow_out": "About 2 to 3 months to adult color", "parents": "No care; adults eat eggs and fry, so pick eggs daily"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 5 to 10 gallon tank is plenty for one male and two or three females. Use a sponge filter on gentle flow, a heater set to about 72 to 75°F and one or two spawning mops, either floating or weighted on the bottom. A bare bottom or a thin layer of sand makes it much easier to see and collect eggs.\n\nThe library range of pH 5.5 to 7 and GH 2 to 12 suits breeding. Many breeders use soft, slightly acidic water around pH 6 to 6.5, mixing RO or rain water with tap water, and some add a little peat or leaf litter to soften and tint it. Keep a tight lid on the tank, because lyretails are strong jumpers. Moderate light and a few floating plants help them settle and show color."}, {"heading": "Conditioning and choosing a group", "text": "Sexing is easy. Males are colorful, usually orange to chocolate with red dots, and have the lyre-shaped tail with bright edges and extended tips that gives them their name. Females are plain brown with a few small dots and short, rounded fins.\n\nKeep one male with two or three females so no single female is chased too hard. Condition for 1 to 2 weeks on live and frozen foods such as bloodworms, brine shrimp, daphnia and white worms. They will take flake, but well fed fish on meaty foods lay more eggs, and the eggs hatch better. Keep only one male per small tank, since rival males fight."}, {"heading": "Spawning: what you will see", "text": "Once settled, lyretails spawn most days. The male spreads his fins and shimmies beside a female, then leads her into the mop. The pair press together side by side and she lays one or two eggs at a time, deep among the fibers. Over a day, a female commonly lays 10 to 20 eggs.\n\nCheck the mop every day or two. Eggs are small, clear and surprisingly firm, so you can pick them out with your fingers. Fertile eggs stay clear, while infertile eggs turn white within a day or two."}, {"heading": "Incubating the eggs", "text": "Killifish keepers use two methods with this species.\n\n- Water: place eggs in a small container of tank water with a drop or two of methylene blue. Remove white eggs daily so fungus does not spread. At 72 to 75°F, eggs hatch in about 14 to 21 days.\n- Peat: store eggs on damp, not wet, peat in a sealed container at room temperature for about 2 to 3 weeks, then add water once you can see eyes in the eggs.\n\nIn water, a batch may hatch over several days. Check every day and move new fry to a small growing tank so they are not left without food."}, {"heading": "Raising the fry", "text": "Lyretail fry are free swimming as soon as they hatch and are large enough to take newly hatched brine shrimp or microworms right away.\n\n- Weeks 1 to 2: newly hatched brine shrimp or microworms two or three times a day.\n- Weeks 3 to 4: add crushed frozen foods and fine flake.\n- Weeks 5 to 8: frozen bloodworms, brine shrimp and small pellets.\n\nChange 10 to 20 percent of the water twice a week, matching temperature and softness carefully. A shallow fry tank of a few inches of water makes it easier for fry to find food. Sort fry by size every couple of weeks, since bigger fry may eat smaller siblings."}, {"heading": "Growing out", "text": "With good feeding, males start showing color and tail extensions at about 6 to 8 weeks, and the young reach adult color at around 2 to 3 months. Separate young males if they begin to fight. Lyretails are not long lived, so keep a few pairs from each generation to continue your line. Keep each population labeled with its name or locality and never mix two different strains."}, {"heading": "Common mistakes", "text": "- Leaving eggs in the mop for days, where the adults eat them.\n- Hard, alkaline water that lowers fertility and hatch rates.\n- No lid, so adults jump out.\n- Not sorting fry by size.\n- Mixing populations or strains, which ruins clean lines that other keepers rely on."}]$g$::jsonb, $g$[{"q": "Are lyretail killifish annual?", "a": "No. Aphyosemion australe is non-annual, and its eggs develop in water."}, {"q": "How long do lyretail killifish eggs take to hatch?", "a": "Usually about 14 to 21 days in water at 72 to 75°F."}, {"q": "How do you tell male and female lyretail killifish apart?", "a": "Males are colorful with lyre-shaped tails. Females are plain brown with rounded fins."}, {"q": "What do lyretail killifish fry eat?", "a": "Newly hatched brine shrimp or microworms from the start."}]$g$::jsonb, $g$Open your log before you add the mop and show your trio with the challenge code card in your stage 1 photo. Eggs picked from the mop make simple stage 2 evidence.$g$),
  ($g$striatum-killifish$g$, $g$adc93959-550c-47ca-940e-f7af326d5079$g$::uuid, $g$striatum-killifish$g$, null, $g$How to Breed Red-Striped Killifish (Aphyosemion striatum)$g$, $g$Red-striped killifish spawn in mops in cool, soft water. Learn sexing, egg picking, incubation in water or on peat, and raising fry to adult color.$g$, $g$Aphyosemion striatum is a small, peaceful killifish with bright red stripes on the males. Pairs lay eggs daily in a mop, and the eggs can be incubated in water or on damp peat. They prefer cool, soft water, which is the main thing to get right. With regular egg picking, you can raise a steady line of colorful fry.$g$, $g${"method": "Non-annual killifish: egg layer in mops or fine plants", "sexing": "Males have red stripes on a blue-green body; females plain brown", "group": "1 male to 2 or 3 females", "breeding_tank": "5 to 10 gallons, spawning mop, sponge filter, tight lid", "conditioning": "Live and frozen foods for 1 to 2 weeks", "trigger": "Cool, soft water and conditioned fish with a mop", "spawn": "Commonly about 10 to 20 eggs a day", "eggs": "Hatch in about 2 to 3 weeks in water at 68 to 72°F, or on damp peat", "fry": "Free swimming right after hatching", "first_foods": "Newly hatched brine shrimp or microworms", "grow_out": "About 2 to 3 months to adult color", "parents": "No care; adults eat eggs and fry, so pick eggs daily"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 5 to 10 gallon tank works well for one male and two or three females. Keep the water cool and soft: the library range is 68 to 75°F, pH 6 to 7 and GH 2 to 10, and most breeders spawn them in the low 70s. In a cool room you may not need a heater at all, but keep the temperature steady.\n\nUse a sponge filter on gentle flow, a bare bottom or a thin layer of sand, and one or two spawning mops. A few floating plants and moderate light help them feel secure. A tight lid is essential, since striatum jump readily, especially when startled."}, {"heading": "Conditioning and choosing a group", "text": "Sexing is straightforward in adults. Males have a blue-green body crossed by rows of bright red stripes, with red markings and edges on the fins. Females are plain brown with clear or lightly spotted fins and look much less striking.\n\nKeep one male with two or three females. Condition for 1 to 2 weeks with live and frozen foods such as bloodworms, brine shrimp, daphnia and white worms. Feed small amounts two or three times a day and keep up with water changes, since cool, soft water still fouls if food is left to rot."}, {"heading": "Spawning: what you will see", "text": "The male displays beside a female with spread fins and leads her into the mop. The pair press together and she lays one or a few eggs at a time, tucked into the fibers. Spawning goes on most days once the fish are settled, and a female commonly lays 10 to 20 eggs a day.\n\nCheck the mop every day or two and pick the eggs by hand. The eggs are small, clear and firm. White eggs are infertile and should be thrown away."}, {"heading": "Incubating the eggs", "text": "- Water: keep eggs in a small container of tank water with a drop or two of methylene blue. Remove white eggs daily. At 68 to 72°F, they hatch in about 2 to 3 weeks.\n- Peat: store eggs on damp, not wet, peat in a sealed container for about 2 to 3 weeks, then add water once eyes are visible in the eggs.\n\nWater-incubated eggs may hatch over several days, so check every day. Write the date on each container so you know which batch is due."}, {"heading": "Raising the fry", "text": "The fry are free swimming at hatching and can eat newly hatched brine shrimp or microworms from the start.\n\n- Weeks 1 to 2: newly hatched brine shrimp or microworms two or three times a day.\n- Weeks 3 to 4: add crushed frozen foods and fine flake.\n- Weeks 5 to 8: frozen foods and small pellets.\n\nChange 10 to 20 percent of the water twice a week, keeping it cool and soft. Shallow water helps young fry find food. Sort fry by size every couple of weeks to prevent the bigger ones eating the smaller."}, {"heading": "Growing out", "text": "Males start showing red stripes at about 6 to 8 weeks and reach adult color at around 2 to 3 months. Keep the water cool throughout: warm water speeds growth but is widely reported to shorten their lives. Like most Aphyosemion, striatum are fairly short lived, so keep a few young pairs from each batch to carry the line on, and label each population clearly."}, {"heading": "Common mistakes", "text": "- Water that is too warm or too hard for this cool water species.\n- Leaving eggs in the mop where the adults eat them.\n- No lid.\n- Not sorting fry by size.\n- Mixing populations, which ruins clean lines."}]$g$::jsonb, $g$[{"q": "Are red-striped killifish annual?", "a": "No. Aphyosemion striatum is non-annual, and its eggs develop in water."}, {"q": "How long do striatum eggs take to hatch?", "a": "Usually about 2 to 3 weeks in water at 68 to 72°F."}, {"q": "How do you sex red-striped killifish?", "a": "Males have red stripes on a blue-green body. Females are plain brown."}, {"q": "What temperature do red-striped killifish need?", "a": "They prefer cool water, about 68 to 75°F."}]$g$::jsonb, $g$Open your log before you add the mop and show your trio with the challenge code card in your stage 1 photo. Eggs picked from the mop make simple stage 2 evidence.$g$),
  ($g$golden-wonder-killifish$g$, $g$b94779fa-a11a-4ef8-9d22-c412c377201b$g$::uuid, $g$golden-wonder-killifish$g$, null, $g$How to Breed Striped Panchax (Golden Wonder Killifish)$g$, $g$Striped panchax lay eggs in floating plants near the surface. Learn sexing, a simple spawning setup, egg collection and raising the large, hungry fry.$g$, $g$Aplocheilus lineatus, the striped panchax or golden wonder, is a hardy, predatory killifish that breeds readily. Pairs lay eggs a few at a time in floating plants or mops, and the fry are large enough for baby brine shrimp from the start. The main challenges are keeping adults from eating the young and sorting fry by size to stop cannibalism.$g$, $g${"method": "Non-annual killifish: lays eggs in floating plants or mops", "sexing": "Males larger and more colorful with longer fins; females show dark bars near the tail", "group": "1 male to 2 females", "breeding_tank": "15 to 20 gallons, floating plants or mop, sponge filter, tight lid", "conditioning": "Live and frozen foods such as bloodworms, insects and brine shrimp", "trigger": "Conditioned pair with floating plants; spawns a few eggs most days", "spawn": "Commonly about 10 to 30 eggs at a time", "eggs": "Hatch in about 12 to 14 days at 75 to 78°F", "fry": "Free swimming right after hatching; large and hungry", "first_foods": "Newly hatched brine shrimp and microworms", "grow_out": "About 3 months to adult color", "parents": "No care; adults eat eggs and fry, so remove eggs"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 15 to 20 gallon tank works well for one male and two females. These are larger killifish, up to about 4 inches, so they need more room than the small Aphyosemion. Use floating plants such as water sprite or hornwort, or a floating spawning mop, plus a sponge filter on gentle flow.\n\nKeep the water inside the library range of 72 to 82°F, pH 6 to 7.5 and GH 5 to 20. Many breeders spawn them at about 75 to 78°F. Striped panchax are surface hunters and excellent jumpers, so a tight lid with no gaps is essential. Do not keep them with small fish they can swallow."}, {"heading": "Conditioning and choosing a group", "text": "Males are larger and more colorful, with longer, more pointed fins and more red or orange edging. In wild type fish, females show clear dark vertical bars on the rear half of the body, which is the easiest sign. In the golden form, the bars are faint or missing, so look for the male's larger size, brighter color and longer fins.\n\nCondition with live and frozen foods for 1 to 2 weeks: bloodworms, brine shrimp, crickets or other small insects, and chopped earthworms. These are predators and need meaty foods to produce good eggs."}, {"heading": "Spawning: what you will see", "text": "The male courts the female near the surface with spread fins and quick dashes. She lays a few eggs at a time among the plant roots or mop fibers, and spawning continues on most days once the fish are settled. A female commonly lays 10 to 30 eggs over a day or two.\n\nCheck the mop or plants every day or two and pick the eggs, or move the whole mop to a hatching tank and replace it with a fresh one."}, {"heading": "Incubating the eggs", "text": "Eggs are commonly reported to hatch in about 12 to 14 days at 75 to 78°F. Keep them in a small container of tank water with a drop or two of methylene blue, and remove any white eggs daily so fungus does not spread. A batch may hatch over a few days, so check each day and move fry to a growing tank as they appear.\n\nYou can also leave eggs in a mop moved to a separate hatching tank with a sponge filter. Fry then appear on their own at the surface over a couple of weeks, which saves picking eggs one by one."}, {"heading": "Raising the fry", "text": "The fry are fairly large and free swimming at hatching, and they eat well from day one.\n\n- Weeks 1 to 2: newly hatched brine shrimp and microworms two or three times a day.\n- Weeks 3 to 4: add crushed frozen foods such as bloodworms and brine shrimp.\n- Weeks 5 to 8: frozen bloodworms, small insects and small pellets.\n\nChange 10 to 20 percent of the water twice a week. Sort fry by size at least once a week. Striped panchax fry are strongly cannibalistic, and a fry that gets a head start will quickly eat its smaller siblings."}, {"heading": "Growing out", "text": "Fry grow fast on plenty of live and frozen food. Males start showing color at about 6 to 8 weeks, and adult color develops by around 3 months. Keep only fish of similar size together and give them more space as they grow. Keep a lid on every grow-out tank, since even young fish jump."}, {"heading": "Common mistakes", "text": "- No lid, or gaps around cords and filters.\n- Leaving eggs and fry with the adults.\n- Not sorting fry by size, which leads to heavy losses from cannibalism.\n- Feeding only flake during conditioning.\n- Overcrowding the grow-out tank."}]$g$::jsonb, $g$[{"q": "How do you sex striped panchax?", "a": "Males are larger and more colorful with longer fins. In wild type fish, females have dark bars near the tail."}, {"q": "How long do striped panchax eggs take to hatch?", "a": "Usually about 12 to 14 days at 75 to 78°F."}, {"q": "Do striped panchax eat their fry?", "a": "Yes. Adults eat eggs and fry, and larger fry eat smaller ones."}, {"q": "Is golden wonder the same as striped panchax?", "a": "Yes. Golden wonder is a gold color form of Aplocheilus lineatus."}]$g$::jsonb, $g$Open your log before spawning and show your group with the challenge code card in your stage 1 photo. Eggs in the mop make simple stage 2 evidence.$g$),
  ($g$humpbacked-limia$g$, $g$008c1728-72a5-441c-8339-3e23c7af9abd$g$::uuid, $g$humpbacked-limia$g$, null, $g$How to Breed Black-Barred Limia: Livebearer Fry Guide$g$, $g$Black-barred limia are livebearers that drop broods about every four weeks. Learn sexing, a hard water setup, saving fry and growing them to adult size.$g$, $g$Black-barred limia are peaceful livebearers that breed readily in hard, alkaline water. Females drop a brood every few weeks, and fry are large enough for crushed flake right away. They do eat their young, so plants and a separate fry tank help. They are a great step beyond guppies and mollies.$g$, $g${"method": "Livebearer", "sexing": "Males smaller with a gonopodium and stronger color; females larger with a dark gravid spot", "group": "1 male to 2 or 3 females", "breeding_tank": "15 to 20 gallons, hard water, dense plants, sponge filter", "conditioning": "Varied foods including vegetable flake and frozen foods", "trigger": "Mature males and females together; breeding is continuous", "spawn": "Commonly about 10 to 30 fry per brood", "eggs": "Gestation commonly about 4 weeks, depending on temperature", "fry": "Born free swimming and ready to eat", "first_foods": "Crushed flake, baby brine shrimp and powdered fry food", "grow_out": "About 3 months to adult size", "parents": "No care; adults may eat fry, so give dense plants or a fry tank"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 15 to 20 gallon tank is ideal for a small breeding group. Keep the water inside the library range of 72 to 82°F, pH 7 to 8.5 and GH 10 to 25. Hard, alkaline water is important for limia, and they do poorly in soft, acidic water.\n\nAdd plenty of dense plants and a layer of floating plants such as hornwort, water sprite or java moss. This gives newborn fry somewhere to hide straight away. Use a sponge filter, or cover the filter intake with a sponge, so fry are not sucked in. A gentle light and some algae on the rocks are welcome, since limia graze all day."}, {"heading": "Conditioning and choosing a group", "text": "Sexing adults is easy. Males have a gonopodium, the rod shaped anal fin used for mating, and are smaller and more strongly colored, with darker barring and fin markings. Females are larger and rounder, with a normal fan shaped anal fin and a dark gravid spot near the vent that grows as they fill with young.\n\nKeep one male with two or three females so the male's attention is spread out. Feed a varied diet with plenty of plant matter: vegetable or spirulina flake, algae wafers and blanched vegetables, plus frozen foods such as brine shrimp and daphnia a few times a week."}, {"heading": "Mating and gestation", "text": "Males display and chase females constantly, and mating is quick. Like other livebearers, females can store sperm and may produce several broods from one mating. Gestation is about 4 weeks, depending on temperature. A pregnant female grows deeper and boxier, and the gravid spot darkens. Close to birth she may hang near plants or away from the group. Keep notes of the date each female drops fry so you can predict her next brood about 4 weeks later."}, {"heading": "Birth and saving fry", "text": "Fry are born fully formed and free swimming, commonly about 10 to 30 per brood, with larger females producing more. Adults may eat newborn fry, so dense plants are your first line of defense. For the most fry, move a heavily pregnant female to a planted 5 to 10 gallon tank a few days before she is due, and return her once she has dropped. Small breeding boxes can stress females and cause early or failed births, so a planted tank is usually better."}, {"heading": "Raising the fry", "text": "Limia fry are large enough to eat crushed flake from their first day.\n\n- Weeks 1 to 2: crushed flake, newly hatched brine shrimp and powdered fry food three or four times a day.\n- Weeks 3 to 6: add crushed vegetable flake and small frozen foods.\n- Weeks 7 to 12: regular flake, small pellets and blanched vegetables.\n\nChange 15 to 25 percent of the water weekly with matched temperature and hardness. Keep algae growing on rocks and glass for grazing."}, {"heading": "Growing out", "text": "Fry reach near adult size in about 3 months with good feeding. Males develop their gonopodium and stronger color as they mature, so you can usually sex the young at around 6 to 10 weeks. Sell or trade them once they are well colored, and keep the best fish to continue your line."}, {"heading": "Common mistakes", "text": "- Soft or acidic water, which causes poor health and few fry.\n- No plants for fry cover, so most newborns are eaten.\n- Tiny breeding boxes that stress pregnant females.\n- Overcrowding the tank as broods add up.\n- Crossing limia with other livebearers. Keep the species pure."}]$g$::jsonb, $g$[{"q": "How long are black-barred limia pregnant?", "a": "Gestation is about 4 weeks."}, {"q": "How many fry do black-barred limia have?", "a": "Commonly about 10 to 30 fry per brood."}, {"q": "Do black-barred limia eat their fry?", "a": "Yes. Adults may eat fry, so give dense plants or a separate fry tank."}, {"q": "How do you tell male and female limia apart?", "a": "Males are smaller, with a gonopodium and stronger color. Females are larger with a dark gravid spot."}]$g$::jsonb, $g$Open your log before the first brood arrives and show your male and females with the challenge code card for stage 1. Photograph the newborn fry as your stage 2 evidence, then log stage 3 at least 3 days later with a clear shot of the young swimming and feeding.$g$),
  ($g$butterfly-splitfin$g$, $g$31d57945-18af-4e1f-b6cd-ce116131ecd8$g$::uuid, $g$butterfly-splitfin$g$, null, $g$How to Breed Butterfly Goodeids: Gestation, Broods and Fry$g$, $g$Breeding the butterfly goodeid: a hardy livebearer with large, well developed fry. Easy once you know goodeids need a male for every brood.$g$, $g$The butterfly goodeid is a splitfin livebearer from Mexico that has become very rare in the wild, so every healthy aquarium brood helps keep it going. Breeding it is straightforward: a well fed group in hard, alkaline water will drop small broods of big, ready to eat fry. The catch is that goodeids do not store sperm and nip each other, so a little planning makes all the difference.$g$, $g${"method": "Livebearer (goodeid, fry fed through a placenta-like link)", "sexing": "Males have a yellow band on the tail edge and a notched front anal fin; females are spotted and plainer", "group": "1 male to 2 or 3 females, or a group of 6 or more", "breeding_tank": "30 gallons or more, dense plants, gentle filter, hard alkaline water", "conditioning": "2 to 3 weeks of varied foods with plenty of vegetable matter and some live or frozen food", "trigger": "Mature, well fed fish breed on their own year round; slightly warmer water speeds things up", "spawn": "Commonly 5 to 30 fry per brood, larger females give bigger broods", "eggs": "Gestation commonly reported at about 8 weeks (55 to 60 days) at 72 to 77°F", "fry": "Born large and swimming, with short feeding cords (trophotaeniae) that drop off within a day or two", "first_foods": "Crushed flake, baby brine shrimp and fine vegetable flake from day one", "grow_out": "About 1 inch in 8 to 10 weeks; sexable at roughly 2 to 3 months", "parents": "Adults eat few fry but nip; dense plants or a separate fry tank keeps losses low"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "Give a group at least 30 gallons. Butterfly goodeids are active and can be nippy, so swimming room and cover cut down on stress. Keep the water hard and alkaline, pH 7.0 to 8.0 and GH 10 to 20, at 72 to 77°F for breeding. They handle the cooler end of their 68 to 79°F range well, and a cool winter spell is normal for them.\n\nUse a sponge filter or a filter with a guarded intake. Plant heavily with fine leaved and floating plants such as hornwort, Java moss and water sprite so newborns can hide right away.\n\nLet the tank cycle fully before adding fish, and keep a mature sponge filter running in a spare tank so you can set up a nursery at short notice. A tight lid stops adults jumping."}, {"heading": "Choosing and Conditioning Your Group", "text": "Sexing adults is easy. Males have a bright yellow band across the edge of the tail and a short, notched front section on the anal fin, used for mating. Females are rounder, more heavily spotted and lack the yellow tail band.\n\nKeep 1 male with 2 or 3 females, or a larger group so the male's attention is shared. Feed two or three times a day for 2 to 3 weeks: a quality flake with spirulina, blanched spinach or zucchini, and frozen bloodworms or brine shrimp a few times a week. Vegetable matter matters for this species.\n\nKeep up weekly water changes of 25 to 30 percent while conditioning. Clean, stable water and a varied diet give bigger, healthier broods."}, {"heading": "Mating and Pregnancy", "text": "You will see the male display to the female with fins spread and a shimmy, then brief contact. Goodeids are different from guppies and mollies: females do not store sperm, so each brood needs a fresh mating. If you remove the male, the next brood will be the last.\n\nA pregnant female gets steadily deeper in the body over the weeks. There is no strong gravid spot like a guppy, so the belly shape is your best guide."}, {"heading": "Gestation and Birth", "text": "Gestation is commonly reported at about 8 weeks, often 55 to 60 days, a bit shorter in warmer water. Embryos are nourished through the mother, so the fry are large at birth. Broods are small, commonly 5 to 30.\n\nA heavily pregnant female can go into a well planted 10 gallon tank a week or so before you expect the birth. Avoid small breeding traps: long stays in a cramped box stress goodeids. Return the female once she has dropped her brood."}, {"heading": "Raising the Fry", "text": "Newborns often trail short cords from the vent. These trophotaeniae drop off on their own within a day or two; do not pull them.\n\n- Week 1: baby brine shrimp, crushed flake and fine spirulina flake, three to five times a day.\n- Weeks 2 to 4: add microworms, crushed frozen foods and blanched vegetables.\n- Change 20 to 30 percent of the water two or three times a week.\n- Keep fry at 73 to 77°F for steady growth.\n\nFeed small amounts often and siphon any leftovers, because uneaten food fouls a fry tank quickly. Fry that are fed well in the first month grow into bigger, healthier adults, while stunted fry rarely catch up."}, {"heading": "Growing Out", "text": "Fry grow quickly on good food and reach about 1 inch in 8 to 10 weeks. Males start showing the yellow tail band at around 2 to 3 months. Give growing fish more room as they size up, since crowding leads to fin nipping. Keep notes on parentage: with a fish this rare in nature, good records help other keepers maintain healthy lines.\n\nThin out crowded tanks as the young grow, and keep notes of birth dates and which parents produced each brood. Those records help you pick breeders and plan future broods."}, {"heading": "Common Mistakes", "text": "- Removing the male and expecting more broods: goodeids need a mating for each brood.\n- Soft, acidic water, which leads to poor health and small broods.\n- Too little vegetable food in the diet.\n- Keeping them with long finned or slow fish they will nip.\n- Crossing them with other goodeid species. Keep lines pure."}]$g$::jsonb, $g$[{"q": "How long are butterfly goodeids pregnant?", "a": "Gestation is commonly reported at about 8 weeks, often 55 to 60 days, a little shorter in warmer water."}, {"q": "How many babies do butterfly goodeids have?", "a": "Broods are small for a livebearer, commonly 5 to 30 fry, with larger and older females producing more."}, {"q": "Do butterfly goodeids eat their fry?", "a": "Adults eat fewer fry than most livebearers because the young are born large, but some losses happen. Heavy planting or a separate fry tank keeps more alive."}, {"q": "What are the cords on newborn goodeid fry?", "a": "They are trophotaeniae, the structures that fed the embryo inside the mother. They drop off by themselves within a day or two."}]$g$::jsonb, $g$Goodeids are slow breeders, so open your log as soon as your group is in the tank and get the challenge code in that first photo. For stage 2, a clear photo of the newborn fry with their feeding cords is strong evidence, and with roughly 8 week gestations it pays to be patient.$g$),
  ($g$least-killifish$g$, $g$f5b0d3eb-299f-4522-ac90-af77b3fe5312$g$::uuid, $g$least-killifish$g$, null, $g$How to Breed Least Killifish: A Tiny Livebearer Colony Guide$g$, $g$Breeding least killifish: a tiny livebearer that drops a few fry at a time and rarely eats its young. Easy in a small, well planted species tank.$g$, $g$Despite the name, the least killifish is a livebearer, and one of the smallest fish in the hobby. Breeding it is relaxed and rewarding: females give birth to just a few fry at a time over many days, and adults seldom eat their young. A small planted tank can turn into a busy colony within a few months, which makes it a lovely species for patient keepers.$g$, $g${"method": "Livebearer with superfetation (a few fry born every day or two)", "sexing": "Males are smaller with a long gonopodium; females larger and rounder, about 1.2 inches", "group": "Colony of 1 male to 2 or 3 females, 6 or more fish", "breeding_tank": "5 to 10 gallons, heavily planted, sponge filter, no tankmates", "conditioning": "1 to 2 weeks of baby brine shrimp, microworms and fine flake", "trigger": "Mature, well fed females breed continuously; 72 to 77°F keeps it steady", "spawn": "Commonly 1 to 3 fry a day over a week or two, not one big drop", "eggs": "Embryo development commonly reported at about 4 weeks; broods overlap so births are spread out", "fry": "Tiny but fully formed and swimming at birth", "first_foods": "Microworms, baby brine shrimp and powdered flake", "grow_out": "Mature in about 2 to 3 months", "parents": "Adults rarely eat fry; a species-only planted tank is usually enough"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 5 to 10 gallon tank is plenty for a starter colony. Fill it with fine leaved plants such as Java moss, hornwort and floating plants, since cover is what lets fry survive. Use an air driven sponge filter so the tiny fish are never pulled in, and keep a tight lid.\n\nMatch the site's care numbers: pH 7.0 to 8.0, GH 5 to 20, and 72 to 77°F for breeding. They tolerate cooler water down to the mid 60s, but births slow down.\n\nLet the tank cycle fully before adding fish, and keep a mature sponge filter running in a spare tank so you can set up a nursery at short notice. A tight lid stops adults jumping."}, {"heading": "Choosing and Conditioning Your Group", "text": "Sexing is straightforward once fish are grown. Females reach about 1.2 inches and look deeper bodied. Males are noticeably smaller, slimmer, and carry a long, pointed gonopodium that is easy to see from the side.\n\nStart with 1 male to 2 or 3 females, ideally 6 or more fish. Condition for 1 to 2 weeks with live or frozen baby brine shrimp, microworms, daphnia and crushed flake two or three times a day. These are tiny mouths, so food must be small.\n\nKeep up weekly water changes of 25 to 30 percent while conditioning. Clean, stable water and a varied diet give bigger, healthier broods."}, {"heading": "How They Breed", "text": "Mating is quick and easy to miss. The male darts at a female and swings the gonopodium forward. Females store sperm, so a single male can keep several females producing.\n\nThe big difference from guppies is superfetation: a female carries several batches of embryos at different stages, so instead of dropping 30 fry in one day she releases a few at a time."}, {"heading": "Gestation and Birth", "text": "Each embryo is commonly reported to develop for about 4 weeks, but because batches overlap, births are spread out. Breeders commonly report 1 to 3 fry a day over a week or two. Total output per female is modest, so colony growth is gradual rather than explosive.\n\nThere is no need to move females or use breeding boxes. In a planted species tank the mothers simply give birth among the plants."}, {"heading": "Raising the Fry", "text": "Fry are tiny but swim and eat from birth.\n\n- Week 1: microworms, freshly hatched baby brine shrimp and powdered flake, three or four small feedings a day.\n- Weeks 2 to 4: add crushed flake and small frozen foods like cyclops.\n- Change 15 to 25 percent of the water weekly with a gentle siphon, checking for fry.\n- Keep 72 to 77°F for steady growth.\n\nFeed small amounts often and siphon any leftovers, because uneaten food fouls a fry tank quickly. Fry that are fed well in the first month grow into bigger, healthier adults, while stunted fry rarely catch up."}, {"heading": "Growing Out", "text": "Young fish grow slowly by livebearer standards but are mature in about 2 to 3 months. Males show the gonopodium first. Because adults leave fry alone, you can grow the colony in one tank, though a second small tank helps once numbers pass 30 or so. Least killifish are native to the southeastern United States; never release them or any aquarium fish outdoors.\n\nThin out crowded tanks as the young grow, and keep notes of birth dates and which parents produced each brood. Those records help you pick breeders and plan future broods."}, {"heading": "Common Mistakes", "text": "- Adding tankmates, which quickly eat the fry.\n- Hang on back filters with open intakes.\n- Food that is too big for these tiny fish.\n- Expecting large broods; this species breeds in a slow trickle.\n- Too few plants, leaving fry with nowhere to hide."}]$g$::jsonb, $g$[{"q": "Are least killifish really killifish?", "a": "No. Despite the name they are livebearers, related to mosquitofish and mollies, and they give birth to free swimming young."}, {"q": "How many babies do least killifish have?", "a": "Females release a few fry at a time, commonly 1 to 3 a day over a week or two, rather than one large brood."}, {"q": "Do least killifish eat their fry?", "a": "Adults rarely eat their fry, so a heavily planted species-only tank is usually all you need to grow a colony."}, {"q": "How long does it take least killifish to mature?", "a": "Young fish are commonly mature in about 2 to 3 months on good food."}]$g$::jsonb, $g$Since least killifish drop fry a few at a time, photograph your first newborns quickly for stage 2 and date the photo. Fry this small are hard to see, so use a white spoon or small clear cup for your later fry and grow-out photos.$g$),
  ($g$molly$g$, $g$f5254b4b-b63b-480c-b61a-ce9d8dfbfc02$g$::uuid, $g$molly$g$, null, $g$How to Breed Mollies: Gestation, Fry and Saving the Babies$g$, $g$Breeding mollies: pregnant females drop 20 to 60 or more fry about every 4 to 6 weeks. Easy, as long as you protect the young from hungry adults.$g$, $g$Mollies are some of the easiest fish to breed, and watching a female drop dozens of fully formed fry never gets old. The real job is keeping the water hard and clean, feeding plenty of greens, and saving the babies before the adults find them. With a planted tank or a nursery tank, you can raise strong, colorful mollies from your own line.$g$, $g${"method": "Livebearer", "sexing": "Males have a gonopodium (rod-shaped anal fin); females have a fan-shaped anal fin and rounder body", "group": "1 male to 2 or 3 females", "breeding_tank": "20 gallons or more, hard alkaline water, plants or a separate nursery tank", "conditioning": "2 to 3 weeks of algae-based flake, vegetables and some frozen foods", "trigger": "Mature, healthy fish breed constantly; females store sperm for several broods", "spawn": "Commonly 20 to 60 fry, large females up to about 100", "eggs": "Gestation about 4 to 6 weeks at 75 to 80°F, longer in cooler water", "fry": "Born large and swimming, ready to eat at once", "first_foods": "Crushed flake, baby brine shrimp and spirulina powder", "grow_out": "About 1 inch in 2 to 3 months", "parents": "Adults eat fry; use dense plants or move the female before birth"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "Mollies need room and hard, alkaline water. Use at least 20 gallons for a small group, with pH 7.0 to 8.5 and GH 15 to 30, matching the site's care numbers. Breeding goes best at 75 to 80°F.\n\nAdd dense cover such as hornwort, Java moss and floating plants so newborns can hide. A separate 10 gallon nursery tank with a sponge filter is the most reliable way to raise a full brood. Salt is not required for this species if your water is hard.\n\nLet the tank cycle fully before adding fish, and keep a mature sponge filter running in a spare tank so you can set up a nursery at short notice. A tight lid stops adults jumping."}, {"heading": "Choosing and Conditioning a Breeding Group", "text": "Males have a gonopodium, the narrow, rod-shaped anal fin used to mate. Females have a normal fan-shaped anal fin and are larger and rounder. Keep 1 male to 2 or 3 females so no single female is chased all day.\n\nCondition for 2 to 3 weeks with a spirulina or algae flake as the main food, blanched spinach or zucchini, and frozen brine shrimp or bloodworms a few times a week. Mollies graze constantly, so several small feedings beat one big one.\n\nKeep up weekly water changes of 25 to 30 percent while conditioning. Clean, stable water and a varied diet give bigger, healthier broods."}, {"heading": "Mating and Pregnancy", "text": "Males follow females and make quick thrusts with the gonopodium. Females store sperm, so a female can have several broods from one mating, even after the male is removed.\n\nA pregnant female grows boxy at the back of the belly. The dark gravid area near the vent is often hard to see on dark or black mollies, so body shape is the better guide."}, {"heading": "Gestation and Birth", "text": "Gestation is about 4 to 6 weeks at 75 to 80°F and can stretch in cooler water. Near the end the belly looks square from the front, and the female may hang near cover or stop eating.\n\nYou can move her to a heavily planted nursery tank a few days ahead. Small hang-on breeding boxes stress mollies and can cause early births, so use them only briefly. Broods are commonly 20 to 60, with big females occasionally dropping around 100."}, {"heading": "Raising the Fry", "text": "Molly fry are large and eat right away.\n\n- Week 1: crushed flake, baby brine shrimp and a pinch of spirulina powder, four or five times a day.\n- Weeks 2 to 4: add finely crushed algae wafers, blanched vegetables and frozen foods.\n- Change 25 to 30 percent of the water two or three times a week.\n- Keep 76 to 80°F for fast growth.\n\nFeed small amounts often and siphon any leftovers, because uneaten food fouls a fry tank quickly. Fry that are fed well in the first month grow into bigger, healthier adults, while stunted fry rarely catch up."}, {"heading": "Growing Out", "text": "Fry reach about 1 inch in 2 to 3 months. Males show the gonopodium as they mature, often between 2 and 4 months. Separate young males early if you want to control which fish breed. Cull any with bent spines or poor shape and keep your best fish as the next breeders.\n\nThin out crowded tanks as the young grow, and keep notes of birth dates and which parents produced each brood. Those records help you pick breeders and plan future broods."}, {"heading": "Common Mistakes", "text": "- Soft or acidic water, which leads to clamped fins and poor health.\n- Too many males per female.\n- Leaving fry with the adults in a bare tank.\n- Skipping vegetables in the diet.\n- Mixing molly species and selling the crosses as pure fish.\n- Releasing unwanted fish outdoors. Mollies have become invasive in warm waters in many parts of the world."}]$g$::jsonb, $g$[{"q": "How long are mollies pregnant?", "a": "Molly gestation is usually about 4 to 6 weeks at 75 to 80°F, and can take longer in cooler water."}, {"q": "How many babies do mollies have?", "a": "A typical brood is 20 to 60 fry, and large, mature females occasionally drop around 100."}, {"q": "Do mollies eat their babies?", "a": "Yes, adult mollies will eat fry. Dense plants or moving the female to a nursery tank before birth saves the most babies."}, {"q": "Can a molly get pregnant without a male?", "a": "Not without mating, but females store sperm, so a female kept alone can still give birth to several broods after being with a male."}]$g$::jsonb, $g$Mollies store sperm, so open your log and photograph your actual breeding group with the challenge code before the first brood arrives. For stage 2, a clear photo of the newborn fry in the nursery tank is the most convincing evidence.$g$),
  ($g$red-tailed-splitfin$g$, $g$5cdb536a-7e06-4231-ac01-d78d0ad588ba$g$::uuid, $g$red-tailed-splitfin$g$, null, $g$How to Breed Redtail Splitfins: Goodeid Broods and Fry Care$g$, $g$Breeding the redtail splitfin: a hardy goodeid livebearer with big, well developed fry. Straightforward, but adults are nippy and need a male each brood.$g$, $g$The redtail splitfin is a striking Mexican goodeid, the males showing a blue body, high back and bright orange tail base. It breeds readily in hard, alkaline water and gives birth to large, ready to eat fry. Like other goodeids, females need a fresh mating for each brood, and the adults are known fin nippers, so a planted tank and a little planning go a long way.$g$, $g${"method": "Livebearer (goodeid, fry fed through a placenta-like link)", "sexing": "Males deeper bodied with a raised back, blue sheen and orange-red tail base, notched anal fin", "group": "1 male to 2 or 3 females, or a group of 6 or more", "breeding_tank": "30 gallons or more, dense plants, hard alkaline water", "conditioning": "2 to 3 weeks of flake with vegetable matter plus frozen or live foods", "trigger": "Mature, well fed fish breed on their own; warmer water speeds it up", "spawn": "Commonly 10 to 40 fry, larger females give bigger broods", "eggs": "Gestation commonly reported at about 6 to 8 weeks at 72 to 77°F", "fry": "Born large and swimming, with feeding cords that drop off within a day or two", "first_foods": "Crushed flake, baby brine shrimp and fine vegetable flake", "grow_out": "About 1 inch in 2 to 3 months", "parents": "Adults may eat fry and nip; move females or plant heavily"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 30 gallon tank suits a breeding group. Match the site's numbers: pH 7.0 to 8.0, GH 10 to 25, and 72 to 77°F for breeding within their 68 to 79°F range.\n\nPlant heavily with hornwort, Java moss and floating plants, and use a sponge filter or a guarded intake. A spare 10 gallon tank makes a good birthing and fry tank, because redtails are more likely than many livebearers to pick off newborns.\n\nLet the tank cycle fully before adding fish, and keep a mature sponge filter running in a spare tank so you can set up a nursery at short notice. A tight lid stops adults jumping."}, {"heading": "Choosing and Conditioning Your Group", "text": "Adult males are easy to spot: a taller back that rises behind the head, a blue or purple sheen, a bright orange to red tail base and a notched front section on the anal fin. Females are plainer, greyer and rounder.\n\nKeep 1 male with 2 or 3 females, or a larger group to spread out the chasing. Condition for 2 to 3 weeks with a spirulina flake, blanched vegetables and frozen bloodworms, mysis or brine shrimp. They are greedy eaters, so feed small amounts often.\n\nKeep up weekly water changes of 25 to 30 percent while conditioning. Clean, stable water and a varied diet give bigger, healthier broods."}, {"heading": "Mating and Pregnancy", "text": "The male displays with fins spread beside the female, then makes brief contact. Goodeid females do not store sperm, so the male has to stay with the group for each new brood.\n\nA pregnant female slowly gets deeper in the belly. There is no clear gravid spot, so watch her shape and keep a note of dates."}, {"heading": "Gestation and Birth", "text": "Gestation is commonly reported at about 6 to 8 weeks. Embryos are fed through the mother, so the fry are large at birth, often with short feeding cords (trophotaeniae) hanging from the vent. Broods are commonly 10 to 40.\n\nMove a heavily pregnant female to a planted 10 gallon tank about a week before the expected date, then return her after the birth. Avoid long stays in small breeding boxes."}, {"heading": "Raising the Fry", "text": "The cords fall off by themselves within a day or two, so leave them alone.\n\n- Week 1: baby brine shrimp, crushed flake and spirulina powder, four times a day.\n- Weeks 2 to 4: add microworms, crushed frozen foods and blanched vegetables.\n- Change 25 percent of the water two or three times a week.\n- Keep 73 to 77°F.\n\nFeed small amounts often and siphon any leftovers, because uneaten food fouls a fry tank quickly. Fry that are fed well in the first month grow into bigger, healthier adults, while stunted fry rarely catch up."}, {"heading": "Growing Out", "text": "Fry grow quickly and reach about 1 inch in 2 to 3 months. Males start to show the orange tail base and the raised back as they mature. Give them space as they grow, because crowded redtails nip each other's fins. Pick your best colored, best shaped fish as the next breeders.\n\nThin out crowded tanks as the young grow, and keep notes of birth dates and which parents produced each brood. Those records help you pick breeders and plan future broods."}, {"heading": "Common Mistakes", "text": "- Removing the male and waiting for more broods.\n- Mixing redtails with long finned fish they will shred.\n- Leaving newborns in a bare tank with the adults.\n- Soft, acidic water.\n- Crossing them with other goodeids."}]$g$::jsonb, $g$[{"q": "How long are redtail splitfins pregnant?", "a": "Gestation is commonly reported at about 6 to 8 weeks, a little shorter in warmer water."}, {"q": "How many fry do redtail splitfins have?", "a": "Broods are commonly 10 to 40 large fry, with bigger females producing more."}, {"q": "Do redtail splitfins eat their babies?", "a": "They can, and they are more likely to than some goodeids. Move pregnant females to a planted birthing tank or plant the main tank heavily."}, {"q": "Do goodeids store sperm like guppies?", "a": "No. Goodeid females need to mate again for each brood, so keep the male with the group."}]$g$::jsonb, $g$With a gestation of around 6 to 8 weeks, open your log early and show the full group with the challenge code at stage 1. Newborn fry with their feeding cords make clear stage 2 evidence, so have your camera ready in the birthing tank.$g$),
  ($g$sailfin-molly$g$, $g$ac9b483d-6117-407f-83dd-6797367618d4$g$::uuid, $g$sailfin-molly$g$, null, $g$How to Breed Sailfin Mollies: Big Tanks, Big Broods, Big Fry$g$, $g$Breeding sailfin mollies: big broods of large fry every 4 to 6 weeks. Easy to get babies, harder to raise males with full sails, which need room.$g$, $g$Sailfin mollies breed just as readily as other mollies, and big females can drop a hundred or more fry. The challenge is raising males with the tall, flag-like dorsal fin that makes this fish special. That takes space, warm hard water, clean conditions and plenty of greens over many months. Get those right and you will be proud of every male you grow.$g$, $g${"method": "Livebearer", "sexing": "Males have a gonopodium and, when mature, a tall sail-like dorsal fin; females have a fan-shaped anal fin", "group": "1 male to 2 or 3 females", "breeding_tank": "30 gallons or more, hard alkaline water, plants or a nursery tank", "conditioning": "2 to 3 weeks of algae flake, vegetables and frozen foods", "trigger": "Mature, healthy fish breed constantly; females store sperm", "spawn": "Commonly 20 to 80 fry, very large females 100 or more", "eggs": "Gestation about 4 to 6 weeks at 75 to 80°F", "fry": "Born large and swimming, ready to eat at once", "first_foods": "Crushed flake, baby brine shrimp and spirulina powder", "grow_out": "1 inch in 2 to 3 months; full male sails can take many months", "parents": "Adults eat fry; plant heavily or move the female before birth"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "Sailfins are big mollies that need at least 30 gallons, and more for growing out males. Keep pH 7.0 to 8.5 and GH 12 to 30 to match the site's numbers, and run 75 to 80°F for breeding. They also do well in lightly brackish water, but salt is optional if your water is hard.\n\nFill part of the tank with floating plants and hornwort for fry cover, or set up a separate 10 to 20 gallon nursery tank with a sponge filter.\n\nLet the tank cycle fully before adding fish, and keep a mature sponge filter running in a spare tank so you can set up a nursery at short notice. A tight lid stops adults jumping."}, {"heading": "Choosing and Conditioning a Breeding Group", "text": "Mature males have a gonopodium and a tall dorsal sail that they flare when displaying. Females are deeper bodied with a short dorsal and fan-shaped anal fin. Choose the male with the best sail and shape, and keep 1 male with 2 or 3 females.\n\nCondition for 2 to 3 weeks with algae or spirulina flake as the base, blanched spinach or zucchini, and frozen brine shrimp or mysis a few times a week. Sailfins graze all day, so feed little and often.\n\nKeep up weekly water changes of 25 to 30 percent while conditioning. Clean, stable water and a varied diet give bigger, healthier broods."}, {"heading": "Mating and Pregnancy", "text": "The male raises his sail and displays beside the female before quick mating attempts with the gonopodium. Females store sperm and can produce several broods from one mating.\n\nA pregnant female grows deep and square through the belly. On darker strains the gravid spot is hard to see, so watch her shape."}, {"heading": "Gestation and Birth", "text": "Gestation is about 4 to 6 weeks at 75 to 80°F, longer when cooler. Broods are commonly 20 to 80, and very large females can drop 100 or more.\n\nMove the female a few days before birth into a heavily planted nursery tank, and return her once she has finished. Small breeding traps stress sailfins and can cause premature births, so avoid long stays in them."}, {"heading": "Raising the Fry", "text": "The fry are large and eat right away.\n\n- Week 1: crushed flake, baby brine shrimp and spirulina powder, four or five times a day.\n- Weeks 2 to 4: add crushed algae wafers, blanched vegetables and frozen foods.\n- Change 25 to 30 percent of the water two or three times a week.\n- Keep 76 to 80°F.\n\nFeed small amounts often and siphon any leftovers, because uneaten food fouls a fry tank quickly. Fry that are fed well in the first month grow into bigger, healthier adults, while stunted fry rarely catch up."}, {"heading": "Growing Out Sailfin Males", "text": "Fry reach about 1 inch in 2 to 3 months. Males that mature late often grow the biggest sails, so be patient before culling. Breeders commonly report that full sails need a roomy tank, warm stable water, low nitrate and a rich diet, and can take many months to develop. Crowded males often mature small with short fins. Move promising males to a larger grow out tank.\n\nThin out crowded tanks as the young grow, and keep notes of birth dates and which parents produced each brood. Those records help you pick breeders and plan future broods."}, {"heading": "Common Mistakes", "text": "- Growing males in a small, crowded tank and expecting big sails.\n- Soft or acidic water.\n- Too many males chasing too few females.\n- Leaving fry with adults in a bare tank.\n- Crossing with other molly species and passing the fry off as pure sailfins.\n- Releasing unwanted fish outdoors. Sailfin mollies have become invasive outside their native range."}]$g$::jsonb, $g$[{"q": "How long are sailfin mollies pregnant?", "a": "Gestation is usually about 4 to 6 weeks at 75 to 80°F, and can be longer in cooler water."}, {"q": "How many babies do sailfin mollies have?", "a": "Broods are commonly 20 to 80 fry, with very large females sometimes dropping 100 or more."}, {"q": "Why doesn't my male sailfin molly have a big sail?", "a": "Sails develop best in large tanks with warm, clean, hard water and a rich diet, and can take many months. Crowding and early maturity often produce short sails."}, {"q": "Do sailfin mollies need salt?", "a": "Not necessarily. They tolerate brackish water, but hard, alkaline freshwater with good care suits them well."}]$g$::jsonb, $g$Show your chosen sailfin male and his females together with the challenge code in your stage 1 photo. Your 60 day grow-out photo is a good chance to show off young males starting their sails, so keep the fry in a roomy tank to give them the best start.$g$),
  ($g$swordtail$g$, $g$3446f272-ceb0-457e-b447-a8b98facabe0$g$::uuid, $g$swordtail$g$, null, $g$How to Breed Swordtails: Pregnancy, Fry and Raising Males$g$, $g$Breeding swordtails: females drop 20 to 80 or more fry about every 4 to 6 weeks. Easy and fun, as long as you protect the fry from the adults.$g$, $g$Swordtails are classic beginner livebearers, and a healthy female will give you a brood about every month. The fry are large and hardy, so the main task is keeping them away from hungry adults and feeding them well. Growing out a batch of swordtails is especially fun because the males develop their swords at different ages, and late bloomers often turn into the biggest fish.$g$, $g${"method": "Livebearer", "sexing": "Males have a gonopodium and a sword extension on the lower tail; females have neither", "group": "1 male to 2 or 3 females", "breeding_tank": "20 gallons or more, plants or a separate nursery tank", "conditioning": "2 to 3 weeks of quality flake plus frozen and vegetable foods", "trigger": "Mature, healthy fish breed on their own; females store sperm", "spawn": "Commonly 20 to 80 fry, large females well over 100", "eggs": "Gestation about 4 to 6 weeks at 75 to 80°F", "fry": "Born large and swimming, ready to eat at once", "first_foods": "Crushed flake and baby brine shrimp", "grow_out": "1 inch in about 2 to 3 months; males show swords from about 3 months", "parents": "Adults eat fry; plant heavily or move the female before birth"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "Swordtails are active swimmers, so use at least 20 gallons for a breeding group. Match the site's care numbers: pH 7.0 to 8.4, GH 12 to 30, and 75 to 80°F for breeding. Good filtration is important, and swordtails are known jumpers.\n\nPlant one end heavily with floating plants, hornwort or Java moss for fry cover, or keep a 10 gallon nursery tank with a sponge filter ready for the births.\n\nLet the tank cycle fully before adding fish, and keep a mature sponge filter running in a spare tank so you can set up a nursery at short notice. A tight lid stops adults jumping."}, {"heading": "Choosing and Conditioning a Breeding Group", "text": "Mature males are easy to sex: they have a gonopodium and the long sword on the bottom of the tail. Females are larger bodied with a fan-shaped anal fin and no sword. Young males can develop late, so a fish without a sword is not always a female until you check the anal fin.\n\nKeep 1 male to 2 or 3 females, because males chase hard and can fight each other. Condition for 2 to 3 weeks with flake, frozen bloodworms or brine shrimp and some vegetable flake.\n\nKeep up weekly water changes of 25 to 30 percent while conditioning. Clean, stable water and a varied diet give bigger, healthier broods."}, {"heading": "Mating and Pregnancy", "text": "The male swims in front of the female with his sword showing, then darts in to mate with the gonopodium. Females store sperm, so they can produce several broods from a single mating.\n\nA pregnant female grows deep and boxy, and the dark gravid spot near the vent becomes larger and darker as birth gets close."}, {"heading": "Gestation and Birth", "text": "Gestation is about 4 to 6 weeks at 75 to 80°F. Broods are commonly 20 to 80, and big, mature females can drop well over 100.\n\nMove the female a few days ahead to a heavily planted nursery tank, or use plenty of floating plants in the main tank. Small breeding boxes stress swordtails, so keep any time in them short. Return the female once she has finished giving birth."}, {"heading": "Raising the Fry", "text": "The fry are large and start eating right away.\n\n- Week 1: crushed flake and baby brine shrimp, four or five times a day.\n- Weeks 2 to 4: add microworms, crushed frozen foods and vegetable flake.\n- Change 25 to 30 percent of the water two or three times a week.\n- Keep 76 to 80°F for steady growth.\n\nFeed small amounts often and siphon any leftovers, because uneaten food fouls a fry tank quickly. Fry that are fed well in the first month grow into bigger, healthier adults, while stunted fry rarely catch up."}, {"heading": "Growing Out", "text": "Fry reach about 1 inch in 2 to 3 months. Some males show swords from around 3 months, but others take much longer, and these late developers often become the largest males. Separate males and females once you can sex them if you want control over pairings. Keep the best shaped fish with the strongest color as your next breeders.\n\nThin out crowded tanks as the young grow, and keep notes of birth dates and which parents produced each brood. Those records help you pick breeders and plan future broods."}, {"heading": "Common Mistakes", "text": "- Too many males in a small tank, leading to fighting.\n- Leaving fry with adults in a bare tank.\n- Culling swordless fish too early, when some are late males.\n- No lid on the tank.\n- Selling platy crosses as pure swordtails.\n- Releasing unwanted fish outdoors. Swordtails have become invasive in warm waters in several countries."}]$g$::jsonb, $g$[{"q": "How long are swordtails pregnant?", "a": "Swordtail gestation is about 4 to 6 weeks at 75 to 80°F, longer in cooler water."}, {"q": "How many babies do swordtails have?", "a": "Broods are commonly 20 to 80 fry, and large, mature females can drop well over 100."}, {"q": "Do swordtails eat their babies?", "a": "Yes, adults will eat fry. Use thick plants or a separate nursery tank to save most of the brood."}, {"q": "How can you tell a male swordtail from a female?", "a": "Males have a gonopodium (a rod-shaped anal fin) and usually a sword on the tail. Females have a fan-shaped anal fin, but young males may grow their sword late."}]$g$::jsonb, $g$Photograph your male, with his sword in view, and his females together with the challenge code for stage 1. At stage 5, a photo of the youngsters showing the first males developing swords makes a great finish to the log.$g$),
  ($g$electric-blue-acara$g$, $g$36c94ee2-1c06-438d-b4e2-1cbb05246b87$g$::uuid, $g$electric-blue-acara$g$, null, $g$How to Breed Blue Acaras: Pairs, Flat Stones and Raising Fry$g$, $g$Breeding blue acaras: a devoted cichlid pair lays a few hundred eggs on a flat stone and guards the fry. Straightforward with a dedicated tank.$g$, $g$Blue acaras are one of the friendliest cichlids to breed. A settled pair cleans a flat stone, lays a few hundred eggs and then guards the cloud of fry together, which is a real joy to watch. The electric blue form sold in many stores breeds the same way. Give the pair their own tank, keep the water clean, and they will often spawn again and again.$g$, $g${"method": "Substrate spawner (eggs on a flat stone, parents guard)", "sexing": "Males larger with longer, pointed dorsal and anal fins; females smaller; check the breeding tube at spawning", "group": "One pair, ideally formed from a group of young fish", "breeding_tank": "30 to 40 gallons, flat stones, sand, sponge filter", "conditioning": "2 to 3 weeks of frozen bloodworms, brine shrimp, mysis and quality pellets", "trigger": "A large water change with slightly cooler water and a cleaned stone", "spawn": "Commonly 150 to 400 eggs, sometimes more", "eggs": "Hatch in about 2 to 3 days at 78 to 80°F", "fry": "Free swimming about 3 to 5 days after hatching", "first_foods": "Baby brine shrimp and microworms", "grow_out": "About 1 inch in 6 to 8 weeks", "parents": "Usually good parents; young pairs may eat the first few spawns"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A pair does best in a 30 to 40 gallon tank of its own; the site lists 40 gallons for keeping adults. Use a sand bottom, a couple of smooth flat stones or a slate, and a few hiding spots. A sponge filter is safest for the fry.\n\nKeep pH 6.5 to 7.5, GH 5 to 18 and 78 to 80°F for spawning, which sits inside the site's 72 to 82°F range.\n\nSet the tank up and let it run for a few weeks before adding the fish, so the filter is fully cycled. Fry tanks get a lot of food, and a mature sponge filter handles that load far better than a new one. A heater guard and a tight lid are worth adding too."}, {"heading": "Choosing and Conditioning a Pair", "text": "Sexing young acaras is tricky. Adult males are usually larger, with longer, more pointed dorsal and anal fins and sometimes a steeper forehead. Females are smaller and rounder. The surest check is the breeding tube at spawning time: the female's is short and blunt, the male's is thinner and pointed.\n\nThe best way to get a pair is to grow 6 young fish together and let two pair off. Condition for 2 to 3 weeks with frozen bloodworms, brine shrimp, mysis and a good cichlid pellet.\n\nFeed small amounts two or three times a day rather than one large meal, and keep up water changes of 25 to 30 percent weekly while conditioning. Clean, stable water does as much to bring fish into spawning condition as rich food."}, {"heading": "Spawning", "text": "A ready pair darkens, locks jaws and digs, then scrubs a flat stone clean. A 30 to 50 percent water change with slightly cooler water often sets them off. The female makes passes laying rows of eggs, and the male follows to fertilize them.\n\nClutches are commonly 150 to 400 eggs. Both parents fan the eggs and chase away anything that comes close."}, {"heading": "Eggs and Fungus", "text": "Eggs hatch in about 2 to 3 days at 78 to 80°F. The parents pick out white, fungused eggs. If you choose to hatch them yourself, move the stone to a tank or container with the same water, an airstone beside the eggs, and a small dose of methylene blue.\n\nAfter hatching, the parents often move the wrigglers into pits in the sand. They become free swimming about 3 to 5 days later."}, {"heading": "Raising the Fry", "text": "- Week 1: newly hatched baby brine shrimp and microworms, three or four times a day.\n- Weeks 2 to 3: baby brine shrimp plus crushed flake and powdered pellets.\n- Week 4 onward: crushed pellets, frozen daphnia and cyclops.\n- Change 20 to 30 percent of the water twice a week, siphoning gently.\n- Keep 78 to 80°F.\n\nHatch baby brine shrimp daily so fresh live food is always on hand; fry that miss meals in the first week rarely catch up. Feed only what they clear in a few minutes and siphon leftovers, because uneaten food fouls small tanks quickly. Orange bellies after feeding mean the fry are eating well."}, {"heading": "Growing Out", "text": "Fry reach about 1 inch in 6 to 8 weeks with frequent feeding and clean water. Move them to a larger grow out tank once the parents start getting ready to spawn again, as they may chase older fry. Acaras grow steadily and are popular with local fish stores once they reach 1.5 to 2 inches.\n\nSeparate fry by size if some race ahead, since bigger siblings can outcompete or bully smaller ones. Keep notes of spawn dates, hatch dates and growth; they make future spawns easier to plan."}, {"heading": "Common Mistakes", "text": "- Pulling the eggs after one lost clutch; young pairs often need a few tries.\n- Tankmates that keep the parents stressed and distracted.\n- Too little food for the fry in the first week.\n- Big temperature swings during water changes.\n- Crossing acaras with other cichlids."}]$g$::jsonb, $g$[{"q": "How many eggs do blue acaras lay?", "a": "A typical clutch is about 150 to 400 eggs, and large, mature females can lay more."}, {"q": "How long do blue acara eggs take to hatch?", "a": "About 2 to 3 days at 78 to 80°F. The fry become free swimming roughly 3 to 5 days after that."}, {"q": "Do acaras eat their eggs?", "a": "Young pairs sometimes eat their first spawns. Most settle down after a few attempts if kept in a calm tank."}, {"q": "Do electric blue acaras breed the same way?", "a": "Yes. The electric blue is a line-bred aquarium form whose exact origin is debated, but it spawns on flat stones and guards its fry just like the regular blue acara."}]$g$::jsonb, $g$Get your pair in the tank and your log open before they clean a stone, and show the challenge code at stage 1. A clear photo of the eggs on the stone with a parent guarding makes excellent stage 2 evidence.$g$),
  ($g$bolivian-ram$g$, $g$3ab7d7f6-907e-4da1-a067-5c5baddc96c8$g$::uuid, $g$bolivian-ram$g$, null, $g$How to Breed Bolivian Rams: Pairing, Spawning and Fry Care$g$, $g$Breeding Bolivian rams: pairs lay 75 to 300 eggs on a flat stone and guard the fry. Hardier than German blue rams, with a little patience in pairing.$g$, $g$Bolivian rams are peaceful, hardy dwarf cichlids that make devoted parents. A pair cleans a flat stone, lays a neat patch of eggs, then herds the fry around the tank together. They are much more forgiving than German blue rams, so they make a great first dwarf cichlid to breed. The main hurdle is getting a true, compatible pair.$g$, $g${"method": "Substrate spawner (flat stone or shallow pit, both parents guard)", "sexing": "Males larger with longer tail extensions and pointed dorsal; hard to sex reliably when young", "group": "One pair, ideally picked from a group of 6 young fish", "breeding_tank": "20 to 30 gallons, sand, flat stones, cover, sponge filter", "conditioning": "2 to 3 weeks of frozen bloodworms, brine shrimp and quality small pellets", "trigger": "Stable warm water and a water change; pairs spawn on their own once settled", "spawn": "Commonly 75 to 300 eggs", "eggs": "Hatch in about 2 to 4 days at 78 to 80°F", "fry": "Free swimming about 4 to 6 days after hatching", "first_foods": "Baby brine shrimp and microworms", "grow_out": "About 1 inch in 8 to 10 weeks", "parents": "Usually good parents; young pairs may eat early clutches"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 20 to 30 gallon tank works for one pair; the site lists 30 gallons for keeping them. Use sand, a few flat stones or slate pieces, and plants or wood for cover. A sponge filter keeps the fry safe.\n\nKeep pH 6.5 to 7.0 and GH 4 to 10 for spawning, within the site's range of pH 6.0 to 7.8, and run 78 to 80°F. A few dither fish like a small tetra school help nervous pairs feel safe.\n\nSet the tank up and let it run for a few weeks before adding the fish, so the filter is fully cycled. Fry tanks get a lot of food, and a mature sponge filter handles that load far better than a new one. A heater guard and a tight lid are worth adding too."}, {"heading": "Choosing and Conditioning a Pair", "text": "Sexing Bolivian rams is not easy. Adult males are usually larger, with longer extensions on the tail and more pointed dorsal fin rays. Females tend to be rounder and may show a pinkish belly when ready. Even experienced keepers get it wrong with young fish.\n\nThe reliable route is to grow 6 juveniles together and let a pair form, then rehome the rest. Condition for 2 to 3 weeks with frozen bloodworms, brine shrimp and small, quality pellets.\n\nFeed small amounts two or three times a day rather than one large meal, and keep up water changes of 25 to 30 percent weekly while conditioning. Clean, stable water does as much to bring fish into spawning condition as rich food."}, {"heading": "Spawning", "text": "A ready pair stays close, cleans a flat stone and may dig shallow pits. The female lays rows of eggs and the male fertilizes them. Clutches are commonly 75 to 300 eggs.\n\nBoth parents take turns fanning the eggs and guarding the area. Keep the room quiet and avoid moving decor while they are busy."}, {"heading": "Eggs and Fungus", "text": "Eggs hatch in about 2 to 4 days at 78 to 80°F, and the parents often move the wrigglers into pits. Fry become free swimming roughly 4 to 6 days after hatching.\n\nThe parents normally remove infertile eggs. If you hatch eggs artificially, use water from the breeding tank, gentle aeration beside the stone and a little methylene blue to limit fungus."}, {"heading": "Raising the Fry", "text": "- Week 1: microworms and newly hatched baby brine shrimp, three or four times a day.\n- Weeks 2 to 4: baby brine shrimp plus finely crushed flake.\n- Change 15 to 25 percent of the water two or three times a week, matching temperature.\n- Keep 78 to 80°F.\n\nThe parents lead the fry to food, so feed near the school.\n\nHatch baby brine shrimp daily so fresh live food is always on hand; fry that miss meals in the first week rarely catch up. Feed only what they clear in a few minutes and siphon leftovers, because uneaten food fouls small tanks quickly. Orange bellies after feeding mean the fry are eating well."}, {"heading": "Growing Out", "text": "Bolivian ram fry grow at a moderate pace, reaching about 1 inch in 8 to 10 weeks. Move them to a grow out tank when the parents start preparing for the next spawn. Feed several small meals a day and keep nitrates low for good finnage and color.\n\nSeparate fry by size if some race ahead, since bigger siblings can outcompete or bully smaller ones. Keep notes of spawn dates, hatch dates and growth; they make future spawns easier to plan."}, {"heading": "Common Mistakes", "text": "- Buying two fish and assuming they are a pair.\n- Rough tankmates that bully the pair.\n- Giving up after one or two eaten clutches.\n- Letting nitrates build up while fry are being heavily fed.\n- Confusing them with German blue rams, which need much softer, warmer water."}]$g$::jsonb, $g$[{"q": "How many eggs do Bolivian rams lay?", "a": "A clutch is commonly 75 to 300 eggs, laid on a flat stone or in a shallow pit."}, {"q": "How long do Bolivian ram eggs take to hatch?", "a": "About 2 to 4 days at 78 to 80°F, with free swimming fry about 4 to 6 days after that."}, {"q": "How do you tell male and female Bolivian rams apart?", "a": "Males are usually bigger with longer tail extensions and more pointed fins, but it is unreliable in young fish. Growing up a group and letting a pair form is best."}, {"q": "Do Bolivian rams eat their eggs?", "a": "Young or stressed pairs sometimes do. A calm tank and a few practice spawns usually solve it."}]$g$::jsonb, $g$Bolivian rams can take a while to pair up, so open your log once your chosen pair is settled in the breeding tank and show both fish with the challenge code. For stage 2, photograph the eggs on the stone with a parent standing guard.$g$),
  ($g$umbrella-cichlid$g$, $g$8418c455-5fc3-4af1-abbb-8d37eea6c595$g$::uuid, $g$umbrella-cichlid$g$, null, $g$How to Breed Borelli's Apistogramma: Caves, Harems and Fry$g$, $g$Breeding Apistogramma borellii: the female lays in a cave and guards the fry alone. A rewarding, straightforward dwarf cichlid for a dedicated tank.$g$, $g$Apistogramma borellii, the umbrella dwarf cichlid, is one of the gentlest apistos and a great species to learn cave spawning with. The female lays her eggs on the ceiling of a cave and turns bright yellow while she guards them. Watching her lead a little cloud of fry across the sand is one of the best moments in the hobby, and the species breeds well in a quiet, soft water tank.$g$, $g${"method": "Cave spawner (female guards eggs and fry)", "sexing": "Males larger with tall, colorful dorsal and longer fins; females smaller and turn yellow when breeding", "group": "1 male to 1 or 2 females", "breeding_tank": "20 gallons, several small caves, sand, leaf litter, sponge filter", "conditioning": "2 to 3 weeks of live or frozen foods such as brine shrimp, daphnia and bloodworms", "trigger": "Soft, slightly acidic water and a cave to claim", "spawn": "Commonly about 40 to 100 eggs, occasionally more", "eggs": "Hatch in about 2 to 3 days at 76 to 78°F", "fry": "Free swimming about 4 to 6 days after hatching", "first_foods": "Microworms and baby brine shrimp", "grow_out": "About 0.5 inch in 6 to 8 weeks; slow growers", "parents": "Female guards; remove the male if he is harassed or in a small tank"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 20 gallon tank suits a male and one or two females. Give each female her own small cave, such as a coconut shell or clay cave, plus plants and leaf litter to break up lines of sight. Use sand and a sponge filter.\n\nFor spawning, aim for soft, slightly acidic water: pH 6.0 to 6.8 and GH 2 to 8, within the site's numbers. Borellii likes it a little cooler than many apistos, so 76 to 78°F works well.\n\nSet the tank up and let it run for a few weeks before adding the fish, so the filter is fully cycled. Fry tanks get a lot of food, and a mature sponge filter handles that load far better than a new one. A heater guard and a tight lid are worth adding too."}, {"heading": "Choosing and Conditioning Your Fish", "text": "Males are clearly larger, with a taller, colorful dorsal fin and longer fins, often with blue and yellow on the face and body. Females are smaller and plainer until breeding, when they turn bright yellow with dark markings.\n\nKeep 1 male with 1 or 2 females. Condition for 2 to 3 weeks with live or frozen foods: baby brine shrimp, daphnia, bloodworms and mosquito larvae. Apistos are mainly carnivores, so meaty foods matter.\n\nFeed small amounts two or three times a day rather than one large meal, and keep up water changes of 25 to 30 percent weekly while conditioning. Clean, stable water does as much to bring fish into spawning condition as rich food."}, {"heading": "Spawning", "text": "The male displays with fins spread in front of a female's cave. She leads him in and lays a clutch on the cave ceiling, commonly about 40 to 100 eggs. Afterward she drives him away and stays at the entrance.\n\nYou will rarely see the eggs. The best sign is a bright yellow female guarding a cave and refusing to leave it."}, {"heading": "Eggs and Hatching", "text": "Eggs hatch in about 2 to 3 days at 76 to 78°F. The wrigglers stay in the cave for roughly 4 to 6 more days before the female brings them out as free swimming fry.\n\nApisto mothers handle fungus well on their own. Keep the tank calm, avoid big water changes during this week, and do not shine lights into the cave."}, {"heading": "Raising the Fry", "text": "- Week 1: microworms and newly hatched baby brine shrimp, three or four small feedings a day.\n- Weeks 2 to 4: baby brine shrimp plus powdered flake.\n- Change 10 to 20 percent of the water twice a week with matched, soft water.\n- Keep 76 to 78°F.\n\nLeave the fry with the mother for 3 to 4 weeks, as she guards them and leads them to food.\n\nHatch baby brine shrimp daily so fresh live food is always on hand; fry that miss meals in the first week rarely catch up. Feed only what they clear in a few minutes and siphon leftovers, because uneaten food fouls small tanks quickly. Orange bellies after feeding mean the fry are eating well."}, {"heading": "Growing Out", "text": "Fry grow slowly, reaching about half an inch in 6 to 8 weeks. Move them to a grow out tank with gentle filtration once the mother loses interest. Several small meals a day and steady soft water give the best growth and color.\n\nSeparate fry by size if some race ahead, since bigger siblings can outcompete or bully smaller ones. Keep notes of spawn dates, hatch dates and growth; they make future spawns easier to plan."}, {"heading": "Common Mistakes", "text": "- Hard, alkaline water, which can reduce hatch rates.\n- No caves, or only one cave for two females.\n- Busy, aggressive tankmates that stress the mother.\n- Overfeeding and fouling a small tank.\n- Siphoning near the cave during the first week."}]$g$::jsonb, $g$[{"q": "How many eggs do Apistogramma borellii lay?", "a": "Clutches are commonly about 40 to 100 eggs, laid on the ceiling of a cave."}, {"q": "How long do Apistogramma eggs take to hatch?", "a": "About 2 to 3 days at 76 to 78°F. The fry usually come out of the cave free swimming 4 to 6 days later."}, {"q": "Does the male Apistogramma help with the fry?", "a": "Not usually. The female guards the eggs and fry and often chases the male away."}, {"q": "How do you know an Apistogramma female has spawned?", "a": "She turns bright yellow with dark markings and stays at the cave entrance, chasing off other fish."}]$g$::jsonb, $g$Open your log with the male and females in the tank and the challenge code showing, before any yellow female appears. Since the eggs are hidden in a cave, a clear photo of the bright yellow female guarding her cave is good stage 2 evidence, followed by the fry when she brings them out.$g$),
  ($g$cockatoo-dwarf-cichlid$g$, $g$b1716dbf-6180-4ebb-a1e8-95229b7416c1$g$::uuid, $g$cockatoo-dwarf-cichlid$g$, null, $g$How to Breed Cockatoo Cichlids: Harems, Caves and Fry Care$g$, $g$Breeding cockatoo cichlids: females lay in caves and guard the fry alone. Hardy and reliable, a great first Apistogramma for a dedicated tank.$g$, $g$The cockatoo cichlid is one of the hardiest and most popular Apistogramma, and one of the most reliable to breed. The male shows off his tall, crest-like dorsal fin, and each female claims a cave, lays her eggs and turns yellow while she guards them. A male with two or three females in a well planted tank can give you several broods to raise.$g$, $g${"method": "Cave spawner (female guards eggs and fry)", "sexing": "Males much larger with crest-like dorsal and colorful tail; females small, yellow when breeding", "group": "1 male to 2 or 3 females (harem)", "breeding_tank": "20 gallons or more, a cave per female, sand, plants, sponge filter", "conditioning": "2 to 3 weeks of live or frozen baby brine shrimp, daphnia and bloodworms", "trigger": "Soft, slightly acidic water and a cave for each female", "spawn": "Commonly 50 to 150 eggs", "eggs": "Hatch in about 2 to 3 days at 78 to 82°F", "fry": "Free swimming about 4 to 6 days after hatching", "first_foods": "Microworms and baby brine shrimp", "grow_out": "About 0.5 to 0.75 inch in 6 to 8 weeks", "parents": "Female guards; the male may be chased off or remove him"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 20 gallon long tank suits a male and two or three females, with more room better for a harem. Give each female her own cave, spaced apart, with plants, wood and leaf litter between them. Use sand and a sponge filter.\n\nThe site lists 75 to 82°F, pH 6.0 to 7.5 and GH 2 to 12. For spawning, aim for pH 6.0 to 7.0 and soft water. Temperature is known to affect the sex ratio of Apistogramma fry: breeders commonly report more males at the warm end and more females when cooler, so around 78°F gives a better mix.\n\nSet the tank up and let it run for a few weeks before adding the fish, so the filter is fully cycled. Fry tanks get a lot of food, and a mature sponge filter handles that load far better than a new one. A heater guard and a tight lid are worth adding too."}, {"heading": "Choosing and Conditioning Your Fish", "text": "Males are easy to sex once grown. They are much larger, with long, crest-like front dorsal rays and a colorful tail that is often marked with red or orange in tank strains. Females stay small and plain, turning bright yellow with dark markings when breeding.\n\nCondition for 2 to 3 weeks with live or frozen baby brine shrimp, daphnia, bloodworms and mosquito larvae, plus a good small pellet.\n\nFeed small amounts two or three times a day rather than one large meal, and keep up water changes of 25 to 30 percent weekly while conditioning. Clean, stable water does as much to bring fish into spawning condition as rich food."}, {"heading": "Spawning", "text": "The male displays at the cave entrances. A ready female invites him in and lays her eggs on the cave ceiling, commonly 50 to 150. She then guards the cave and drives off the male and other fish.\n\nWith several females, spawns may be spread out, and you may have more than one yellow mother at once."}, {"heading": "Eggs and Hatching", "text": "Eggs hatch in about 2 to 3 days at 78 to 82°F. The wrigglers stay in the cave for roughly another 4 to 6 days, and then the female brings out free swimming fry.\n\nThe mother handles fungus. Keep the tank calm, light lower than usual, and hold off on big water changes until the fry are out and feeding."}, {"heading": "Raising the Fry", "text": "- Week 1: microworms and newly hatched baby brine shrimp, three or four times a day.\n- Weeks 2 to 4: baby brine shrimp plus powdered flake or fine crumble.\n- Change 15 to 20 percent of the water twice a week, matched for temperature.\n- Keep 78 to 80°F.\n\nIn a busy tank, the male or other females may pick at fry. Moving the mother and her brood to a small tank of their own gives the best results.\n\nHatch baby brine shrimp daily so fresh live food is always on hand; fry that miss meals in the first week rarely catch up. Feed only what they clear in a few minutes and siphon leftovers, because uneaten food fouls small tanks quickly. Orange bellies after feeding mean the fry are eating well."}, {"heading": "Growing Out", "text": "Fry reach about 0.5 to 0.75 inch in 6 to 8 weeks. Males show their longer fins and the start of the crest from around 2 to 3 months. Grow them in a tank with gentle flow and plenty of small meals for the best fins and color.\n\nSeparate fry by size if some race ahead, since bigger siblings can outcompete or bully smaller ones. Keep notes of spawn dates, hatch dates and growth; they make future spawns easier to plan."}, {"heading": "Common Mistakes", "text": "- Too few caves, leading to fighting between females.\n- Breeding only at very high temperatures and ending up with mostly males.\n- Leaving fry in a crowded community tank.\n- Hard, alkaline water that lowers hatch rates.\n- Disturbing the cave in the first few days."}]$g$::jsonb, $g$[{"q": "How many eggs do cockatoo cichlids lay?", "a": "A clutch is commonly 50 to 150 eggs, laid on the ceiling of a cave."}, {"q": "How long do cockatoo cichlid eggs take to hatch?", "a": "About 2 to 3 days at 78 to 82°F, with free swimming fry about 4 to 6 days later."}, {"q": "Does temperature affect the sex of Apistogramma fry?", "a": "Yes. Breeders commonly report that warmer water produces more males and cooler water more females, so a middle temperature gives a better mix."}, {"q": "Can you keep one male cockatoo cichlid with several females?", "a": "Yes. They are commonly kept as a harem of one male with two or three females, as long as each female has her own cave."}]$g$::jsonb, $g$With a harem, make sure your stage 1 photo shows the male and the females you expect to breed, plus the challenge code. A yellow female at her cave, then her fry when she brings them out, gives clear evidence for stages 2 and 3.$g$),
  ($g$firemouth-cichlid$g$, $g$49d3e84b-6928-43c0-a23f-b30fbc1f3c8e$g$::uuid, $g$firemouth-cichlid$g$, null, $g$How to Breed Firemouth Cichlids: Pairs, Stones and Fry Care$g$, $g$Breeding firemouth cichlids: pairs lay 100 to 500 eggs on a flat stone and guard the fry together. Straightforward with a dedicated tank.$g$, $g$Firemouths are classic Central American cichlids and dependable breeders. A pair flares their red throats, cleans a flat stone and lays a few hundred eggs, then both parents guard the fry as a team. They are less aggressive than many of their relatives, so a breeding pair is manageable in a modest tank, and the fry are easy to raise on baby brine shrimp.$g$, $g${"method": "Substrate spawner (flat stone, both parents guard)", "sexing": "Males larger with longer, pointed dorsal and anal fins and more red; check breeding tubes at spawning", "group": "One pair, ideally formed from a group", "breeding_tank": "40 gallons, sand, flat stones, some cover", "conditioning": "2 to 3 weeks of pellets, frozen bloodworms, brine shrimp and mysis", "trigger": "A cool water change and a cleaned flat stone", "spawn": "Commonly 100 to 500 eggs", "eggs": "Hatch in about 2 to 3 days at 78 to 80°F", "fry": "Free swimming about 3 to 5 days after hatching", "first_foods": "Baby brine shrimp", "grow_out": "About 1 inch in 6 to 8 weeks", "parents": "Good parents; remove other fish so the pair is not stressed"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A pair needs about 40 gallons, matching the site's minimum. Use sand, two or three flat stones or a slate, and some wood or rocks so the pair can claim a territory. Firemouths dig, so anchor plants or use hardy ones on wood.\n\nKeep pH 7.0 to 7.5, GH 8 to 15 and 78 to 80°F for breeding, within the site's numbers. A sponge filter or a canister with a guarded intake protects the fry.\n\nSet the tank up and let it run for a few weeks before adding the fish, so the filter is fully cycled. Fry tanks get a lot of food, and a mature sponge filter handles that load far better than a new one. A heater guard and a tight lid are worth adding too."}, {"heading": "Choosing and Conditioning a Pair", "text": "Adult males are usually larger, with longer and more pointed dorsal and anal fins and a deeper red throat. Females are smaller and rounder. At spawning time the breeding tubes settle it: the female's is broad and blunt, the male's thin and pointed.\n\nGrowing 6 juveniles together and letting a pair form gives the best results. Condition for 2 to 3 weeks with good cichlid pellets, frozen bloodworms, brine shrimp and mysis.\n\nFeed small amounts two or three times a day rather than one large meal, and keep up water changes of 25 to 30 percent weekly while conditioning. Clean, stable water does as much to bring fish into spawning condition as rich food."}, {"heading": "Spawning", "text": "Paired firemouths flare their red throats at each other and other fish. They clean a flat stone, and the female lays rows of eggs while the male fertilizes them. A cool 30 to 40 percent water change often triggers the spawn.\n\nClutches are commonly 100 to 500 eggs. Both parents fan the eggs and defend the area hard."}, {"heading": "Eggs and Fungus", "text": "Eggs hatch in about 2 to 3 days at 78 to 80°F. The parents usually move the wrigglers to pits in the sand and keep them there until they are free swimming, about 3 to 5 days after hatching.\n\nThe parents remove fungused eggs. If you hatch the stone yourself, use tank water, an airstone beside the eggs and a little methylene blue."}, {"heading": "Raising the Fry", "text": "- Week 1: newly hatched baby brine shrimp, three or four times a day.\n- Weeks 2 to 3: baby brine shrimp plus crushed flake.\n- Week 4 onward: crushed pellets and frozen daphnia or cyclops.\n- Change 25 to 30 percent of the water twice a week.\n- Keep 78 to 80°F.\n\nHatch baby brine shrimp daily so fresh live food is always on hand; fry that miss meals in the first week rarely catch up. Feed only what they clear in a few minutes and siphon leftovers, because uneaten food fouls small tanks quickly. Orange bellies after feeding mean the fry are eating well."}, {"heading": "Growing Out", "text": "Fry grow quickly and reach about 1 inch in 6 to 8 weeks. Move them out once the parents start to prepare for the next spawn, because older fry may be chased. Juveniles sell best at 1.5 to 2 inches, when the red is starting to show.\n\nSeparate fry by size if some race ahead, since bigger siblings can outcompete or bully smaller ones. Keep notes of spawn dates, hatch dates and growth; they make future spawns easier to plan."}, {"heading": "Common Mistakes", "text": "- Keeping a breeding pair with tankmates that get beaten up.\n- Forcing two random adults together.\n- Underfeeding the fry in the first two weeks.\n- Letting nitrate climb in a heavily fed fry tank.\n- Crossing firemouths with other Thorichthys species."}]$g$::jsonb, $g$[{"q": "How many eggs do firemouth cichlids lay?", "a": "Clutches are commonly 100 to 500 eggs, laid on a flat stone."}, {"q": "How long do firemouth eggs take to hatch?", "a": "About 2 to 3 days at 78 to 80°F. The fry are free swimming roughly 3 to 5 days after hatching."}, {"q": "Do firemouth cichlids protect their babies?", "a": "Yes. Both parents guard the eggs and fry, often for several weeks."}, {"q": "How can you tell a male firemouth from a female?", "a": "Males are usually larger with longer, pointed fins and more red. The breeding tubes seen at spawning time are the surest check."}]$g$::jsonb, $g$Open the log and show your pair with the challenge code before they start cleaning stones. Firemouth parents guard closely, so a photo of the pair hovering over a cloud of free swimming fry makes a strong stage 3 shot.$g$),
  ($g$dwarf-flag-cichlid$g$, $g$ea06fa64-6297-4db6-9d7f-37c416f80228$g$::uuid, $g$dwarf-flag-cichlid$g$, null, $g$How to Breed Flag Cichlids (Laetacara curviceps): Full Guide$g$, $g$Breeding the flag cichlid: a gentle dwarf that lays on a flat stone or leaf and guards fry as a pair. Straightforward, though sexing is tricky.$g$, $g$The flag cichlid, Laetacara curviceps, is a small, peaceful South American cichlid that makes a lovely breeding project. Pairs lay their eggs on a flat stone or broad leaf and care for the fry together, often moving them between pits. They are gentle enough for a planted tank, and once a pair forms they spawn regularly. The hardest part is telling males from females.$g$, $g${"method": "Substrate spawner (flat stone or broad leaf, both parents guard)", "sexing": "Difficult; males slightly larger with longer, pointed dorsal and anal fins", "group": "One pair, ideally picked from a group of 6", "breeding_tank": "20 gallons, flat stones, broad leaved plants, sand, sponge filter", "conditioning": "2 to 3 weeks of frozen bloodworms, brine shrimp, daphnia and small pellets", "trigger": "Soft, slightly acidic water and a water change", "spawn": "Commonly 100 to 200 eggs, sometimes more", "eggs": "Hatch in about 2 to 3 days at 78 to 80°F", "fry": "Free swimming about 4 to 6 days after hatching", "first_foods": "Microworms and baby brine shrimp", "grow_out": "About 0.5 to 0.75 inch in 8 weeks", "parents": "Usually good parents; young pairs may eat early spawns"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 20 gallon tank is enough for one pair, matching the site's minimum. Add sand, a few smooth stones and broad leaved plants such as Amazon swords, plus wood for cover. A sponge filter keeps the fry safe.\n\nThe site lists 75 to 82°F, pH 6.0 to 7.5 and GH 2 to 12. For spawning, soft water at pH 6.0 to 7.0 and 78 to 80°F works well. A small school of peaceful dither fish helps the pair feel secure.\n\nSet the tank up and let it run for a few weeks before adding the fish, so the filter is fully cycled. Fry tanks get a lot of food, and a mature sponge filter handles that load far better than a new one. A heater guard and a tight lid are worth adding too."}, {"heading": "Choosing and Conditioning a Pair", "text": "Sexing is honestly difficult. Males tend to be slightly larger, with longer and more pointed dorsal and anal fins, but the differences are small and inconsistent. The breeding tubes at spawning time are the surest check.\n\nBuy 6 young fish and let a pair form on its own. Condition for 2 to 3 weeks with frozen bloodworms, brine shrimp, daphnia and small, quality pellets.\n\nFeed small amounts two or three times a day rather than one large meal, and keep up water changes of 25 to 30 percent weekly while conditioning. Clean, stable water does as much to bring fish into spawning condition as rich food."}, {"heading": "Spawning", "text": "A pair stays together, darkens a little and cleans a flat stone or a broad leaf. The female lays rows of eggs, followed by the male. Clutches are commonly 100 to 200, sometimes more from large females.\n\nBoth parents tend the eggs. They are gentle with tankmates for a cichlid, but will still chase fish away from the nest."}, {"heading": "Eggs and Hatching", "text": "Eggs hatch in about 2 to 3 days at 78 to 80°F. The parents commonly move the wrigglers between small pits, and the fry become free swimming roughly 4 to 6 days after hatching.\n\nParents remove bad eggs. If eggs keep turning white, check that the water is soft enough and that the pair is not disturbed."}, {"heading": "Raising the Fry", "text": "- Week 1: microworms and newly hatched baby brine shrimp, three or four times a day.\n- Weeks 2 to 4: baby brine shrimp plus powdered flake.\n- Change 15 to 25 percent of the water twice a week, matching temperature.\n- Keep 78 to 80°F.\n\nHatch baby brine shrimp daily so fresh live food is always on hand; fry that miss meals in the first week rarely catch up. Feed only what they clear in a few minutes and siphon leftovers, because uneaten food fouls small tanks quickly. Orange bellies after feeding mean the fry are eating well."}, {"heading": "Growing Out", "text": "Flag cichlid fry grow at a moderate pace, reaching around 0.5 to 0.75 inch in 8 weeks. Move them to a grow out tank once the parents begin preparing to spawn again. Clean water and several small meals a day bring out the best shape and color.\n\nSeparate fry by size if some race ahead, since bigger siblings can outcompete or bully smaller ones. Keep notes of spawn dates, hatch dates and growth; they make future spawns easier to plan."}, {"heading": "Common Mistakes", "text": "- Assuming two store fish are a pair.\n- Hard, alkaline water that lowers hatch rates.\n- Busy, aggressive tankmates.\n- Giving up after one eaten clutch.\n- Big water changes during the egg stage."}]$g$::jsonb, $g$[{"q": "How many eggs do flag cichlids lay?", "a": "Laetacara curviceps commonly lays around 100 to 200 eggs on a flat stone or broad leaf."}, {"q": "How long do flag cichlid eggs take to hatch?", "a": "About 2 to 3 days at 78 to 80°F, with free swimming fry about 4 to 6 days later."}, {"q": "How do you sex flag cichlids?", "a": "It is difficult. Males are often slightly larger with longer fins, but the breeding tubes at spawning are the only sure sign."}, {"q": "Are flag cichlids good parents?", "a": "Usually yes. Both parents guard the eggs and fry, though young pairs may eat their first spawns."}]$g$::jsonb, $g$Because sexing is hard, your stage 1 photo should show the two fish that have clearly paired off, together with the challenge code. Eggs on a stone or leaf with a parent hovering close make solid stage 2 evidence.$g$),
  ($g$golden-dwarf-cichlid$g$, $g$fbc263ac-3883-44dc-a523-874744281d26$g$::uuid, null, null, $g$How to Breed Golden Dwarf Cichlids (Nannacara anomala)$g$, $g$Breeding Nannacara anomala: the female guards eggs and fry, often chasing the male away. A rewarding dwarf cichlid with a dedicated tank and caves.$g$, $g$The golden dwarf cichlid, Nannacara anomala, is a small, hardy cichlid with a big personality. The male shines with metallic green and gold, and after spawning the female takes over, wearing a bold checkerboard pattern while she guards the fry. She is a fierce mother and often chases the male away, so the trick to success is giving him somewhere to hide or moving him out.$g$, $g${"method": "Substrate spawner, often under cover (female guards)", "sexing": "Males much larger and metallic; females smaller, show a dark checkerboard when guarding", "group": "One pair or 1 male to 2 females", "breeding_tank": "20 gallons, caves and flat stones, plants, sand, sponge filter", "conditioning": "2 to 3 weeks of frozen bloodworms, brine shrimp, daphnia and small pellets", "trigger": "Soft, slightly acidic water at 76 to 80°F", "spawn": "Commonly 100 to 300 eggs", "eggs": "Hatch in about 2 to 4 days at 78 to 80°F", "fry": "Free swimming about 4 to 6 days after hatching", "first_foods": "Microworms and baby brine shrimp", "grow_out": "About 0.5 inch in 6 to 8 weeks", "parents": "Female guards and may attack the male; remove him in small tanks"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 20 gallon tank works for a pair. Add a couple of caves or overhangs, flat stones, plants and wood, so the male can stay out of sight once the female takes over. Use sand and a sponge filter.\n\nNannacara anomala is adaptable, but soft, slightly acidic water helps spawning: pH 6.0 to 7.0, low hardness and 76 to 80°F.\n\nSet the tank up and let it run for a few weeks before adding the fish, so the filter is fully cycled. Fry tanks get a lot of food, and a mature sponge filter handles that load far better than a new one. A heater guard and a tight lid are worth adding too."}, {"heading": "Choosing and Conditioning a Pair", "text": "Adults are easy to sex. Males grow clearly larger, around 3 inches, with a metallic green to gold sheen and longer fins. Females stay smaller, about 2 inches, and are plainer, turning a striking checkerboard of dark patches when breeding.\n\nKeep 1 male with 1 or 2 females. Condition for 2 to 3 weeks with frozen bloodworms, brine shrimp, daphnia and small pellets.\n\nFeed small amounts two or three times a day rather than one large meal, and keep up water changes of 25 to 30 percent weekly while conditioning. Clean, stable water does as much to bring fish into spawning condition as rich food."}, {"heading": "Spawning", "text": "The male displays to the female with fins spread. They clean a stone or a surface inside a cave, and the female lays her eggs, commonly 100 to 300. Soon after, she darkens into her checkered breeding colors and starts driving the male off.\n\nIn a small tank she can injure him. If he is being chased constantly, move him out."}, {"heading": "Eggs and Hatching", "text": "Eggs hatch in about 2 to 4 days at 78 to 80°F. The female often moves the wrigglers to pits, and they become free swimming roughly 4 to 6 days after hatching.\n\nShe removes bad eggs herself. Keep the tank quiet and avoid moving decor during this stage."}, {"heading": "Raising the Fry", "text": "- Week 1: microworms and newly hatched baby brine shrimp, three or four times a day.\n- Weeks 2 to 4: baby brine shrimp plus powdered flake.\n- Change 15 to 20 percent of the water twice a week.\n- Keep 78 to 80°F.\n\nThe mother leads the fry around the tank for several weeks and is a dedicated guardian.\n\nHatch baby brine shrimp daily so fresh live food is always on hand; fry that miss meals in the first week rarely catch up. Feed only what they clear in a few minutes and siphon leftovers, because uneaten food fouls small tanks quickly. Orange bellies after feeding mean the fry are eating well."}, {"heading": "Growing Out", "text": "Fry reach about half an inch in 6 to 8 weeks. Once the mother loses interest or the fry are well grown, move them to a grow out tank. Males start to show their extra size and metallic color as they mature.\n\nSeparate fry by size if some race ahead, since bigger siblings can outcompete or bully smaller ones. Keep notes of spawn dates, hatch dates and growth; they make future spawns easier to plan."}, {"heading": "Common Mistakes", "text": "- Leaving the male in a small tank with a guarding female.\n- No cover or caves for the fish to retreat to.\n- Hard, alkaline water that lowers hatch rates.\n- Food too big for the fry in the first week.\n- Big water changes while eggs are developing."}]$g$::jsonb, $g$[{"q": "Does the male Nannacara help raise the fry?", "a": "Usually not. The female takes over care and often chases the male away, sometimes hard enough to hurt him."}, {"q": "How many eggs does Nannacara anomala lay?", "a": "Clutches are commonly 100 to 300 eggs, laid on a stone or inside a cave."}, {"q": "How do you tell male and female golden dwarf cichlids apart?", "a": "Males are much larger and metallic green to gold. Females are smaller and show a dark checkerboard pattern when breeding."}, {"q": "How long do golden dwarf cichlid eggs take to hatch?", "a": "About 2 to 4 days at 78 to 80°F, with free swimming fry about 4 to 6 days later."}]$g$::jsonb, $g$Open your log with the pair together in the tank and the challenge code in the shot, before the female drives the male off. A photo of the checkered female guarding her eggs or fry makes clear stage 2 or 3 evidence.$g$),
  ($g$jack-dempsey$g$, $g$c673fb2b-d454-4cb7-93c8-7337843919a7$g$::uuid, $g$jack-dempsey$g$, null, $g$How to Breed Jack Dempsey Cichlids: Pairs, Eggs and Fry Care$g$, $g$Breeding Jack Dempseys: a bonded pair lays hundreds of eggs on a flat stone and guards the fry fiercely. Straightforward with a large dedicated tank.$g$, $g$Jack Dempseys are big, bold cichlids, and a bonded pair makes impressive parents. They clean a flat stone, lay hundreds of eggs and guard their fry fiercely together. Breeding is not hard once you have a compatible pair, but adults can be rough with each other, so the real work is forming the pair and giving them enough room.$g$, $g${"method": "Substrate spawner (flat stone, both parents guard)", "sexing": "Males larger with longer, pointed fins and more blue spangling; check breeding tubes at spawning", "group": "One pair, ideally formed from a group of juveniles", "breeding_tank": "55 to 75 gallons, sand, flat stones, rockwork", "conditioning": "2 to 3 weeks of quality pellets, frozen krill, mysis and bloodworms", "trigger": "A large water change and a cleaned flat stone", "spawn": "Commonly 500 to 800 eggs, sometimes over 1,000", "eggs": "Hatch in about 2 to 4 days at 78 to 82°F", "fry": "Free swimming about 4 to 6 days after hatching", "first_foods": "Baby brine shrimp", "grow_out": "About 1 inch in 6 to 8 weeks", "parents": "Devoted parents; watch for the male turning on the female"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A breeding pair needs at least 55 gallons, matching the site's minimum, and 75 gallons gives more room for the female to escape if the male gets rough. Use sand, a large flat stone or slate, and rock caves that create separate territories.\n\nKeep pH 7.0 to 7.5, GH 8 to 15 and 78 to 82°F for breeding, all inside the site's ranges. Use strong filtration, since this is a messy, heavily fed species.\n\nSet the tank up and let it run for a few weeks before adding the fish, so the filter is fully cycled. Fry tanks get a lot of food, and a mature sponge filter handles that load far better than a new one. A heater guard and a tight lid are worth adding too."}, {"heading": "Choosing and Conditioning a Pair", "text": "Adult males are usually larger, with longer and more pointed dorsal and anal fins and more blue and green spangles. Females are smaller, with shorter fins and usually less spangling. The breeding tubes at spawning time are the surest check.\n\nPairs are safest formed by growing 5 or 6 juveniles together, then removing the rest once two pair off. Condition for 2 to 3 weeks with pellets, frozen krill, mysis and bloodworms.\n\nFeed small amounts two or three times a day rather than one large meal, and keep up water changes of 25 to 30 percent weekly while conditioning. Clean, stable water does as much to bring fish into spawning condition as rich food."}, {"heading": "Spawning", "text": "A ready pair darkens almost to black with bright spangles, digs pits and cleans a flat stone. The female lays rows of eggs and the male fertilizes them. A large water change often sets them off.\n\nClutches are commonly 500 to 800 eggs and can exceed 1,000. Both parents defend the site and will charge your hand."}, {"heading": "Eggs and Fungus", "text": "Eggs hatch in about 2 to 4 days at 78 to 82°F. The parents move the wrigglers to pits, and the fry become free swimming roughly 4 to 6 days after hatching.\n\nThe parents remove fungused eggs. To hatch artificially, move the stone to a tank with matching water, an airstone beside it and a little methylene blue."}, {"heading": "Raising the Fry", "text": "- Week 1: newly hatched baby brine shrimp, three or four times a day.\n- Weeks 2 to 3: baby brine shrimp plus crushed flake.\n- Week 4 onward: crushed pellets and frozen foods.\n- Change 30 percent of the water twice a week, as fry produce a lot of waste.\n- Keep 78 to 80°F.\n\nHatch baby brine shrimp daily so fresh live food is always on hand; fry that miss meals in the first week rarely catch up. Feed only what they clear in a few minutes and siphon leftovers, because uneaten food fouls small tanks quickly. Orange bellies after feeding mean the fry are eating well."}, {"heading": "Growing Out", "text": "Fry grow quickly to about 1 inch in 6 to 8 weeks. With hundreds of fry, you will need grow out space fast. Split them into larger tanks to avoid stunting and aggression. Juveniles sell best at 1.5 to 2 inches.\n\nSeparate fry by size if some race ahead, since bigger siblings can outcompete or bully smaller ones. Keep notes of spawn dates, hatch dates and growth; they make future spawns easier to plan."}, {"heading": "Common Mistakes", "text": "- Putting two random adults together, which can end in injury.\n- A tank too small for the female to escape.\n- Not planning grow out space for hundreds of fry.\n- Hands in the tank during guarding, which can lead to bites.\n- Crossing with other cichlids. Never release fish or fry outdoors."}]$g$::jsonb, $g$[{"q": "How many eggs do Jack Dempseys lay?", "a": "Clutches are commonly 500 to 800 eggs and can exceed 1,000 from large females."}, {"q": "How long do Jack Dempsey eggs take to hatch?", "a": "About 2 to 4 days at 78 to 82°F, with free swimming fry about 4 to 6 days later."}, {"q": "Do Jack Dempseys protect their fry?", "a": "Yes. Both parents guard the eggs and fry closely and will attack tankmates and even your hand."}, {"q": "What size tank do Jack Dempseys need to breed?", "a": "At least 55 gallons for a pair, and 75 gallons gives more room if the male becomes aggressive."}]$g$::jsonb, $g$Open the log and show the bonded pair with the challenge code as soon as they are settled together. Jack Dempseys produce big spawns, so plan your grow out tanks before stage 3 and photograph a good sample of fry for the 30 and 60 day stages.$g$),
  ($g$keyhole-cichlid$g$, $g$e4b52d84-dd7b-473b-97f7-6758500aef72$g$::uuid, $g$keyhole-cichlid$g$, null, $g$How to Breed Keyhole Cichlids: Shy Pairs, Leaves and Fry Care$g$, $g$Breeding keyhole cichlids: a shy, peaceful pair lays eggs on a leaf or stone and guards slow growing fry. Straightforward in a calm, dedicated tank.$g$, $g$Keyhole cichlids are among the gentlest cichlids you can keep, and a settled pair makes calm, attentive parents. They usually lay their eggs on a flat stone or a loose leaf and care for the fry together. Breeding them is mostly about patience: they are shy, take time to settle and pair up, and the fry grow slowly, but a well raised batch of keyholes is very satisfying.$g$, $g${"method": "Substrate spawner (flat stone or loose leaf, both parents guard)", "sexing": "Difficult; males often slightly larger with longer dorsal and anal fins", "group": "One pair, ideally picked from a group of 6", "breeding_tank": "30 gallons, sand, flat stones, leaf litter, dense cover, sponge filter", "conditioning": "2 to 3 weeks of frozen bloodworms, brine shrimp, daphnia and small pellets", "trigger": "A calm, settled tank and a slightly cool water change", "spawn": "Commonly 100 to 300 eggs", "eggs": "Hatch in about 2 to 4 days at 78 to 80°F", "fry": "Free swimming about 4 to 6 days after hatching", "first_foods": "Microworms and baby brine shrimp", "grow_out": "Slow; about 0.5 to 0.75 inch in 8 weeks", "parents": "Good parents once settled; shy pairs may eat eggs if disturbed"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 30 gallon tank suits one pair, matching the site's minimum. Keyholes are shy, so give them plenty of cover: wood, plants, leaf litter and a few flat stones. Dim light and a small school of peaceful dither fish help them feel safe enough to spawn.\n\nThe site lists 72 to 82°F, pH 6.0 to 7.5 and GH 3 to 12. For spawning, soft water at pH 6.0 to 7.0 and 78 to 80°F works well. Use a sponge filter.\n\nSet the tank up and let it run for a few weeks before adding the fish, so the filter is fully cycled. Fry tanks get a lot of food, and a mature sponge filter handles that load far better than a new one. A heater guard and a tight lid are worth adding too."}, {"heading": "Choosing and Conditioning a Pair", "text": "Sexing keyholes is difficult. Males are often slightly larger, with longer, more pointed dorsal and anal fins, but the differences are subtle. The breeding tubes seen at spawning time are the surest sign.\n\nGrow a group of 6 juveniles and let a pair form. Condition for 2 to 3 weeks with frozen bloodworms, brine shrimp, daphnia and small, quality pellets.\n\nFeed small amounts two or three times a day rather than one large meal, and keep up water changes of 25 to 30 percent weekly while conditioning. Clean, stable water does as much to bring fish into spawning condition as rich food."}, {"heading": "Spawning", "text": "A pair stays close and cleans a flat stone or a loose leaf. The female lays rows of eggs and the male fertilizes them, commonly 100 to 300. Breeders often report that keyholes like a loose leaf because they can move it, eggs and all, if they feel threatened.\n\nKeep foot traffic and disturbance low for the first week."}, {"heading": "Eggs and Hatching", "text": "Eggs hatch in about 2 to 4 days at 78 to 80°F. The parents move the wrigglers into pits or onto leaves, and the fry become free swimming roughly 4 to 6 days after hatching.\n\nIf a shy pair keeps eating eggs, more cover, a quieter spot and dither fish usually help more than artificial hatching."}, {"heading": "Raising the Fry", "text": "- Week 1: microworms and newly hatched baby brine shrimp, three or four times a day.\n- Weeks 2 to 4: baby brine shrimp plus powdered flake.\n- Change 15 to 25 percent of the water twice a week, matching temperature.\n- Keep 78 to 80°F.\n\nThe parents guard the fry for several weeks and are rarely aggressive about it.\n\nHatch baby brine shrimp daily so fresh live food is always on hand; fry that miss meals in the first week rarely catch up. Feed only what they clear in a few minutes and siphon leftovers, because uneaten food fouls small tanks quickly. Orange bellies after feeding mean the fry are eating well."}, {"heading": "Growing Out", "text": "Keyhole fry are known as slow growers. Expect about 0.5 to 0.75 inch by 8 weeks with good feeding. Move them to a grow out tank once the parents prepare to spawn again, and keep them with gentle tankmates, since they are easily outcompeted for food.\n\nSeparate fry by size if some race ahead, since bigger siblings can outcompete or bully smaller ones. Keep notes of spawn dates, hatch dates and growth; they make future spawns easier to plan."}, {"heading": "Common Mistakes", "text": "- A bright, bare tank with no cover.\n- Boisterous tankmates that stress the pair.\n- Expecting fast growth from the fry.\n- Big water changes or rearranging decor while eggs are present.\n- Assuming two fish are a pair before they bond."}]$g$::jsonb, $g$[{"q": "How many eggs do keyhole cichlids lay?", "a": "Clutches are commonly 100 to 300 eggs, laid on a flat stone or loose leaf."}, {"q": "How long do keyhole cichlid eggs take to hatch?", "a": "About 2 to 4 days at 78 to 80°F, with free swimming fry about 4 to 6 days later."}, {"q": "Are keyhole cichlids good parents?", "a": "Yes, once they are settled. Shy or stressed pairs sometimes eat early spawns."}, {"q": "How fast do keyhole cichlid fry grow?", "a": "Slowly compared with most cichlids. Around 0.5 to 0.75 inch by 8 weeks is typical with good care."}]$g$::jsonb, $g$Keyholes are shy, so take your stage 1 photo with the challenge code quickly and quietly, then leave the pair in peace. Because the fry grow slowly, give them plenty of small meals so they show clear progress at your 30 and 60 day grow-out stages.$g$),
  ($g$rainbow-cichlid$g$, $g$9135a46e-6425-4f83-b93a-eba783c09c8a$g$::uuid, $g$rainbow-cichlid$g$, null, $g$How to Breed Rainbow Cichlids: Color Changes, Eggs and Fry$g$, $g$Breeding rainbow cichlids: a pair lays hundreds of eggs on a stone and guards the fry together. One of the easier Central American cichlids.$g$, $g$Rainbow cichlids are small, hardy Central American cichlids that are among the easiest of their group to breed. Pairs put on a great show, switching to bold breeding colors with dark lower bodies and bright yellow, then laying hundreds of eggs on a flat stone. Both parents guard the fry, and with a dedicated tank and good food you can expect regular spawns.$g$, $g${"method": "Substrate spawner (flat stone or cave, both parents guard)", "sexing": "Males usually larger with longer, pointed fins; colors change with mood, so check breeding tubes", "group": "One pair, ideally formed from a group", "breeding_tank": "30 gallons, sand, flat stones, caves, sponge filter", "conditioning": "2 to 3 weeks of pellets, vegetable foods, frozen bloodworms and brine shrimp", "trigger": "Stable water and a water change; pairs spawn readily once settled", "spawn": "Commonly several hundred eggs, large females up to around 1,000", "eggs": "Hatch in about 2 to 3 days at 78 to 80°F", "fry": "Free swimming about 4 to 6 days after hatching", "first_foods": "Baby brine shrimp", "grow_out": "About 1 inch in 6 to 8 weeks", "parents": "Good parents; remove fry once the pair prepares to spawn again"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 30 gallon tank works for one pair, matching the site's minimum. Use sand, flat stones or slate and a couple of caves. Rainbow cichlids graze algae and plants, so use hardy plants or wood with moss rather than soft stem plants.\n\nKeep pH 7.0 to 8.0, GH 8 to 20 and 78 to 80°F for breeding, all within the site's numbers. A sponge filter or a guarded intake protects the fry.\n\nSet the tank up and let it run for a few weeks before adding the fish, so the filter is fully cycled. Fry tanks get a lot of food, and a mature sponge filter handles that load far better than a new one. A heater guard and a tight lid are worth adding too."}, {"heading": "Choosing and Conditioning a Pair", "text": "Males are usually larger with longer, more pointed dorsal and anal fins. Colors are not a reliable guide, because both sexes change color with mood and breeding condition. The breeding tubes at spawning time are the surest check.\n\nGrow 6 juveniles together and let a pair form. Condition for 2 to 3 weeks with good pellets, spirulina or vegetable flake, blanched vegetables and frozen bloodworms and brine shrimp. This species eats a lot of plant matter.\n\nFeed small amounts two or three times a day rather than one large meal, and keep up water changes of 25 to 30 percent weekly while conditioning. Clean, stable water does as much to bring fish into spawning condition as rich food."}, {"heading": "Spawning", "text": "A pair in breeding dress darkens on the lower body and shows bright yellow on top. They clean a flat stone or the inside of a cave, and the female lays rows of eggs while the male fertilizes them.\n\nClutches are commonly several hundred, with large females reported at up to around 1,000. Both parents fan and guard the eggs."}, {"heading": "Eggs and Hatching", "text": "Eggs hatch in about 2 to 3 days at 78 to 80°F. The parents move the wrigglers to pits, and the fry become free swimming roughly 4 to 6 days after hatching.\n\nParents remove bad eggs. For artificial hatching, move the stone to matching water with an airstone beside it and a little methylene blue."}, {"heading": "Raising the Fry", "text": "- Week 1: newly hatched baby brine shrimp, three or four times a day.\n- Weeks 2 to 3: baby brine shrimp plus crushed flake and spirulina flake.\n- Week 4 onward: crushed pellets and frozen foods.\n- Change 25 to 30 percent of the water twice a week.\n- Keep 78 to 80°F.\n\nHatch baby brine shrimp daily so fresh live food is always on hand; fry that miss meals in the first week rarely catch up. Feed only what they clear in a few minutes and siphon leftovers, because uneaten food fouls small tanks quickly. Orange bellies after feeding mean the fry are eating well."}, {"heading": "Growing Out", "text": "Fry reach about 1 inch in 6 to 8 weeks with frequent feeding. Move them out when the parents start to clean a stone again, as they may chase older fry. Include vegetable foods in the grow out diet for healthy growth.\n\nSeparate fry by size if some race ahead, since bigger siblings can outcompete or bully smaller ones. Keep notes of spawn dates, hatch dates and growth; they make future spawns easier to plan."}, {"heading": "Common Mistakes", "text": "- Sexing by color, which changes with mood.\n- Skipping vegetable foods.\n- Soft, acidic water.\n- Not planning space for a large brood.\n- Crossing with other cichlids."}]$g$::jsonb, $g$[{"q": "How many eggs do rainbow cichlids lay?", "a": "Clutches are commonly several hundred eggs, and large females are reported to lay up to around 1,000."}, {"q": "How long do rainbow cichlid eggs take to hatch?", "a": "About 2 to 3 days at 78 to 80°F, with free swimming fry about 4 to 6 days later."}, {"q": "Why do rainbow cichlids change color?", "a": "Their colors shift with mood and breeding condition. Breeding pairs typically darken on the lower body and show bright yellow on top."}, {"q": "Are rainbow cichlids good parents?", "a": "Yes. Both parents guard the eggs and fry together."}]$g$::jsonb, $g$Show your pair with the challenge code in stage 1, ideally in their breeding colors. With big broods, pick a healthy sample of fry for each grow-out photo and keep the same tank in view so the progress is easy to follow.$g$),
  ($g$salvini-cichlid$g$, $g$8bba2904-8101-4ce3-aa15-c32de0418099$g$::uuid, $g$salvini-cichlid$g$, null, $g$How to Breed Salvini Cichlids: Pairing, Spawning and Fry$g$, $g$Breeding salvini cichlids: a pair lays a few hundred eggs on a flat stone and guards the fry fiercely. Straightforward once a compatible pair forms.$g$, $g$Salvini cichlids are colorful, feisty Central Americans, and a bonded pair makes devoted, protective parents. They clean a flat stone, lay a few hundred eggs and guard the fry hard. Spawning comes easily once you have a pair. The main challenges are pairing two fish that will not fight, and giving them a tank big enough to keep the peace.$g$, $g${"method": "Substrate spawner (flat stone, both parents guard)", "sexing": "Males larger with longer, pointed fins; females often show a dark spot in the dorsal fin", "group": "One pair, ideally formed from a group", "breeding_tank": "55 gallons, sand, flat stones, rockwork", "conditioning": "2 to 3 weeks of pellets, frozen bloodworms, mysis and krill", "trigger": "A water change and a cleaned flat stone", "spawn": "Commonly a few hundred eggs, up to about 500", "eggs": "Hatch in about 2 to 4 days at 78 to 80°F", "fry": "Free swimming about 4 to 6 days after hatching", "first_foods": "Baby brine shrimp", "grow_out": "About 1 inch in 6 to 8 weeks", "parents": "Fierce parents; remove fry when the pair spawns again"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A pair needs at least 55 gallons, matching the site's minimum. Use sand, a large flat stone or slate, and rockwork with caves so the female has places to retreat.\n\nKeep pH 7.0 to 8.0, GH 8 to 20 and 78 to 80°F for breeding, all within the site's numbers. Strong filtration with a guarded intake keeps water clean for a heavily fed pair and their fry.\n\nSet the tank up and let it run for a few weeks before adding the fish, so the filter is fully cycled. Fry tanks get a lot of food, and a mature sponge filter handles that load far better than a new one. A heater guard and a tight lid are worth adding too."}, {"heading": "Choosing and Conditioning a Pair", "text": "Males are usually larger with longer, more pointed dorsal and anal fins. Females are smaller and commonly show a dark spot in the dorsal fin. The breeding tubes at spawning time are the surest check.\n\nPairs are best formed by growing 5 or 6 juveniles together, then rehoming the rest once two pair off. Condition for 2 to 3 weeks with quality pellets, frozen bloodworms, mysis and krill.\n\nFeed small amounts two or three times a day rather than one large meal, and keep up water changes of 25 to 30 percent weekly while conditioning. Clean, stable water does as much to bring fish into spawning condition as rich food."}, {"heading": "Spawning", "text": "Breeding salvinis show intense yellow and red with darker markings. They clean a flat stone and the female lays rows of eggs as the male follows. Clutches are commonly a few hundred eggs, up to about 500.\n\nBoth parents guard aggressively and will chase anything that comes near, including tankmates and your hand."}, {"heading": "Eggs and Fungus", "text": "Eggs hatch in about 2 to 4 days at 78 to 80°F. The parents move the wrigglers to pits, and the fry become free swimming roughly 4 to 6 days after hatching.\n\nParents remove bad eggs. If you prefer to hatch them yourself, move the stone to a tank with matching water, an airstone beside it and a little methylene blue."}, {"heading": "Raising the Fry", "text": "- Week 1: newly hatched baby brine shrimp, three or four times a day.\n- Weeks 2 to 3: baby brine shrimp plus crushed flake.\n- Week 4 onward: crushed pellets and frozen foods.\n- Change 25 to 30 percent of the water twice a week.\n- Keep 78 to 80°F.\n\nHatch baby brine shrimp daily so fresh live food is always on hand; fry that miss meals in the first week rarely catch up. Feed only what they clear in a few minutes and siphon leftovers, because uneaten food fouls small tanks quickly. Orange bellies after feeding mean the fry are eating well."}, {"heading": "Growing Out", "text": "Fry reach about 1 inch in 6 to 8 weeks. Move them to a grow out tank once the parents begin preparing for their next spawn. Keep groups roomy to limit fighting, and juveniles will start to show yellow and dark markings as they grow.\n\nSeparate fry by size if some race ahead, since bigger siblings can outcompete or bully smaller ones. Keep notes of spawn dates, hatch dates and growth; they make future spawns easier to plan."}, {"heading": "Common Mistakes", "text": "- Forcing two adults together without a backup plan.\n- A tank too small for the female to escape.\n- Keeping peaceful tankmates in with a breeding pair.\n- Overcrowded grow out tanks, leading to nipping.\n- Crossing salvinis with other cichlids."}]$g$::jsonb, $g$[{"q": "How many eggs do salvini cichlids lay?", "a": "Clutches are commonly a few hundred eggs, up to about 500, laid on a flat stone."}, {"q": "How long do salvini cichlid eggs take to hatch?", "a": "About 2 to 4 days at 78 to 80°F, with free swimming fry about 4 to 6 days later."}, {"q": "How do you sex salvini cichlids?", "a": "Males are larger with longer, pointed fins. Females are smaller and commonly show a dark spot in the dorsal fin."}, {"q": "Are salvini cichlids aggressive when breeding?", "a": "Yes. Breeding pairs guard their eggs and fry fiercely, so a species-only tank is best."}]$g$::jsonb, $g$Open your log with the pair in the breeding tank and the challenge code showing, once you are sure they are getting along. A photo of the parents guarding eggs on the stone makes strong stage 2 evidence.$g$),
  ($g$texas-cichlid$g$, $g$b22da37f-989a-495e-a0d6-2b4e0e75c1ef$g$::uuid, $g$texas-cichlid$g$, null, $g$How to Breed Texas Cichlids: Pairs, Big Spawns and Fry Care$g$, $g$Breeding Texas cichlids: a bonded pair lays hundreds of eggs and guards the fry. Spawning is easy, but pairing and space take real planning.$g$, $g$The Texas cichlid is the only cichlid native to the United States, and a bonded pair puts on a spectacular show, darkening into bold breeding colors and guarding huge clouds of fry. Spawning is easy for a compatible pair. The real work is finding two fish that will not fight, giving them a large tank, and having room for hundreds of fast growing youngsters.$g$, $g${"method": "Substrate spawner (flat stone, both parents guard)", "sexing": "Adult males larger, often with a forehead hump; check breeding tubes to be sure", "group": "One pair, ideally formed from a group of juveniles", "breeding_tank": "75 gallons or more, sand, large flat stones, rockwork", "conditioning": "2 to 3 weeks of pellets, vegetable foods and frozen krill or mysis", "trigger": "A large water change and a cleaned flat stone", "spawn": "Commonly 500 to 1,000 eggs", "eggs": "Hatch in about 2 to 4 days at 78 to 80°F", "fry": "Free swimming about 4 to 6 days after hatching", "first_foods": "Baby brine shrimp", "grow_out": "About 1 inch in 6 to 8 weeks", "parents": "Fierce parents; watch for the male turning on the female"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "Texas cichlids grow large, and the site lists 75 gallons as a minimum. A breeding pair is happier in more space. Use sand, a large flat stone and rockwork that gives the female places to retreat. Use heavy filtration with a guarded intake.\n\nKeep pH 7.0 to 8.0, GH 8 to 20 and 78 to 80°F for breeding, all within the site's ranges.\n\nSet the tank up and let it run for a few weeks before adding the fish, so the filter is fully cycled. Fry tanks get a lot of food, and a mature sponge filter handles that load far better than a new one. A heater guard and a tight lid are worth adding too."}, {"heading": "Choosing and Conditioning a Pair", "text": "Adult males are usually larger and often develop a hump on the forehead. Females are smaller, and breeding females typically show a dark lower body. Sexing young fish is unreliable, and the breeding tubes at spawning time are the surest check.\n\nGrow 5 or 6 juveniles together and remove the rest once a pair forms. Condition for 2 to 3 weeks with quality pellets, vegetable foods and frozen krill or mysis.\n\nFeed small amounts two or three times a day rather than one large meal, and keep up water changes of 25 to 30 percent weekly while conditioning. Clean, stable water does as much to bring fish into spawning condition as rich food."}, {"heading": "Spawning", "text": "A pair in breeding dress turns dark on the lower body with pale upper sides, digs pits and cleans a flat stone. The female lays rows of eggs and the male fertilizes them.\n\nClutches are commonly 500 to 1,000 eggs. Both parents guard aggressively. Watch the male closely: if he starts chasing the female hard, a divider or a rock barrier with a gap only she fits through can save her."}, {"heading": "Eggs and Fungus", "text": "Eggs hatch in about 2 to 4 days at 78 to 80°F. The parents move the wrigglers to pits, and the fry become free swimming roughly 4 to 6 days after hatching.\n\nParents remove bad eggs. To hatch artificially, move the stone to matching water with an airstone beside it and a little methylene blue."}, {"heading": "Raising the Fry", "text": "- Week 1: newly hatched baby brine shrimp, three or four times a day.\n- Weeks 2 to 3: baby brine shrimp plus crushed flake.\n- Week 4 onward: crushed pellets, vegetable flake and frozen foods.\n- Change 30 to 40 percent of the water twice a week.\n- Keep 78 to 80°F.\n\nHatch baby brine shrimp daily so fresh live food is always on hand; fry that miss meals in the first week rarely catch up. Feed only what they clear in a few minutes and siphon leftovers, because uneaten food fouls small tanks quickly. Orange bellies after feeding mean the fry are eating well."}, {"heading": "Growing Out", "text": "Fry grow fast and reach about 1 inch in 6 to 8 weeks. A big spawn quickly outgrows a small tank, so plan for several grow out tanks or cull to a number you can raise well. Texas cichlids are native to Texas and northern Mexico and have become invasive where released, such as around New Orleans; never release fish or fry outdoors.\n\nSeparate fry by size if some race ahead, since bigger siblings can outcompete or bully smaller ones. Keep notes of spawn dates, hatch dates and growth; they make future spawns easier to plan."}, {"heading": "Common Mistakes", "text": "- Forcing two adults together, which can end badly.\n- A tank too small for a pair of large fish.\n- No plan for hundreds of fry.\n- Weak filtration for a heavily fed tank.\n- Crossing Texas cichlids with other cichlids."}]$g$::jsonb, $g$[{"q": "How many eggs do Texas cichlids lay?", "a": "Clutches are commonly 500 to 1,000 eggs, laid on a flat stone."}, {"q": "How long do Texas cichlid eggs take to hatch?", "a": "About 2 to 4 days at 78 to 80°F, with free swimming fry about 4 to 6 days later."}, {"q": "How do you tell a male Texas cichlid from a female?", "a": "Adult males are usually larger and often have a forehead hump, but this is unreliable in young fish. The breeding tubes at spawning are the surest check."}, {"q": "What size tank do Texas cichlids need to breed?", "a": "At least 75 gallons for a pair, and more space is better if the male becomes aggressive."}]$g$::jsonb, $g$Open your log once your pair is settled and getting along, and show them with the challenge code at stage 1. Big spawns mean plenty of fry, so focus your grow-out photos on a healthy group that shows clear growth by day 60.$g$),
  ($g$peacock-gudgeon$g$, $g$e6e6320e-c627-4345-ac26-40f6ad4e4d6e$g$::uuid, $g$peacock-gudgeon$g$, null, $g$How to Breed Peacock Gudgeons: Caves, Eggs and Tiny Fry$g$, $g$Breeding peacock gudgeons: females court males, eggs are laid in a cave and the male guards them. Spawning is easy; raising the small fry takes care.$g$, $g$Peacock gudgeons are small, colorful sleeper gobies from Papua New Guinea that spawn readily in caves. The female, with her bright yellow belly, courts the male, then lays her eggs on the cave ceiling, where he guards them until they hatch. Getting eggs is easy. The challenge is the small fry, which need tiny live foods in the first days.$g$, $g${"method": "Cave spawner (male guards eggs)", "sexing": "Males have a forehead hump and brighter color; females have a yellow belly when ready", "group": "One pair, or a group with extra caves", "breeding_tank": "10 to 15 gallons, several small caves, plants, sponge filter", "conditioning": "2 to 3 weeks of live or frozen brine shrimp, daphnia and bloodworms", "trigger": "Caves available and well fed, ready females", "spawn": "Commonly a few dozen to around 150 eggs", "eggs": "Breeders report hatching in roughly 7 to 10 days at 77 to 79°F", "fry": "Small; free swimming soon after hatching and need very tiny food", "first_foods": "Infusoria or vinegar eels, then microworms and baby brine shrimp", "grow_out": "About 0.5 inch in 8 to 10 weeks", "parents": "Male guards eggs; adults may eat free swimming fry, so move them"}$g$::jsonb, $g$[{"heading": "Setting Up the Breeding Tank", "text": "A 10 to 15 gallon tank suits a pair; the site lists 15 gallons for keeping a group. Provide several small caves, such as narrow clay caves or short PVC pipe, plus plants and Java moss. Use a gentle sponge filter.\n\nKeep pH 6.5 to 7.5, GH 5 to 12 and 77 to 79°F for breeding, within the site's 72 to 79°F range. Start some infusoria or vinegar eel cultures before you expect eggs.\n\nSet the tank up and let it run for a few weeks before adding the fish, so the filter is fully cycled. Fry tanks get a lot of food, and a mature sponge filter handles that load far better than a new one. A heater guard and a tight lid are worth adding too."}, {"heading": "Choosing and Conditioning a Pair", "text": "Males are larger, more colorful and develop a hump on the forehead as they mature. Females are smaller and show a bright yellow belly when ready to spawn. Both sexes have the black eyespot at the base of the tail.\n\nKeep one pair or a small group with more caves than males. Condition for 2 to 3 weeks with live or frozen baby brine shrimp, daphnia, cyclops and bloodworms. They often ignore dry food.\n\nFeed small amounts two or three times a day rather than one large meal, and keep up water changes of 25 to 30 percent weekly while conditioning. Clean, stable water does as much to bring fish into spawning condition as rich food."}, {"heading": "Spawning", "text": "Unusually, the female often does the courting, swimming around the male with her yellow belly on show. She follows him into a cave and lays her eggs on the ceiling or walls, commonly a few dozen to around 150.\n\nThe male then stays inside or at the entrance, fanning and guarding the eggs, and may barely come out to eat."}, {"heading": "Eggs and Hatching", "text": "Breeders commonly report hatching in roughly 7 to 10 days at 77 to 79°F, longer than for many egg layers. Many breeders move the whole cave with the eggs to a small hatching tank or container with gentle aeration, so the fry are not eaten once they leave the cave.\n\nIf you leave the eggs with the male, check the cave daily from about day 6 and be ready to move the fry."}, {"heading": "Raising the Fry", "text": "The fry are small, and first foods are the hardest part.\n\n- Days 1 to 5: infusoria or vinegar eels, several times a day.\n- Week 2: add microworms and newly hatched baby brine shrimp once the fry can take them.\n- Weeks 3 to 4: baby brine shrimp and powdered flake.\n- Change 10 to 15 percent of the water every two days, carefully.\n- Keep 77 to 79°F.\n\nStart infusoria or vinegar eel cultures a week or two before you expect a hatch so they are thick and ready. Feed little and often and siphon leftovers gently, because tiny fry are very sensitive to fouled water. Rounded bellies after feeding mean the fry are eating well."}, {"heading": "Growing Out", "text": "Fry grow steadily once they are on baby brine shrimp, reaching about half an inch in 8 to 10 weeks. Young fish start to show the tail eyespot early, while the male's forehead hump comes later. Keep them in a quiet tank with plenty of live and frozen food.\n\nSeparate fry by size if some race ahead, since bigger siblings can outcompete or bully smaller ones. Keep notes of spawn dates, hatch dates and growth; they make future spawns easier to plan."}, {"heading": "Common Mistakes", "text": "- No tiny live food ready when the eggs hatch.\n- Leaving free swimming fry with hungry adults.\n- Too few caves for the number of males.\n- Strong filter flow that sweeps away fry.\n- Disturbing the male so often that he abandons the eggs."}]$g$::jsonb, $g$[{"q": "How long do peacock gudgeon eggs take to hatch?", "a": "Breeders commonly report about 7 to 10 days at 77 to 79°F, with the male guarding them in the cave."}, {"q": "How do you sex peacock gudgeons?", "a": "Males are larger with a forehead hump and brighter colors. Females have a bright yellow belly, especially when ready to spawn."}, {"q": "What do peacock gudgeon fry eat?", "a": "They need very small foods at first, such as infusoria or vinegar eels, then microworms and baby brine shrimp."}, {"q": "Do peacock gudgeons eat their fry?", "a": "The male guards the eggs, but adults may eat free swimming fry. Moving the cave or the fry to a separate tank is safest."}]$g$::jsonb, $g$Show your pair and the cave setup with the challenge code at stage 1. For stage 2, a photo of eggs on the cave ceiling or the male guarding the entrance works well, and since hatching takes about a week or more, expect stage 3 to come later than for most egg layers.$g$)
) as v(slug, award_species_id, species_slug, glossary_slug, seo_title, summary, intro, facts, sections, faq, society_tip)
